import subprocess
import sys

def install(package):
    """Install a package using pip."""
    subprocess.check_call([sys.executable, "-m", "pip", "install", package])

def read_requirements(file_path):
    """Read the requirements file and return a list of package names."""
    with open(file_path, 'r') as file:
        return [line.strip() for line in file if line.strip() and not line.startswith('#')]

def check_and_install_requirements(file_path):
    """Check if the required packages are installed, and install them if necessary."""
    required_packages = read_requirements(file_path)
    for package in required_packages:
        try:
            __import__(package.split('==')[0])
        except ImportError:
            print(f"Installing {package}")
            install(package)

if __name__ == "__main__":
    requirements_file = "requirements.txt"
    check_and_install_requirements(requirements_file)
    print("All required packages are installed.")

