def is_prime(num):
    if num < 2:
        return False
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0:
            return False
    return True

def prime_factors(num):
    factors = []
    for i in range(2, num + 1):
        while num % i == 0:
            factors.append(i)
            num //= i
    return factors

def factorize_below_with_frequency(n):
    if n < 2:
        return {}

    factor_frequency = {}

    for i in range(2, n):
        factors = prime_factors(i)
        for factor in factors:
            if factor in factor_frequency:
                factor_frequency[factor] += 1
            else:
                factor_frequency[factor] = 1

    return factor_frequency

# Test cases
def test_factorize_below_with_frequency():
    test_cases = [
        (1, {}),
        (2, {}),
        (3, {2: 1}),
        (4, {2: 3}),
        (5, {2: 3, 3: 1}),
        (6, {2: 4, 3: 2}),
        (7, {2: 4, 3: 2, 5: 1}),
        (10, {2: 8, 3: 2, 5: 2, 7: 1}),
        (15, {2: 11, 3: 5, 5: 2, 7: 2, 11: 1, 13: 1}),
        (20, {2: 18, 3: 5, 5: 3, 7: 2, 11: 1, 13: 1, 17: 1, 19: 1})
    ]

    for i, (input_val, expected_output) in enumerate(test_cases, 1):
