import random

def get_player_guess(player_name, min_num, max_num):
    while True:
        try:
            guess = int(input(f"{player_name}, guess a number between {min_num} and {max_num}: "))
            if min_num <= guess <= max_num:
                return guess
            else:
                print(f"Please enter a number between {min_num} and {max_num}.")
        except ValueError:
            print("Please enter a valid number.")

def play_game():
    min_num = 1
    max_num = 100
    max_tries = 10

    random_number = random.randint(min_num, max_num)
    player1_name = input("Enter Player 1's name: ")
    player2_name = input("Enter Player 2's name: ")

    player1_tries = 0
    player2_tries = 0

    while player1_tries < max_tries and player2_tries < max_tries:
        # Player 1's turn
        if player1_tries < max_tries:
            guess = get_player_guess(player1_name, min_num, max_num)
            player1_tries += 1
            if guess == random_number:
                print(f"{player1_name} wins! The number was {random_number}.")
                return
            else:
                print(f"Wrong guess, {player1_name}. Tries left: {max_tries - player1_tries}")

        # Player 2's turn
        if player2_tries < max_tries:
            guess = get_player_guess(player2_name, min_num, max_num)
            player2_tries += 1
            if guess == random_number:
                print(f"{player2_name} wins! The number was {random_number}.")
                return
            else:
                print(f"Wrong guess, {player2_name}. Tries left: {max_tries - player2_tries}")

    print("Both players have run out of tries. The number was {random_number}.")

if __name__ == "__main__":
    play_game()

class ISBNValidator:
    def __init__(self, isbn):
        self.isbn = isbn.strip().replace('-', '')
        self.length = len(self.isbn)
        self.is_valid = False
        self.error_message = None

    def validate(self):
        if self.length == 10:
            self.is_valid = self._validate_isbn10()
        elif self.length == 13:
            self.is_valid = self._validate_isbn13()
        else:
            self.error_message = f"Invalid length: ISBN must be 10 or 13 characters, not {self.length}"
        return self.is_valid

    def _validate_isbn10(self):
        if not self.isbn[:-1].isdigit() or not (self.isbn[-1].isdigit() or self.isbn[-1] == 'X'):
            self.error_message = "Invalid characters: ISBN-10 must contain digits and an 'X' as the last character if applicable"
            return False

        digits = [int(d) if d != 'X' else 10 for d in self.isbn]
        weights = list(range(10, 0, -1))
        checksum = sum(d * w for d, w in zip(digits, weights)) % 11

        if checksum != 0:
            self.error_message = "Invalid checksum: ISBN-10 checksum is incorrect"
            return False

        return True

    def _validate_isbn13(self):
        if not self.isbn.isdigit():
            self.error_message = "Invalid characters: ISBN-13 must contain only digits"
            return False

        digits = [int(d) for d in self.isbn]
        weights = [1 if i % 2 == 0 else 3 for i in range(13)]
        checksum = sum(d * w for d, w in zip(digits, weights)) % 10

        if checksum != 0:
            self.error_message = "Invalid checksum: ISBN-13 checksum is incorrect"
            return False

        return True

    def get_error_message(self):
        return self.error_message


# Example usage
if __name__ == "__main__":
    isbns = [
        "0-306-40615-2",  # Valid ISBN-10
        "978-0-306-40615-7",  # Valid ISBN-13
        "0-306-40615-3",  # Invalid ISBN-10
        "978-0-306-40615-8",  # Invalid ISBN-13
        "12345678901234",  # Invalid length
        "0-306-4061X-2"  # Invalid characters
    ]

    for isbn in isbns:
        validator = ISBNValidator(isbn)
        if validator.validate():
            print(f"{isbn} is a valid ISBN")
        else:
            print(f"{isbn} is an invalid ISBN: {validator.get_error_message()}")

import subprocess
import sys
import os

def run_git_command(command, cwd=None):
    try:
        result = subprocess.run(command, check=True, text=True, capture_output=True, cwd=cwd)
        return result.stdout.strip()
    except subprocess.CalledProcessError as e:
        return e.stderr.strip()

def clone_repository(repo_url, repo_dir):
    command = ['git', 'clone', repo_url, repo_dir]
    output = run_git_command(command)
    if "fatal" in output:
        raise ValueError(f"Failed to clone repository: {output}")

def create_branch_from_commit(repo_dir, branch_name, commit_hash):
    command = ['git', 'checkout', commit_hash]
    output = run_git_command(command, cwd=repo_dir)
    if "fatal" in output:
        raise ValueError(f"Invalid commit hash: {output}")

    command = ['git', 'checkout', '-b', branch_name]
    output = run_git_command(command, cwd=repo_dir)
    if "fatal" in output:
        raise ValueError(f"Failed to create branch: {output}")

def main(repo_url, commit_hash, branch_name):
    repo_dir = os.path.basename(repo_url).replace('.git', '')

    # Clone the repository
    try:
        clone_repository(repo_url, repo_dir)
    except ValueError as e:
        print(e)
        sys.exit(1)

    # Create a new branch from the specified commit
    try:
        create_branch_from_commit(repo_dir, branch_name, commit_hash)
    except ValueError as e:
        print(e)
        sys.exit(1)

    print(f"Branch '{branch_name}' created from commit '{commit_hash}' in repository '{repo_url}'.")

if __name__ == "__main__":
    if len(sys.argv) != 4:
        print("Usage: python git_branch_creator.py <repository_url> <commit_hash> <branch_name>")
        sys.exit(1)

    repo_url = sys.argv[1]
    commit_hash = sys.argv[2]
    branch_name = sys.argv[3]

    main(repo_url, commit_hash, branch_name)

def numeric_to_grade(numeric_score):
    if not 1 <= numeric_score <= 100:
        raise ValueError("Score must be between 1 and 100.")

    if numeric_score >= 90:
        return 'A'
    elif numeric_score >= 80:
        return 'B'
    elif numeric_score >= 70:
        return 'C'
    elif numeric_score >= 60:
        return 'D'
    else:
        return 'F'

def grade_to_gpa(grade):
    grade_points = {
        'A': 4.0,
        'B': 3.0,
        'C': 2.0,
        'D': 1.0,
        'F': 0.0
    }
    return grade_points.get(grade, 0.0)

def calculate_gpa(grades):
    if not grades:
        return 0.0
    total_gpa = sum(grade_to_gpa(grade) for grade in grades)
    return total_gpa / len(grades)

def main():
    scores = []
    while True:
        try:
            score_input = input("Enter a numeric score between 1 and 100 (or 'done' to finish): ")
            if score_input.lower() == 'done':
                break
            score = float(score_input)
            grade = numeric_to_grade(score)
            print(f"Numeric Score: {score} -> Grade: {grade}")
            scores.append(grade)
        except ValueError as e:
            print(f"Error: {e}")

    if scores:
        gpa = calculate_gpa(scores)
        print(f"Grades: {', '.join(scores)}")
        print(f"Grade Point Average (GPA): {gpa:.2f}")
    else:
        print("No valid scores entered.")

if __name__ == "__main__":
    main()

from typing import List

def separate_paren_groups(paren_string: str, inner_paren: bool = False) -> List[str]:
    """
    The function consumes a string, including nested round and square brackets. It separates these groups into individual strings and returns them in a list, ignoring any spaces. Ensure all brackets are balanced in the separated groups.

    :param paren_string: The input string containing nested parentheses and square brackets.
    :param inner_paren: A flag to determine whether to include inner nested groups.
    :return: A list of separated groups.
    """
    def is_matching_pair(opening, closing):
        return (opening == '(' and closing == ')') or (opening == '[' and closing == ']')

    def parse_groups(s: str, include_inner: bool) -> List[str]:
        stack = []
        result = []
        current_group = []

        for char in s:
            if char in '([':
                if not stack or (stack and include_inner):
                    current_group.append(char)
                stack.append(char)
            elif char in ')]':
                if stack:
                    open_char = stack.pop()
                    if is_matching_pair(open_char, char):
                        current_group.append(char)
                        if not stack:
                            result.append(''.join(current_group))
                            current_group = []
                    else:
                        raise ValueError("Unbalanced parentheses or brackets")
                else:
                    raise ValueError("Unbalanced parentheses or brackets")
            elif char != ' ':
                current_group.append(char)

        if stack:
            raise ValueError("Unbalanced parentheses or brackets")

        return result

    cleaned_string = paren_string.replace(' ', '')
    return parse_groups(cleaned_string, inner_paren)

