from rest_framework import serializers
from .models import Book, Page

class PageSerializer(serializers.ModelSerializer):
    class Meta:
        model = Page
        fields = ['id', 'text']

class RequestSerializer(serializers.Serializer):
    book_id = serializers.IntegerField()
    pages = PageSerializer(many=True)

    def create(self, validated_data):
        book_id = validated_data['book_id']
        pages_data = validated_data['pages']

        # Get or create the book
        book, created = Book.objects.get_or_create(id=book_id)

        # Create or update pages
        for page_data in pages_data:
            page_id = page_data.get('id')
            if page_id:
                # Update existing page
                Page.objects.update_or_create(id=page_id, book=book, defaults=page_data)
            else:
                # Create new page
                Page.objects.create(book=book, **page_data)

        return {'book_id': book_id, 'pages': pages_data}

    def update(self, instance, validated_data):
        book_id = validated_data['book_id']
        pages_data = validated_data['pages']

        # Get the book
        book = Book.objects.get(id=book_id)

        # Update pages
        for page_data in pages_data:
            page_id = page_data.get('id')
            if page_id:
                # Update existing page
                Page.objects.update_or_create(id=page_id, book=book, defaults=page_data)
            else:
                # Create new page
                Page.objects.create(book=book, **page_data)

        return {'book_id': book_id, 'pages': pages_data}

