import math

def factorial(n):
    if n == 0:
        return 1
    return math.prod(range(1, n+1))

import threading
from typing import List, Any

class LimitedList:
    def __init__(self):
        self._data: List[Any] = []
        self._lock = threading.Lock()
        self._max_elements = 10

    def add(self, element: Any) -> None:
        with self._lock:
            if len(self._data) >= self._max_elements:
                raise ValueError("The list is full and cannot accept more elements.")
            self._data.append(element)

    def remove(self, element: Any) -> None:
        with self._lock:
            if element in self._data:
                self._data.remove(element)

    def is_present(self, element: Any) -> bool:
        with self._lock:
            return element in self._data

    def sort(self) -> None:
        with self._lock:
            self._data = self._merge_sort(self._data)

    def _merge_sort(self, arr: List[Any]) -> List[Any]:
        if len(arr) <= 1:
            return arr

        mid = len(arr) // 2
        left = self._merge_sort(arr[:mid])
        right = self._merge_sort(arr[mid:])

        return self._merge(left, right)

    def _merge(self, left: List[Any], right: List[Any]) -> List[Any]:
        result = []
        i = j = 0

        while i < len(left) and j < len(right):
            if left[i] < right[j]:
                result.append(left[i])
                i += 1
            else:
                result.append(right[j])
                j += 1

        result.extend(left[i:])
        result.extend(right[j:])
        return result

    def __str__(self):
        return str(self._data)

### Unit Tests

import unittest
from concurrent.futures import ThreadPoolExecutor

class TestLimitedList(unittest.TestCase):
    def test_add_and_remove_elements(self):
        ll = LimitedList()
        ll.add(5)
        ll.add(10)
        self.assertTrue(ll.is_present(5))
        self.assertTrue(ll.is_present(10))
        ll.remove(5)
        self.assertFalse(ll.is_present(5))
        self.assertTrue(ll.is_present(10))

    def test_add_elements_until_full(self):
        ll = LimitedList()
        for i in range(10):
            ll.add(i)
        with self.assertRaises(ValueError):
            ll.add(10)

    def test_sort_elements(self):
        ll = LimitedList()
        ll.add(5)
        ll.add(1)
        ll.add(3)
        ll.add(10)
        ll.sort()
        self.assertEqual(str(ll), "[1, 3, 5, 10]")

    def test_thread_safety(self):
        ll = LimitedList()
        def add_elements(ll, elements):
            for element in elements:
                ll.add(element)

        elements = list(range(20))
        with ThreadPoolExecutor(max_workers=5) as executor:
            for i in range(2):
                executor.submit(add_elements, ll, elements)

        self.assertEqual(len(ll._data), 10)
        self.assertTrue(all(element in ll._data for element in range(10)))

if __name__ == "__main__":
    unittest.main()

from typing import List, Tuple, Dict

class InsufficientBalanceException(Exception):
    pass

def below_zero(operations: Dict[int, List[Tuple[str, int]]], case_insensitive: bool = False) -> Dict[str, List[int]]:
    """
    Starting with zero balance, implement a system to track deposit and withdrawal operations on different bank accounts. Recognize when a balance turns negative and invoke an "InsufficientBalanceException" at such instances. End the operation by returning a dictionary presenting a list of account numbers that stayed above zero. If a case_insensitive flag is true, interpret 'Deposit' and 'deposit', 'Withdrawal' and 'withdrawal' as identical, and consider the balance at zero as well.

    Input dictionary presents tuples in the structure (Operation_type, Operation_value) as the value and Account_number as the key.

    Examples:
    >>> below_zero({1: [('Deposit', 1), ('Deposit', 2), ('Deposit', 3)]})
    {1: ['No negative balance']}
    >>> below_zero({1: [('Deposit', 1), ('Deposit', 2), ('Withdrawal', 4), ('Deposit', 5)]})
    InsufficientBalanceException: 'Account 1 has insufficient balance.'
    >>> below_zero({1: [('Deposit', 1), ('Deposit', 2), ('withdrawal', 3)]}, True)
    InsufficientBalanceException: 'Account 1 has insufficient balance.'
    """

    positive_balance_accounts = {}

    for account_number, ops in operations.items():
        balance = 0
        for op_type, op_value in ops:
            if case_insensitive:
                op_type = op_type.lower()

            if op_type == 'deposit':
                balance += op_value
            elif op_type == 'withdrawal':
                balance -= op_value
            else:
                raise ValueError(f"Unknown operation type: {op_type}")

            if balance < 0:
                raise InsufficientBalanceException(f'Account {account_number} has insufficient balance.')
            if case_insensitive and balance == 0:
                raise InsufficientBalanceException(f'Account {account_number} has insufficient balance.')

        positive_balance_accounts[account_number] = ['No negative balance']

    return positive_balance_accounts

# Example usage:
if __name__ == "__main__":
    try:
        print(below_zero({1: [('Deposit', 1), ('Deposit', 2), ('Deposit', 3)]}))
        print(below_zero({1: [('Deposit', 1), ('Deposit', 2), ('Withdrawal', 4), ('Deposit', 5)]}))
        print(below_zero({1: [('Deposit', 1), ('Deposit', 2), ('withdrawal', 3)]}, True))
    except InsufficientBalanceException as e:
        print(e)

import ast
import os

def find_unused_functions(directory):
    function_definitions = {}
    function_references = set()

    for root, _, files in os.walk(directory):
        for file in files:
            if file.endswith('.py'):
                with open(os.path.join(root, file), 'r') as f:
                    tree = ast.parse(f.read(), filename=file)
                    for node in ast.walk(tree):
                        if isinstance(node, ast.FunctionDef):
                            function_definitions[node.name] = file
                        elif isinstance(node, ast.Name) and isinstance(node.ctx, ast.Load):
                            function_references.add(node.id)

    unused_functions = {name: file for name, file in function_definitions.items() if name not in function_references}
    return unused_functions

unused_functions = find_unused_functions('your_project_directory')
for name, file in unused_functions.items():
    print(f'Function {name} in file {file} is unused.')

