class Student:
    def __init__(self, student_id, full_name, age, grades, activities):
        self.student_id = student_id
        self.full_name = full_name
        self.age = age
        self.grades = grades
        self.activities = activities

class StudentSystem:
    def __init__(self):
        self.students = []
        self.age_index = {}
        self.grade_range_index = {}
        self.activity_index = {}

    def add_student(self, student_id, full_name, age, grades, activities):
        student = Student(student_id, full_name, age, grades, activities)
        self.students.append(student)
        self._update_indices(student, add=True)

    def update_student(self, student_id, full_name=None, age=None, grades=None, activities=None):
        for student in self.students:
            if student.student_id == student_id:
                if full_name is not None:
                    student.full_name = full_name
                if age is not None:
                    student.age = age
                if grades is not None:
                    student.grades = grades
                if activities is not None:
                    student.activities = activities
                self._update_indices(student, add=True)
                return
        raise ValueError(f"Student with ID {student_id} not found")

    def get_students_by_age(self, age):
        return [student for student in self.students if student.student_id in self.age_index.get(age, [])]

    def get_students_by_grade_range(self, min_grade, max_grade):
        grade_range = (min_grade, max_grade)
        return [student for student in self.students if student.student_id in self.grade_range_index.get(grade_range, [])]

    def get_students_by_activity(self, activity):
        return [student for student in self.students if student.student_id in self.activity_index.get(activity, [])]

    def _update_indices(self, student, add=False):
        if add:
            self.age_index.setdefault(student.age, []).append(student.student_id)
            for grade in student.grades:
                grade_range = (min(grade), max(grade))
                self.grade_range_index.setdefault(grade_range, []).append(student.student_id)
            for activity in student.activities:
                self.activity_index.setdefault(activity, []).append(student.student_id)
        else:
            self.age_index[student.age].remove(student.student_id)
            for grade in student.grades:
                grade_range = (min(grade), max(grade))
                self.grade_range_index[grade_range].remove(student.student_id)
            for activity in student.activities:
                self.activity_index[activity].remove(student.student_id)

# Example usage
if __name__ == "__main__":
    system = StudentSystem()

    system.add_student(1, "Alice Smith", 18, [85, 90, 92], ["Chess Club", "Debate Team"])
    system.add_student(2, "Bob Johnson", 19, [78, 80, 85], ["Chess Club", "Robotics Club"])
    system.add_student(3, "Charlie Brown", 20, [95, 98, 99], ["Drama Club"])

    print("Students of age 18:")
    for student in system.get_students_by_age(18):
        print(student.full_name)

    print("Students with grades between 80 and 90:")
    for student in system.get_students_by_grade_range(80, 90):
        print(student.full_name)

    print("Students in Chess Club:")
    for student in system.get_students_by_activity("Chess Club"):
        print(student.full_name)

    system.update_student(1, full_name="Alice Doe")
    print("Updated student with ID 1:")
    for student in system.get_students_by_age(18):
        print(student.full_name)

import re
from datetime import datetime, date
from collections import defaultdict
from typing import List, Dict

class Customer:
    def __init__(self, name: str, email: str, phone: str, dob: str, address: str):
        self._name = None
        self._email = None
        self._phone = None
        self._dob = None
        self._address = None
        self.name = name
        self.email = email
        self.phone = phone
        self.dob = dob
        self.address = address

    @property
    def name(self) -> str:
        return self._name

    @name.setter
    def name(self, value: str):
        if not (2 <= len(value) <= 50) or not value.isalpha():
            raise ValueError("Name must be between 2 and 50 characters and contain only letters.")
        self._name = value

    @property
    def email(self) -> str:
        return self._email

    @email.setter
    def email(self, value: str):
        if len(value) > 100 or not re.match(r"[^@]+@[^@]+\.[^@]+", value):
            raise ValueError("Email must be valid and not exceed 100 characters.")
        self._email = value

    @property
    def phone(self) -> str:
        return self._phone

    @phone.setter
    def phone(self, value: str):
        if not re.match(r"^\d{3}-\d{3}-\d{4}$", value):
            raise ValueError("Phone number must be in the format 123-456-7890.")
        self._phone = value

    @property
    def dob(self) -> str:
        return self._dob

    @dob.setter
    def dob(self, value: str):
        try:
            dob = datetime.strptime(value, '%d/%m/%Y').date()
            if dob > date.today():
                raise ValueError
        except ValueError:
            raise ValueError("Invalid date of birth or date in the future. Format should be dd/mm/yyyy.")
        self._dob = value

    @property
    def address(self) -> str:
        return self._address

    @address.setter
    def address(self, value: str):
        if len(value) > 200:
            raise ValueError("Address must not exceed 200 characters.")
        self._address = value

    def display_info(self) -> str:
        dob = datetime.strptime(self.dob, '%d/%m/%Y').date()
        age = (date.today() - dob).days // 365
        return f"Name: {self.name}, Email: {self.email}, Phone: {self.phone}, Age: {age}, Address: {self.address}"

    @staticmethod
    def sort_customers(customers: List['Customer']) -> List['Customer']:
        return sorted(customers, key=lambda c: (c.name, (date.today() - datetime.strptime(c.dob, '%d/%m/%Y').date()).days))

    @staticmethod
    def filter_customers(customers: List['Customer'], domain: str, min_age: int) -> List['Customer']:
        filtered_customers = []
        for customer in customers:
            dob = datetime.strptime(customer.dob, '%d/%m/%Y').date()
            age = (date.today() - dob).days // 365
            if customer.email.endswith(f"@{domain}") and age > min_age:
                filtered_customers.append(customer)
        return filtered_customers

    @staticmethod
    def average_age(customers: List['Customer']) -> float:
        total_age = 0
        for customer in customers:
            dob = datetime.strptime(customer.dob, '%d/%m/%Y').date()
            age = (date.today() - dob).days // 365
            total_age += age
        return total_age / len(customers) if customers else 0

    @staticmethod
    def group_by_email_domain(customers: List['Customer']) -> Dict[str, List['Customer']]:
        groups = defaultdict(list)
        for customer in customers:
            domain = customer.email.split('@')[1]
            groups[domain].append(customer)
        return groups

    @staticmethod
    def group_by_name_initial(customers: List['Customer']) -> Dict[str, List['Customer']]:
        groups = defaultdict(list)
        for customer in customers:
            initial = customer.name[0].upper()
            groups[initial].append(customer)
        return groups

class SimpleSentimentAnalyzer:
    def __init__(self):
        self.positive_keywords = {"good", "great", "excellent", "amazing", "wonderful", "fantastic", "love", "happy", "best", "enjoy"}
        self.negative_keywords = {"bad", "terrible", "awful", "horrible", "poor", "disappointing", "hate", "sad", "worst", "annoying"}

    def classify_sentiment(self, sentence):
        words = sentence.lower().split()
        positive_count = sum(1 for word in words if word in self.positive_keywords)
        negative_count = sum(1 for word in words if word in self.negative_keywords)

        if positive_count > negative_count:
            return "Positive"
        elif negative_count > positive_count:
            return "Negative"
        else:
            return "Neutral"

# Example usage
