sentences = [
    "I love this place, it's amazing!",
    "The food is terrible and the service is poor.",
    "It's not bad, but it could be better.",
    "This is the best day ever!",
    "I am so sad, everything is wrong."
]

for sentence in sentences:
    sentiment = analyzer.classify_sentiment(sentence)
    print(f"'{sentence}' -> {sentiment}")

