from typing import List
import bisect

def is_prime(n: int) -> bool:
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def next_prime(n: int) -> int:
    while True:
        n += 1
        if is_prime(n):
            return n

def nearest_fibonacci(n: int) -> int:
    fibs = [0, 1]
    while fibs[-1] < 100:  # Precompute up to the largest single-digit number
        fibs.append(fibs[-1] + fibs[-2])
    idx = bisect.bisect_left(fibs, n)
    if idx == 0:
        return fibs[0]
    if idx == len(fibs) or fibs[idx] - n > n - fibs[idx - 1]:
        return fibs[idx - 1]
    return fibs[idx]

def toggle_case(c: str) -> str:
    if c.islower():
        return c.upper()
    elif c.isupper():
        return c.lower()
    return c

def modify_string(string: str) -> str:
    # Step 1: Toggle case of alphabetic characters
    toggled_string = ''.join(toggle_case(c) for c in string)

    # Step 2: Map each odd number to its adjacent Fibonacci number
    fib_mapped_string = ''
    for c in toggled_string:
        if c.isdigit() and int(c) % 2 != 0:
            fib_mapped_string += str(nearest_fibonacci(int(c)))
        else:
            fib_mapped_string += c

    # Step 3: Replicate special characters based on the next prime number after their count
    special_chars = [c for c in fib_mapped_string if not c.isalnum()]
    special_count = len(special_chars)
    next_prime_count = next_prime(special_count)
    replicated_string = ''
    for c in fib_mapped_string:
        if not c.isalnum():
            replicated_string += c * next_prime_count
        else:
            replicated_string += c

    # Step 4: Arrange all characters in a balanced Binary Search Tree
    class TreeNode:
        def __init__(self, val=0):
            self.val = val
            self.left = None
            self.right = None

    def insert_into_bst(root: TreeNode, val: int) -> TreeNode:
        if not root:
            return TreeNode(val)
        if val < root.val:
            root.left = insert_into_bst(root.left, val)
        else:
            root.right = insert_into_bst(root.right, val)
        return root

    def in_order_traversal(root: TreeNode) -> List[int]:
        return in_order_traversal(root.left) + [root.val] + in_order_traversal(root.right) if root else []

    root = None
    for c in replicated_string:
        root = insert_into_bst(root, ord(c))

    in_order_vals = in_order_traversal(root)
    result_string = ''.join(chr(val) for val in in_order_vals)

    return result_string

# Example usage
print(modify_string('Greet5!'))

import math

class Vector2D:
    def __init__(self, x: float, y: float):
        self.x = round(x, 6)
        self.y = round(y, 6)

    def get_x(self) -> float:
        return self.x

    def get_y(self) -> float:
        return self.y

    def magnitude(self) -> float:
        return round(math.sqrt(self.x**2 + self.y**2), 6)

    def add(self, other: 'Vector2D') -> 'Vector2D':
        return Vector2D(self.x + other.x, self.y + other.y)

    def subtract(self, other: 'Vector2D') -> 'Vector2D':
        return Vector2D(self.x - other.x, self.y - other.y)

    def multiply(self, scalar: float) -> 'Vector2D':
        return Vector2D(self.x * scalar, self.y * scalar)

    def dot_product(self, other: 'Vector2D') -> float:
        return round(self.x * other.x + self.y * other.y, 6)

    def cross_product(self, other: 'Vector2D') -> float:
        return 0.0

    def normalize(self) -> 'Vector2D':
        mag = self.magnitude()
        if mag == 0:
            return Vector2D(0, 0)
        return Vector2D(self.x / mag, self.y / mag)

    def distance(self, other: 'Vector2D') -> float:
        return round(math.sqrt((self.x - other.x)**2 + (self.y - other.y)**2), 6)

    def angle(self, other: 'Vector2D') -> float:
        dot = self.dot_product(other)
        mag_self = self.magnitude()
        mag_other = other.magnitude()
        if mag_self == 0 or mag_other == 0:
            return 0.0
        cos_theta = dot / (mag_self * mag_other)
        return round(math.degrees(math.acos(cos_theta)), 6)

    def rotate(self, angle: float) -> 'Vector2D':
        rad = math.radians(angle)
        cos_theta = math.cos(rad)
        sin_theta = math.sin(rad)
        new_x = self.x * cos_theta - self.y * sin_theta
        new_y = self.x * sin_theta + self.y * cos_theta
        return Vector2D(new_x, new_y)

    def project(self, other: 'Vector2D') -> 'Vector2D':
        dot = self.dot_product(other)
        mag_other_sq = other.magnitude() ** 2
        if mag_other_sq == 0:
            return Vector2D(0, 0)
        scalar = dot / mag_other_sq
        return other.multiply(scalar)

    def is_parallel(self, other: 'Vector2D') -> bool:
        return self.cross_product(other) == 0

    def is_orthogonal(self, other: 'Vector2D') -> bool:
        return self.dot_product(other) == 0

# Example usage
v1 = Vector2D(2, 3)
v2 = Vector2D(4, -1)

