print("3rd smallest:", bst.kth_smallest(3).key if bst.kth_smallest(3) else "Not Found")
print("Height:", bst.height())
print("Is balanced:", bst.is_balanced())
print("Least common ancestor of 20 and 40:", bst.least_common_ancestor(20, 40).key if bst.least_common_ancestor(20, 40) else "Not Found")
