# Load JSON data
visits_data = json.loads(data)

def query_visits(data, start_date, end_date):
    """
    Query visits based on a specified date range.

    :param data: JSON data containing user visits
    :param start_date: Start date for the query (inclusive)
    :param end_date: End date for the query (inclusive)
    :return: Dictionary with visits within the specified date range
    """
    start_date = datetime.strptime(start_date, "%Y-%m-%d")
    end_date = datetime.strptime(end_date, "%Y-%m-%d")
    result = {}

    for domain, visits in data["visits"].items():
        result[domain] = []
        for visit in visits:
            visit_date = datetime.strptime(visit["timestamp"], "%Y-%m-%dT%H:%M:%SZ")
            if start_date <= visit_date <= end_date:
                result[domain].append(visit)

    return result

