        if self.is_powered_on:
            if self.battery_level >= usage:
                self.battery_level -= usage
                print(f"Battery level: {self.battery_level} mAh")
            else:
                print("Not enough battery to perform this action.")
        else:
            print("The phone is powered off. Please power it on.")

