    ll.append(1)
    ll.append(2)
    ll.append(3)
    ll.prepend(0)
    ll.print_list()  # Output: 0 -> 1 -> 2 -> 3 -> None
    ll.delete(2)
    ll.print_list()  # Output: 0 -> 1 -> 3 -> None

def cmyk_to_hex(cmyk):
    try:
        c, m, y, k = cmyk
        if not (0 <= c <= 1 and 0 <= m <= 1 and 0 <= y <= 1 and 0 <= k <= 1):
            raise ValueError("CMYK values must be between 0 and 1")

        r = int(255 * (1 - c) * (1 - k))
        g = int(255 * (1 - m) * (1 - k))
        b = int(255 * (1 - y) * (1 - k))

        return f"#{r:02X}{g:02X}{b:02X}"
    except (ValueError, TypeError) as e:
        return f"Error: {e}"

def hex_to_cmyk(hex_color):
    try:
        if hex_color[0] != '#' or len(hex_color) != 7:
            raise ValueError("Invalid HEX color format")

        r = int(hex_color[1:3], 16) / 255.0
        g = int(hex_color[3:5], 16) / 255.0
        b = int(hex_color[5:7], 16) / 255.0

        k = 1 - max(r, g, b)
        if k == 1:
            return (0, 0, 0, 1)

        c = (1 - r - k) / (1 - k)
        m = (1 - g - k) / (1 - k)
        y = (1 - b - k) / (1 - k)

        return (c, m, y, k)
    except (ValueError, TypeError) as e:
        return f"Error: {e}"

def convert_cmyk_to_hex(cmyk_list):
    hex_list = []
    for cmyk in cmyk_list:
        hex_color = cmyk_to_hex(cmyk)
        hex_list.append(hex_color)
    return hex_list

def convert_hex_to_cmyk(hex_list):
    cmyk_list = []
    for hex_color in hex_list:
        cmyk = hex_to_cmyk(hex_color)
        cmyk_list.append(cmyk)
    return cmyk_list

