from datetime import datetime

def is_leap_year(year):
    return (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0)

def validate_date(day, month, year):
    if year < 1600 or year > 2100:
        return False
    if month < 1 or month > 12:
        return False
    if day < 1:
        return False
    if month in [4, 6, 9, 11] and day > 30:
        return False
    if month == 2:
        if is_leap_year(year) and day > 29:
            return False
        if not is_leap_year(year) and day > 28:
            return False
    if day > 31:
        return False
    return True

def day_of_week(day, month, year):
    if month < 3:
        month += 12
        year -= 1
    k = year % 100
    j = year // 100
    day_of_week = (day + 13 * (month + 1) // 5 + k + k // 4 + j // 4 + 5 * j) % 7
    days = ["Saturday", "Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday"]
    return days[day_of_week]

def julian_date(day, month, year):
    if is_leap_year(year):
        days_in_month = [31, 29, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    else:
        days_in_month = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]

    julian = day
    for i in range(month - 1):
        julian += days_in_month[i]
    return julian

def translate_date(date_str):
    if len(date_str) != 8 or not date_str.isdigit():
        return "Invalid date format. Please use DDMMYYYY."

    day = int(date_str[:2])
    month = int(date_str[2:4])
    year = int(date_str[4:])

    if not validate_date(day, month, year):
        return "Invalid date."

    dow = day_of_week(day, month, year)
    julian = julian_date(day, month, year)

    return f"Day of the week: {dow}, Julian date: {julian}"

