import math

def is_perfect_cube(n):
    """Check if a number is a perfect cube."""
    return round(n ** (1/3)) ** 3 == n

def is_factorial(n):
    """Check if a number is a factorial."""
    if n == 1:
        return True
    i = 1
    fact = 1
    while fact < n:
        i += 1
        fact *= i
    return fact == n

def cube_and_factorial_numbers(N):
    """Generator function to produce the first N numbers that are both perfect cubes and factorials."""
    if not isinstance(N, int) or N < 0:
        raise ValueError("N must be a non-negative integer.")

    count = 0
    num = 1
    while count < N:
        if is_perfect_cube(num) and is_factorial(num):
            yield num
            count += 1
        num += 1

# Example usage:
