def flatten(lst):
    """Flatten a list of lists."""
    for item in lst:
        if isinstance(item, list):
            yield from flatten(item)
        else:
            yield item

def merge_lists(*lists):
    """Merge an arbitrary number of lists by alternating elements."""
    # Flatten all input lists
    flat_lists = [list(flatten(lst)) for lst in lists]

    # Initialize an iterator for each list
    iterators = [iter(lst) for lst in flat_lists]

    # Use a flag to keep track of whether we have more elements to yield
    has_more_elements = True

    while has_more_elements:
        has_more_elements = False
        for it in iterators:
            try:
                yield next(it)
                has_more_elements = True
            except StopIteration:
                pass

