import re
from typing import Union, List

class Token:
    def __init__(self, type: str, value: str):
        self.type = type
        self.value = value

class Parser:
    def __init__(self, expression: str):
        self.expression = expression
        self.tokens = self.tokenize(expression)
        self.current_token = 0

    def tokenize(self, expression: str) -> List[Token]:
        token_specification = [
            ('NUMBER',   r'\d+(\.\d*)?'),  # Integer or decimal number
            ('IDENTIFIER', r'[a-zA-Z_][a-zA-Z_0-9]*'),  # Identifiers
            ('OPERATOR', r'[\+\-\*/=\!\&\|\<\>\~\^]'),  # Operators
            ('QUANTIFIER', r'\b(forall|exists)\b'),  # Quantifiers
            ('PAREN', r'[\(\)]'),  # Parentheses
            ('WHITESPACE', r'\s+'),  # Whitespace
            ('INVALID', r'.'),  # Any other character
        ]
        tok_regex = '|'.join('(?P<%s>%s)' % pair for pair in token_specification)
        tokens = []
        for mo in re.finditer(tok_regex, expression):
            kind = mo.lastgroup
            value = mo.group(kind)
            if kind == 'WHITESPACE':
                continue
            elif kind == 'INVALID':
                raise ValueError(f'Invalid token: {value}')
            token = Token(kind, value)
            tokens.append(token)
        return tokens

    def parse(self) -> dict:
        return self.parse_expression()

    def parse_expression(self) -> dict:
        token = self.tokens[self.current_token]
        if token.type == 'IDENTIFIER':
            self.current_token += 1
            return {'type': 'identifier', 'value': token.value}
        elif token.type == 'NUMBER':
            self.current_token += 1
            return {'type': 'number', 'value': float(token.value)}
        elif token.type == 'PAREN' and token.value == '(':
            self.current_token += 1
            expr = self.parse_expression()
            if self.tokens[self.current_token].type == 'PAREN' and self.tokens[self.current_token].value == ')':
                self.current_token += 1
                return expr
            else:
                raise ValueError('Unbalanced parentheses')
        elif token.type == 'OPERATOR':
            self.current_token += 1
            left = self.parse_expression()
            right = self.parse_expression()
            return {'type': 'binary_op', 'operator': token.value, 'left': left, 'right': right}
        elif token.type == 'QUANTIFIER':
            self.current_token += 1
            variable = self.parse_expression()
            sub_expr = self.parse_expression()
            return {'type': 'quantifier', 'quantifier': token.value, 'variable': variable, 'sub_expr': sub_expr}
        else:
            raise ValueError(f'Unexpected token: {token.value}')

