import re

def is_comment_line(line):
    return line.strip().startswith('--')

def is_empty_line(line):
    return line.strip() == ''

def is_start_of_multi_line_insert(line):
    return line.strip().upper().startswith('INSERT')

def is_end_of_multi_line_insert(line):
    return line.strip().upper().endswith(';')

def is_start_of_create_function(line):
    return 'CREATE FUNCTION' in line.upper()

def is_end_of_create_function(line, function_stack):
    if 'END' in line.upper():
        function_stack.pop()
    return not function_stack

def clean_sql_file(input_file, output_file):
    with open(input_file, 'r') as f:
        lines = f.readlines()

    in_multi_line_insert = False
    in_create_function = False
    function_stack = []
    cleaned_lines = []

    for line in lines:
        if is_start_of_multi_line_insert(line):
            in_multi_line_insert = True
        if is_start_of_create_function(line):
            function_stack.append(True)
            in_create_function = True

        if not (is_comment_line(line) or is_empty_line(line)) or in_multi_line_insert or in_create_function:
            cleaned_lines.append(line)

        if in_multi_line_insert and is_end_of_multi_line_insert(line):
            in_multi_line_insert = False
        if in_create_function:
            in_create_function = is_end_of_create_function(line, function_stack)

    with open(output_file, 'w') as f:
        f.writelines(cleaned_lines)

# Example usage
