class Person:
    def __init__(self, full_name, age, salutation=None):
        self.full_name = full_name
        self.age = None
        self.set_age(age)
        self.salutation = self.determine_salutation(salutation)

    def determine_salutation(self, salutation):
        if salutation in ["Mr.", "Mrs.", "Miss", "Dr.", "Ms."]:
            return salutation
        else:
            return "Mr."  # Default to Mr. if no valid salutation is provided

    def set_age(self, age):
        if isinstance(age, int) and age > 0:
            self.age = age
        else:
            raise ValueError("Age must be a positive integer")

    def is_leap_year(self, year):
        if (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0):
            return True
        return False

    def generate_expressive_statement(self, current_year):
        if self.age is None:
            raise ValueError("Age is not set")

        birth_year = current_year - self.age
        if self.is_leap_year(birth_year):
            leap_year_note = " (a leap year)"
        else:
            leap_year_note = ""

        return f"{self.salutation} {self.full_name} is {self.age} years old, born in {birth_year}{leap_year_note}."

