import re

def is_independent_clause(clause):
    # A simple heuristic to check if a clause is independent
    # This can be improved with more sophisticated NLP techniques
    return any(word in clause for word in ["is", "are", "was", "were", "am", "be", "been", "being"])

def is_dependent_clause(clause):
    # A simple heuristic to check if a clause is dependent
    # This can be improved with more sophisticated NLP techniques
    subordinating_conjunctions = ["although", "as", "because", "since", "unless", "until", "while", "who", "whom", "whose", "which", "that", "even though", "provided that", "in order", "as if", "if"]
    return any(clause.startswith(conj) for conj in subordinating_conjunctions)

def classify_sentence(sentence):
    clauses = re.split(r'(\band\b|\bor\b|\bbut\b|\bso\b|\byet\b|\balthough\b|\bas\b|\bbecause\b|\bsince\b|\bunless\b|\buntil\b|\bwhile\b|\bwho\b|\bwhom\b|\bwhose\b|\bwhich\b|\bthat\b|\beven though\b|\bprovided that\b|\bin order\b|\bas if\b|\bif\b)', sentence)
    independent_clauses = [clause for clause in clauses if is_independent_clause(clause)]
    dependent_clauses = [clause for clause in clauses if is_dependent_clause(clause)]

    if len(independent_clauses) == 1 and len(dependent_clauses) == 0:
        return "simple"
    elif len(independent_clauses) >= 2 and len(dependent_clauses) == 0:
        return "compound"
    else:
        return "complex"

text = "The quick brown fox jumped over the lazy dog. She jumped happily. Consider compound and complex sentences as separate types. Although it was raining, she went out. She went out, and she was happy."

sentences = re.split(r'(?<=[.!?])\s+', text)
sentences = [s.strip() for s in sentences if s.strip()]

simple_count = 0
compound_count = 0
complex_count = 0

for sentence in sentences:
    sentence_type = classify_sentence(sentence)
    if sentence_type == "simple":
        simple_count += 1
    elif sentence_type == "compound":
        compound_count += 1
    elif sentence_type == "complex":
        complex_count += 1

print(f"Simple sentences: {simple_count}")
