def advanced_monotonic(l: list, strict: bool = False):
    """
    Return True if list elements rise or fall monotonically, while taking into account the strictness criteria as well as probable non-integer or non-floating-point elements.
    If strict is made True, neighbouring elements must differ; otherwise, they could be alike.

    >>> advanced_monotonic([1, "2", 4, 20])
    True
    >>> advanced_monotonic([1, 20, None, 4, 10])
    False
    >>> advanced_monotonic([4, 1, "1", 0, -10], strict=True)
    False
    >>> advanced_monotonic([1, 1, "one", 1, 1], strict=False)
    True
    """
    def is_number(x):
        return isinstance(x, (int, float))

    # Filter out non-integer and non-floating-point elements
    filtered_list = [x for x in l if is_number(x)]

    if len(filtered_list) < 2:
        return True  # A list with fewer than 2 valid numbers is trivially monotonic

    increasing = None
    for i in range(len(filtered_list) - 1):
        if filtered_list[i] < filtered_list[i + 1]:
            if increasing is None:
                increasing = True
            elif not increasing:
                return False
        elif filtered_list[i] > filtered_list[i + 1]:
            if increasing is None:
                increasing = False
            elif increasing:
                return False
        elif strict:
            return False  # Neighbours must differ if strict is True

    return True

# Test cases
print(advanced_monotonic([1, "2", 4, 20]))  # True
print(advanced_monotonic([1, 20, None, 4, 10]))  # False
print(advanced_monotonic([4, 1, "1", 0, -10], strict=True))  # False
print(advanced_monotonic([1, 1, "one", 1, 1], strict=False))  # True

def median(l: list):
    """
    Returns the median of elements in list l without using built-in functions or sorting.
    It can process tuples with negative and floating point numbers in constant time.
    Also handles scenarios with multiple medians and non-numeric items.

    >>> median([3, 1, 2, 4, 5])
    3
    >>> median([-10, 4, 6, 1000, 10, 20])
    15.0
    >>> median([1, 2, (3, 4), 5])
    3
    >>> median([1, 'a', 2, 3])
    TypeError: List contains non-numeric elements.
    >>> median([1])
    ValueError: List must contain at least two elements.
    """

    def flatten(lst):
        """Flatten a list that may contain tuples."""
        result = []
        for item in lst:
            if isinstance(item, tuple):
                result.extend(flatten(item))
            elif isinstance(item, (int, float)):
                result.append(item)
            else:
                raise TypeError("List contains non-numeric elements.")
        return result

    def quickselect(lst, k):
        """Select the k-th smallest element from lst using Quickselect."""
        if len(lst) == 1:
            return lst[0]

        pivot = lst[len(lst) // 2]
        lows = [el for el in lst if el < pivot]
        highs = [el for el in lst if el > pivot]
        pivots = [el for el in lst if el == pivot]

        if k < len(lows):
            return quickselect(lows, k)
        elif k < len(lows) + len(pivots):
            return pivots[0]
        else:
            return quickselect(highs, k - len(lows) - len(pivots))

    # Flatten the list
    flat_list = flatten(l)

    # Check if the list has at least two elements
    if len(flat_list) < 2:
        raise ValueError("List must contain at least two elements.")

    n = len(flat_list)
    if n % 2 == 1:
        # Odd number of elements
        return quickselect(flat_list, n // 2)
    else:
        # Even number of elements
        return (quickselect(flat_list, n // 2 - 1) + quickselect(flat_list, n // 2)) / 2

# Test cases
print(median([3, 1, 2, 4, 5]))  # 3
print(median([-10, 4, 6, 1000, 10, 20]))  # 15.0
print(median([1, 2, (3, 4), 5]))  # 3
