class CRUDSystem:
    def __init__(self):
        self.users = {}

    def create(self, user_id, name):
        if user_id in self.users:
            return f"User with ID {user_id} already exists."
        self.users[user_id] = name
        return f"User with ID {user_id} created successfully."

    def read(self, user_id):
        if user_id in self.users:
            return f"User ID: {user_id}, Name: {self.users[user_id]}"
        return f"User with ID {user_id} does not exist."

    def update(self, user_id, new_name):
        if user_id in self.users:
            self.users[user_id] = new_name
            return f"User with ID {user_id} updated successfully."
        return f"User with ID {user_id} does not exist."

    def delete(self, user_id):
        if user_id in self.users:
            del self.users[user_id]
            return f"User with ID {user_id} deleted successfully."
        return f"User with ID {user_id} does not exist."

    def list_all(self):
        if not self.users:
            return "No users in the system."
        return "\n".join([f"User ID: {user_id}, Name: {name}" for user_id, name in self.users.items()])


# Example usage:
