    crud_system = CRUDSystem()

    print(crud_system.create(1, "Alice"))
    print(crud_system.create(2, "Bob"))
    print(crud_system.read(1))
    print(crud_system.update(1, "Alicia"))
    print(crud_system.delete(2))
    print(crud_system.list_all())

import num2words
from num2words import num2words

def number_to_words(n, lang='en'):
    if lang == 'en':
        return num2words(n, lang='en').replace('-', ' ').replace(',', '')
    elif lang == 'fr':
        return num2words(n, lang='fr').replace('-', ' ').replace(',', '')
    else:
        raise ValueError("Unsupported language")

def generate_latex_table(numbers):
    if not all(1 <= n <= 100 for n in numbers):
        raise ValueError("All numbers must be between 1 and 100")

    latex_table = "\\begin{tabular}{|c|c|c|}\n"
    latex_table += "\\hline\n"
    latex_table += "Numerical Value & English & French \\\\\n"
    latex_table += "\\hline\n"

    for n in numbers:
        en_word = number_to_words(n, 'en')
        fr_word = number_to_words(n, 'fr')
        latex_table += f"{n} & {en_word} & {fr_word} \\\\\n"
        latex_table += "\\hline\n"

    latex_table += "\\end{tabular}\n"
    return latex_table

def main():
    import sys

    if len(sys.argv) < 2:
        print("Usage: python script.py <comma-separated-list-of-numbers>")
        sys.exit(1)

    try:
        input_list = [int(n) for n in sys.argv[1].split(',')]
    except ValueError:
        print("All input values must be integers.")
        sys.exit(1)

    if len(input_list) > 1000:
        print("Input list cannot contain more than 1000 values.")
        sys.exit(1)

    try:
        latex_table = generate_latex_table(input_list)
        print(latex_table)
    except ValueError as e:
        print(e)
        sys.exit(1)

if __name__ == "__main__":
    main()

import math

class VolumeAdvanced:
    def __init__(self, shape_type, *dimensions):
        self.shape_type = shape_type.lower()
        self.dimensions = dimensions
        self.volume = self.calculate_volume()

    def calculate_volume(self):
        if self.shape_type == 'sphere':
            if len(self.dimensions) != 1 or self.dimensions[0] <= 0:
                raise ValueError("Sphere requires a positive radius.")
            radius = self.dimensions[0]
            return (4/3) * math.pi * (radius ** 3)
        elif self.shape_type == 'cylinder':
            if len(self.dimensions) != 2 or any(d <= 0 for d in self.dimensions):
                raise ValueError("Cylinder requires positive radius and height.")
            radius, height = self.dimensions
            return math.pi * (radius ** 2) * height
        elif self.shape_type == 'cone':
            if len(self.dimensions) != 2 or any(d <= 0 for d in self.dimensions):
                raise ValueError("Cone requires positive radius and height.")
            radius, height = self.dimensions
            return (1/3) * math.pi * (radius ** 2) * height
        elif self.shape_type == 'cube':
            if len(self.dimensions) != 1 or self.dimensions[0] <= 0:
                raise ValueError("Cube requires a positive side length.")
            side = self.dimensions[0]
            return side ** 3
        elif self.shape_type == 'cuboid':
            if len(self.dimensions) != 3 or any(d <= 0 for d in self.dimensions):
                raise ValueError("Cuboid requires positive length, width, and height.")
            length, width, height = self.dimensions
            return length * width * height
        elif self.shape_type == 'pyramid':
            if len(self.dimensions) != 3 or any(d <= 0 for d in self.dimensions):
                raise ValueError("Pyramid requires positive base length, base width, and height.")
            base_length, base_width, height = self.dimensions
            return (1/3) * base_length * base_width * height
        else:
            raise ValueError("Unsupported shape type.")

    def compare_volumes(self, other):
        if not isinstance(other, VolumeAdvanced):
            raise TypeError("Comparison must be with another VolumeAdvanced object.")
        if self.shape_type != other.shape_type:
            raise ValueError("Can only compare volumes of the same shape type.")

        if self.volume > other.volume:
            percentage = ((self.volume - other.volume) / other.volume) * 100
            return f"The {self.shape_type} with volume {self.volume} is larger by {percentage:.2f}%."
        elif self.volume < other.volume:
            percentage = ((other.volume - self.volume) / self.volume) * 100
            return f"The {other.shape_type} with volume {other.volume} is larger by {percentage:.2f}%."
        else:
            return f"Both {self.shape_type}s have the same volume of {self.volume}."

    def subtract_volume(self, other):
        if not isinstance(other, VolumeAdvanced):
            raise TypeError("Subtraction must be with another VolumeAdvanced object.")
        if self.shape_type != other.shape_type:
            raise ValueError("Can only subtract volumes of the same shape type.")

        if self.volume < other.volume:
            raise ValueError("The volume to subtract is larger than the current volume.")

        return self.volume - other.volume

