class Node:
    def __init__(self, data):
        self.data = data
        self.next = None

class LinkedList:
    def __init__(self):
        self.head = None

    def append(self, data):
        new_node = Node(data)
        if self.head is None:
            self.head = new_node
        else:
            current = self.head
            while current.next:
                current = current.next
            current.next = new_node

    def display(self):
        current = self.head
        while current:
            print(current.data, end=" -> ")
            current = current.next
        print("None")

    def prepend(self, data):
        new_node = Node(data)
        new_node.next = self.head
        self.head = new_node

    def delete(self, key):
        current = self.head
        if current and current.data == key:
            self.head = current.next
            current = None
            return
        prev = None
        while current and current.data != key:
            prev = current
            current = current.next
        if current is None:
            return
        prev.next = current.next
        current = None

# Example usage
if __name__ == "__main__":
    linked_list = LinkedList()
    linked_list.append(1)
    linked_list.append(2)
    linked_list.append(3)
    linked_list.prepend(0)
    linked_list.display()  # Output: 0 -> 1 -> 2 -> 3 -> None
    linked_list.delete(2)
    linked_list.display()  # Output: 0 -> 1 -> 3 -> None

from datetime import datetime

def calculate_age(dob):
    try:
        # Parse the date of birth
        dob = datetime.strptime(dob, "%d-%m-%Y")

        # Calculate the age
        today = datetime.today()
        age = today.year - dob.year - ((today.month, today.day) < (dob.month, dob.day))
        return age
    except ValueError:
        # Handle invalid date format
        return None

def display_sorted_users(users):
    # List to store the user data with calculated age
    user_data = []

    for user in users:
        full_name = user.get('Full Name')
        dob = user.get('Date of Birth')

        if full_name and dob:
            age = calculate_age(dob)
            if age is not None:
                user_data.append({
                    'Full Name': full_name,
                    'Date of Birth': dob,
                    'Age': age
                })
            else:
                print(f"Invalid date format for {full_name}: {dob}")
        else:
            print(f"Missing data for user: {full_name}")

    # Sort users by age in descending order
    user_data.sort(key=lambda x: x['Age'], reverse=True)

    # Display the sorted users
    for user in user_data:
        print(f"Full Name: {user['Full Name']}, Date of Birth: {user['Date of Birth']}, Age: {user['Age']}")

