class LibraryMember:
    def __init__(self, member_id, name, address, phone, email):
        self.member_id = member_id
        self.name = name
        self.address = address
        self.phone = phone
        self.email = email

    def __str__(self):
        return f"Member ID: {self.member_id}\nName: {self.name}\nAddress: {self.address}\nPhone: {self.phone}\nEmail: {self.email}"

    def update_name(self, new_name):
        self.name = new_name

    def update_address(self, new_address):
        self.address = new_address

    def update_phone(self, new_phone):
        self.phone = new_phone

    def update_email(self, new_email):
        self.email = new_email

class LibraryMemberManager:
    def __init__(self):
        self.members = {}

    def add_member(self, member_id, name, address, phone, email):
        if member_id in self.members:
            raise ValueError(f"Member with ID {member_id} already exists.")
        new_member = LibraryMember(member_id, name, address, phone, email)
        self.members[member_id] = new_member
        print(f"Member with ID {member_id} added successfully.")

    def get_member(self, member_id):
        if member_id not in self.members:
            raise ValueError(f"Member with ID {member_id} does not exist.")
        return self.members[member_id]

    def update_member(self, member_id, **kwargs):
        if member_id not in self.members:
            raise ValueError(f"Member with ID {member_id} does not exist.")
        member = self.members[member_id]
        if 'name' in kwargs:
            member.update_name(kwargs['name'])
        if 'address' in kwargs:
            member.update_address(kwargs['address'])
        if 'phone' in kwargs:
            member.update_phone(kwargs['phone'])
        if 'email' in kwargs:
            member.update_email(kwargs['email'])
        print(f"Member with ID {member_id} updated successfully.")

    def remove_member(self, member_id):
        if member_id not in self.members:
            raise ValueError(f"Member with ID {member_id} does not exist.")
        del self.members[member_id]
        print(f"Member with ID {member_id} removed successfully.")

    def list_members(self):
        if not self.members:
            print("No members in the library.")
            return
        for member_id, member in self.members.items():
            print(member)
            print("-" * 40)

# Example usage
