def find_second_smallest(numbers):
    if len(numbers) < 2:
        return None  # Not enough elements to find the second smallest

    first = None
    second = None

    for num in numbers:
        if first is None or num < first:
            second = first
            first = num
        elif num != first and (second is None or num < second):
            second = num

    return second

