import requests
from bs4 import BeautifulSoup
from urllib.parse import urljoin, urlparse

def fetch_images(url, depth=2):
    visited = set()
    images = []

    def scrape(url, current_depth=0):
        if current_depth > depth or url in visited:
            return
        visited.add(url)
        try:
            response = requests.get(url)
            soup = BeautifulSoup(response.text, 'html.parser')
            for img in soup.find_all('img'):
                img_url = urljoin(url, img.get('src'))
                images.append(img_url)

            for link in soup.find_all('a', href=True):
                next_url = urljoin(url, link['href'])
                if urlparse(next_url).netloc == urlparse(url).netloc:
                    scrape(next_url, current_depth + 1)
        except Exception as e:
            print(f"Error fetching {url}: {e}")

    scrape(url)
    return images

import math

def hcf_of_four(a, b, c, d):
    """Calculate the HCF of four numbers."""
    return math.gcd(math.gcd(a, b), math.gcd(c, d))

def closest_divisible_number(n, divisor):
    """Find the closest number to n that is divisible by divisor."""
    quotient = n // divisor
    remainder = n % divisor
    if remainder < divisor / 2:
        return quotient * divisor
    else:
        return (quotient + 1) * divisor

def hcf_and_divisibility_check(x1, x2, x3, x4, divisor):
    try:
        # Calculate the HCF of the four numbers
        hcf = hcf_of_four(x1, x2, x3, x4)
        print(f"The Highest Common Factor (HCF) of {x1}, {x2}, {x3}, and {x4} is: {hcf}")

        # Check divisibility and find closest divisible numbers if necessary
        results = {}
        for num in [x1, x2, x3, x4]:
            if num % divisor == 0:
                results[num] = f"{num} is divisible by {divisor}"
            else:
                closest_num = closest_divisible_number(num, divisor)
                results[num] = f"{num} is not divisible by {divisor}. The closest divisible number is {closest_num}"

        for num, result in results.items():
            print(result)

    except ZeroDivisionError:
        print("Error: Divisor cannot be zero.")
    except TypeError:
        print("Error: All inputs must be integers.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")

