def find_extreme_values(l, n):
    if len(l) < 2 * n:
        raise ValueError("List must contain at least 10 elements to find 5 highest and 5 lowest values.")

    max_vals = []
    min_vals = []

    for _ in range(n):
        max_val = float('-inf')
        min_val = float('inf')

        for val in l:
            if val > max_val and val not in max_vals:
                max_val = val
            if val < min_val and val not in min_vals:
                min_val = val

        max_vals.append(max_val)
        min_vals.append(min_val)

    return max_vals, min_vals

def average_of_extremes(l):
    try:
        max_vals, min_vals = find_extreme_values(l, 5)
        return (sum(max_vals) + sum(min_vals)) / 10
    except ValueError as e:
        return str(e)

