from typing import Any, Hashable, Optional

class HashTable:
    def __init__(self, initial_size: int = 10, load_factor: float = 0.7):
        self.size = initial_size
        self.load_factor = load_factor
        self.buckets = [None] * self.size
        self.lock = threading.Lock()
        self.count = 0

    def _hash(self, key: Hashable) -> int:
        if isinstance(key, int):
            return key % self.size
        elif isinstance(key, str):
            return sum(ord(char) for char in key) % self.size
        else:
            raise TypeError("Key must be an integer or a string")

    def _resize(self) -> None:
        with self.lock:
            old_buckets = self.buckets
            self.size *= 2
            self.buckets = [None] * self.size
            self.count = 0

            for bucket in old_buckets:
                if bucket is not None:
                    for key, value in bucket:
                        self.insert(key, value)

    def insert(self, key: Hashable, value: Any) -> None:
        with self.lock:
            index = self._hash(key)
            if self.buckets[index] is None:
                self.buckets[index] = []
            for i, (k, v) in enumerate(self.buckets[index]):
                if k == key:
                    self.buckets[index][i] = (key, value)
                    return
            self.buckets[index].append((key, value))
            self.count += 1

            if self.count / self.size >= self.load_factor:
                self._resize()

    def search(self, key: Hashable) -> Optional[Any]:
        with self.lock:
            index = self._hash(key)
            if self.buckets[index] is None:
                return None
            for k, v in self.buckets[index]:
                if k == key:
                    return v
            return None

    def delete(self, key: Hashable) -> None:
        with self.lock:
            index = self._hash(key)
            if self.buckets[index] is None:
                return
            for i, (k, v) in enumerate(self.buckets[index]):
                if k == key:
                    del self.buckets[index][i]
                    self.count -= 1
                    return

    def __str__(self):
        return str(self.buckets)

# Example usage
if __name__ == "__main__":
    ht = HashTable()
    ht.insert(1, "one")
    ht.insert(2, "two")
    ht.insert("three", 3)
    ht.insert(11, "eleven")  # Should trigger resize
    print(ht.search(1))  # Output: one
    print(ht.search("three"))  # Output: 3
    ht.delete(2)
    print(ht.search(2))  # Output: None
    print(ht)

def convert_dictionary_to_lists(input_dict):
    """
    Converts a dictionary into multiple lists. One list contains the keys, and the other lists contain the values,
    separated by their data types.

    :param input_dict: Dictionary to be converted.
    :return: A tuple containing the list of keys and a dictionary of lists, where each key is a data type and the value
             is a list of values of that type.
    """
    if not isinstance(input_dict, dict):
        raise ValueError("Input must be a dictionary.")

    keys = []
    value_types = {}

    for key, value in input_dict.items():
        if not isinstance(key, (str, int, float)):
            raise ValueError("Dictionary keys must be of type str, int, or float.")

        keys.append(key)

        if isinstance(value, list):
            for item in value:
                item_type = type(item)
                if item_type not in value_types:
                    value_types[item_type] = []
                value_types[item_type].append(item)
        else:
            item_type = type(value)
            if item_type not in value_types:
                value_types[item_type] = []
            value_types[item_type].append(value)

    return keys, value_types

# Test the function with various dictionaries
def test_conversion():
    # Test with a simple dictionary
    simple_dict = {"Alice": 24, "Bob": 3, "Carol": 15}
    keys, value_types = convert_dictionary_to_lists(simple_dict)
    print("Simple Dictionary:")
    print("Keys:", keys)
    print("Values by Type:", value_types)
    print()

    # Test with a multi-type dictionary
    multi_type_dict = {"Alice": [24, "Female"], "Bob": [3, "Male"], "Carol": [15, "Female"]}
    keys, value_types = convert_dictionary_to_lists(multi_type_dict)
    print("Multi-Type Dictionary:")
    print("Keys:", keys)
    print("Values by Type:", value_types)
    print()

    # Test with an incorrect input type
    try:
        invalid_input = "Not a dictionary"
        keys, value_types = convert_dictionary_to_lists(invalid_input)
    except ValueError as e:
        print("Error:", e)
    print()

    # Test with a dictionary containing invalid keys
    try:
        invalid_keys_dict = {["Invalid", "Key"]: 24, "Bob": 3, "Carol": 15}
        keys, value_types = convert_dictionary_to_lists(invalid_keys_dict)
    except ValueError as e:
        print("Error:", e)
    print()

# Run the test function
test_conversion()

import json
from collections import defaultdict
from typing import Any, Dict, List, Union

class JSONParser:
    def __init__(self):
        self.seen_objects = set()
        self.unique_keys = defaultdict(int)

    def parse(self, json_string: str) -> Dict[str, str]:
        try:
            data = json.loads(json_string)
        except json.JSONDecodeError as e:
            raise ValueError(f"Invalid JSON syntax: {e}")

        return self._parse_value(data)

    def _parse_value(self, value: Any) -> Union[str, List[str], Dict[str, str]]:
        if isinstance(value, dict):
            return self._parse_dict(value)
        elif isinstance(value, list):
            return self._parse_list(value)
        else:
            return self._convert_to_string(value)

    def _parse_dict(self, data: Dict[Any, Any]) -> Dict[str, str]:
        result = {}
        for key, value in data.items():
            key = self._ensure_unique_key(key)
            result[key] = self._parse_value(value)
        return result

    def _parse_list(self, data: List[Any]) -> List[str]:
        return [self._parse_value(item) for item in data]

    def _ensure_unique_key(self, key: Any) -> str:
        key = str(key)
        if self.unique_keys[key] > 0:
            key = f"{key}_{self.unique_keys[key]}"
        self.unique_keys[key] += 1
        return key

    def _convert_to_string(self, value: Any) -> str:
        if value is None:
            return "null"
        return str(value)

    def _detect_circular_reference(self, obj: Any) -> bool:
        obj_id = id(obj)
        if obj_id in self.seen_objects:
            return True
        self.seen_objects.add(obj_id)
        return False

    def validate_against_schema(self, data: Dict[str, str], schema: Dict[str, Any]) -> bool:
        for key, value in schema.items():
            if key not in data:
                raise ValueError(f"Missing key: {key}")
            if not isinstance(data[key], str):
                raise ValueError(f"Value for key {key} is not a string")
            if value is not None and not data[key].startswith(value):
                raise ValueError(f"Value for key {key} does not match the schema")
        return True

# Example usage
json_string = '{"name": "John", "age": 30, "address": {"city": "New York", "zip": 10001}, "hobbies": ["reading", "coding"], "name": "Jane"}'
parser = JSONParser()
parsed_data = parser.parse(json_string)
print(parsed_data)

# Example schema
schema = {
    "name": "J",
    "age": None,
    "address": {
        "city": "N",
        "zip": "1"
    },
    "hobbies": ["r", "c"]
}

# Validate parsed data against schema
try:
    parser.validate_against_schema(parsed_data, schema)
    print("Data is valid according to the schema")
except ValueError as e:
    print(f"Validation error: {e}")

from abc import ABC, abstractmethod
from datetime import datetime, timedelta

class Book(ABC):
    def __init__(self, title, author, year, book_type):
        self.title = title
        self.author = author
        self.year = year
        self.book_type = book_type
        self.digital_rights = "Unspecified"
        self.is_borrowed = False
        self.due_date = None

    @abstractmethod
    def get_book_info(self):
        pass

    def borrow(self, days):
        if not self.is_borrowed:
            self.is_borrowed = True
            self.due_date = datetime.now() + timedelta(days=days)
            print(f"{self.title} has been borrowed and is due on {self.due_date}")
        else:
            print(f"{self.title} is already borrowed.")

    def return_book(self):
        if self.is_borrowed:
            self.is_borrowed = False
            self.due_date = None
            print(f"{self.title} has been returned.")
        else:
            print(f"{self.title} is not currently borrowed.")

    def check_overdue(self):
        if self.is_borrowed and self.due_date < datetime.now():
            print(f"{self.title} is overdue.")
        else:
            print(f"{self.title} is not overdue.")

def is_empty_and_count_empty_dicts(data, visited=None):
    if visited is None:
        visited = set()

    if id(data) in visited:
        return True, 0  # Already visited, treat as non-empty to avoid infinite loop

    visited.add(id(data))

    if isinstance(data, dict):
        if not data:
            return True, 1  # This dictionary is empty

        all_empty = True
        empty_count = 0

        for value in data.values():
            is_empty, count = is_empty_and_count_empty_dicts(value, visited)
            if not is_empty:
                all_empty = False
            empty_count += count

        return all_empty, empty_count

    elif isinstance(data, (list, tuple, set)):
        all_empty = True
        empty_count = 0

        for item in data:
            is_empty, count = is_empty_and_count_empty_dicts(item, visited)
            if not is_empty:
                all_empty = False
            empty_count += count

        return all_empty, empty_count

    else:
        return False, 0  # Non-iterable object, treat as non-empty

