def shortest_unique_substring(strings):
    def build_suffix_array(s):
        n = len(s)
        suffixes = [(s[i:], i) for i in range(n)]
        suffixes.sort()
        return [index for _, index in suffixes]

    def is_unique(substring, strings, exclude_index):
        for i, s in enumerate(strings):
            if i == exclude_index:
                continue
            if substring in s:
                return False
        return True

    def find_shortest_unique_substring(s, strings, exclude_index):
        n = len(s)
        suffix_array = build_suffix_array(s)
        for length in range(1, n + 1):
            seen = {}
            for i in suffix_array:
                if i + length > n:
                    break
                sub = s[i:i + length]
                if sub in seen:
                    seen[sub] += 1
                else:
                    seen[sub] = 1
            for sub, count in seen.items():
                if count == 1 and is_unique(sub, strings, exclude_index):
                    return sub
        return None

    shortest_unique = None
    for i, s in enumerate(strings):
        if not s.strip():
            continue
        sub = find_shortest_unique_substring(s, strings, i)
        if sub and (shortest_unique is None or len(sub) < len(shortest_unique)):
            shortest_unique = sub

    if shortest_unique:
        return shortest_unique
    else:
        return "No unique sub-string found"

# Unit Tests
def test_shortest_unique_substring():
    assert shortest_unique_substring(["abc", "def", "ghi"]) == "a"
    assert shortest_unique_substring(["abc", "abc", "abc"]) == "No unique sub-string found"
    assert shortest_unique_substring(["abc", "defg", "def"]) == "a"
    assert shortest_unique_substring(["a", "b", "c"]) == "a"
    assert shortest_unique_substring(["", " ", "a"]) == "a"
    assert shortest_unique_substring(["a", "b", "c", "d", "e"]) == "a"
    assert shortest_unique_substring(["abc", "def", "ghi", "jkl"]) == "a"
    assert shortest_unique_substring(["abc", "def", "def", "ghi"]) == "a"
    assert shortest_unique_substring(["abc", "abc", "abc", "def"]) == "d"
    assert shortest_unique_substring(["abc", "def", "defg", "def"]) == "a"
    assert shortest_unique_substring(["abc", "def", "def", "ghi"]) == "a"
    assert shortest_unique_substring(["abc", "abc", "abc", "def", "def"]) == "g"
    assert shortest_unique_substring(["abc", "def", "defg", "def", "ghi"]) == "a"
    assert shortest_unique_substring(["abc", "def", "def", "ghi", "jkl"]) == "a"
    assert shortest_unique_substring(["abc", "def", "defg", "def", "ghi", "jkl"]) == "a"
    assert shortest_unique_substring(["a", "a", "a", "b", "b", "b", "c", "c", "c"]) == "b"
    assert shortest_unique_substring(["a", "a", "a", "b", "b", "b", "c", "c", "c", "d", "d", "d"]) == "b"
    assert shortest_unique_substring(["a", "a", "a", "b", "b", "b", "c", "c", "c", "d", "d", "d", "e", "e", "e"]) == "b"

    print("All tests passed!")

test_shortest_unique_substring()

import math

class HashTable:
    def __init__(self, initial_size=1009):
        self.size = initial_size
        self.table = [None] * self.size
        self.num_entries = 0

    def _hash(self, key):
        return hash(key) % self.size

    def _next_prime(self, n):
        def is_prime(x):
            if x < 2:
                return False
            for i in range(2, int(math.sqrt(x)) + 1):
                if x % i == 0:
                    return False
            return True

        prime_candidate = n
        while not is_prime(prime_candidate):
            prime_candidate += 1
        return prime_candidate

    def _resize(self):
        new_size = self._next_prime(2 * self.size)
        new_table = [None] * new_size
        for entry in self.table:
            if entry is not None:
                key, value = entry
                new_index = self._hash(key)
                while new_table[new_index] is not None:
                    new_index = (new_index + 1) % new_size
                new_table[new_index] = (key, value)
        self.table = new_table
        self.size = new_size

    def insert(self, key, value):
        if self.num_entries / self.size >= 0.4:
            self._resize()
        index = self._hash(key)
        while self.table[index] is not None and self.table[index][0] != key:
            index = (index + 1) % self.size
        self.table[index] = (key, value)
        self.num_entries += 1

    def get(self, key):
        index = self._hash(key)
        while self.table[index] is not None:
            if self.table[index][0] == key:
                return self.table[index][1]
            index = (index + 1) % self.size
        raise KeyError(f"Key '{key}' not found")

    def delete(self, key):
        index = self._hash(key)
        while self.table[index] is not None:
            if self.table[index][0] == key:
                self.table[index] = None
                self.num_entries -= 1
                return
            index = (index + 1) % self.size
        raise KeyError(f"Key '{key}' not found")

# Example usage
ht = HashTable()
ht.insert('a', 1)
ht.insert('b', 2)
ht.insert('c', 3)
print(ht.get('a'))  # Output: 1
ht.delete('b')
print(ht.get('c'))  # Output: 3

class GoBoard:
    def __init__(self, size=19):
        self.size = size
        self.board = [[None for _ in range(size)] for _ in range(size)]
        self.current_player = 'B'  # 'B' for black, 'W' for white

    def print_board(self):
        for row in self.board:
            print(' '.join('.' if cell is None else cell for cell in row))
        print()

    def place_stone(self, row, col):
        if self.board[row][col] is not None:
            print("Position already occupied.")
            return False
        self.board[row][col] = self.current_player
        self.current_player = 'W' if self.current_player == 'B' else 'B'
        return True

    def is_valid_move(self, row, col):
        if row < 0 or row >= self.size or col < 0 or col >= self.size:
            return False
        if self.board[row][col] is not None:
            return False
        return True

    def game_over(self):
        # Simple check: if all positions are occupied
        for row in self.board:
            for cell in row:
                if cell is None:
                    return False
        return True

    def play(self):
        print("Welcome to Go!")
        self.print_board()
        while not self.game_over():
            row = int(input(f"Player {self.current_player}, enter row: "))
            col = int(input(f"Player {self.current_player}, enter column: "))
            if self.is_valid_move(row, col):
                self.place_stone(row, col)
                self.print_board()
            else:
                print("Invalid move, try again.")

        print("Game Over! The board is full.")

if __name__ == "__main__":
    game = GoBoard()
    game.play()

import threading
import time
from abc import ABC, abstractmethod

# Abstract class for ASCII art generation
class ASCIIArtGenerator(ABC):
    @abstractmethod
    def generate_art(self, text: str) -> str:
        pass

# Concrete class for generating ASCII art
class HelloWorldASCIIArtGenerator(ASCIIArtGenerator):
    def generate_art(self, text: str) -> str:
        if text.lower() != "hello world":
            raise ValueError("Only 'hello world' is supported for ASCII art generation.")
        return r"""
 _   _      _ _        __        __         _     _ 
| | | | ___| | | ___   \ \      / /__  _ __| |__ | |
| |_| |/ _ \ | |/ _ \   \ \ /\ / / _ \| '__| '_ \| |
|  _  |  __/ | | (_) |   \ V  V / (_) | |  | |_) | |
|_| |_|\___|_|_|\___( )   \_/\_/ \___/|_|  |_.__/|_|
                    |/                              
"""

# Abstract class for displaying ASCII art
class DisplayManager(ABC):
    @abstractmethod
    def display_art(self, art: str) -> None:
        pass

# Concrete class for displaying ASCII art
class ConsoleDisplayManager(DisplayManager):
    def display_art(self, art: str) -> None:
        print(art)

# Exception handler class
class ExceptionHandler:
    @staticmethod
    def handle_exception(e: Exception) -> None:
        print(f"An error occurred: {e}")

# Main controller class
class MainController:
    def __init__(self, generator: ASCIIArtGenerator, display: DisplayManager, exception_handler: ExceptionHandler):
        self.generator = generator
        self.display = display
        self.exception_handler = exception_handler
        self.lock = threading.Lock()

    def generate_and_display_art(self, text: str) -> None:
        try:
            with self.lock:
                art = self.generator.generate_art(text)
                self.display.display_art(art)
        except Exception as e:
            self.exception_handler.handle_exception(e)

    def run(self, text: str) -> None:
        thread = threading.Thread(target=self.generate_and_display_art, args=(text,))
        thread.start()
        thread.join()

# Example usage
if __name__ == "__main__":
    generator = HelloWorldASCIIArtGenerator()
    display = ConsoleDisplayManager()
    exception_handler = ExceptionHandler()
    controller = MainController(generator, display, exception_handler)

    # Simulate multiple threads
    texts = ["hello world", "hello world", "hello world"]
    threads = []

    for text in texts:
        thread = threading.Thread(target=controller.run, args=(text,))
        threads.append(thread)
        thread.start()
        time.sleep(0.1)  # Introduce a small delay to simulate concurrent execution

    for thread in threads:
        thread.join()

import sys
import csv
from sympy import isprime

def is_prime(n):
    """Check if a number is prime."""
    return isprime(n)

def get_primes(n):
    """Return a list of prime numbers less than or equal to n."""
    return [num for num in range(2, n + 1) if is_prime(num)]

def convert_to_binary(num):
    """Convert a number to binary format."""
    return bin(num)[2:]

def print_table(primes, format_func, file=None):
    """Print the multiplication table in the specified format."""
    # Create the header row
    header = [''] + [format_func(p) for p in primes]
    rows = [header]

    # Create the rows for the table
    for p1 in primes:
        row = [format_func(p1)] + [format_func(p1 * p2) for p2 in primes]
        rows.append(row)

    # Print or write to file
    if file:
        with open(file, 'w', newline='') as csvfile:
            writer = csv.writer(csvfile)
            writer.writerows(rows)
    else:
        for row in rows:
            print(', '.join(row))

def parse_input(input_str):
    """Parse the input string to determine if it's decimal or hexadecimal."""
    try:
        return int(input_str, 10)
    except ValueError:
        return int(input_str, 16)

def main():
    # Parse command-line arguments
    if len(sys.argv) < 4:
        print("Usage: python script.py <decimal/hex> <decimal/binary> <number1> [number2] ... [output_file]")
        sys.exit(1)

    input_format = sys.argv[1].lower()
    output_format = sys.argv[2].lower()
    numbers = [parse_input(num) for num in sys.argv[3:-1]]
    output_file = sys.argv[-1] if len(sys.argv) > 4 else None

    if input_format not in ['decimal', 'hex']:
        print("Input format must be 'decimal' or 'hex'.")
        sys.exit(1)

    if output_format not in ['decimal', 'binary']:
        print("Output format must be 'decimal' or 'binary'.")
        sys.exit(1)

    format_func = str if output_format == 'decimal' else convert_to_binary

    for number in numbers:
        primes = get_primes(number)
        print(f"Multiplication table for prime numbers <= {number} in {output_format} format:")
        print_table(primes, format_func, output_file)

if __name__ == "__main__":
    main()

