from datetime import datetime

def is_leap_year(year):
    return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)

def convert_date(date_str):
    try:
        date = datetime.strptime(date_str, '%m/%d/%Y')
        year = date.year
        if not is_leap_year(year):
            return f"Error: The year {year} is not a leap year. Date cannot be converted."

        converted_date_str = date.strftime('%d-%m-%Y')
        day_of_week = date.strftime('%A')

        return {
            'numerical_format': converted_date_str,
            'textual_format': date.strftime('%d %B %Y'),
            'day_of_week': day_of_week
        }
    except ValueError:
        return "Error: Invalid date format. Please use mm/dd/yyyy format."

