import json

def validate_and_parse(json_data):
    if isinstance(json_data, dict):
        # Validate and transform the root dictionary
        if 'name' in json_data:
            name = json_data['name']
            if not (isinstance(name, str) and len(name) >= 3 and name.isalpha()):
                raise ValueError("Invalid 'name' value. It should be a string of at least 3 alphabetic characters.")

        if 'age' in json_data:
            age = json_data['age']
            if not (isinstance(age, int) and 18 <= age <= 99):
                raise ValueError("Invalid 'age' value. It should be an integer between 18 and 99 (inclusive).")

        # Validate nested objects
        for key, value in json_data.items():
            if isinstance(value, dict):
                if key == 'address':
                    if not (isinstance(value, str) and value.strip()):
                        raise ValueError("Invalid 'address' value. It should be a non-empty string.")
                validate_and_parse(value)
            elif isinstance(value, list):
                if key == 'hobbies':
                    if not (isinstance(value, list) and all(isinstance(hobby, str) for hobby in value) and value):
                        raise ValueError("Invalid 'hobbies' value. It should be a non-empty list of strings.")
                for item in value:
                    validate_and_parse(item)

    elif isinstance(json_data, list):
        for item in json_data:
            validate_and_parse(item)

    return json_data

