def advanced_median(l: list, cmp_func: callable):
    """
    Return median of elements in the list l without sorting it and handles mixed datatypes.
    Handles tuples with variable sizes, duplicates, and uses cmp_func for comparisons.
    """
    def partition(arr, low, high):
        pivot = arr[high]
        i = low - 1
        for j in range(low, high):
            if cmp_func(arr[j], pivot) < 0:
                i += 1
                arr[i], arr[j] = arr[j], arr[i]
        arr[i + 1], arr[high] = arr[high], arr[i + 1]
        return i + 1

    def quickselect(arr, k, low, high):
        if low == high:
            return arr[low]

        pi = partition(arr, low, high)

        if k == pi:
            return arr[k]
        elif k < pi:
            return quickselect(arr, k, low, pi - 1)
        else:
            return quickselect(arr, k, pi + 1, high)

    def is_comparable(a, b):
        try:
            cmp_func(a, b)
            return True
        except TypeError:
            return False

    # Filter out incomparable elements
    filtered_list = [x for i, x in enumerate(l) if all(is_comparable(x, y) for y in l if i != l.index(y))]

    if not filtered_list:
        return None

    n = len(filtered_list)
    if n % 2 == 1:
        return quickselect(filtered_list, n // 2, 0, n - 1)
    else:
        left_median = quickselect(filtered_list, n // 2 - 1, 0, n - 1)
        right_median = quickselect(filtered_list, n // 2, 0, n - 1)
        return (left_median + right_median) / 2

# Examples
print(advanced_median([3, 1, 2, 4, 5], lambda a, b: a - b))  # => 3
print(advanced_median([-10, 4, 6, 1000, 10, 20], lambda a, b: a - b))  # => 15.0
print(advanced_median([1, 2, 2, 4, 5], lambda a, b: a - b))  # => 2
print(advanced_median(['a', 'b', 1, 2], lambda a, b: a - b))  # => None

import requests
from bs4 import BeautifulSoup, Tag
import networkx as nx
import matplotlib.pyplot as plt

def fetch_html(url):
    try:
        response = requests.get(url)
        response.raise_for_status()
        return response.text
    except requests.RequestException as e:
        print(f"Error fetching URL: {e}")
        return None

def parse_html(html):
    return BeautifulSoup(html, 'html.parser')

def filter_divs(soup, keywords):
    def contains_keyword(element, keywords):
        if isinstance(element, Tag):
            # Check content
            if element.string and any(keyword in element.string for keyword in keywords):
                return True
            # Check attributes
            for attr, value in element.attrs.items():
                if isinstance(value, str) and any(keyword in value for keyword in keywords):
                    return True
            # Check nested elements
            for child in element.children:
                if contains_keyword(child, keywords):
                    return True
        return False

    divs = soup.find_all('div')
    filtered_divs = [div for div in divs if contains_keyword(div, keywords)]
    return filtered_divs

def build_tree(div, parent=None, tree=None):
    if tree is None:
        tree = nx.DiGraph()
        tree.add_node(div, label=div.get('id', div.get('class', 'div')))
        parent = div
    for child in div.children:
        if isinstance(child, Tag):
            tree.add_node(child, label=child.get('id', child.get('class', 'div')))
            tree.add_edge(parent, child)
            build_tree(child, child, tree)
    return tree

def visualize_tree(tree):
    plt.figure(figsize=(12, 8))
    pos = nx.drawing.nx_agraph.graphviz_layout(tree, prog='dot')
    labels = {node: data['label'] for node, data in tree.nodes(data=True)}
    nx.draw(tree, pos, with_labels=True, labels=labels, node_size=3000, node_color='lightblue', font_size=10, font_weight='bold')
    plt.title("Hierarchical Structure of Filtered Div Elements")
    plt.show()

def main(url, keywords):
    html = fetch_html(url)
    if html:
        soup = parse_html(html)
        filtered_divs = filter_divs(soup, keywords)
        if filtered_divs:
            tree = build_tree(filtered_divs[0])
            visualize_tree(tree)
        else:
            print("No div elements found with the specified keywords.")

