import re

def is_palindrome(sentence):
    # Remove all non-alphanumeric characters and convert to lowercase
    cleaned_sentence = re.sub(r'[^a-zA-Z0-9]', '', sentence).lower()
    return cleaned_sentence == cleaned_sentence[::-1]

def sum_of_ascii(sentence):
    return sum(ord(char) for char in sentence)

def process_sentences(sentences):
    results = {}
    for sentence in sentences:
        palindrome = is_palindrome(sentence)
        result = 'yes' if palindrome else 'no'
        if palindrome:
            ascii_sum = sum_of_ascii(sentence)
        else:
            ascii_sum = None
        results[sentence] = (result, ascii_sum)
    return results

