class CSVTable:
    def __init__(self, data):
        self.data = self._parse_data(data)
        self.headers = ['name', 'age', 'city']

    def _parse_data(self, data):
        entries = []
        for entry in data.split(';'):
            parts = entry.split(',')
            if len(parts) == 3 and all(part.strip() for part in parts):
                entries.append(parts)
            elif len(parts) > 1 and any(part.strip() for part in parts):
                # Handle incomplete entries
                entry_dict = {self.headers[i]: parts[i] if i < len(parts) else '' for i in range(3)}
                entries.append([entry_dict[header] for header in self.headers])
        return entries

    def display_table(self):
        print(f"{self.headers[0]:<10} | {self.headers[1]:<5} | {self.headers[2]:<15}")
        print("-" * 35)
