from abc import ABC, abstractmethod
from typing import List

class Node(ABC):
    @abstractmethod
    def evaluate(self) -> int:
        pass

    @abstractmethod
    def print(self) -> str:
        pass

class OperandNode(Node):
    def __init__(self, value: int):
        self.value = value

    def evaluate(self) -> int:
        return self.value

    def print(self) -> str:
        return str(self.value)

class OperatorNode(Node):
    def __init__(self, operator: str, left: Node, right: Node):
        self.operator = operator
        self.left = left
        self.right = right

    def evaluate(self) -> int:
        if self.operator == '+':
            return self.left.evaluate() + self.right.evaluate()
        elif self.operator == '-':
            return self.left.evaluate() - self.right.evaluate()
        elif self.operator == '*':
            return self.left.evaluate() * self.right.evaluate()
        elif self.operator == '/':
            return self.left.evaluate() // self.right.evaluate()

    def print(self) -> str:
        left_str = self.left.print()
        right_str = self.right.print()
        return f"({left_str} {self.operator} {right_str})"

def build_expression_tree(postfix: List[str]) -> Node:
    stack = []
    for token in postfix:
        if token.isdigit():
            stack.append(OperandNode(int(token)))
        else:
            right = stack.pop()
            left = stack.pop()
            stack.append(OperatorNode(token, left, right))
    return stack[0]

def solve(postfix: List[str]) -> (int, str):
    tree = build_expression_tree(postfix)
    result = tree.evaluate()
    expression = tree.print()
    return result, expression

# Example usage:
postfix1 = ["3", "4", "+", "2", "*", "7", "/"]
print(solve(postfix1))  # Output: (2, "(3 + 4) * 2 / 7")

postfix2 = ["4", "5", "7", "2", "+", "-", "*"]
print(solve(postfix2))  # Output: (-16, "4 * (5 - (7 + 2))")

postfix3 = ["4", "2", "+", "3", "5", "1", "-", "*", "+"]
print(solve(postfix3))  # Output: (18, "4 + 2 * (3 - (5 - 1))")

postfix4 = ["100", "200", "+", "2", "/", "5", "*", "7", "+"]
print(solve(postfix4))  # Output: (757, "((100 + 200) / 2) * 5 + 7")

def initialize_board():
    return [[0 for _ in range(3)] for _ in range(3)]

def print_board(board):
    for row in board:
        print(" ".join(["X" if cell == 1 else "O" if cell == 2 else "." for cell in row]))

def is_valid_move(board, row, col):
    return board[row][col] == 0

def make_move(board, row, col, player):
    if is_valid_move(board, row, col):
        board[row][col] = player
        return True
    return False

def check_win(board, player):
    # Check rows, columns, and diagonals
    for i in range(3):
        if all(board[i][j] == player for j in range(3)) or all(board[j][i] == player for j in range(3)):
            return True
    if all(board[i][i] == player for i in range(3)) or all(board[i][2-i] == player for i in range(3)):
        return True
    return False

def is_board_full(board):
    return all(cell != 0 for row in board for cell in row)

def play_game():
    board = initialize_board()
    current_player = 1

    while True:
        print_board(board)
        row = int(input(f"Player {current_player}, enter row (0-2): "))
        col = int(input(f"Player {current_player}, enter column (0-2): "))

        if make_move(board, row, col, current_player):
            if check_win(board, current_player):
                print_board(board)
                print(f"Player {current_player} wins!")
                break
            elif is_board_full(board):
                print_board(board)
                print("It's a draw!")
                break
            current_player = 3 - current_player  # Switch player (1 -> 2, 2 -> 1)
        else:
            print("Invalid move. Try again.")

play_game()

import threading
from concurrent.futures import ThreadPoolExecutor

# Dictionary to store computed heptagonal numbers
heptagonal_cache = {0: 0}

def heptagonal(n):
    if n in heptagonal_cache:
        return heptagonal_cache[n]
    heptagonal_cache[n] = (5 * n * n - 3 * n) // 2
    return heptagonal_cache[n]

def compute_heptagonal(n):
    if not isinstance(n, int) or n < 1:
        raise ValueError("Input must be a positive integer.")
    return heptagonal(n)

def compute_sequence(n):
    if not isinstance(n, int) or n < 1:
        raise ValueError("Input must be a positive integer.")
    return [heptagonal(i) for i in range(1, n + 1)]

def compute_cumulative_sum(n):
    sequence = compute_sequence(n)
    return sum(sequence)

def compute_product(n):
    sequence = compute_sequence(n)
    product = 1
    for num in sequence:
        product *= num
    return product

def compute_range(start, end):
    if not (isinstance(start, int) and isinstance(end, int) and start >= 1 and end >= start):
        raise ValueError("Range inputs must be positive integers and start <= end.")
    return [heptagonal(i) for i in range(start, end + 1)]

def compute_array(inputs):
    if not all(isinstance(x, (int, list, tuple)) for x in inputs):
        raise ValueError("Array inputs must be integers or ranges (lists/tuples).")

    results = []
    with ThreadPoolExecutor() as executor:
        for input in inputs:
            if isinstance(input, int):
                results.append(executor.submit(compute_heptagonal, input))
            elif isinstance(input, (list, tuple)) and len(input) == 2:
                results.append(executor.submit(compute_range, *input))
            else:
                raise ValueError("Invalid input type in array.")

    return [result.result() for result in results]

# Example usage
try:
    n = 10
    print(f"Heptagonal number at position {n}: {compute_heptagonal(n)}")
    print(f"Heptagonal sequence up to {n}: {compute_sequence(n)}")
    print(f"Cumulative sum up to {n}: {compute_cumulative_sum(n)}")
    print(f"Product up to {n}: {compute_product(n)}")
    print(f"Heptagonal numbers from 5 to 10: {compute_range(5, 10)}")
    print(f"Compute multiple inputs: {compute_array([5, (10, 15), 20])}")
except ValueError as e:
    print(e)

import unittest
from threading import Thread, Event
import time
from your_module import KitchenTimer

class TestKitchenTimer(unittest.TestCase):

    def test_race_condition_start_stop(self):
        timer = KitchenTimer()
        stop_event = Event()

        def start_timer():
            try:
                timer.start(1, lambda: stop_event.set())
            except AlreadyRunningError:
                pass

        def stop_timer():
            time.sleep(0.5)  # Wait for the timer to start
            try:
                timer.stop()
            except NotRunningError:
                pass

        start_thread = Thread(target=start_timer)
        stop_thread = Thread(target=stop_timer)

        start_thread.start()
        stop_thread.start()

        start_thread.join()
        stop_thread.join()

        self.assertFalse(timer.isRunning())
        self.assertTrue(stop_event.is_set())

    def test_race_condition_time_remaining(self):
        timer = KitchenTimer()
        timer.start(1)

        def check_time_remaining():
            for _ in range(100):
                time.sleep(0.01)
                remaining = timer.timeRemaining
                self.assertGreaterEqual(remaining, 0)
                self.assertLessEqual(remaining, 1)

        threads = [Thread(target=check_time_remaining) for _ in range(10)]

        for thread in threads:
            thread.start()

        for thread in threads:
            thread.join()

