def get_evens_primes_and_merge(l1: list, l2: list):
    """Return only even and prime numbers from both lists, merged and sorted in descending order.

    Implement a helper function to detect prime numbers.
    """

    def is_prime(num: int) -> bool:
        """Check if a number is a prime number."""
        if num <= 1:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        for i in range(3, int(num**0.5) + 1, 2):
            if num % i == 0:
                return False
        return True

    def merge_and_sort(m: list, n: list) -> list:
        """Merge and sort two lists in descending order."""
        merged_list = m + n
        merged_list.sort(reverse=True)
        return merged_list

    even_and_prime_numbers = []
    for num in l1 + l2:
        if num >= 0 and (num % 2 == 0 or is_prime(num)):
            even_and_prime_numbers.append(num)

    return merge_and_sort(even_and_prime_numbers, [])

