import threading
import time
import uuid

class TimerManager:
    def __init__(self):
        self.timers = {}
        self.lock = threading.Lock()

    def start_timer(self, duration, callback=None):
        if not isinstance(duration, int) or duration <= 0:
            raise ValueError("Duration must be a positive integer greater than 0")

        timer_id = str(uuid.uuid4())
        timer = Timer(duration, callback, self._on_timer_expired, timer_id)
        timer.start()

        with self.lock:
            self.timers[timer_id] = timer

        return timer_id

    def _on_timer_expired(self, timer_id):
        with self.lock:
            if timer_id in self.timers:
                del self.timers[timer_id]
                timer = self.timers.pop(timer_id, None)
                if timer and timer.callback:
                    timer.callback()

    def pause_timer(self, timer_id):
        with self.lock:
            timer = self.timers.get(timer_id)
            if timer:
                timer.pause()

    def resume_timer(self, timer_id):
        with self.lock:
            timer = self.timers.get(timer_id)
            if timer:
                timer.resume()

    def cancel_timer(self, timer_id):
        with self.lock:
            timer = self.timers.pop(timer_id, None)
            if timer:
                timer.cancel()

class Timer:
    def __init__(self, duration, callback, on_expired, timer_id):
        self.duration = duration
        self.callback = callback
        self.on_expired = on_expired
        self.timer_id = timer_id
        self.thread = None
        self.running = False
        self.paused = False
        self.remaining_time = duration

    def start(self):
        if not self.running:
            self.running = True
            self.thread = threading.Thread(target=self._run)
            self.thread.start()

    def _run(self):
        start_time = time.time()
        while self.remaining_time > 0 and not self.paused:
            elapsed_time = time.time() - start_time
            self.remaining_time = max(0, self.duration - elapsed_time)
            time.sleep(0.1)  # Small sleep to reduce CPU usage

        if self.remaining_time == 0:
            self.on_expired(self.timer_id)

    def pause(self):
        if self.running and not self.paused:
            self.paused = True

    def resume(self):
        if self.running and self.paused:
            self.paused = False
            self.thread = threading.Thread(target=self._run)
            self.thread.start()

    def cancel(self):
        self.running = False
        self.paused = False
        if self.thread and self.thread.is_alive():
            self.thread.join()

