def hanoi(n, source, auxiliary, target, step=1):
    if n == 1:
        print(f"Step {step}: Move disk 1 from {source} to {target}")
        return 1
    else:
        step = hanoi(n - 1, source, target, auxiliary, step)
        print(f"Step {step + 1}: Move disk {n} from {source} to {target}")
        step += 1
        step = hanoi(n - 1, auxiliary, source, target, step + 1)
        return step

def solve_tower_of_hanoi(n):
