def code_review(file_path: str) -> dict:
    """
    Perform a basic code review on the given file.
    """
    issues = []
    with open(file_path, 'r') as file:
        lines = file.readlines()
        for i, line in enumerate(lines, start=1):
            if len(line.strip()) > 80:
                issues.append(f"Line {i}: Line length exceeds 80 characters")
            if 'print(' in line:
                issues.append(f"Line {i}: Use logging instead of print for debugging")
    return {'file': file_path, 'issues': issues}

