from sklearn.feature_extraction.text import TfidfVectorizer
from sklearn.metrics.pairwise import cosine_similarity
import numpy as np

def preprocess_text(text):
    # Tokenization, normalization, stop words removal, and stemming can be added here
    return text.lower()

def calculate_similarity(text1, text2):
    vectorizer = TfidfVectorizer()
    tfidf_matrix = vectorizer.fit_transform([text1, text2])
    similarity_score = cosine_similarity(tfidf_matrix[0:1], tfidf_matrix[1:2])
    return similarity_score[0][0]

def check_plagiarism(text, reference_texts, threshold=0.8):
    text = preprocess_text(text)
    for ref_text in reference_texts:
        ref_text = preprocess_text(ref_text)
        similarity = calculate_similarity(text, ref_text)
        if similarity > threshold:
            return True, similarity
    return False, 0

