def GetFolderSize(path):
    TotalSize = 0
    for entry in os.scandir(path):
        if entry.is_file():
            try:
                TotalSize += entry.stat().st_size
            except OSError:
                print("error with file: " + entry.path)
        elif entry.is_dir():
            TotalSize += GetFolderSize(entry.path)
    return TotalSize

