class MaxKey(object):
    """MongoDB internal MaxKey type."""
    __slots__ = ()
    _type_marker = 127
    def __getstate__(self):
        return {}
    def __setstate__(self, state):
        pass
    def __eq__(self, other):
        return isinstance(other, MaxKey)
    def __hash__(self):
        return hash(self._type_marker)
    def __ne__(self, other):
        return not self == other
    def __le__(self, other):
        return isinstance(other, MaxKey)
    def __lt__(self, dummy):
        return False
    def __ge__(self, dummy):
        return True
    def __gt__(self, other):
        return not isinstance(other, MaxKey)
    def __repr__(self):
        return "MaxKey()"

import binascii
import hashlib
import hmac
import sys
from common.cmp.cloud_apis.resource_apis.tcecloud.common.exception.tce_cloud_sdk_exception import TceCloudSDKException
class Sign(object):
    @staticmethod
    def sign(secretKey, signStr, signMethod):
        if sys.version_info[0] > 2:
            signStr = bytes(signStr, "utf-8")
            secretKey = bytes(secretKey, "utf-8")
        digestmod = None
        if signMethod == "HmacSHA256":
            digestmod = hashlib.sha256
        elif signMethod == "HmacSHA1":
            digestmod = hashlib.sha1
        else:
            raise TceCloudSDKException("signMethod invalid", "signMethod only support (HmacSHA1, HmacSHA256)")
        hashed = hmac.new(secretKey, signStr, digestmod)
        base64 = binascii.b2a_base64(hashed.digest())[:-1]
        if sys.version_info[0] > 2:
            base64 = base64.decode()
        return base64
    @staticmethod
    def sign_tc3(secret_key, date, service, str2sign):
        def _hmac_sha256(key, msg):
            return hmac.new(key, msg.encode("utf-8"), hashlib.sha256)
        def _get_signature_key(key, date, service):
            k_date = _hmac_sha256(("TC3" + key).encode("utf-8"), date)
            k_service = _hmac_sha256(k_date.digest(), service)
            k_signing = _hmac_sha256(k_service.digest(), "tc3_request")
            return k_signing.digest()
        signing_key = _get_signature_key(secret_key, date, service)
        signature = _hmac_sha256(signing_key, str2sign).hexdigest()
        return signature

from django.http import JsonResponse, FileResponse
from rest_framework import status
class WebUtils:
    @staticmethod
    def response_success(response_data={}, message=""):
        return JsonResponse({"data": response_data, "result": True, "message": message}, status=status.HTTP_200_OK)
    @staticmethod
    def response_error(response_data={}, error_message="", status_code=status.HTTP_400_BAD_REQUEST):
        return JsonResponse({"data": response_data, "result": False, "message": error_message}, status=status_code)
    @staticmethod
    def response_401(message):
        return JsonResponse({"result": False, "message": message}, status=status.HTTP_401_UNAUTHORIZED)
    @staticmethod
    def response_403(message):
        return JsonResponse({"result": False, "message": message}, status=status.HTTP_403_FORBIDDEN)
    @staticmethod
    def response_file(file, filename):
        if isinstance(file, bytes):
            file = io.BytesIO(file)
        response = FileResponse(file, content_type="application/octet-stream")
        response['Content-Disposition'] = f'attachment; filename="{filename}"'
