from enum import Enum, auto
from itertools import count
from ..layers.sampler import SamplingParams
class SequenceStatus(Enum):
    WAITING = auto()
    RUNNING = auto()
    FINISHED = auto()
class Sequence:
    block_size = 256
    counter = count()
    def __init__(self, token_ids: list[int], sampling_params = SamplingParams()):
        self.seq_id = next(Sequence.counter)
        self.status = SequenceStatus.WAITING
        self.token_ids = copy(token_ids)
        self.last_token = token_ids[-1]
        self.num_tokens = len(self.token_ids)
        self.num_prompt_tokens = len(token_ids)
        self.num_cached_tokens = 0
        self.block_table = []
        self.temperature = sampling_params.temperature
        self.max_tokens = sampling_params.max_tokens
        self.ignore_eos = sampling_params.ignore_eos
        self.pre_verify = True
        self.num_acc_tokens = []
        self.cur_acc_tokens = 0
    def __len__(self):
        return self.num_tokens
    def __getitem__(self, key):
        return self.token_ids[key]
    @property
    def is_finished(self):
        return self.status == SequenceStatus.FINISHED
    @property
    def num_completion_tokens(self):
        return self.num_tokens - self.num_prompt_tokens
    @property
    def prompt_token_ids(self):
        return self.token_ids[:self.num_prompt_tokens]
    @property
    def completion_token_ids(self):
        return self.token_ids[self.num_prompt_tokens:]
    @property
    def num_cached_blocks(self):
        return self.num_cached_tokens // self.block_size
    @property
    def num_blocks(self):
        return (self.num_tokens + self.block_size - 1) // self.block_size
    @property
    def last_block_num_tokens(self):
        return self.num_tokens - (self.num_blocks - 1) * self.block_size
    def block(self, i):
        assert 0 <= i < self.num_blocks
        return self.token_ids[i*self.block_size: (i+1)*self.block_size]
    def append_token(self, token_id: int):
        self.token_ids.append(token_id)
        self.last_token = token_id
        self.num_tokens += 1
    # PEARL KV cache Rollback
    def rollback_tokens(self, n: int):
        assert n > 0
        self.token_ids = self.token_ids[:-n]
        self.last_token = self.token_ids[-1]
        self.num_tokens -= n
    def token_to_slot(self, token_index: int):
        block_id = token_index // self.block_size
        block_offset = token_index % self.block_size
        slot = self.block_table[block_id] * self.block_size + block_offset
        return slot
    def __getstate__(self):
        return (self.num_tokens, self.num_prompt_tokens, self.num_cached_tokens, self.block_table,
                self.temperature, self.ignore_eos, self.max_tokens, self.seq_id, self.pre_verify, 
                self.num_acc_tokens, self.cur_acc_tokens,
                self.token_ids if self.num_completion_tokens == 0 else self.last_token)
    def __setstate__(self, state):
        self.num_tokens, self.num_prompt_tokens, self.num_cached_tokens, self.block_table, self.temperature, self.ignore_eos, self.max_tokens, self.seq_id, self.pre_verify, self.num_acc_tokens, self.cur_acc_tokens = state[:-1]
        if self.num_completion_tokens == 0:
            self.token_ids = state[-1]
        else:
            self.last_token = state[-1]

import ast
from skylos.rules.quality.unreachable import UnreachableCodeRule
class TestUnreachableCodeRule(unittest.TestCase):
    def setUp(self):
        self.rule = UnreachableCodeRule()
        self.context = {"filename": "test_sample.py"}
    def _analyze(self, source_code):
        """
        parse code and run the rule on the first function definition found
        """
        tree = ast.parse(source_code)
        for node in ast.walk(tree):
            if isinstance(node, ast.FunctionDef):
                return self.rule.visit_node(node, self.context) or []
            if isinstance(node, (ast.For, ast.While)):
                return self.rule.visit_node(node, self.context) or []
        return []
    def test_no_issues_clean_code(self):
        code = """
def clean_function():
    x = 1
    y = 2
    return x + y
"""
        findings = self._analyze(code)
        self.assertEqual(len(findings), 0, "Should not flag valid code.")
    def test_simple_return_unreachable(self):
        code = """
def dead_code():
    return True
    print("unreachable")
"""
        findings = self._analyze(code)
        self.assertEqual(len(findings), 1)
        self.assertEqual(findings[0]["line"], 4)
        self.assertIn("follows a return", findings[0]["message"])
    def test_raise_unreachable(self):
        code = """
def error_func():
    raise ValueError("Stop")
    x = 100  # Unreachable
"""
        findings = self._analyze(code)
        self.assertEqual(len(findings), 1)
        self.assertEqual(findings[0]["line"], 4)
    def test_break_in_loop(self):
        code = """
def loop_func():
    for i in range(10):
        if i > 5:
            break
            print("unreachable")     
"""
        tree = ast.parse(code)
        if_node = tree.body[0].body[0].body[0]
        findings = self.rule.visit_node(if_node, self.context)
        self.assertIsNotNone(findings)
        self.assertEqual(len(findings), 1)
        self.assertEqual(findings[0]["line"], 6)
    def test_continue_unreachable(self):
        code = """
def loop_func():
    for i in range(10):
        continue
        print("unreachable")
"""
        tree = ast.parse(code)
        for_node = tree.body[0].body[0]
        findings = self.rule.visit_node(for_node, self.context)
        self.assertEqual(len(findings), 1)
        self.assertEqual(findings[0]["line"], 5)
    def test_if_else_both_return(self):
        code = """
def check_branches(x):
    if x > 0:
        return 1
    else:
        return 2

    print("unreachable")
"""
        findings = self._analyze(code)
        self.assertEqual(len(findings), 1)
        self.assertEqual(findings[0]["line"], 8)
    def test_if_else_partial_return(self):
        code = """
def check_branches(x):
    if x > 0:
        return 1
    else:
        x = 2
        # No return here

    print("Reachable!")
"""
        findings = self._analyze(code)
        self.assertEqual(len(findings), 0, "Should not flag")
    def test_if_without_else(self):
        code = """
def check_branches(x):
    if x > 0:
        return 1

    print("Reachable")
"""
        findings = self._analyze(code)
        self.assertEqual(len(findings), 0)
    def test_nested_if_else_termination(self):
        code = """
def complex_logic(x, y):
    if x:
        if y:
            return 1
        else:
            return 2
    else:
        raise ValueError("Bad")  
    print("unreachable")
"""
        findings = self._analyze(code)
        self.assertEqual(len(findings), 1)
        self.assertEqual(findings[0]["line"], 10)
    def test_flag_only_first_unreachable(self):
        code = """
def noise():
    return
    print("First unreachable line")
    print("Second unreachable line")
    x = 1 + 1
"""
        findings = self._analyze(code)
        self.assertEqual(len(findings), 1)
        self.assertEqual(findings[0]["line"], 4)
if __name__ == "__main__":
    unittest.main()

