# Function to check dictionary case consistency
def check_dict_case(dct):
    # Empty dictionary returns False
    if not dct:
        return False

    # Count lowercase and uppercase keys
    lower_case = sum([k.islower() for k in dct.keys()])
    upper_case = sum([k.isupper() for k in dct.keys()])

    # Check if all keys are lowercase
    if lower_case == len(dct):
        return all(v.islower() for v in dct.values())
    # Check if all keys are uppercase
    elif upper_case == len(dct):
        return all(v.isupper() for v in dct.values())
    # Mixed case keys - invalid
    else:
        return False

# Function to calculate median without sorting or using built-in functions
def median(l: list):
    """Return median of elements in the list l without sorting it or using built-in functions.
    Handles tuples with negative numbers.
    >>> median([3, 1, 2, 4, 5])
    3
    >>> median([-10, 4, 6, 1000, 10, 20])
    15.0
    >>> median([-5, -1, -3, -4, -2])
    -3
    >>> median([1, 2, 3, 4, 5, 6])
    3.5
    """

    # Partition function for quickselect
    def partition(arr, low, high):
        pivot = arr[high]
        i = low - 1

        for j in range(low, high):
            if arr[j] <= pivot:
                i += 1
                arr[i], arr[j] = arr[j], arr[i]

        arr[i + 1], arr[high] = arr[high], arr[i + 1]
        return i + 1

    # Quickselect function to find k-th smallest element
    def quickselect(arr, k, low, high):
        if low == high:
            return arr[low]

        pivot_index = partition(arr, low, high)

        if k == pivot_index:
            return arr[k]
        elif k < pivot_index:
            return quickselect(arr, k, low, pivot_index - 1)
        else:
            return quickselect(arr, k, pivot_index + 1, high)

    # Calculate median based on list length
    n = len(l)

    if n % 2 == 1:
        # Odd number of elements: return middle element
        return quickselect(l, n // 2, 0, n - 1)
    else:
        # Even number of elements: return average of two middle elements
        return 0.5 * (quickselect(l, n // 2 - 1, 0, n - 1) + quickselect(l, n // 2, 0, n - 1))

