    def add_parent(self, parent):
        if parent not in self.parents:
            self.parents.append(parent)
            if self not in parent.children:
                parent.children.append(self)

    # Add a spouse to the person
    def add_spouse(self, spouse):
        if self.spouse is None:
            self.spouse = spouse
            if spouse.spouse is None:
                spouse.spouse = self

    # Add a child to the person
    def add_child(self, child):
        if child not in self.children:
            self.children.append(child)
            if self not in child.parents:
                child.parents.append(self)

    # String representation of the Person object
    def __repr__(self):
        return f"Person(name={self.name}, birth_date={self.birth_date}, gender={self.gender})"

# Function to check if a number is prime
def is_prime(num):
    # Numbers less than 2 are not prime
    if num < 2:
        return False

    # Check divisibility from 2 to square root of num
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0:
            return False

    return True

# Function to get prime factors of a number
def prime_factors(num):
    factors = []

    # Find all prime factors by trial division
    for i in range(2, num + 1):
        while num % i == 0:
            factors.append(i)
            num //= i

    return factors

# Function to factorize all numbers below n with frequency count
def factorize_below_with_frequency(n):
    # For n < 2, return empty dictionary
    if n < 2:
        return {}

    # Dictionary to store factor frequencies
    factor_frequency = {}

    # Process each number from 2 to n-1
    for i in range(2, n):
        factors = prime_factors(i)

        # Update frequency count for each factor
        for factor in factors:
            if factor in factor_frequency:
                factor_frequency[factor] += 1
            else:
                factor_frequency[factor] = 1

    return factor_frequency

