from datetime import datetime
import uuid


class Employee:
    def __init__(self, name, age, salary, role, date_of_joining):
        # Generate a unique ID for each employee
        self.id = str(uuid.uuid4())
        self.name = name
        self.age = age
        self.salary = salary
        self.role = role
        self.date_of_joining = date_of_joining

    def calculate_years_of_service(self):
        today = datetime.today()
        start_date = datetime.strptime(self.date_of_joining, '%Y-%m-%d')
        service_days = (today - start_date).days
        return service_days // 365

    def __str__(self):
        return f"ID: {self.id}, Name: {self.name}, Age: {self.age}, Salary: {self.salary}, Role: {self.role}, Date of Joining: {self.date_of_joining}"


class EmployeeManagementSystem:
    def __init__(self):
        self.employees = []

    def add_employee(self, name, age, salary, role, date_of_joining):
        new_employee = Employee(name, age, salary, role, date_of_joining)
        self.employees.append(new_employee)
        print(f"Employee {name} added successfully.")

    def remove_employee(self, employee_id):
        for employee in self.employees:
            if employee.id == employee_id:
                self.employees.remove(employee)
                print(f"Employee with ID {employee_id} removed successfully.")
                return
        print(f"Employee with ID {employee_id} not found.")

    def update_employee(self, employee_id, **kwargs):
        for employee in self.employees:
            if employee.id == employee_id:
                for key, value in kwargs.items():
                    setattr(employee, key, value)
                print(f"Employee with ID {employee_id} updated successfully.")
                return
        print(f"Employee with ID {employee_id} not found.")

    def get_employee(self, employee_id):
        for employee in self.employees:
            if employee.id == employee_id:
                return employee
        print(f"Employee with ID {employee_id} not found.")
        return None

    def calculate_years_of_service(self, employee_id):
        employee = self.get_employee(employee_id)
        if employee:
            return employee.calculate_years_of_service()
        return None

    def list_employees(self):
        for employee in self.employees:
            print(employee)

    def is_management(self, employee_id):
        employee = self.get_employee(employee_id)
        if employee and employee.role.lower() == 'management':
            return True
        return False


