import math

# Function to calculate factorial of a number
def factorial(n):
    # Base case: factorial of 0 is 1
    if n == 0:
        return 1
    # Calculate product of range from 1 to n
    return math.prod(range(1, n+1))

# Import necessary modules
import ast
import os

def find_unused_functions(directory):
    # Dictionaries and sets to track function definitions and references
    function_definitions = {}
    function_references = set()

    # Walk through the directory tree
    for root, _, files in os.walk(directory):
        for file in files:
            if file.endswith('.py'):
                # Open and parse each Python file
                with open(os.path.join(root, file), 'r') as f:
                    tree = ast.parse(f.read(), filename=file)

                    # Traverse the AST to find functions and their usages
                    for node in ast.walk(tree):
                        if isinstance(node, ast.FunctionDef):
                            # Record function definition
                            function_definitions[node.name] = file
                        elif isinstance(node, ast.Name) and isinstance(node.ctx, ast.Load):
                            # Record function reference (usage)
                            function_references.add(node.id)

    # Identify unused functions
    unused_functions = {
        name: file 
        for name, file in function_definitions.items() 
        if name not in function_references
    }

    return unused_functions

# Find unused functions in the specified directory
