def load_inventory_data(table_data):
    inventory = {}

    for item in table_data:
        inventory[item['Item ID']] = {
            'Item Name': item['Item Name'],
            'Price (USD)': item['Price (USD)'],
            'Stock Level': item['Stock Level']
        }

    return inventory


def validate_inventory_data(inventory):
    item_ids = set()

    for item_id, details in inventory.items():
        if item_id in item_ids:
            raise ValueError(f"Duplicate Item ID: {item_id}")

        if details['Price (USD)'] <= 0:
            raise ValueError(f"Invalid Price for Item ID {item_id}: {details['Price (USD)']}")

        if details['Stock Level'] < 0:
            raise ValueError(f"Invalid Stock Level for Item ID {item_id}: {details['Stock Level']}")

        item_ids.add(item_id)


# Sub-Challenge 2: Process Customer Orders
def process_order(inventory, order):
    for item_id, quantity in order.items():
        if item_id not in inventory:
            raise ValueError(f"Item ID {item_id} does not exist in the inventory")

        if quantity > inventory[item_id]['Stock Level']:
            raise ValueError(f"Insufficient stock for Item ID {item_id}")

        inventory[item_id]['Stock Level'] -= quantity

    total_cost = sum(
        inventory[item_id]['Price (USD)'] * quantity 
        for item_id, quantity in order.items()
    )

    return total_cost


# Sub-Challenge 3: Generate Sales Report
def generate_sales_report(sales_data):
    total_revenue = sum(details['Total Revenue'] for details in sales_data.values())
    total_items_sold = sum(details['Quantity Sold'] for details in sales_data.values())

    top_selling_item = max(
        sales_data, 
        key=lambda k: sales_data[k]['Quantity Sold']
    )

    report = {
        'Total Revenue': total_revenue,
        'Total Items Sold': total_items_sold,
        'Top-Selling Item': sales_data[top_selling_item]['Item Name']
    }

    return report


