# Flattens a nested list
def flatten(lst):
    """Flatten a nested list."""
    for el in lst:
        if isinstance(el, list):
            yield from flatten(el)
        else:
            yield el

# Converts various types to numeric values
def convert_to_numeric(value):
    """Convert boolean, string, and other values to numeric types."""
    if isinstance(value, bool):
        return int(value)

    if isinstance(value, str):
        try:
            return int(value)
        except ValueError:
            try:
                return float(value)
            except ValueError:
                return None

    if isinstance(value, (int, float, complex)):
        return value

    return None

# Finds the minimum disparity between adjacent elements in a numeric array
def find_min_disparity(arr):
    # Flatten the array
    flat_arr = list(flatten(arr))

    # Convert and filter non-numeric elements
    numeric_arr = [convert_to_numeric(x) for x in flat_arr if convert_to_numeric(x) is not None]

    # Handle edge cases
    if len(numeric_arr) < 2:
        return "Array should contain at least two numeric elements for comparison."

    # Sort the array
    numeric_arr.sort(key=lambda x: abs(x) if isinstance(x, complex) else x)

    # Initialize minimum disparity and pair
    min_disparity = float('inf')
    min_pair = (None, None)

    # Find the minimum disparity
    for i in range(len(numeric_arr) - 1):
        current_disparity = abs(numeric_arr[i] - numeric_arr[i + 1])
        if current_disparity < min_disparity:
            min_disparity = current_disparity
            min_pair = (numeric_arr[i], numeric_arr[i + 1])

    return min_disparity, min_pair

# Unit tests
def test_find_min_disparity():
    assert find_min_disparity([1, 5, 3, 9, 2]) == (1, (1, 2))
    assert find_min_disparity([1, 1, 1, 1]) == (0, (1, 1))
    assert find_min_disparity([1, 2, 3, 4, 5]) == (1, (1, 2))
    assert find_min_disparity([1, 2, 3, 4, 5, 1.01]) == (0.01, (1, 1.01))
    assert find_min_disparity([1, 2, 3, 4, 5, 1.01, '2.01']) == (0.01, (1, 1.01))
    assert find_min_disparity([1, 2, 3, 4, 5, True, False]) == (1, (0, 1))
    assert find_min_disparity([1, 2, 3, 4, 5, None, 'a', [1, 2], 1.01]) == (0.01, (1, 1.01))
    assert find_min_disparity([1, 2, 3, 4, 5, complex(1, 1), complex(1, 2)]) == (1, (1, 1.4142135623730951))
    assert find_min_disparity([]) == "Array should contain at least two numeric elements for comparison."
    assert find_min_disparity([1]) == "Array should contain at least two numeric elements for comparison."
    assert find_min_disparity(['a', 'b', 'c']) == "Array should contain at least two numeric elements for comparison."
    assert find_min_disparity([None, None, None]) == "Array should contain at least two numeric elements for comparison."
    assert find_min_disparity([1, '2', '3.14', True, False, None, [1, 2], 1.01]) == (0.01, (1, 1.01))
    assert find_min_disparity([1, 2, 3, 4, 5, complex(1, 1), complex(1, 2), 1.01]) == (0.01, (1, 1.01))

test_find_min_disparity()
print("All tests passed.")

from typing import List
import bisect


def is_prime(n: int) -> bool:
    # Check if n is less than or equal to 1
    if n <= 1:
        return False
    # Check if n is 2 or 3
    if n <= 3:
        return True
    # Check divisibility by 2 or 3
    if n % 2 == 0 or n % 3 == 0:
        return False
    # Check for factors up to sqrt(n)
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True


def next_prime(n: int) -> int:
    # Find the next prime number greater than n
    while True:
        n += 1
        if is_prime(n):
            return n


def nearest_fibonacci(n: int) -> int:
    # Precompute Fibonacci numbers up to 100
    fibs = [0, 1]
    while fibs[-1] < 100:
        fibs.append(fibs[-1] + fibs[-2])

    # Find insertion point for n in fibs
    idx = bisect.bisect_left(fibs, n)

    # Handle edge cases
    if idx == 0:
        return fibs[0]
    if idx == len(fibs) or fibs[idx] - n > n - fibs[idx - 1]:
        return fibs[idx - 1]
    return fibs[idx]


def toggle_case(c: str) -> str:
    # Toggle case of a character
    if c.islower():
        return c.upper()
    elif c.isupper():
        return c.lower()
    return c


def modify_string(string: str) -> str:
    # Step 1: Toggle case of alphabetic characters
    toggled_string = ''.join(toggle_case(c) for c in string)

    # Step 2: Map each odd digit to its nearest Fibonacci number
    fib_mapped_string = ''
    for c in toggled_string:
        if c.isdigit() and int(c) % 2 != 0:
            fib_mapped_string += str(nearest_fibonacci(int(c)))
        else:
            fib_mapped_string += c

    # Step 3: Replicate special characters based on next prime count
    special_chars = [c for c in fib_mapped_string if not c.isalnum()]
    special_count = len(special_chars)
    next_prime_count = next_prime(special_count)

    replicated_string = ''
    for c in fib_mapped_string:
        if not c.isalnum():
            replicated_string += c * next_prime_count
        else:
            replicated_string += c

    # Step 4: Build BST and perform in-order traversal
    class TreeNode:
        def __init__(self, val=0):
            self.val = val
            self.left = None
            self.right = None

    def insert_into_bst(root: TreeNode, val: int) -> TreeNode:
        if not root:
            return TreeNode(val)
        if val < root.val:
            root.left = insert_into_bst(root.left, val)
        else:
            root.right = insert_into_bst(root.right, val)
        return root

    def in_order_traversal(root: TreeNode) -> List[int]:
        return in_order_traversal(root.left) + [root.val] + in_order_traversal(root.right) if root else []

    # Build BST from character codes
    root = None
    for c in replicated_string:
        root = insert_into_bst(root, ord(c))

    # Perform in-order traversal and convert back to string
    in_order_vals = in_order_traversal(root)
    result_string = ''.join(chr(val) for val in in_order_vals)

    return result_string


# Example usage
print(modify_string('Greet5!'))

# Import math module for mathematical operations
import math


class Vector2D:
    # Initialize the vector with x and y coordinates, rounded to 6 decimal places
    def __init__(self, x: float, y: float):
        self.x = round(x, 6)
        self.y = round(y, 6)

    # Get x-coordinate
    def get_x(self) -> float:
        return self.x

    # Get y-coordinate
    def get_y(self) -> float:
        return self.y

    # Calculate magnitude (length) of the vector
    def magnitude(self) -> float:
        return round(math.sqrt(self.x**2 + self.y**2), 6)

    # Add two vectors
    def add(self, other: 'Vector2D') -> 'Vector2D':
        return Vector2D(self.x + other.x, self.y + other.y)

    # Subtract another vector from this vector
    def subtract(self, other: 'Vector2D') -> 'Vector2D':
        return Vector2D(self.x - other.x, self.y - other.y)

    # Multiply vector by a scalar
    def multiply(self, scalar: float) -> 'Vector2D':
        return Vector2D(self.x * scalar, self.y * scalar)

    # Calculate dot product with another vector
    def dot_product(self, other: 'Vector2D') -> float:
        return round(self.x * other.x + self.y * other.y, 6)

    # Cross product in 2D returns a scalar (z-component of 3D cross product)
    def cross_product(self, other: 'Vector2D') -> float:
        return 0.0

    # Normalize the vector (make it unit length)
    def normalize(self) -> 'Vector2D':
        mag = self.magnitude()
        if mag == 0:
            return Vector2D(0, 0)
        return Vector2D(self.x / mag, self.y / mag)

    # Calculate distance to another vector (as points)
    def distance(self, other: 'Vector2D') -> float:
        return round(math.sqrt((self.x - other.x)**2 + (self.y - other.y)**2), 6)

    # Calculate angle between two vectors in degrees
    def angle(self, other: 'Vector2D') -> float:
        dot = self.dot_product(other)
        mag_self = self.magnitude()
        mag_other = other.magnitude()
        if mag_self == 0 or mag_other == 0:
            return 0.0
        cos_theta = dot / (mag_self * mag_other)
        return round(math.degrees(math.acos(cos_theta)), 6)

    # Rotate the vector by given angle (in degrees)
    def rotate(self, angle: float) -> 'Vector2D':
        rad = math.radians(angle)
        cos_theta = math.cos(rad)
        sin_theta = math.sin(rad)
        new_x = self.x * cos_theta - self.y * sin_theta
        new_y = self.x * sin_theta + self.y * cos_theta
        return Vector2D(new_x, new_y)

    # Project this vector onto another vector
    def project(self, other: 'Vector2D') -> 'Vector2D':
        dot = self.dot_product(other)
        mag_other_sq = other.magnitude() ** 2
        if mag_other_sq == 0:
            return Vector2D(0, 0)
        scalar = dot / mag_other_sq
        return other.multiply(scalar)

    # Check if two vectors are parallel
    def is_parallel(self, other: 'Vector2D') -> bool:
        return self.cross_product(other) == 0

    # Check if two vectors are orthogonal (perpendicular)
    def is_orthogonal(self, other: 'Vector2D') -> bool:
        return self.dot_product(other) == 0


# Example usage
