# Node class for BST
class Node:
    def __init__(self, key):
        self.key = key
        self.left = None
        self.right = None


# Binary Search Tree implementation
class BST:
    def __init__(self):
        self.root = None

    # Public insert method
    def insert(self, key):
        self.root = self._insert(self.root, key)

    # Recursive helper for insertion
    def _insert(self, node, key):
        if node is None:
            return Node(key)
        if key < node.key:
            node.left = self._insert(node.left, key)
        else:
            node.right = self._insert(node.right, key)
        return node

    # Public delete method
    def delete(self, key):
        self.root = self._delete(self.root, key)

    # Recursive helper for deletion
    def _delete(self, node, key):
        if node is None:
            return node
        if key < node.key:
            node.left = self._delete(node.left, key)
        elif key > node.key:
            node.right = self._delete(node.right, key)
        else:
            # Node with only one child or no child
            if node.left is None:
                return node.right
            elif node.right is None:
                return node.left
            # Node with two children: get inorder successor
            min_larger_node = self._find_min(node.right)
            node.key = min_larger_node.key
            node.right = self._delete(node.right, min_larger_node.key)
        return node

    # Public search method
    def search(self, key):
        return self._search(self.root, key)

    # Recursive helper for search
    def _search(self, node, key):
        if node is None or node.key == key:
            return node
        if key < node.key:
            return self._search(node.left, key)
        return self._search(node.right, key)

    # Find minimum value node in the tree
    def find_min(self):
        return self._find_min(self.root)

    # Helper to find minimum
    def _find_min(self, node):
        if node is None:
            return None
        while node.left is not None:
            node = node.left
        return node

    # Find maximum value node in the tree
    def find_max(self):
        return self._find_max(self.root)

    # Helper to find maximum
    def _find_max(self, node):
        if node is None:
            return None
        while node.right is not None:
            node = node.right
        return node

    # Find k-th smallest element
    def kth_smallest(self, k):
        return self._kth_smallest(self.root, k, [0])

    # Helper for k-th smallest (using list for mutable count)
    def _kth_smallest(self, node, k, count):
        if node is None:
            return None
        left = self._kth_smallest(node.left, k, count)
        if left is not None:
            return left
        count[0] += 1
        if count[0] == k:
            return node
        return self._kth_smallest(node.right, k, count)

    # Calculate height of the tree
    def height(self):
        return self._height(self.root)

    # Recursive helper for height calculation
    def _height(self, node):
        if node is None:
            return 0
        return 1 + max(self._height(node.left), self._height(node.right))

    # Check if tree is balanced
    def is_balanced(self):
        return self._is_balanced(self.root) != -1

    # Helper for balanced check (returns -1 if unbalanced)
    def _is_balanced(self, node):
        if node is None:
            return 0
        left_height = self._is_balanced(node.left)
        if left_height == -1:
            return -1
        right_height = self._is_balanced(node.right)
        if right_height == -1:
            return -1
        if abs(left_height - right_height) > 1:
            return -1
        return 1 + max(left_height, right_height)

    # Find least common ancestor of two keys
    def least_common_ancestor(self, key1, key2):
        return self._least_common_ancestor(self.root, key1, key2)

    # Helper for LCA
    def _least_common_ancestor(self, node, key1, key2):
        if node is None:
            return None
        if key1 < node.key and key2 < node.key:
            return self._least_common_ancestor(node.left, key1, key2)
        if key1 > node.key and key2 > node.key:
            return self._least_common_ancestor(node.right, key1, key2)
        return node

    # Level order traversal (BFS)
    def level_order_traversal(self):
        if self.root is None:
            return
        queue = [self.root]
        while queue:
            level = []
            for _ in range(len(queue)):
                node = queue.pop(0)
                level.append(node.key)
                if node.left:
                    queue.append(node.left)
                if node.right:
                    queue.append(node.right)
            print(level)


