class Phone:
    def __init__(self, brand, model, os, battery_capacity, screen_size):
        # Initialize phone attributes
        self.brand = brand
        self.model = model
        self.os = os
        self.battery_capacity = battery_capacity
        self.screen_size = screen_size
        self.battery_level = battery_capacity  # Initially fully charged
        self.is_powered_on = False

    def power_on(self):
        if not self.is_powered_on:
            self.is_powered_on = True
            print(f"{self.brand} {self.model} is powered on.")
        else:
            print(f"{self.brand} {self.model} is already powered on.")

    def power_off(self):
        if self.is_powered_on:
            self.is_powered_on = False
            print(f"{self.brand} {self.model} is powered off.")
        else:
            print(f"{self.brand} {self.model} is already powered off.")

    def use_battery(self, usage):
        if self.is_powered_on:
            if self.battery_level >= usage:
                self.battery_level -= usage
                print(f"Battery level: {self.battery_level} mAh")
            else:
                print("Not enough battery to perform this action.")
        else:
            print("The phone is powered off. Please power it on.")

    def charge_battery(self, amount):
        if self.battery_level + amount <= self.battery_capacity:
            self.battery_level += amount
            print(f"Battery level: {self.battery_level} mAh")
        else:
            self.battery_level = self.battery_capacity
            print("Battery is fully charged.")

# Import required module
from functools import cmp_to_key

def compare_items(x, y):
    # Custom comparison function to handle various data types
    if isinstance(x, list) and isinstance(y, list):
        return (sum(x) - sum(y))
    elif isinstance(x, dict) and isinstance(y, dict):
        return (sum(x.values()) - sum(y.values()))
    elif isinstance(x, (int, float, complex)) and isinstance(y, (int, float, complex)):
        return (x - y)
    elif isinstance(x, str) and isinstance(y, str):
        return (x > y) - (x < y)
    elif isinstance(x, (int, float, complex)) and isinstance(y, str):
        return -1
    elif isinstance(x, str) and isinstance(y, (int, float, complex)):
        return 1
    elif isinstance(x, list) and isinstance(y, (int, float, complex, str)):
        return 1
    elif isinstance(x, (int, float, complex, str)) and isinstance(y, list):
        return -1
    elif isinstance(x, dict) and isinstance(y, (int, float, complex, str, list)):
        return 1
    elif isinstance(x, (int, float, complex, str, list)) and isinstance(y, dict):
        return -1
    elif isinstance(x, tuple) and isinstance(y, tuple):
        return (x[0] - y[0])
    elif isinstance(x, tuple) and isinstance(y, (int, float, complex, str, list, dict)):
        return 1
    elif isinstance(x, (int, float, complex, str, list, dict)) and isinstance(y, tuple):
        return -1
    elif isinstance(x, set) and isinstance(y, set):
        return (len(x) - len(y))
    elif isinstance(x, set) and isinstance(y, (int, float, complex, str, list, dict, tuple)):
        return 1
    elif isinstance(x, (int, float, complex, str, list, dict, tuple)) and isinstance(y, set):
        return -1
    elif isinstance(x, frozenset) and isinstance(y, frozenset):
        return (len(x) - len(y))
    elif isinstance(x, frozenset) and isinstance(y, (int, float, complex, str, list, dict, tuple, set)):
        return 1
    elif isinstance(x, (int, float, complex, str, list, dict, tuple, set)) and isinstance(y, frozenset):
        return -1
    else:
        raise TypeError("Unsupported data types for comparison")

def shift_and_sort(lst, num):
    n = len(lst)

    # Handle empty list or no effective shift
    if n == 0 or num % n == 0:
        return lst

    # Normalize shift count
    num = num % n

    # Perform the shift
    lst = lst[num:] + lst[:num]

    # Sort the remaining part of the list
    lst[num:] = sorted(lst[num:], key=cmp_to_key(compare_items))

    return lst

