lst = [1, -3, 2.5, "apple", [1, 2], {"a": 1, "b": 2}, (1, 2), {1, 2}, frozenset([1, 2])]
shifted_sorted_lst = shift_and_sort(lst, 3)

# Print the result
print(shifted_sorted_lst)

