class ScreeningRoom:
    def __init__(self, room_number: int, seating_capacity: int):
        self.room_number = room_number
        self.seating_capacity = seating_capacity
        self.screenings: List['Screening'] = []
        # Initialize all seats as available (True)
        self.seats: Dict[str, bool] = {f'Seat_{i}': True for i in range(1, seating_capacity + 1)}

    def add_screening(self, screening: 'Screening'):
        self.screenings.append(screening)

    def get_screenings(self) -> List['Screening']:
        return self.screenings

    def get_available_seats(self, screening: 'Screening') -> List[str]:
        return [seat for seat, available in self.seats.items() if available]


