import itertools
import math
from typing import List, Tuple

def generate_expression(numbers: List[int], target: int, allow_duplicates: bool) -> Tuple[str, int]:
    def evaluate_expression(expr: str) -> float:
        try:
            return eval(expr)
        except ZeroDivisionError:
            return float('inf')
        except Exception:
            return float('nan')

    def is_valid_expression(expr: str) -> bool:
        try:
            eval(expr)
            return True
        except:
            return False

    def generate_expressions(nums: List[int], target: int, max_steps: int) -> Tuple[str, int]:
        if not nums:
            return "", -1

        # Generate all permutations of the numbers
        permutations = list(itertools.permutations(nums))
        if not allow_duplicates:
            permutations = list(set(permutations))

        # Generate all possible combinations of operations
        operations = ['+', '-', '*', '/', '**', 'math.log']

        for perm in permutations:
            for steps in range(1, max_steps + 1):
                for ops in itertools.product(operations, repeat=steps):
                    expr = str(perm[0])
                    used_numbers = 1
                    for i, op in enumerate(ops):
                        if used_numbers < len(perm):
                            if op == 'math.log':
                                if perm[used_numbers] > 0 and perm[used_numbers] != 1:
                                    expr += f" {op}({perm[used_numbers]})"
                                    used_numbers += 1
                                else:
                                    break
                            else:
                                expr += f" {op} {perm[used_numbers]}"
                                used_numbers += 1
                        else:
                            break

                    if is_valid_expression(expr):
                        result = evaluate_expression(expr)
                        if math.isclose(result, target, rel_tol=1e-9):
                            return expr, steps

        return "", -1

    # Set a reasonable maximum number of steps
    max_steps = 5
    expression, steps = generate_expressions(numbers, target, max_steps)
    return expression, steps

# Example usage
numbers = [2, 3, 5, 7]
target = 10
allow_duplicates = False
expression, steps = generate_expression(numbers, target, allow_duplicates)

# Print results
