print(f"Steps: {steps}")

# Node class for circular linked list
class Node:
    def __init__(self, data):
        self.data = data
        self.next = None

# Circular Linked List implementation
class CircularLinkedList:
    def __init__(self):
        self.head = None

    # Append a new node to the end
    def append(self, data):
        new_node = Node(data)
        if not self.head:
            self.head = new_node
            new_node.next = self.head
        else:
            temp = self.head
            while temp.next != self.head:
                temp = temp.next
            temp.next = new_node
            new_node.next = self.head

    # Insert a new node at a specific position
    def insert(self, data, position):
        if position < 0:
            raise ValueError("Position must be non-negative")

        new_node = Node(data)
        if position == 0:
            if not self.head:
                self.head = new_node
                new_node.next = self.head
            else:
                temp = self.head
                while temp.next != self.head:
                    temp = temp.next
                temp.next = new_node
                new_node.next = self.head
                self.head = new_node
        else:
            temp = self.head
            count = 0
            while temp and count < position - 1:
                temp = temp.next
                count += 1
            if not temp:
                raise IndexError("Position out of range")
            new_node.next = temp.next
            temp.next = new_node

    # Display the circular linked list
    def display(self):
        if not self.head:
            return "Empty list"
        result = []
        temp = self.head
        while True:
            result.append(str(temp.data))
            temp = temp.next
            if temp == self.head:
                break
        return " -> ".join(result) + " -> " + str(self.head.data)

# Create a circular linked list and insert "Hello" at position 2
