# Vector class implementation with generic type support
from typing import List, TypeVar, Generic, Type
import math

T = TypeVar('T', bound=float)

class Vector(Generic[T]):
    def __init__(self, elements: List[T]):
        self.elements = elements

    def __len__(self):
        return len(self.elements)

    def __repr__(self):
        return f"Vector({self.elements})"

    def __add__(self, other: 'Vector[T]') -> 'Vector[T]':
        if len(self) != len(other):
            raise ValueError("Vectors must be of the same length for addition.")
        return Vector([a + b for a, b in zip(self.elements, other.elements)])

    def __sub__(self, other: 'Vector[T]') -> 'Vector[T]':
        if len(self) != len(other):
            raise ValueError("Vectors must be of the same length for subtraction.")
        return Vector([a - b for a, b in zip(self.elements, other.elements)])

    def __mul__(self, scalar: T) -> 'Vector[T]':
        return Vector([a * scalar for a in self.elements])

    def dot(self, other: 'Vector[T]') -> T:
        if len(self) != len(other):
            raise ValueError("Vectors must be of the same length for dot product.")
        return sum(a * b for a, b in zip(self.elements, other.elements))

    def cross(self, other: 'Vector[T]') -> 'Vector[T]':
        if len(self) != 3 or len(other) != 3:
            raise ValueError("Cross product is only defined for 3-dimensional vectors.")
        a1, a2, a3 = self.elements
        b1, b2, b3 = other.elements
        return Vector([
            a2 * b3 - a3 * b2,
            a3 * b1 - a1 * b3,
            a1 * b2 - a2 * b1
        ])

    def magnitude(self) -> T:
        return math.sqrt(sum(a ** 2 for a in self.elements))

    def normalize(self) -> 'Vector[T]':
        mag = self.magnitude()
        if mag == 0:
            raise ValueError("Cannot normalize a zero vector.")
        return Vector([a / mag for a in self.elements])

    def angle(self, other: 'Vector[T]') -> float:
        if len(self) != len(other):
            raise ValueError("Vectors must be of the same length to calculate the angle.")
        dot_product = self.dot(other)
        mag_self = self.magnitude()
        mag_other = other.magnitude()
        if mag_self == 0 or mag_other == 0:
            raise ValueError("Cannot calculate the angle with zero vector.")
        return math.acos(dot_product / (mag_self * mag_other))

    def projection(self, other: 'Vector[T]') -> 'Vector[T]':
        if len(self) != len(other):
            raise ValueError("Vectors must be of the same length to calculate the projection.")
        dot_product = self.dot(other)
        mag_other_squared = other.magnitude() ** 2
        if mag_other_squared == 0:
            raise ValueError("Cannot project onto a zero vector.")
        scalar = dot_product / mag_other_squared
        return other * scalar

# Example usage:
v1 = Vector([1, 2, 3])
v2 = Vector([4, 5, 6])

print(v1 + v2)  # Vector([5, 7, 9])
print(v1 - v2)  # Vector([-3, -3, -3])
print(v1 * 2)   # Vector([2, 4, 6])
print(v1.dot(v2))  # 32
print(v1.cross(v2))  # Vector([-3, 6, -3])
print(v1.magnitude())  # 3.7416573867739413
print(v1.normalize())  # Vector([0.2672612419124244, 0.5345224838248488, 0.8017837257372732])
print(v1.angle(v2))  # 0.2257261285527342
print(v1.projection(v2))  # Vector([1.7142857142857142, 2.142857142857143, 2.5714285714285716])

