# SQL file cleaner - removes comments and empty lines
# while preserving multi-line INSERT statements and CREATE FUNCTION blocks

import re

def is_comment_line(line):
    # Check if line is a comment (starts with --)
    return line.strip().startswith('--')

def is_empty_line(line):
    # Check if line is empty or contains only whitespace
    return line.strip() == ''

def is_start_of_multi_line_insert(line):
    # Detect start of INSERT statement
    return line.strip().upper().startswith('INSERT')

def is_end_of_multi_line_insert(line):
    # Detect end of INSERT statement (ends with semicolon)
    return line.strip().upper().endswith(';')

def is_start_of_create_function(line):
    # Detect start of CREATE FUNCTION statement
    return 'CREATE FUNCTION' in line.upper()

def is_end_of_create_function(line, function_stack):
    # Check if we've reached the end of a function block
    if 'END' in line.upper():
        function_stack.pop()
    return not function_stack

def clean_sql_file(input_file, output_file):
    # Read input file
    with open(input_file, 'r') as f:
        lines = f.readlines()

    # Track state for multi-line constructs
    in_multi_line_insert = False
    in_create_function = False
    function_stack = []
    cleaned_lines = []

    # Process each line
    for line in lines:
        # Detect start of blocks
        if is_start_of_multi_line_insert(line):
            in_multi_line_insert = True
        if is_start_of_create_function(line):
            function_stack.append(True)
            in_create_function = True

        # Add line to output if it's not a comment/empty line
        # OR if we're inside a multi-line construct
        if not (is_comment_line(line) or is_empty_line(line)) or in_multi_line_insert or in_create_function:
            cleaned_lines.append(line)

        # Detect end of blocks
        if in_multi_line_insert and is_end_of_multi_line_insert(line):
            in_multi_line_insert = False
        if in_create_function:
            in_create_function = is_end_of_create_function(line, function_stack)

    # Write cleaned content to output file
    with open(output_file, 'w') as f:
        f.writelines(cleaned_lines)

# Example usage
input_file = 'file.sql'
output_file = 'cleaned_file.sql'
clean_sql_file(input_file, output_file)

# Function to calculate average of a list of numbers
def sum_of_values(num_list):
    total = 0

    # Sum all values in the list
    for value in num_list:
        total += value

    # Return the average (sum divided by count)
    return total / len(num_list)

# Person class definition
class Person:
    def __init__(self, full_name, age, salutation=None):
        self.full_name = full_name
        self.age = None
        # Set age using the setter method
        self.set_age(age)
        # Determine and set salutation
        self.salutation = self.determine_salutation(salutation)

    # Method to determine appropriate salutation
    def determine_salutation(self, salutation):
        if salutation in ["Mr.", "Mrs.", "Miss", "Dr.", "Ms."]:
            return salutation
        else:
            return "Mr."  # Default salutation

    # Method to validate and set age
    def set_age(self, age):
        if isinstance(age, int) and age > 0:
            self.age = age
        else:
            raise ValueError("Age must be a positive integer")

    # Leap year check helper method
    def is_leap_year(self, year):
        if (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0):
            return True
        return False

    # Generate expressive personal statement
    def generate_expressive_statement(self, current_year):
        if self.age is None:
            raise ValueError("Age is not set")

        birth_year = current_year - self.age
        leap_year_note = " (a leap year)" if self.is_leap_year(birth_year) else ""

        return f"{self.salutation} {self.full_name} is {self.age} years old, born in {birth_year}{leap_year_note}."

