# Function to compute median without using built-in sorting or functions
def median(l: list):
    """
    Returns the median of elements in list l without using built-in functions or sorting.
    It can process tuples with negative and floating point numbers in constant time.
    Also handles scenarios with multiple medians and non-numeric items.

    >>> median([3, 1, 2, 4, 5])
    3
    >>> median([-10, 4, 6, 1000, 10, 20])
    15.0
    >>> median([1, 2, (3, 4), 5])
    3
    >>> median([1, 'a', 2, 3])
    TypeError: List contains non-numeric elements.
    >>> median([1])
    ValueError: List must contain at least two elements.
    """

    # Helper function to flatten nested structures
    def flatten(lst):
        """Flatten a list that may contain tuples."""
        result = []
        for item in lst:
            if isinstance(item, tuple):
                result.extend(flatten(item))
            elif isinstance(item, (int, float)):
                result.append(item)
            else:
                raise TypeError("List contains non-numeric elements.")
        return result

    # Quickselect algorithm to find k-th smallest element
    def quickselect(lst, k):
        """Select the k-th smallest element from lst using Quickselect."""
        if len(lst) == 1:
            return lst[0]

        pivot = lst[len(lst) // 2]
        lows = [el for el in lst if el < pivot]
        highs = [el for el in lst if el > pivot]
        pivots = [el for el in lst if el == pivot]

        if k < len(lows):
            return quickselect(lows, k)
        elif k < len(lows) + len(pivots):
            return pivots[0]
        else:
            return quickselect(highs, k - len(lows) - len(pivots))

    # Process input list
    flat_list = flatten(l)

    # Validate minimum length
    if len(flat_list) < 2:
        raise ValueError("List must contain at least two elements.")

    n = len(flat_list)
    if n % 2 == 1:
        # Odd number of elements: return middle element
        return quickselect(flat_list, n // 2)
    else:
        # Even number of elements: average of two middle elements
        return (quickselect(flat_list, n // 2 - 1) + quickselect(flat_list, n // 2)) / 2

