student.add_class("Math 101")
student.add_class("English 101")
student.update_grade_level(11)
student.update_gpa(3.7)

class_grades = {
    "Math 101": 90,
    "English 101": 85
}

new_gpa = student.calculate_gpa(class_grades)
print(f"New GPA: {new_gpa}")

# Import regular expressions module
import re

def read_file(file_path):
    try:
        # Open file in read mode and return all lines
        with open(file_path, 'r') as file:
            return file.readlines()
    except FileNotFoundError:
        print(f"Error: File {file_path} not found.")
        return None
    except Exception as e:
        print(f"Error reading file: {e}")
        return None

def find_function_calls(lines, function_name):
    calls = []
    # Iterate through each line with its line number
    for line_number, line in enumerate(lines, 1):
        # Search for function call pattern
        match = re.search(rf'\b{function_name}\s*\(', line)
        if match:
            calls.append((line_number, line.strip()))
    return calls

def is_valid_object_reference(line, context_objects, reference_objects):
    # Check if the object is created in the current context
    for obj in context_objects:
        if obj in line:
            return True

    # Check if the object has its reference count increased
    for obj in reference_objects:
        if obj in line:
            return True

    return False

def check_json_object_usage(file_path):
    # Read file content
    lines = read_file(file_path)
    if not lines:
        return

    context_objects = []
    reference_objects = []

    # Find all object creations
    for line in lines:
        # Look for json_object_new assignments
        match = re.search(r'\bj\s*=\s*json_object_new\s*\(', line)
        if match:
            context_objects.append('j')

        # Look for json_object_get assignments
        match = re.search(r'\bj\s*=\s*json_object_get\s*\(', line)
        if match:
            reference_objects.append('j')

    # Find all calls to json_object_object_add and json_object_array_add
    object_add_calls = find_function_calls(lines, 'json_object_object_add')
    array_add_calls = find_function_calls(lines, 'json_object_array_add')

    all_add_calls = object_add_calls + array_add_calls

    # Check each add call for valid object references
    for line_number, line in all_add_calls:
        if not is_valid_object_reference(line, context_objects, reference_objects):
            print(f"Error: Invalid object reference in line {line_number}: {line}")

# Main execution block
if __name__ == "__main__":
    file_path = 'example.c'  # Replace with the path to your C file
    check_json_object_usage(file_path)

