# Import math module for calculations
import math

def validate_input(r1, r2, h, a1=None, a2=None, b1=None, b2=None):
    # Check if radii and height are positive
    if r1 <= 0 or r2 <= 0 or h <= 0:
        raise ValueError("All radii and height must be positive.")

    # Check elliptical parameters if provided
    if a1 is not None and a2 is not None and b1 is not None and b2 is not None:
        if a1 <= 0 or a2 <= 0 or b1 <= 0 or b2 <= 0:
            raise ValueError("All radii and height must be positive.")

def lateral_surface_area_circular(r1, r2, h):
    # Calculate lateral surface area for circular frustum
    return math.pi * (r1 + r2) * math.sqrt((r2 - r1)**2 + h**2)

def lateral_surface_area_elliptical(a1, a2, b1, b2, h):
    # Calculate lateral surface area for elliptical frustum
    term1 = math.pi * (a1 + a2) * math.sqrt((a2 - a1)**2 + h**2)
    term2 = math.pi * (b1 + b2) * math.sqrt((b2 - b1)**2 + h**2)
    return term1 + term2

def volume_circular(r1, r2, h):
    # Calculate volume for circular frustum
    return (math.pi * h / 3) * (r1**2 + r2**2 + r1 * r2)

def volume_elliptical(a1, a2, b1, b2, h):
    # Calculate volume for elliptical frustum
    return (math.pi * h / 3) * (a1 * b1 + a2 * b2 + math.sqrt(a1 * b1 * a2 * b2))

def calculate_frustum_properties(frustums):
    results = []

    # Process each frustum in the list
    for frustum in frustums:
        r1 = frustum['r1']
        r2 = frustum['r2']
        h = frustum['h']
        a1 = frustum.get('a1')
        a2 = frustum.get('a2')
        b1 = frustum.get('b1')
        b2 = frustum.get('b2')

        # Validate input parameters
        validate_input(r1, r2, h, a1, a2, b1, b2)

        # Determine frustum type and calculate properties accordingly
        if a1 is not None and a2 is not None and b1 is not None and b2 is not None:
            lateral_surface_area = lateral_surface_area_elliptical(a1, a2, b1, b2, h)
            volume = volume_elliptical(a1, a2, b1, b2, h)
        else:
            lateral_surface_area = lateral_surface_area_circular(r1, r2, h)
            volume = volume_circular(r1, r2, h)

        # Store results
        results.append({
            'lateral_surface_area': lateral_surface_area,
            'volume': volume
        })

    return results

