# Rectangle class definition
class Rectangle:
    def __init__(self, length, width):
        self.set_length(length)
        self.set_width(width)

    def set_length(self, length):
        # Validate length parameter
        if not isinstance(length, (int, float)) or length <= 0:
            raise ValueError("Length must be a positive non-zero number.")
        self._length = length

    def get_length(self):
        return self._length

    def set_width(self, width):
        # Validate width parameter
        if not isinstance(width, (int, float)) or width <= 0:
            raise ValueError("Width must be a positive non-zero number.")
        self._width = width

    def get_width(self):
        return self._width

    def area(self):
        try:
            # Calculate area as length * width
            return self._length * self._width
        except Exception as e:
            raise RuntimeError("An error occurred while calculating the area.") from e

    def perimeter(self):
        try:
            # Calculate perimeter as 2 * (length + width)
            return 2 * (self._length + self._width)
        except Exception as e:
            raise RuntimeError("An error occurred while calculating the perimeter.") from e

    def is_same_area(self, other):
        # Check if other is a Rectangle instance
        if not isinstance(other, Rectangle):
            raise TypeError("The 'other' parameter must be an instance of Rectangle.")
        return self.area() == other.area()

