# LLDP Network Topology Discovery Tool
from scapy.all import *

def get_lldp_info(pkt):
    # Extract LLDP information from packet
    if pkt.haslayer(LLDPDU):
        lldpdu = pkt[LLDPDU]
        chassis_id = lldpdu.get_tlv_val(1).decode("utf-8")
        port_id = lldpdu.get_tlv_val(2).decode("utf-8")
        ttl = lldpdu.get_tlv_val(3)

        return (chassis_id, port_id, ttl)

def send_lldp_broadcast(interface):
    # Build and send LLDP broadcast packet
    ether = Ether(dst="01:80:c2:00:00:0e")

    chassis_id_tl = LLDPChassisID(
        subtype=7,
        id=bytes(BPFProgram(interface=interface).filter[0].bh_mac)
    )

    port_id_tl = LLDPPortID(
        subtype=7,
        id=str(interface).encode()
    )

    ttl_tl = LLDPDUTimeToLive(seconds=120)

    lldpdu = LLDPDU(tlvs=[chassis_id_tl, port_id_tl, ttl_tl])
    pkt = ether / lldpdu

    sendp(pkt, iface=interface, loop=1)

def main():
    # Initialize topology dictionary and interface list
    topology = {}

    # Get available network interfaces based on OS
    interfaces = (
        get_windows_if_list() 
        if sys.platform == "win32" 
        else get_if_list()
    )

    print("Available network interfaces:")
    for i in range(len(interfaces)):
        print(f"{i}: {interfaces[i]}")

    # User selects interface
    interface_idx = int(input("Choose an interface to broadcast LLDP frames: "))
    interface = interfaces[interface_idx]

    try:
        while True:
            # Send LLDP broadcast
            send_lldp_broadcast(interface)

            # Sniff for incoming LLDP packets
            pkt = sniff(
                iface=interface, 
                timeout=1, 
                filter="ether dst 01:80:c2:00:00:0e"
            )

            # Process received packets
            for p in pkt:
                info = get_lldp_info(p)
                if info:
                    chassis_id, port_id, ttl = info

                    # Update topology
                    if chassis_id not in topology:
                        topology[chassis_id] = []
                    topology[chassis_id].append(port_id)

            # Display current network topology
            print("\nNetwork topology:")
            for i, (chassis_id, port_ids) in enumerate(topology.items()):
                print(f"{i+1}. {chassis_id}")
                for port_id in port_ids:
                    print(f"   {port_id}")

    except KeyboardInterrupt:
        pass

if __name__ == "__main__":
    main()

