class LibraryMemberManager:
    def __init__(self):
        # Dictionary to store members with member_id as key
        self.members = {}

    def add_member(self, member_id, name, address, phone, email):
        # Check if member already exists
        if member_id in self.members:
            raise ValueError(f"Member with ID {member_id} already exists.")

        # Create and store new member
        new_member = LibraryMember(member_id, name, address, phone, email)
        self.members[member_id] = new_member

        print(f"Member with ID {member_id} added successfully.")

    def get_member(self, member_id):
        # Validate member existence
        if member_id not in self.members:
            raise ValueError(f"Member with ID {member_id} does not exist.")
        return self.members[member_id]

    def update_member(self, member_id, **kwargs):
        # Check if member exists
        if member_id not in self.members:
            raise ValueError(f"Member with ID {member_id} does not exist.")

        member = self.members[member_id]

        # Update provided fields
        if 'name' in kwargs:
            member.update_name(kwargs['name'])
        if 'address' in kwargs:
            member.update_address(kwargs['address'])
        if 'phone' in kwargs:
            member.update_phone(kwargs['phone'])
        if 'email' in kwargs:
            member.update_email(kwargs['email'])

