# Thread-safe Hash Table implementation with dynamic resizing
import threading
from typing import Any, Hashable, Optional


class HashTable:
    def __init__(self, initial_size: int = 10, load_factor: float = 0.7):
        self.size = initial_size
        self.load_factor = load_factor
        self.buckets = [None] * self.size
        self.lock = threading.Lock()
        self.count = 0

    def _hash(self, key: Hashable) -> int:
        # Hash function for different key types
        if isinstance(key, int):
            return key % self.size
        elif isinstance(key, str):
            return sum(ord(char) for char in key) % self.size
        else:
            raise TypeError("Key must be an integer or a string")

    def _resize(self) -> None:
        # Resize the hash table when load factor exceeds threshold
        with self.lock:
            old_buckets = self.buckets
            self.size *= 2
            self.buckets = [None] * self.size
            self.count = 0

            for bucket in old_buckets:
                if bucket is not None:
                    for key, value in bucket:
                        self.insert(key, value)

    def insert(self, key: Hashable, value: Any) -> None:
        # Insert a key-value pair into the hash table
        with self.lock:
            index = self._hash(key)
            if self.buckets[index] is None:
                self.buckets[index] = []

            # Update existing key or append new one
            for i, (k, v) in enumerate(self.buckets[index]):
                if k == key:
                    self.buckets[index][i] = (key, value)
                    return

            self.buckets[index].append((key, value))
            self.count += 1

            # Check if resize is needed
            if self.count / self.size >= self.load_factor:
                self._resize()

    def search(self, key: Hashable) -> Optional[Any]:
        # Search for a key and return its value if found
        with self.lock:
            index = self._hash(key)
            if self.buckets[index] is None:
                return None

            for k, v in self.buckets[index]:
                if k == key:
                    return v
            return None

    def delete(self, key: Hashable) -> None:
        # Delete a key from the hash table
        with self.lock:
            index = self._hash(key)
            if self.buckets[index] is None:
                return

            for i, (k, v) in enumerate(self.buckets[index]):
                if k == key:
                    del self.buckets[index][i]
                    self.count -= 1
                    return

    def __str__(self):
        return str(self.buckets)


# Example usage
if __name__ == "__main__":
    ht = HashTable()
    ht.insert(1, "one")
    ht.insert(2, "two")
    ht.insert("three", 3)
    ht.insert(11, "eleven")  # Should trigger resize

    print(ht.search(1))      # Output: one
    print(ht.search("three"))  # Output: 3

    ht.delete(2)
    print(ht.search(2))      # Output: None
    print(ht)

# JSON Parser implementation with circular reference detection and schema validation
import json
from collections import defaultdict
from typing import Any, Dict, List, Union

class JSONParser:
    def __init__(self):
        self.seen_objects = set()
        self.unique_keys = defaultdict(int)

    def parse(self, json_string: str) -> Dict[str, str]:
        try:
            data = json.loads(json_string)
        except json.JSONDecodeError as e:
            raise ValueError(f"Invalid JSON syntax: {e}")

        return self._parse_value(data)

    def _parse_value(self, value: Any) -> Union[str, List[str], Dict[str, str]]:
        if isinstance(value, dict):
            return self._parse_dict(value)
        elif isinstance(value, list):
            return self._parse_list(value)
        else:
            return self._convert_to_string(value)

    def _parse_dict(self, data: Dict[Any, Any]) -> Dict[str, str]:
        result = {}
        for key, value in data.items():
            key = self._ensure_unique_key(key)
            result[key] = self._parse_value(value)
        return result

    def _parse_list(self, data: List[Any]) -> List[str]:
        return [self._parse_value(item) for item in data]

    def _ensure_unique_key(self, key: Any) -> str:
        key = str(key)
        if self.unique_keys[key] > 0:
            key = f"{key}_{self.unique_keys[key]}"
        self.unique_keys[key] += 1
        return key

    def _convert_to_string(self, value: Any) -> str:
        if value is None:
            return "null"
        return str(value)

    def _detect_circular_reference(self, obj: Any) -> bool:
        obj_id = id(obj)
        if obj_id in self.seen_objects:
            return True
        self.seen_objects.add(obj_id)
        return False

    def validate_against_schema(self, data: Dict[str, str], schema: Dict[str, Any]) -> bool:
        for key, value in schema.items():
            if key not in data:
                raise ValueError(f"Missing key: {key}")
            if not isinstance(data[key], str):
                raise ValueError(f"Value for key {key} is not a string")
            if value is not None and not data[key].startswith(value):
                raise ValueError(f"Value for key {key} does not match the schema")
        return True


# Example usage
json_string = '{"name": "John", "age": 30, "address": {"city": "New York", "zip": 10001}, "hobbies": ["reading", "coding"], "name": "Jane"}'
parser = JSONParser()
parsed_data = parser.parse(json_string)
print(parsed_data)


