        if not self.is_borrowed:
            self.is_borrowed = True
            self.due_date = datetime.now() + timedelta(days=days)
            print(f"{self.title} has been borrowed and is due on {self.due_date}")
        else:
            print(f"{self.title} is already borrowed.")

    def return_book(self):
        if self.is_borrowed:
            self.is_borrowed = False
            self.due_date = None
            print(f"{self.title} has been returned.")
        else:
            print(f"{self.title} is not currently borrowed.")

    def check_overdue(self):
        if self.is_borrowed and self.due_date < datetime.now():
            print(f"{self.title} is overdue.")
        else:
            print(f"{self.title} is not overdue.")

# Function to check if data structure is empty and count empty dicts
def is_empty_and_count_empty_dicts(data, visited=None):
    # Initialize visited set if not provided
    if visited is None:
        visited = set()

    # Avoid infinite recursion for circular references
    if id(data) in visited:
        return True, 0  # Already visited, treat as non-empty to avoid infinite loop

    visited.add(id(data))

    # Handle dictionary type
    if isinstance(data, dict):
        if not data:
            return True, 1  # This dictionary is empty

        all_empty = True
        empty_count = 0

        # Recursively check each value
        for value in data.values():
            is_empty, count = is_empty_and_count_empty_dicts(value, visited)
            if not is_empty:
                all_empty = False
            empty_count += count

        return all_empty, empty_count

    # Handle list, tuple, and set types
    elif isinstance(data, (list, tuple, set)):
        all_empty = True
        empty_count = 0

        # Recursively check each item
        for item in data:
            is_empty, count = is_empty_and_count_empty_dicts(item, visited)
            if not is_empty:
                all_empty = False
            empty_count += count

        return all_empty, empty_count

    # Non-iterable objects are considered non-empty
    else:
        return False, 0  # Non-iterable object, treat as non-empty


