repeated_word, repeated_word_pos, unique_letter, unique_letter_pos = find_repeated_word_and_unique_letter(text)

if repeated_word:
    print(f"Repeated word: '{repeated_word}' at position {repeated_word_pos}")
else:
    print("No repeated word with at least 4 consecutive occurrences found.")

if unique_letter:
    print(f"Unique letter: '{unique_letter}' at position {unique_letter_pos}")
else:
    print("No unique letter found.")

