# Import required modules
import hashlib
import json
from datetime import datetime

def custom_sort_key(item):
    # Extract key and value from the item tuple
    key, value = item

    # Return sort priority based on value type
    if isinstance(value, (int, float)):
        return (0, -value)
    elif isinstance(value, str):
        return (1, value.lower())
    elif isinstance(value, bool):
        return (2, value)
    elif isinstance(value, (list, dict, datetime)):
        return (3, value)
    else:
        raise TypeError(f"Unsupported data type: {type(value)}")

def normalize_value(value):
    # Normalize string values to lowercase
    if isinstance(value, str):
        return value.lower()
    # Keep numeric and boolean values as-is
    elif isinstance(value, (int, float, bool)):
        return value
    # Recursively normalize list items
    elif isinstance(value, list):
        return [normalize_value(v) for v in value]
    # Normalize dictionary values
    elif isinstance(value, dict):
        return normalize_dict(value)
    # Convert datetime to ISO format string (lowercase)
    elif isinstance(value, datetime):
        return value.isoformat().lower()
    else:
        raise TypeError(f"Unsupported data type: {type(value)}")

def normalize_dict(d):
    # Ensure input is a dictionary
    if not isinstance(d, dict):
        raise TypeError("Input must be a dictionary")

    # Create normalized and sorted items
    normalized_items = sorted(
        ((k.lower(), normalize_value(v)) 
         for k, v in d.items() 
         if v is not None and v != ""),
        key=custom_sort_key
    )

    return dict(normalized_items)

def hash_dict(d, algorithm='sha512'):
    # Normalize the input dictionary
    normalized_dict = normalize_dict(d)

    # Convert to JSON string with sorted keys
    json_str = json.dumps(normalized_dict, sort_keys=True)

    # Generate hash using specified algorithm
    hash_object = hashlib.new(algorithm)
    hash_object.update(json_str.encode('utf-8'))

    return hash_object.hexdigest()

