# Import required modules
from abc import ABC, abstractmethod

# Abstract Base Class (ABC)
class BankAccount(ABC):
    def __init__(self, account_number, balance=0):
        self.account_number = account_number
        self.balance = balance

    @abstractmethod
    def deposit(self, amount):
        pass

    @abstractmethod
    def withdraw(self, amount):
        pass

    @abstractmethod
    def get_balance(self):
        pass

# Concrete Class - Savings Account
class SavingsAccount(BankAccount):
    def __init__(self, account_number, balance=0, interest_rate=0.01):
        super().__init__(account_number, balance)
        self.interest_rate = interest_rate

    def deposit(self, amount):
        self.balance += amount
        print(f"Deposited {amount} to Savings Account {self.account_number}. New balance: {self.balance}")

    def withdraw(self, amount):
        if amount > self.balance:
            print("Insufficient funds")
        else:
            self.balance -= amount
            print(f"Withdrew {amount} from Savings Account {self.account_number}. New balance: {self.balance}")

    def get_balance(self):
        return self.balance

    def apply_interest(self):
        interest = self.balance * self.interest_rate
        self.balance += interest
        print(f"Applied interest of {interest} to Savings Account {self.account_number}. New balance: {self.balance}")

# Concrete Class - Checking Account
class CheckingAccount(BankAccount):
    def __init__(self, account_number, balance=0, overdraft_limit=100):
        super().__init__(account_number, balance)
        self.overdraft_limit = overdraft_limit

    def deposit(self, amount):
        self.balance += amount
        print(f"Deposited {amount} to Checking Account {self.account_number}. New balance: {self.balance}")

    def withdraw(self, amount):
        if amount > self.balance + self.overdraft_limit:
            print("Exceeds overdraft limit")
        else:
            self.balance -= amount
            print(f"Withdrew {amount} from Checking Account {self.account_number}. New balance: {self.balance}")

    def get_balance(self):
        return self.balance

# Client Code
def main():
    # Create accounts
    savings_account = SavingsAccount("SA123456", 1000)
    checking_account = CheckingAccount("CA789012", 500)

    # Perform operations on savings account
    savings_account.deposit(500)
    savings_account.withdraw(200)
    savings_account.apply_interest()
    print(f"Final balance of Savings Account: {savings_account.get_balance()}")

    # Perform operations on checking account
    checking_account.deposit(300)
    checking_account.withdraw(1000)
    print(f"Final balance of Checking Account: {checking_account.get_balance()}")

if __name__ == "__main__":
