# FCFS Scheduler Implementation

class Process:
    def __init__(self, pid, arrival_time, burst_time):
        self.pid = pid
        self.arrival_time = arrival_time
        self.burst_time = burst_time
        self.remaining_time = burst_time
        self.start_time = None
        self.end_time = None

    def __repr__(self):
        return f"Process({self.pid}, arrival_time={self.arrival_time}, burst_time={self.burst_time})"


class FCFS_Scheduler:
    def __init__(self):
        self.processes = []

    def add_process(self, process):
        self.processes.append(process)

    def schedule(self):
        # Sort processes based on arrival time
        self.processes.sort(key=lambda x: x.arrival_time)

        current_time = 0
        for process in self.processes:
            if process.arrival_time > current_time:
                current_time = process.arrival_time
            process.start_time = current_time
            current_time += process.burst_time
            process.end_time = current_time

    def get_gantt_chart(self):
        gantt_chart = []
        for process in self.processes:
            gantt_chart.append((process.start_time, process.end_time, process.pid))
        return gantt_chart

    def get_average_waiting_time(self):
        total_waiting_time = 0
        for process in self.processes:
            if process.start_time is not None:
                total_waiting_time += process.start_time - process.arrival_time
        return total_waiting_time / len(self.processes)

    def get_average_turnaround_time(self):
        total_turnaround_time = 0
        for process in self.processes:
            if process.end_time is not None:
                total_turnaround_time += process.end_time - process.arrival_time
        return total_turnaround_time / len(self.processes)


# Example usage
if __name__ == "__main__":
    scheduler = FCFS_Scheduler()

    # Add processes
    scheduler.add_process(Process(1, 0, 24))
    scheduler.add_process(Process(2, 4, 3))
    scheduler.add_process(Process(3, 5, 3))

    # Schedule processes
    scheduler.schedule()

    # Output results
    gantt_chart = scheduler.get_gantt_chart()
    print("Gantt Chart:")
    for start, end, pid in gantt_chart:
        print(f"Process {pid} from {start} to {end}")

    print(f"Average Waiting Time: {scheduler.get_average_waiting_time():.2f}")
    print(f"Average Turnaround Time: {scheduler.get_average_turnaround_time():.2f}")

# Import json module for parsing JSON data
import json


def validate_and_parse(json_data):
    # Check if input is a dictionary
    if isinstance(json_data, dict):
        # Validate 'name' field if present
        if 'name' in json_data:
            name = json_data['name']
            # Ensure name is a string with at least 3 alphabetic characters
            if not (isinstance(name, str) and len(name) >= 3 and name.isalpha()):
                raise ValueError("Invalid 'name' value. It should be a string of at least 3 alphabetic characters.")

        # Validate 'age' field if present
        if 'age' in json_data:
            age = json_data['age']
            # Ensure age is an integer between 18 and 99 (inclusive)
            if not (isinstance(age, int) and 18 <= age <= 99):
                raise ValueError("Invalid 'age' value. It should be an integer between 18 and 99 (inclusive).")

        # Process nested dictionaries and lists
        for key, value in json_data.items():
            if isinstance(value, dict):
                # Special validation for 'address'
                if key == 'address':
                    if not (isinstance(value, str) and value.strip()):
                        raise ValueError("Invalid 'address' value. It should be a non-empty string.")
                # Recursively validate nested dictionary
                validate_and_parse(value)
            elif isinstance(value, list):
                # Special validation for 'hobbies'
                if key == 'hobbies':
                    if not (isinstance(value, list) and all(isinstance(hobby, str) for hobby in value) and value):
                        raise ValueError("Invalid 'hobbies' value. It should be a non-empty list of strings.")
                # Recursively validate each item in the list
                for item in value:
                    validate_and_parse(item)

    # Handle list inputs by validating each item
    elif isinstance(json_data, list):
        for item in json_data:
            validate_and_parse(item)

    return json_data


