# Advanced median calculation function
def advanced_median(l: list, cmp_func: callable):
    """
    Return median of elements in the list l without sorting it and handles mixed datatypes.
    Handles tuples with variable sizes, duplicates, and uses cmp_func for comparisons.
    """

    def partition(arr, low, high):
        # Partition function for quickselect
        pivot = arr[high]
        i = low - 1

        for j in range(low, high):
            if cmp_func(arr[j], pivot) < 0:
                i += 1
                arr[i], arr[j] = arr[j], arr[i]

        arr[i + 1], arr[high] = arr[high], arr[i + 1]
        return i + 1

    def quickselect(arr, k, low, high):
        # Quickselect algorithm to find k-th smallest element
        if low == high:
            return arr[low]

        pi = partition(arr, low, high)

        if k == pi:
            return arr[k]
        elif k < pi:
            return quickselect(arr, k, low, pi - 1)
        else:
            return quickselect(arr, k, pi + 1, high)

    def is_comparable(a, b):
        # Check if two elements can be compared using cmp_func
        try:
            cmp_func(a, b)
            return True
        except TypeError:
            return False

    # Filter out incomparable elements
    filtered_list = [
        x 
        for i, x in enumerate(l) 
        if all(is_comparable(x, y) for y in l if i != l.index(y))
    ]

    if not filtered_list:
        return None

    n = len(filtered_list)

    if n % 2 == 1:
        # Odd number of elements - return middle element
        return quickselect(filtered_list, n // 2, 0, n - 1)
    else:
        # Even number of elements - return average of two middle elements
        left_median = quickselect(filtered_list, n // 2 - 1, 0, n - 1)
        right_median = quickselect(filtered_list, n // 2, 0, n - 1)
        return (left_median + right_median) / 2


# Examples demonstrating usage
print(advanced_median([3, 1, 2, 4, 5], lambda a, b: a - b))  # => 3
print(advanced_median([-10, 4, 6, 1000, 10, 20], lambda a, b: a - b))  # => 15.0
print(advanced_median([1, 2, 2, 4, 5], lambda a, b: a - b))  # => 2
print(advanced_median(['a', 'b', 1, 2], lambda a, b: a - b))  # => None

import sqlparse

def extract_columns_and_tables(sql_query):
    # Parse the SQL query
    parsed = sqlparse.parse(sql_query)
    statement = parsed[0]

    columns = []
    tables = []

    # Extract columns from the SELECT clause
    for token in statement.tokens:
        if isinstance(token, sqlparse.sql.IdentifierList):
            for identifier in token.get_identifiers():
                if '.' in identifier.value:
                    columns.append(identifier.value)
        elif isinstance(token, sqlparse.sql.Identifier):
            if '.' in token.value:
                columns.append(token.value)

    # Extract tables from the FROM clause
    from_seen = False
    for token in statement.tokens:
        if isinstance(token, sqlparse.sql.Token) and token.ttype == sqlparse.tokens.Keyword and token.value.upper() == 'FROM':
            from_seen = True
        elif from_seen and isinstance(token, sqlparse.sql.IdentifierList):
            for identifier in token.get_identifiers():
                tables.append(identifier.value)
            from_seen = False
        elif from_seen and isinstance(token, sqlparse.sql.Identifier):
            tables.append(token.value)
            from_seen = False

    return columns, tables

# Example SQL query
sql_query = """
select TABLE1.Id, TABLE2.Name, TABLE3.Observations, TABLE3.Address, --and more 70 fields
from TABLE1, TABLE2, TABLE3, TABLE4
"""

# Extract and print results
columns, tables = extract_columns_and_tables(sql_query)
print("Columns:", columns)
print("Tables:", tables)

