import json
from typing import List, Dict

class Book:
    def __init__(self, title: str, isbn: str, author: str, publish_date: str, genre: str):
        self.title = title
        self.isbn = isbn
        self.author = author
        self.publish_date = publish_date
        self.genre = genre

    def to_dict(self):
        return {
            'title': self.title,
            'isbn': self.isbn,
            'author': self.author,
            'publish_date': self.publish_date,
            'genre': self.genre
        }

    @classmethod
    def from_dict(cls, data: Dict):
        return cls(
            title=data['title'],
            isbn=data['isbn'],
            author=data['author'],
            publish_date=data['publish_date'],
            genre=data['genre']
        )

class Library:
    def __init__(self, data_file: str = 'library_data.json'):
        self.data_file = data_file
        self.books_by_title = {}
        self.books_by_isbn = {}
        self.load()

    def add_book(self, title: str, isbn: str, author: str, publish_date: str, genre: str):
        if isbn in self.books_by_isbn:
            raise ValueError(f"A book with ISBN {isbn} already exists.")
        book = Book(title, isbn, author, publish_date, genre)
        if title not in self.books_by_title:
            self.books_by_title[title] = []
        self.books_by_title[title].append(book)
        self.books_by_isbn[isbn] = book
        self.save()

    def search_by_title(self, title: str) -> List[Book]:
        return self.books_by_title.get(title, [])

    def search_by_isbn(self, isbn: str) -> Book:
        return self.books_by_isbn.get(isbn, None)

    def search_partial(self, query: str) -> List[Book]:
        results = []
        for book_list in self.books_by_title.values():
            for book in book_list:
                if query in book.title or query in book.isbn:
                    results.append(book)
        return results

    def remove_book(self, title: str = None, isbn: str = None):
        if title and isbn:
            raise ValueError("Please provide either title or ISBN, not both.")
        if title:
            if title in self.books_by_title:
                for book in self.books_by_title[title]:
                    del self.books_by_isbn[book.isbn]
                del self.books_by_title[title]
        elif isbn:
            if isbn in self.books_by_isbn:
                book = self.books_by_isbn[isbn]
                self.books_by_title[book.title].remove(book)
                if not self.books_by_title[book.title]:
                    del self.books_by_title[book.title]
                del self.books_by_isbn[isbn]
        self.save()

    def save(self):
        with open(self.data_file, 'w') as f:
            data = {isbn: book.to_dict() for isbn, book in self.books_by_isbn.items()}
            json.dump(data, f, indent=4)

    def load(self):
        try:
            with open(self.data_file, 'r') as f:
                data = json.load(f)
                for isbn, book_data in data.items():
                    book = Book.from_dict(book_data)
                    if book.title not in self.books_by_title:
                        self.books_by_title[book.title] = []
                    self.books_by_title[book.title].append(book)
                    self.books_by_isbn[isbn] = book
        except FileNotFoundError:
            pass

# Example usage
if __name__ == '__main__':
    library = Library()

    # Add some books
    library.add_book("The Great Gatsby", "123456", "F. Scott Fitzgerald", "1925", "Novel")
    library.add_book("1984", "654321", "George Orwell", "1949", "Dystopian")
    library.add_book("The Great Gatsby", "7891011", "F. Scott Fitzgerald", "1925", "Novel")  # Different ISBN

    print("Books by title 'The Great Gatsby':")
    for book in library.search_by_title("The Great Gatsby"):
        print(book.to_dict())

    print("\nBook by ISBN '654321':")
    print(library.search_by_isbn("654321").to_dict())

    print("\nPartial search for '198':")
    for book in library.search_partial("198"):
        print(book.to_dict())

    library.remove_book(isbn="654321")
    print("\nBooks after removing ISBN '654321':")
    for book in library.search_by_title("1984"):
        print(book.to_dict())

# Import necessary types from typing module
from typing import List, Dict, Any, Optional


class ListV2:
    def __init__(self, lst):
        self.lst = lst
        self.index = 0

    def __iter__(self):
        return self

    def __next__(self):
        if self.index == len(self.lst):
            raise StopIteration
        else:
            item = self.lst[self.index]
            self.index += 1
            return item


class DataFrame:
    def __init__(
        self,
        data: Optional[Dict[str, List[Any]]] = None,
        columns: Optional[List[str]] = None
    ):
        # Initialize empty structure if no data or columns provided
        if not data and not columns:
            self.data = {}
            self.columns = []
        elif columns:
            # Initialize with column names but empty lists
            self.columns = columns
            self.data = {col: ListV2([]) for col in columns}
        else:
            raise ValueError("Columns cannot be empty if data is provided")

        # Populate data if provided
        if data:
            for col, values in data.items():
                if col not in self.columns:
                    self.columns.append(col)
                self.data[col].lst = values

        # Index dictionary for row lookup
        self.index = {}

    def set_index(self, index: str):
        # Move specified column to index dictionary
        if index in self.data.keys():
            col = self.data.pop(index)
            self.index = {name: idx for idx, name in enumerate(col)}

    def __setitem__(self, col_name: str, values: List[Any]):
        # Add new column or update existing one
        if col_name not in self.columns:
            self.columns.append(col_name)
            self.data[col_name] = ListV2([])
        self.data[col_name].lst = values

    def __getitem__(self, col_name: str) -> ListV2:
        # Return column data as ListV2
        return self.data[col_name]

    def loc(self, row_name: str) -> Dict[str, Any]:
        # Get row data by index name
        idx = self.index[row_name]
        return {col: self.data[col][idx] for col in self.columns}

    def iteritems(self):
        # Iterate over columns (key-value pairs)
        return self.data.items()

    def iterrows(self):
        # Iterate over rows with their index names
        for name, idx in self.index.items():
            row = self.loc(name)
            yield name, row

    def astype(self, dtype: type, col_name: Optional[str] = None):
        # Convert column(s) data type
        if col_name:
            self.data[col_name] = ListV2([dtype(x) for x in self.data[col_name]])
        else:
            for col in self.columns:
                self.data[col] = ListV2([dtype(x) for x in self.data[col]])

    def drop(self, col_name: str):
        # Remove a column from the DataFrame
        if col_name in self.columns:
            self.columns.remove(col_name)
            self.data.pop(col_name)

    def mean(self) -> Dict[str, float]:
        # Calculate mean for each column
        result = {}
        for col in self.columns:
            total = sum(self.data[col])
            mean = total / len(self.data[col])
            result[col] = mean
        return result

    def __repr__(self):
        # Create string representation of DataFrame
        table = [self.columns]
        for row in zip(*self.data.values()):
            table.append(list(row))
        return "\n".join(
            ["\t".join([str(el) for el in row]) for row in table]
        )


