BLACK = (0, 0, 0)
RED = (255, 0, 0)
GREEN = (0, 255, 0)
BLUE = (0, 0, 255)

# Shapes list
shapes = [
    {"type": "circle", "color": RED, "center": (100, 100), "radius": 20},
    {"type": "rectangle", "color": GREEN, "rect": pygame.Rect(200, 100, 50, 50)},
    {"type": "triangle", "color": BLUE, "points": [(300, 100), (350, 150), (400, 100)]}
]

# Selected shape
selected_shape = None

# Main game loop
running = True
while running:
    for event in pygame.event.get():
        if event.type == pygame.QUIT:
            running = False
        elif event.type == pygame.MOUSEBUTTONDOWN:
            if event.button == 1:  # Left mouse button
                for shape in shapes:
                    if shape["type"] == "circle":
                        if pygame.math.Vector2(shape["center"]).distance_to(event.pos) <= shape["radius"]:
                            selected_shape = shape
                            break
                    elif shape["type"] == "rectangle":
                        if shape["rect"].collidepoint(event.pos):
                            selected_shape = shape
                            break
                    elif shape["type"] == "triangle":
                        if pygame.math.Vector2(shape["points"][0]).distance_to(event.pos) <= 10 or \
                           pygame.math.Vector2(shape["points"][1]).distance_to(event.pos) <= 10 or \
                           pygame.math.Vector2(shape["points"][2]).distance_to(event.pos) <= 10:
                            selected_shape = shape
                            break
        elif event.type == pygame.MOUSEMOTION:
            if selected_shape:
                if selected_shape["type"] == "circle":
                    selected_shape["center"] = event.pos
                elif selected_shape["type"] == "rectangle":
                    selected_shape["rect"].center = event.pos
                elif selected_shape["type"] == "triangle":
                    dx, dy = event.rel
                    selected_shape["points"] = [(x + dx, y + dy) for x, y in selected_shape["points"]]
        elif event.type == pygame.MOUSEBUTTONUP:
            if event.button == 1:  # Left mouse button
                selected_shape = None

    # Clear the screen
    screen.fill(WHITE)

    # Draw shapes
    for shape in shapes:
        if shape["type"] == "circle":
            pygame.draw.circle(screen, shape["color"], shape["center"], shape["radius"])
        elif shape["type"] == "rectangle":
            pygame.draw.rect(screen, shape["color"], shape["rect"])
        elif shape["type"] == "triangle":
            pygame.draw.polygon(screen, shape["color"], shape["points"])

    # Update the display
    pygame.display.flip()

# Quit Pygame
pygame.quit()
sys.exit()

# Function to calculate square roots of positive numbers
def square_roots(numbers):
    result = []

    for number in numbers:
        # Only process positive numbers
        if number > 0:
            result.append(number ** 0.5)

    # Return the list of square roots
    return result

# MahJonggHand class for checking hand patterns
class MahJonggHand:
    def __init__(self, tiles):
        self.tiles = tiles
        # Initialize standard pattern counts
        self.standard_patterns = {'pungs': 0, 'kongs': 0, 'chows': 0, 'pairs': 0}

        # Map special hand names to their checking methods
        self.special_hands = {
            'Thirteen Orphans': self.is_thirteen_orphans,
            'Seven Pairs': self.is_seven_pairs,
            'All Pungs': self.is_all_pungs,
            'All Chows': self.is_all_chows,
            'Mixed Shifted Chows': self.is_mixed_shifted_chows,
            'All Terminals and Honors': self.is_all_terminals_and_honors,
            'All Simples': self.is_all_simples,
            'Half Flush': self.is_half_flush,
            'Full Flush': self.is_full_flush
        }

    # Check for Thirteen Orphans hand
    def is_thirteen_orphans(self):
        required_tiles = ['1m', '9m', '1p', '9p', '1s', '9s', 'E', 'S', 'W', 'N', 'C', 'F', 'B']
        return all(tile in self.tiles for tile in required_tiles) and self.tiles.count(self.tiles[0]) == 2

    # Check for Seven Pairs hand
    def is_seven_pairs(self):
        pairs = set([tile for tile in self.tiles if self.tiles.count(tile) == 2])
        return len(pairs) == 7

    # Check for All Pungs hand
    def is_all_pungs(self):
        return all(self.tiles.count(tile) == 3 for tile in self.tiles) and len(set(self.tiles)) == 4

    # Check for All Chows hand
    def is_all_chows(self):
        return all(self.tiles.count(tile) == 3 for tile in self.tiles) and len(set(self.tiles)) == 4

    # Placeholder for Mixed Shifted Chows check
    def is_mixed_shifted_chows(self):
        return False

    # Check for All Terminals and Honors hand
    def is_all_terminals_and_honors(self):
        terminal_honor_tiles = ['1m', '9m', '1p', '9p', '1s', '9s', 'E', 'S', 'W', 'N', 'C', 'F', 'B']
        return all(tile in terminal_honor_tiles for tile in self.tiles)

    # Check for All Simples hand
    def is_all_simples(self):
        simple_tiles = ['2m', '3m', '4m', '5m', '6m', '7m', '8m',
                        '2p', '3p', '4p', '5p', '6p', '7p', '8p',
                        '2s', '3s', '4s', '5s', '6s', '7s', '8s']
        return all(tile in simple_tiles for tile in self.tiles)

    # Check for Half Flush (two suits)
    def is_half_flush(self):
        suits = set([tile[-1] for tile in self.tiles])
        return len(suits) == 2

    # Check for Full Flush (one suit)
    def is_full_flush(self):
        suits = set([tile[-1] for tile in self.tiles])
        return len(suits) == 1

# Import necessary libraries
import numpy as np
from collections import Counter
from statistics import mean, median, mode, stdev, variance, quantiles

def flatten(lst):
    """Flatten a nested list."""
    result = []
    for i in lst:
        if isinstance(i, list):
            result.extend(flatten(i))
        else:
            result.append(i)
    return result

def remove_duplicates(lst):
    """Remove duplicates from a list while preserving order."""
    seen = set()
    result = []
    for item in lst:
        if item not in seen:
            seen.add(item)
            result.append(item)
    return result

def process_lists(list1, list2, operations):
    # Input validation
    if not isinstance(list1, list) or not isinstance(list2, list) or not isinstance(operations, list):
        return "Error: All inputs must be lists."

    # Check for empty lists
    if not list1 and not list2:
        return "Error: Both lists are empty."

    # Return original lists if no operations specified
    if not operations:
        return list1, list2

    results = []
    for operation in operations:
        try:
            if operation == "merge":
                result = list1 + list2
            elif operation == "common_elements":
                result = list(set(flatten(list1)) & set(flatten(list2)))
            elif operation == "unique_elements":
                result = list(set(flatten(list1)) ^ set(flatten(list2)))
            elif operation == "sort_in_descending":
                result = sorted(flatten(list1 + list2), reverse=True)
            elif operation == "element_difference":
                result = [x - y for x, y in zip(flatten(list1), flatten(list2))]
            elif operation == "length_of_list":
                result = [len(flatten(list1)), len(flatten(list2))]
            elif operation == "sum_of_elements":
                result = [sum(flatten(list1)), sum(flatten(list2))]
            elif operation == "average_of_elements":
                result = [mean(flatten(list1)), mean(flatten(list2))]
            elif operation == "max_element":
                result = [max(flatten(list1)), max(flatten(list2))]
            elif operation == "min_element":
                result = [min(flatten(list1)), min(flatten(list2))]
            elif operation == "flatten_nested_list":
                result = flatten(list1 + list2)
            elif operation == "remove_duplicates":
                result = remove_duplicates(flatten(list1 + list2))
            elif operation == "find_median":
                result = [median(flatten(list1)), median(flatten(list2))]
            elif operation == "find_mode":
                result = [mode(flatten(list1)), mode(flatten(list2))]
            elif operation == "find_range":
                result = [max(flatten(list1)) - min(flatten(list1)), max(flatten(list2)) - min(flatten(list2))]
            elif operation == "find_standard_deviation":
                result = [stdev(flatten(list1)), stdev(flatten(list2))]
            elif operation == "find_variance":
                result = [variance(flatten(list1)), variance(flatten(list2))]
            elif operation == "find_percentile":
                result = [np.percentile(flatten(list1), 50), np.percentile(flatten(list2), 50)]
            elif operation == "find_quartile":
                result = [quantiles(flatten(list1), n=4), quantiles(flatten(list2), n=4)]
            elif operation == "find_interquartile_range":
                q1, q3 = quantiles(flatten(list1), n=4)[1], quantiles(flatten(list1), n=4)[2]
                result = [q3 - q1, q3 - q1]
            else:
                return f"Error: Undefined operation '{operation}'."

            # Sort result in descending order before appending
            results.append(sorted(result, reverse=True))
        except Exception as e:
            return f"Error: {e}"

    return results

# Example usage
list1 = [1, 2, [3, 4], 5]
list2 = [4, 5, [6, 7], 8]
operations = ["merge", "common_elements", "unique_elements", "sort_in_descending"]

print(process_lists(list1, list2, operations))

# URL Manager module
import re
import random
import string
import logging

# Configure logging
logging.basicConfig(
    level=logging.DEBUG, 
    format='%(asctime)s - %(levelname)s - %(message)s'
)

class URLManager:
    def __init__(self, protocol, subdomain, primary_domain, cc_tld, resource_path):
        self.protocol = protocol
        self.subdomain = subdomain
        self.primary_domain = primary_domain
        self.cc_tld = cc_tld
        self.resource_path = resource_path

    def construct_url(self):
        # Validate components before constructing URL
        if not self.validate_components():
            return None

        # Construct and return the URL
        return f"{self.protocol}://{self.subdomain}.{self.primary_domain}{self.cc_tld}/{self.encode_resource_path()}"

    def deconstruct_url(self, url):
        # Regular expression pattern for URL parsing
        pattern = r'^(?P<protocol>[a-zA-Z]+)://(?P<subdomain>[a-zA-Z0-9-]+)\.(?P<primary_domain>[a-zA-Z0-9-]+)(?P<cc_tld>\.[a-zA-Z]{2,6})/(?P<resource_path>.+)$'

        match = re.match(pattern, url)
        if match:
            return match.groupdict()
        else:
            logging.error(f"Invalid URL format: {url}")
            return None

    def validate_components(self):
        # Check if all components are provided
        if not self.protocol or not self.subdomain or not self.primary_domain or not self.cc_tld or not self.resource_path:
            logging.error("All URL components must be provided.")
            return False

        # Validate protocol
        if self.protocol not in ['http', 'https', 'ftp', 'sftp']:
            logging.error(f"Unsupported protocol: {self.protocol}")
            return False

        # Validate subdomain
        if not re.match(r'^[a-zA-Z0-9-]+$', self.subdomain):
            logging.error(f"Invalid subdomain: {self.subdomain}")
            return False

        # Validate primary domain
        if not re.match(r'^[a-zA-Z0-9-]+$', self.primary_domain):
            logging.error(f"Invalid primary domain: {self.primary_domain}")
            return False

        # Validate country code top-level domain
        if not re.match(r'^\.[a-zA-Z]{2,6}$', self.cc_tld):
            logging.error(f"Invalid country code top-level domain: {self.cc_tld}")
            return False

        return True

    def encode_resource_path(self, random_encode=False):
        # Choose encoding method based on parameter
        if random_encode:
            return self.random_encode_resource_path()
        else:
            return self.sequential_encode_resource_path()

    def sequential_encode_resource_path(self):
        # Encode special characters using sequential percent-encoding
        return re.sub(
            r'[^a-zA-Z0-9/]', 
            lambda match: f"%{ord(match.group(0)):02X}", 
            self.resource_path
        )

    def random_encode_resource_path(self):
        # Randomly encode special characters
        encoded_path = ""
        for char in self.resource_path:
            if re.match(r'[^a-zA-Z0-9/]', char):
                if random.choice([True, False]):
                    encoded_path += f"%{ord(char):02X}"
                else:
                    encoded_path += char
            else:
                encoded_path += char
        return encoded_path

# Import necessary modules
import psutil
import time
from datetime import datetime, timedelta

# List of common web browser process names
BROWSER_PROCESSES = ['chrome', 'firefox', 'safari', 'microsoftedge', 'opera', 'brave']

def get_active_window_title():
    """ Get the title of the active window. """
    import os

    if os.name == 'nt':  # Windows
        try:
            import win32gui
            return win32gui.GetWindowText(win32gui.GetForegroundWindow())
        except ImportError:
            print("Please install pywin32: pip install pywin32")
            return None

    elif os.name == 'posix':  # Linux and macOS
        try:
            import subprocess
            return subprocess.check_output(["xdotool", "getwindowfocus", "getwindowname"]).strip().decode()
        except ImportError:
            print("Please install xdotool: sudo apt-get install xdotool")
            return None
    else:
        return None

def is_browser_active():
    """ Check if the active window belongs to a web browser. """
    active_window_title = get_active_window_title()

    if active_window_title:
        for process in BROWSER_PROCESSES:
            if process in active_window_title.lower():
                return True

    return False

def track_browser_time():
    """ Track the time spent in a web browser. """
    start_time = None
    total_time = timedelta()

    while True:
        if is_browser_active():
            if start_time is None:
                start_time = datetime.now()
        else:
            if start_time:
                end_time = datetime.now()
                total_time += end_time - start_time
                start_time = None

                # Print current browser usage time
                print(f"Time spent in browser: {total_time}")

        time.sleep(1)  # Check every second

if __name__ == "__main__":
    track_browser_time()

# Import necessary modules
from math import isqrt
from functools import reduce
from operator import mul

def is_prime(n):
    """Check if a number is a prime number."""
    # Handle edge cases
    if n <= 1:
        return False
    if n <= 3:
        return True
    # Eliminate multiples of 2 and 3
    if n % 2 == 0 or n % 3 == 0:
        return False

    # Check for factors up to sqrt(n) using 6k ± 1 optimization
    for i in range(5, isqrt(n) + 1, 6):
        if n % i == 0 or n % (i + 2) == 0:
            return False

    return True

def find_prime_numbers(input_lists):
    results = []

    # Process each list in the input
    for input_list in input_lists:
        prime_numbers = []

        try:
            # Iterate through numbers in the current list
            for num in input_list:
                # Validate that the number is an integer
                if isinstance(num, int):
                    if is_prime(num):
                        prime_numbers.append(num)
                else:
                    raise ValueError(f"Invalid input: {num} is not an integer")

        except Exception as e:
            print(f"Error processing list: {e}")
            continue

        # Sort primes in ascending order
        prime_numbers.sort()

        # Calculate product of primes (1 if no primes found)
        product_of_primes = reduce(mul, prime_numbers, 1) if prime_numbers else 1

        # Store result as tuple of (primes_list, product)
        results.append((prime_numbers, product_of_primes))

    return results

