# Flask application for managing notes
from flask import Flask, request, jsonify, g
import sqlite3

app = Flask(__name__)
DATABASE = 'notes.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    with app.app_context():
        db = get_db()
        with app.open_resource('schema.sql', mode='r') as f:
            db.cursor().executescript(f.read())
        db.commit()

@app.route('/notes', methods=['GET'])
def get_notes():
    db = get_db()
    cursor = db.execute('SELECT id, title, content FROM notes')
    notes = cursor.fetchall()
    return jsonify([{'id': note[0], 'title': note[1], 'content': note[2]} for note in notes])

@app.route('/notes', methods=['POST'])
def create_note():
    data = request.get_json()
    title = data.get('title')
    content = data.get('content')

    if not title or not content:
        return jsonify({'error': 'Title and content are required'}), 400

    db = get_db()
    db.execute('INSERT INTO notes (title, content) VALUES (?, ?)', (title, content))
    db.commit()
    return jsonify({'message': 'Note created successfully'}), 201

@app.route('/notes/<int:note_id>', methods=['GET'])
def get_note(note_id):
    db = get_db()
    cursor = db.execute('SELECT id, title, content FROM notes WHERE id = ?', (note_id,))
    note = cursor.fetchone()

    if note is None:
        return jsonify({'error': 'Note not found'}), 404

    return jsonify({'id': note[0], 'title': note[1], 'content': note[2]})

@app.route('/notes/<int:note_id>', methods=['PUT'])
def update_note(note_id):
    data = request.get_json()
    title = data.get('title')
    content = data.get('content')

    if not title or not content:
        return jsonify({'error': 'Title and content are required'}), 400

    db = get_db()
    cursor = db.execute('UPDATE notes SET title = ?, content = ? WHERE id = ?', (title, content, note_id))

    if cursor.rowcount == 0:
        return jsonify({'error': 'Note not found'}), 404

    db.commit()
    return jsonify({'message': 'Note updated successfully'})

@app.route('/notes/<int:note_id>', methods=['DELETE'])
