ht.insert('apple', 10)
ht.insert('banana', 20)

print(ht.get('apple'))  # Output: 10

ht.delete('banana')
print(ht)  # Output: [None, ..., [('apple', 10)], ..., None]

# Code analysis script using AST and Pylint
import ast
import pylint.lint
import astroid
from pylint.reporters import text

def analyze_code(code):
    # Parse the code into an AST (Abstract Syntax Tree)
    tree = ast.parse(code)

    # Use Pylint to analyze the code
    pylint_runner = pylint.lint.PyLinter(reporter=text.TextReporter())
    pylint_runner.load_default_plugins()
    pylint_runner.check(astroid.builder.parse(code))

    # Collect Pylint messages
    messages = []
    for msg in pylint_runner.reporter.messages:
        messages.append({
            'line': msg.line,
            'column': msg.column,
            'message': msg.msg,
            'type': msg.symbol
        })

    return tree, messages

def suggest_improvements(tree, messages):
    suggestions = []

    # Example: Suggest using list comprehensions for better readability
    for node in ast.walk(tree):
        if isinstance(node, ast.ListComp):
            suggestions.append({
                'line': node.lineno,
                'column': node.col_offset,
                'suggestion': "Consider using a list comprehension for better readability."
            })

    # Example: Suggest using set() for membership tests for better time complexity
    for msg in messages:
        if msg['type'] == 'consider-using-set':
            suggestions.append({
                'line': msg['line'],
                'column': msg['column'],
                'suggestion': "Consider using a set for membership tests to improve time complexity."
            })

    return suggestions

def main(code):
    tree, messages = analyze_code(code)
    suggestions = suggest_improvements(tree, messages)

    print("Code Analysis:")
    for msg in messages:
        print(f"Line {msg['line']}, Column {msg['column']}: {msg['message']} ({msg['type']})")

    print("\nSuggestions for Improvement:")
    for suggestion in suggestions:
        print(f"Line {suggestion['line']}, Column {suggestion['column']}: {suggestion['suggestion']}")

