import os
from os.path import join, getsize

# Function to calculate total size of a folder recursively
def GetFolderSize(path):
    TotalSize = 0

    # Iterate through directory entries
    for entry in os.scandir(path):
        if entry.is_file():
            try:
                # Add file size to total
                TotalSize += entry.stat().st_size
            except OSError:
                print("error with file: " + entry.path)
        elif entry.is_dir():
            # Recursively add subdirectory size
            TotalSize += GetFolderSize(entry.path)

    return TotalSize

