# Import necessary libraries
import numpy as np

class Connect4Environment:
    def __init__(self):
        # Initialize board dimensions and state
        self.rows = 6
        self.columns = 7
        self.board = np.zeros((self.rows, self.columns), dtype=int)
        self.current_player = 1

    # Check if a move is valid (column not full)
    def _is_valid_move(self, column):
        return self.board[0, column] == 0

    # Drop a piece in the specified column
    def _make_move(self, column):
        for row in range(self.rows - 1, -1, -1):
            if self.board[row, column] == 0:
                self.board[row, column] = self.current_player
                break

    # Check if there's a winner on the board
    def _check_winner(self):
        directions = [(-1, 0), (0, -1), (-1, -1), (-1, 1)]
        for row in range(self.rows):
            for col in range(self.columns):
                if self.board[row, col] == 0:
                    continue
                for dr, dc in directions:
                    if self._check_line(row, col, dr, dc):
                        return self.board[row, col]
        return 0

    # Helper function to check a line of 4 pieces
    def _check_line(self, row, col, dr, dc):
        player = self.board[row, col]
        for _ in range(4):
            if not (0 <= row < self.rows and 0 <= col < self.columns) or self.board[row, col] != player:
                return False
            row += dr
            col += dc
        return True

    # Execute one step in the environment
    def step(self, action):
        if not self._is_valid_move(action):
            return self.board.copy(), -1, False, "Invalid move"

        self._make_move(action)
        reward = 0
        done = False
        winner = self._check_winner()

        if winner == self.current_player:
            reward = 1
            done = True
        elif np.all(self.board != 0):
            done = True

        self.current_player = 3 - self.current_player  # Switch player (1 -> 2, 2 -> 1)
        return self.board.copy(), reward, done, {}

    # Reset the environment to initial state
    def reset(self):
        self.board = np.zeros((self.rows, self.columns), dtype=int)
        self.current_player = 1
        return self.board.copy()

    # Render the current board state
    def render(self):
        print(self.board)

# Traverses a nested dictionary/list structure and prints paths to leaf values
def traverse_dict(d, path=None):
    # Initialize path if not provided
    if path is None:
        path = []

    # Handle dictionary case
    if isinstance(d, dict):
        for key, value in d.items():
            new_path = path + [key]
            print(f"{' -> '.join(map(str, new_path))}: {value}")
            traverse_dict(value, new_path)

    # Handle list case
    elif isinstance(d, list):
        for index, item in enumerate(d):
            new_path = path + [index]
            print(f"{' -> '.join(map(str, new_path))}: {item}")
            traverse_dict(item, new_path)

    # Handle leaf node (neither dict nor list)
    else:
        print(f"{' -> '.join(map(str, path))}: {d}")

