from django.http import JsonResponse, FileResponse
from rest_framework import status

class WebUtils:
    @staticmethod
    def response_success(response_data={}, message=""):
        # Returns a success JSON response with HTTP 200 status
        return JsonResponse(
            {
                "data": response_data,
                "result": True,
                "message": message
            },
            status=status.HTTP_200_OK
        )

    @staticmethod
    def response_error(response_data={}, error_message="", status_code=status.HTTP_400_BAD_REQUEST):
        # Returns an error JSON response with specified status code (default 400)
        return JsonResponse(
            {
                "data": response_data,
                "result": False,
                "message": error_message
            },
            status=status_code
        )

    @staticmethod
    def response_401(message):
        # Returns a 401 Unauthorized JSON response
        return JsonResponse(
            {
                "result": False,
                "message": message
            },
            status=status.HTTP_401_UNAUTHORIZED
        )

    @staticmethod
    def response_403(message):
        # Returns a 403 Forbidden JSON response
        return JsonResponse(
            {
                "result": False,
                "message": message
            },
            status=status.HTTP_403_FORBIDDEN
        )

    @staticmethod
    def response_file(file, filename):
        # Handles file response for download
        if isinstance(file, bytes):
            file = io.BytesIO(file)

        response = FileResponse(
            file,
            content_type="application/octet-stream"
        )
        response['Content-Disposition'] = f'attachment; filename="{filename}"'
        return response

# Function to sort numbers by sum of their digits
def order_by_points(nums):
    """
    Write a function which sorts the given list of integers
    in ascending order according to the sum of their digits.
    Note: if there are several items with similar sum of their digits,
    order them based on their index in original list.
    For example:
    >>> order_by_points([1, 11, -1, -11, -12]) == [-1, -11, 1, -12, 11]
    >>> order_by_points([]) == []
    """

    # Helper function to calculate digit sum
    def digit_sum(n):
        s = str(n)
        if s[0] == '-':
            return -int(s[1]) + sum(int(d) for d in s[2:])
        else:
            return sum(int(d) for d in s)

    # Return sorted list based on digit sum
    return sorted(nums, key=digit_sum)

