import dataclasses
import einops
import numpy as np

from openpi import transforms
from openpi.models import model as _model


def make_gsenv_example() -> dict:
    """Creates a random input example for the GSEnv policy."""
    return {
        "observation/state": np.random.rand(8),
        "observation/image": np.random.randint(256, size=(480, 640, 3), dtype=np.uint8),
        "prompt": "do something",
    }


def _parse_image(image) -> np.ndarray:
    # Convert input to numpy array
    image = np.asarray(image)

    # Handle floating-point images
    if np.issubdtype(image.dtype, np.floating):
        image = (255 * image).astype(np.uint8)

    # Rearrange channel-first to channel-last format if needed
    if image.shape[0] == 3:
        image = einops.rearrange(image, "c h w -> h w c")

    return image


@dataclasses.dataclass(frozen=True)
class GSEnvInputs(transforms.DataTransformFn):
    model_type: _model.ModelType

    def __call__(self, data: dict) -> dict:
        # Process base image
        base_image = _parse_image(data["observation/image"])

        # Construct input dictionary
        inputs = {
            "state": data["observation/state"],
            "image": {
                "base_0_rgb": base_image,
                "left_wrist_0_rgb": np.zeros_like(base_image),
                "right_wrist_0_rgb": np.zeros_like(base_image),
            },
            "image_mask": {
                "base_0_rgb": np.True_,
                "left_wrist_0_rgb": np.False_,
                "right_wrist_0_rgb": np.False_,
            },
        }

        # Add actions if present
        if "actions" in data:
            inputs["actions"] = data["actions"]

        # Add prompt if present
        if "prompt" in data:
            inputs["prompt"] = data["prompt"]

        return inputs


@dataclasses.dataclass(frozen=True)
class GSEnvOutputs(transforms.DataTransformFn):
    def __call__(self, data: dict) -> dict:
        # Extract first 7 action dimensions
        return {"actions": np.asarray(data["actions"][:, :7])}

