import json
from io import BytesIO


class DummyResponse:
    """Minimal HTTP response stand-in."""

    def __init__(self, status=200, body=None):
        self.status = status
        self._body = body or {}

    def read(self):
        return json.dumps(self._body).encode("utf-8")


class DummyHTTPConnection:
    """Stand-in for http.client.HTTPConnection.
    Records requests and returns configured responses for
    ExternalRFClient integration testing without real HTTP.
    """

    def __init__(self, host="localhost", port=8270, timeout=5):
        self.host = host
        self.port = port
        self.timeout = timeout
        self.requests = []
        self._response = DummyResponse()
        self._connected = False

    def connect(self):
        self._connected = True

    def close(self):
        self._connected = False

    def request(self, method, path, body=None, headers=None):
        parsed_body = json.loads(body) if isinstance(body, str) else body
        self.requests.append({
            "method": method,
            "path": path,
            "body": parsed_body,
            "headers": headers or {},
        })

    def getresponse(self):
        return self._response

    def set_response(self, status=200, body=None):
        """Configure the response to return."""
        self._response = DummyResponse(status=status, body=body)
        return self

    def get_last_request(self):
        """Get the most recent request, or None."""
        return self.requests[-1] if self.requests else None

# Import necessary modules
import torch.fx as fx
from graph_net.torch.dim_gen_passes import DimensionGeneralizationPass
from collections import namedtuple
import os
import operator


class ConcretePass(DimensionGeneralizationPass):
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)

    def get_pass_name(cls) -> bool:
        return os.path.basename(__file__)[:-3]

    def need_rewrite(self, traced_module: fx.GraphModule) -> bool:
        # non batch
        if 0 in self.axes:
            return False
        return any(self._node_need_rewrite(node) for node in traced_module.graph.nodes)

    def _node_target(self):
        return torch.full

    def _node_need_rewrite(self, node) -> bool:
        if not (node.op == "call_function"):
            return False
        if not (node.target == self._node_target()):
            return False
        if not (len(node.args) == 1):
            return False
        if not (any(dim == self.dim + self._dyn_dim_delta() for dim in node.args[0])):
            return False
        if not (any(self._is_triu(downstream) for downstream in node.users)):
            return False
        return True

    def _dyn_dim_delta(self):
        return 1

    def _is_triu(self, node):
        return node.op == "call_function" and node.target == torch.triu

    def rewrite(self, traced_module: fx.GraphModule) -> fx.GraphModule:
        # Create a new graph to hold the rewritten nodes
        new_graph = fx.Graph()

        # Create a map to link nodes from the old graph to nodes in the new graph
        val_map = {}

        NodeAxis = namedtuple("NodeAxis", ["node", "shape_axis"])
        last_node_axis = None

        def try_reset_last_node_axis(node, new_node):
            nonlocal last_node_axis
            node_meta = node.meta.get("tensor_meta")
            if node_meta is None:
                return
            if not hasattr(node_meta, "shape"):
                return
            for axis, dim in enumerate(node_meta.shape):
                if not (dim == self.dim and axis > 0):
                    continue
                last_node_axis = NodeAxis(node=new_node, shape_axis=axis)
                return

        def get_new_node_dim(i, dim):
            if not (dim == self.dim + self._dyn_dim_delta()):
                return val_map[dim] if dim in val_map else dim
            assert dim == self.dim + self._dyn_dim_delta()
            # Use the size() method to retrieve the dynamic dimension
            size_node = new_graph.call_method(
                "size", args=(last_node_axis.node, last_node_axis.shape_axis)
            )
            plus_one_node = new_graph.call_function(operator.add, args=(size_node, 1))
            return plus_one_node

        def create_new_node(node):
            if not (self._node_need_rewrite(node) and last_node_axis is not None):
                # Copy other nodes to the new graph
                new_node = new_graph.node_copy(node, lambda x: val_map[x])
                try_reset_last_node_axis(node=node, new_node=new_node)
                return new_node

            new_node_dims = tuple(
                get_new_node_dim(i, dim) for i, dim in enumerate(node.args[0])
            )
            new_node = new_graph.call_function(
                self._node_target(), args=(new_node_dims,), kwargs=node.kwargs
            )
            return new_node

        for node in traced_module.graph.nodes:
            val_map[node] = create_new_node(node)

        # Replace the old graph with the new graph and return
        traced_module.graph = new_graph
        traced_module.recompile()
        return traced_module

# Import required modules
import sys
import os
import json
import re
import urllib.request
import urllib.error

# Environment variables for API configuration
AGENT_ID = os.environ.get("ELEVENLABS_AGENT_ID", "")
API_KEY = os.environ.get("ELEVENLABS_API_KEY", "")
PHONE_NUMBER_ID = os.environ.get("ELEVENLABS_PHONE_NUMBER_ID", "")

# API endpoint URL
API_URL = "https://api.elevenlabs.io/v1/convai/twilio/outbound-call"


def make_call(to_number: str, first_message: str = "", context: str = "") -> dict:
    """
    Place an outbound call to the given phone number.

    Args:
        to_number: Phone number in E.164 format (+1XXXXXXXXXX for US).
        first_message: Optional custom greeting for this call.
        context: Optional context to pass as a dynamic variable.
    """
    # Validate API credentials are set
    if not API_KEY:
        return {"error": "ELEVENLABS_API_KEY not set. Add it to your .env file."}

    if not AGENT_ID:
        return {"error": "ELEVENLABS_AGENT_ID not set. Add it to your .env file."}

    if not PHONE_NUMBER_ID:
        return {"error": "ELEVENLABS_PHONE_NUMBER_ID not set. Add it to your .env file."}

    # Validate E.164 format (US numbers: +1 followed by 10 digits)
    if not re.match(r'^\+1\d{10}$', to_number):
        return {
            "error": f"Invalid US phone number: {to_number}. Use +1XXXXXXXXXX format (E.164)."
        }

    # Build request payload
    payload = {
        "agent_id": AGENT_ID,
        "agent_phone_number_id": PHONE_NUMBER_ID,
        "to_number": to_number,
    }

    # Add optional overrides if provided
    client_data = {}
    if first_message:
        client_data["conversation_config_override"] = {
            "agent": {"first_message": first_message}
        }
    if context:
        client_data["dynamic_variables"] = {"call_context": context}

    if client_data:
        payload["conversation_initiation_client_data"] = client_data

    # Prepare and send request
    data = json.dumps(payload).encode()
    req = urllib.request.Request(
        API_URL, 
        data=data, 
        headers={
            "xi-api-key": API_KEY,
            "Content-Type": "application/json",
        }
    )

    try:
        with urllib.request.urlopen(req) as resp:
            result = json.loads(resp.read())

            # Handle API errors even on HTTP 200
            if not result.get("success", True) or "error" in result:
                return {
                    "error": result.get("error", result.get("message", "Unknown API error"))
                }

            return {
                "success": True,
                "conversation_id": result.get("conversation_id", ""),
                "call_sid": result.get("callSid", ""),
                "message": result.get("message", "Call initiated"),
            }

    except urllib.error.HTTPError as e:
        body = e.read().decode()
        return {
            "error": f"ElevenLabs API error (HTTP {e.code}): {body}"
        }
    except urllib.error.URLError as e:
        return {"error": f"Network error: {e.reason}"}


if __name__ == "__main__":
    # Check command line arguments
    if len(sys.argv) < 2:
        print(json.dumps({"error": "Usage: call.py <phone_number> [first_message] [context]"}))
        sys.exit(1)

    # Parse arguments
    to = sys.argv[1]
    first_msg = sys.argv[2] if len(sys.argv) > 2 else ""
    ctx = sys.argv[3] if len(sys.argv) > 3 else ""

    # Make the call
    result = make_call(to, first_msg, ctx)

    # Output result and exit with appropriate code
    print(json.dumps(result, indent=2))
    sys.exit(0 if result.get("success") else 1)

