    request_id: str
    error: ResponseError

    @classmethod
    def from_dict(cls, d: dict):
        c = cls(
            request_id="",
            error=ResponseError(
                code="",
            ),
        )
        if "RequestId" in d:
            c.request_id = d["RequestId"]
        if "Error" in d:
            c.error = ResponseError.from_dict(d["Error"])
        return c

    @staticmethod
    def get_default_response_metadata():
        return ResponseMetaData(
            request_id="",
            error=ResponseError(
                code="",
            ),
        )


