import re
import json
import os

def parse_tools(filepath):
    # Check if file exists
    if not os.path.exists(filepath):
        return {}

    # Read file content
    with open(filepath, "r", encoding="utf-8") as f:
        content = f.read()

    # Initialize tools dictionary
    tools = {}

    # Define regex pattern to extract tool metadata
    pattern = r"@mcp\.tool\(\s*name=[\"\'\']([^\"\']+?)[\"\'\'],\s*description=[\"\'\']([^\"\']+?)[\"\'\']"

    # Find all matches and populate tools dict
    for match in re.finditer(pattern, content):
        tools[match.group(1)] = match.group(2)

    return tools


def parse_directory_tools(directory):
    # Aggregate tools from all Python files in directory
    all_tools = {}
    for root, _, files in os.walk(directory):
        for file in files:
            if file.endswith(".py"):
                all_tools.update(parse_tools(os.path.join(root, file)))
    return all_tools


