# Save API key securely using keyring
def save_key(provider, key):
    if not KEYRING_AVAILABLE:
        print("[warn] 'keyring' not found. Cannot save credentials securely.")
        return False

    try:
        keyring.set_password(SERVICE_NAME, provider, key)
        return True
    except Exception as e:
        print(f"[warn] Failed to save to keyring: {e}")
        return False

# Retrieve API key from environment or keyring
def get_key(provider):
    env_var = PROVIDERS.get(provider)
    if env_var:
        key = os.getenv(env_var)
        if key:
            return key

    if KEYRING_AVAILABLE:
        try:
            return keyring.get_password(SERVICE_NAME, provider)
        except Exception:
            pass

    return None

# Delete stored API key from keyring
def delete_key(provider):
    try:
        import keyring
    except Exception:
        return False

    service = "skylos"
    username = str(provider)

    try:
        keyring.delete_password(service, username)
        return True
    except Exception:
        return False

