        port = find_free_ports(1, (10000, 60000))[0]
        return host_ip, port

    # Create remote task with resource constraints and scheduling strategy
    future = ray.remote(
        num_cpus=1,
        num_gpus=0,
        memory=10 * 1024 * 1024,  # Convert MB to bytes
        scheduling_strategy=PlacementGroupSchedulingStrategy(
            placement_group=placement_group,
            placement_group_bundle_index=placement_group_bundle_index,
        ),
    )(_master_ip_and_port).remote()

    # Wait for result and return
    return ray.get(future)


def create_resource_spec(device, cpu: int, gpu: int, mem_in_bytes: int):
    # Build resource specification dictionary
    res = {"num_cpus": cpu, "memory": mem_in_bytes}

    if device == "GPU":
        res["num_gpus"] = float(gpu)
    elif device != "CPU":
        res["resources"] = {device: float(gpu)}

    return res

