# Import necessary modules
import contextlib
import joblib
from tqdm.autonotebook import tqdm

@contextlib.contextmanager
def tqdm_joblib(*args, **kwargs):
    """
    Context manager to patch joblib to report into tqdm progress bar
    given as argument
    """
    # Initialize the tqdm progress bar
    tqdm_object = tqdm(*args, **kwargs)

    # Define custom callback class
    class TqdmBatchCompletionCallback(joblib.parallel.BatchCompletionCallBack):
        def __init__(self, *args, **kwargs):
            super().__init__(*args, **kwargs)

        def __call__(self, *args, **kwargs):
            # Update progress bar with batch size
            tqdm_object.update(n=self.batch_size)
            return super().__call__(*args, **kwargs)

    # Save original callback and replace with our custom one
    old_batch_callback = joblib.parallel.BatchCompletionCallBack
    joblib.parallel.BatchCompletionCallBack = TqdmBatchCompletionCallback

    try:
        yield tqdm_object
    finally:
        # Restore original callback and close progress bar
        joblib.parallel.BatchCompletionCallBack = old_batch_callback
        tqdm_object.close()

def ParallelPbar(desc=None, **tqdm_kwargs):
    """Create a Parallel class with tqdm progress bar integration"""

    class Parallel(joblib.Parallel):
        def __call__(self, it):
            # Convert iterator to list for length calculation
            it = list(it)

            if self.n_jobs == 1:
                # For single job, directly wrap with tqdm
                it = tqdm(it, desc=desc, **tqdm_kwargs)
                return super().__call__(it)
            else:
                # For parallel jobs, use context manager
                with tqdm_joblib(total=len(it), desc=desc, **tqdm_kwargs):
                    return super().__call__(it)

    return Parallel

