# Determine if dictionary has consistent key-value case patterns
def verify_dictionary_cases(data):
    # Handle empty dictionary case
    if not data:
        return False

    # Count lowercase and uppercase keys
    lower_keys = sum([key.islower() for key in data.keys()])
    upper_keys = sum([key.isupper() for key in data.keys()])

    # Check if all keys are lowercase and all values are lowercase
    if lower_keys == len(data):
        return all(val.islower() for val in data.values())
    # Check if all keys are uppercase and all values are uppercase
    elif upper_keys == len(data):
        return all(val.isupper() for val in data.values())
    else:
        return False

# Calculate areas for different types of sectors
import math

def compute_circular_sector_areas(sector_data):
    def circular_sector_area(radius, angle_deg):
        if radius < 0 or angle_deg < 0 or angle_deg > 360:
            return None
        area = (angle_deg / 360) * math.pi * radius ** 2
        # Check if radius is a float with more than 2 decimal places
        if isinstance(radius, float) and len(str(radius).split('.')[1]) > 2:
            return round(area, 2)
        else:
            return area

    return [circular_sector_area(radius, angle) for radius, angle in sector_data]

def compute_spherical_sector_areas(sector_data):
    def spherical_sector_area(radius, angle_deg):
        if radius < 0 or angle_deg < 0 or angle_deg > 360:
            return None
        half_angle_rad = math.radians(angle_deg / 2)
        area = 2 * math.pi * radius ** 2 * (1 - math.cos(half_angle_rad))
        # Check if radius is a float with more than 2 decimal places
        if isinstance(radius, float) and len(str(radius).split('.')[1]) > 2:
            return round(area, 2)
        else:
            return area

    return [spherical_sector_area(radius, angle) for radius, angle in sector_data]

