# Find all possible paths in a graph from start to end 
def locate_all_routes(adjacency, origin, destination, route=[]):
    route = route + [origin]
    if origin == destination:
        return [route]
    if origin not in adjacency:
        return []
    routes = []
    for neighbor in adjacency[origin]:
        if neighbor not in route:
            subroutes = locate_all_routes(adjacency, neighbor, destination, route)
            for subroute in subroutes:
                routes.append(subroute)
    return routes

def identify_shared_vertices(routes):
    if not routes:
        return []
    shared_vertices = set(routes[0])
    for route in routes[1:]:
        shared_vertices.intersection_update(route)
    return shared_vertices

