# Person class representing an individual with family relationships
class Individual:
    def __init__(self, full_name, date_of_birth, sex):
        self.full_name = full_name
        self.date_of_birth = date_of_birth
        self.sex = sex
        self.ancestors = []
        self.partner = None
        self.offspring = []

    def add_ancestor(self, ancestor):
        if ancestor not in self.ancestors:
            self.ancestors.append(ancestor)
            if self not in ancestor.offspring:
                ancestor.offspring.append(self)

    def add_partner(self, partner):
        if self.partner is None:
            self.partner = partner
            if partner.partner is None:
                partner.partner = self

    def add_offspring(self, child):
        if child not in self.offspring:
            self.offspring.append(child)
            if self not in child.ancestors:
                child.ancestors.append(self)

    def __str__(self):
        return f"Individual(full_name={self.full_name}, date_of_birth={self.date_of_birth}, sex={self.sex})"

# Determine if a number is prime
def check_prime(value):
    if value < 2:
        return False
    for divisor in range(2, int(value**0.5) + 1):
        if value % divisor == 0:
            return False
    return True

# Get all prime factors of a number
def get_prime_factors(value):
    factors_list = []
    for potential_factor in range(2, value + 1):
        while value % potential_factor == 0:
            factors_list.append(potential_factor)
            value //= potential_factor
    return factors_list

# Calculate frequency of prime factors for numbers below n
def compute_prime_factor_frequency(limit):
    if limit < 2:
        return {}

    frequency_dict = {}

    for current_number in range(2, limit):
        prime_factors_list = get_prime_factors(current_number)
        for factor in prime_factors_list:
            if factor in frequency_dict:
                frequency_dict[factor] += 1
            else:
                frequency_dict[factor] = 1

    return frequency_dict

