# Employee Management System Implementation
from datetime import datetime
import uuid

class StaffMember:
    def __init__(self, full_name, years_old, compensation, position, hire_date):
        self.identifier = str(uuid.uuid4())  # Unique identifier for each staff member
        self.full_name = full_name
        self.years_old = years_old
        self.compensation = compensation
        self.position = position
        self.hire_date = hire_date

    def compute_tenure(self):
        current_date = datetime.today()
        commencement_date = datetime.strptime(self.hire_date, '%Y-%m-%d')
        days_worked = (current_date - commencement_date).days
        return days_worked // 365

    def __str__(self):
        return f"ID: {self.identifier}, Name: {self.full_name}, Age: {self.years_old}, Compensation: {self.compensation}, Position: {self.position}, Hire Date: {self.hire_date}"

class HumanResourcesSystem:
    def __init__(self):
        self.staff_members = []

    def add_staff_member(self, full_name, years_old, compensation, position, hire_date):
        new_member = StaffMember(full_name, years_old, compensation, position, hire_date)
        self.staff_members.append(new_member)
        print(f"Staff member {full_name} added successfully.")

    def remove_staff_member(self, member_id):
        for member in self.staff_members:
            if member.identifier == member_id:
                self.staff_members.remove(member)
                print(f"Staff member with ID {member_id} removed successfully.")
                return
        print(f"Staff member with ID {member_id} not found.")

    def modify_staff_member(self, member_id, **kwargs):
        for member in self.staff_members:
            if member.identifier == member_id:
                for attribute, val in kwargs.items():
                    setattr(member, attribute, val)
                print(f"Staff member with ID {member_id} updated successfully.")
                return
        print(f"Staff member with ID {member_id} not found.")

    def retrieve_staff_member(self, member_id):
        for member in self.staff_members:
            if member.identifier == member_id:
                return member
        print(f"Staff member with ID {member_id} not found.")
        return None

    def compute_tenure(self, member_id):
        member = self.retrieve_staff_member(member_id)
        if member:
            return member.compute_tenure()
        return None

    def display_staff_members(self):
        for member in self.staff_members:
            print(member)

    def is_executive_role(self, member_id):
        member = self.retrieve_staff_member(member_id)
        if member and member.position.lower() == 'management':
            return True
        return False

# Demonstration usage
if __name__ == "__main__":
