# Modified version of the number guessing game
import random

def obtain_user_input(player_name, low_limit, high_limit):
    while True:
        try:
            attempt = int(input(f"{player_name}, guess a number between {low_limit} and {high_limit}: "))
            if low_limit <= attempt <= high_limit:
                return attempt
            else:
                print(f"Please enter a number between {low_limit} and {high_limit}.")
        except ValueError:
            print("Please enter a valid number.")

def run_game():
    low_limit = 1
    high_limit = 100
    max_attempts = 10

    secret_number = random.randint(low_limit, high_limit)
    player_a_name = input("Enter Player A's name: ")
    player_b_name = input("Enter Player B's name: ")

    player_a_attempts = 0
    player_b_attempts = 0

    while player_a_attempts < max_attempts and player_b_attempts < max_attempts:
        # Player A's turn
        if player_a_attempts < max_attempts:
            attempt = obtain_user_input(player_a_name, low_limit, high_limit)
            player_a_attempts += 1
            if attempt == secret_number:
                print(f"{player_a_name} wins! The number was {secret_number}.")
                return
            else:
                print(f"Wrong guess, {player_a_name}. Attempts remaining: {max_attempts - player_a_attempts}")

        # Player B's turn
        if player_b_attempts < max_attempts:
            attempt = obtain_user_input(player_b_name, low_limit, high_limit)
            player_b_attempts += 1
            if attempt == secret_number:
                print(f"{player_b_name} wins! The number was {secret_number}.")
                return
            else:
                print(f"Wrong guess, {player_b_name}. Attempts remaining: {max_attempts - player_b_attempts}")

    print(f"Both players have run out of attempts. The number was {secret_number}.")

if __name__ == "__main__":
