# ISBN validation utility class
class BookNumberChecker:
    def __init__(self, number):
        self.number = number.strip().replace('-', '')
        self.size = len(self.number)
        self.is_correct = False
        self.problem_description = None

    def check(self):
        if self.size == 10:
            self.is_correct = self._check_isbn10()
        elif self.size == 13:
            self.is_correct = self._check_isbn13()
        else:
            self.problem_description = f"Wrong size: ISBN should be 10 or 13 characters, got {self.size}"
        return self.is_correct

    def _check_isbn10(self):
        if not self.number[:-1].isdigit() or not (self.number[-1].isdigit() or self.number[-1] == 'X'):
            self.problem_description = "Bad symbols: ISBN-10 needs digits and optionally 'X' as final character"
            return False

        values = [int(c) if c != 'X' else 10 for c in self.number]
        multipliers = list(range(10, 0, -1))
        total = sum(v * m for v, m in zip(values, multipliers)) % 11

        if total != 0:
            self.problem_description = "Checksum error: ISBN-10 verification failed"
            return False

        return True

    def _check_isbn13(self):
        if not self.number.isdigit():
            self.problem_description = "Bad symbols: ISBN-13 must include only digits"
            return False

        values = [int(c) for c in self.number]
        multipliers = [1 if idx % 2 == 0 else 3 for idx in range(13)]
        total = sum(v * m for v, m in zip(values, multipliers)) % 10

        if total != 0:
            self.problem_description = "Checksum error: ISBN-13 verification failed"
            return False

        return True

    def get_issue(self):
        return self.problem_description


# Demonstration of usage
if __name__ == "__main__":
    test_numbers = [
        "0-306-40615-2",  # Correct ISBN-10
        "978-0-306-40615-7",  # Correct ISBN-13
        "0-306-40615-3",  # Incorrect ISBN-10
        "978-0-306-40615-8",  # Incorrect ISBN-13
        "12345678901234",  # Wrong length
        "0-306-4061X-2"  # Invalid symbols
    ]

    for num in test_numbers:
        checker = BookNumberChecker(num)
        if checker.check():
            print(f"{num} is a correct ISBN")
        else:
            print(f"{num} is an incorrect ISBN: {checker.get_issue()}")

# Script to create a new branch from a specific commit in a cloned Git repository
import subprocess
import sys
import os

def execute_git_command(cmd, working_dir=None):
    try:
        process = subprocess.run(cmd, check=True, text=True, capture_output=True, cwd=working_dir)
        return process.stdout.strip()
    except subprocess.CalledProcessError as error:
        return error.stderr.strip()

def fetch_repository(repo_address, target_directory):
    cmd_list = ['git', 'clone', repo_address, target_directory]
    message = execute_git_command(cmd_list)
    if "fatal" in message:
        raise ValueError(f"Unable to clone repository: {message}")

def establish_branch_from_commit(project_path, branch_label, revision_id):
    # Checkout the specified commit
    checkout_cmd = ['git', 'checkout', revision_id]
    checkout_output = execute_git_command(checkout_cmd, cwd=project_path)
    if "fatal" in checkout_output:
        raise ValueError(f"Commit identifier is invalid: {checkout_output}")

    # Create a new branch at this commit
    branch_cmd = ['git', 'checkout', '-b', branch_label]
    branch_output = execute_git_command(branch_cmd, cwd=project_path)
    if "fatal" in branch_output:
        raise ValueError(f"Could not create branch: {branch_output}")

def main(repo_address, revision_id, branch_label):
    project_folder = os.path.basename(repo_address).replace('.git', '')

    # Clone the repository
    try:
        fetch_repository(repo_address, project_folder)
    except ValueError as error:
        print(error)
        sys.exit(1)

    # Create a new branch from the specified commit
    try:
        establish_branch_from_commit(project_folder, branch_label, revision_id)
    except ValueError as error:
        print(error)
        sys.exit(1)

    print(f"Branch '{branch_label}' established from commit '{revision_id}' in repository '{repo_address}'.")

if __name__ == "__main__":
    if len(sys.argv) != 4:
        print("Syntax: python git_branch_creator.py <repository_url> <commit_hash> <branch_name>")
        sys.exit(1)

    repo_address = sys.argv[1]
    revision_id = sys.argv[2]
    branch_label = sys.argv[3]

    main(repo_address, revision_id, branch_label)

# Convert numeric scores to letter grades and calculate GPA
def convert_score_to_letter(score):
    if not 1 <= score <= 100:
        raise ValueError("Score must be between 1 and 100.")

    if score >= 90:
        return 'A'
    elif score >= 80:
        return 'B'
    elif score >= 70:
        return 'C'
    elif score >= 60:
        return 'D'
    else:
        return 'F'

def letter_to_points(letter):
    point_values = {
        'A': 4.0,
        'B': 3.0,
        'C': 2.0,
        'D': 1.0,
        'F': 0.0
    }
    return point_values.get(letter, 0.0)

def compute_average_gpa(grades_list):
    if not grades_list:
        return 0.0
    sum_gpa = sum(letter_to_points(grade) for grade in grades_list)
    return sum_gpa / len(grades_list)

def run_program():
    grade_list = []
    while True:
        try:
            user_input = input("Enter a numeric score between 1 and 100 (or 'quit' to finish): ")
            if user_input.lower() == 'quit':
                break
            numeric_value = float(user_input)
            letter_grade = convert_score_to_letter(numeric_value)
            print(f"Numeric Score: {numeric_value} -> Grade: {letter_grade}")
            grade_list.append(letter_grade)
        except ValueError as error:
            print(f"Error: {error}")

    if grade_list:
        final_gpa = compute_average_gpa(grade_list)
        print(f"Grades: {', '.join(grade_list)}")
        print(f"Grade Point Average (GPA): {final_gpa:.2f}")
    else:
        print("No valid scores entered.")

if __name__ == "__main__":
    run_program()

# Modified version of the original code with renamed variables and adjusted logic
from typing import List

def extract_bracket_sections(input_text: str, nested_flag: bool = False) -> List[str]:
    """
    This function processes a string containing various types of brackets (round and square).
    It isolates each bracketed section into separate strings and returns them as a list,
    while removing whitespace. All bracket pairs must be properly matched in the output sections.

    :param input_text: The input string with nested round and square brackets.
    :param nested_flag: A boolean indicating whether to include innermost nested sections.
    :return: A list of isolated bracketed groups.
    """
    def check_bracket_match(start_char, end_char):
        return (start_char == '(' and end_char == ')') or (start_char == '[' and end_char == ']')

    def process_sections(text: str, capture_inner: bool) -> List[str]:
        bracket_stack = []
        output_list = []
        current_segment = []

        for symbol in text:
            if symbol in '([':
                if not bracket_stack or (bracket_stack and capture_inner):
                    current_segment.append(symbol)
                bracket_stack.append(symbol)
            elif symbol in ')]':
                if bracket_stack:
                    last_open = bracket_stack.pop()
                    if check_bracket_match(last_open, symbol):
                        current_segment.append(symbol)
                        if not bracket_stack:
                            output_list.append(''.join(current_segment))
                            current_segment = []
                    else:
                        raise ValueError("Mismatched or unbalanced brackets")
                else:
                    raise ValueError("Unbalanced brackets detected")
            elif symbol != ' ':
                current_segment.append(symbol)

        if bracket_stack:
            raise ValueError("Unbalanced brackets in input")

        return output_list

    # Remove all spaces from the input
    cleaned_input = input_text.replace(' ', '')
    return process_sections(cleaned_input, nested_flag)

