from rest_framework import serializers
from .models import Book, Page

class PageSerializer(serializers.ModelSerializer):
    class Meta:
        model = Page
        fields = ['id', 'content']

class BookPageRequestSerializer(serializers.Serializer):
    book_identifier = serializers.IntegerField()
    page_list = PageSerializer(many=True)

    def create(self, validated_data):
        book_id = validated_data['book_identifier']
        pages_info = validated_data['page_list']

        # Retrieve or initialize the book
        book, _ = Book.objects.get_or_create(id=book_id)

        # Process each page
        for page_info in pages_info:
            page_pk = page_info.get('id')
            if page_pk:
                # Modify existing page
                Page.objects.update_or_create(id=page_pk, book=book, defaults=page_info)
            else:
                # Add new page
                Page.objects.create(book=book, **page_info)

        return {'book_id': book_id, 'pages': pages_info}

    def update(self, instance, validated_data):
        book_id = validated_data['book_identifier']
        pages_info = validated_data['page_list']

        # Fetch the book
        book = Book.objects.get(id=book_id)

        # Update pages
        for page_info in pages_info:
            page_pk = page_info.get('id')
            if page_pk:
                # Modify existing page
                Page.objects.update_or_create(id=page_pk, book=book, defaults=page_info)
            else:
                # Add new page
                Page.objects.create(book=book, **page_info)

        return {'book_id': book_id, 'pages': pages_info}

