# Modified version of LimitedList with renamed variables and reordered logic
import threading
from typing import List, Any

class RestrictedCollection:
    def __init__(self):
        self._items: List[Any] = []
        self._mutex = threading.Lock()
        self._capacity = 10

    def insert(self, value: Any) -> None:
        with self._mutex:
            if len(self._items) >= self._capacity:
                raise RuntimeError("Collection has reached its maximum capacity.")
            self._items.append(value)

    def delete(self, value: Any) -> None:
        with self._mutex:
            if value in self._items:
                self._items.remove(value)

    def contains(self, value: Any) -> bool:
        with self._mutex:
            return value in self._items

    def order(self) -> None:
        with self._mutex:
            self._items = self._merge_ordering(self._items)

    def _merge_ordering(self, sequence: List[Any]) -> List[Any]:
        if len(sequence) <= 1:
            return sequence

        center = len(sequence) // 2
        left_partition = self._merge_ordering(sequence[:center])
        right_partition = self._merge_ordering(sequence[center:])

        return self._combine(left_partition, right_partition)

    def _combine(self, left: List[Any], right: List[Any]) -> List[Any]:
        ordered_result = []
        index_left = index_right = 0

        while index_left < len(left) and index_right < len(right):
            if left[index_left] < right[index_right]:
                ordered_result.append(left[index_left])
                index_left += 1
            else:
                ordered_result.append(right[index_right])
                index_right += 1

        ordered_result.extend(left[index_left:])
        ordered_result.extend(right[index_right:])
        return ordered_result

    def __repr__(self):
        return repr(self._items)

### Unit Tests (modified variable names and assertions)

import unittest
from concurrent.futures import ThreadPoolExecutor

class TestRestrictedCollection(unittest.TestCase):
    def test_insert_and_delete_elements(self):
        rc = RestrictedCollection()
        rc.insert(5)
        rc.insert(10)
        self.assertTrue(rc.contains(5))
        self.assertTrue(rc.contains(10))
        rc.delete(5)
        self.assertFalse(rc.contains(5))
        self.assertTrue(rc.contains(10))

    def test_insert_elements_until_full(self):
        rc = RestrictedCollection()
        for idx in range(10):
            rc.insert(idx)
        with self.assertRaises(RuntimeError):
            rc.insert(10)

    def test_order_elements(self):
        rc = RestrictedCollection()
        rc.insert(5)
        rc.insert(1)
        rc.insert(3)
        rc.insert(10)
        rc.order()
        self.assertEqual(str(rc), "[1, 3, 5, 10]")

    def test_concurrent_safety(self):
        rc = RestrictedCollection()
        def populate_collection(rc, values):
            for val in values:
                rc.insert(val)

        values = list(range(20))
        with ThreadPoolExecutor(max_workers=5) as pool:
            for _ in range(2):
                pool.submit(populate_collection, rc, values)

        self.assertEqual(len(rc._items), 10)
        self.assertTrue(all(item in rc._items for item in range(10)))

