# Modified version with Type I clone transformations
from typing import List, Tuple, Dict

class InsufficientFundsError(Exception):
    pass

def check_negative_balance(transactions: Dict[int, List[Tuple[str, int]]], ignore_case: bool = False) -> Dict[str, List[int]]:
    """
    Starting with zero balance, implement a system to track deposit and withdrawal operations on different bank accounts. 
    Detect when a balance turns negative and raise an "InsufficientFundsError" at such instances. 
    End the operation by returning a dictionary presenting a list of account numbers that stayed above zero. 
    If the ignore_case flag is true, treat 'Deposit' and 'deposit', 'Withdrawal' and 'withdrawal' as identical, 
    and consider the balance at zero as well.

    Input dictionary presents tuples in the structure (Operation_type, Operation_value) as the value and Account_number as the key.

    Examples:
    >>> check_negative_balance({1: [('Deposit', 1), ('Deposit', 2), ('Deposit', 3)]})
    {1: ['No negative balance']}
    >>> check_negative_balance({1: [('Deposit', 1), ('Deposit', 2), ('Withdrawal', 4), ('Deposit', 5)]})
    InsufficientFundsError: 'Account 1 has insufficient funds.'
    >>> check_negative_balance({1: [('Deposit', 1), ('Deposit', 2), ('withdrawal', 3)]}, True)
    InsufficientFundsError: 'Account 1 has insufficient funds.'
    """

    positive_accounts = {}

    for acc_id, txns in transactions.items():
        current_balance = 0
        for txn_type, txn_amount in txns:
            if ignore_case:
                txn_type = txn_type.lower()

            if txn_type == 'deposit':
                current_balance += txn_amount
            elif txn_type == 'withdrawal':
                current_balance -= txn_amount
            else:
                raise ValueError(f"Unknown operation type: {txn_type}")

            if current_balance < 0:
                raise InsufficientFundsError(f'Account {acc_id} has insufficient funds.')
            if ignore_case and current_balance == 0:
                raise InsufficientFundsError(f'Account {acc_id} has insufficient funds.')

        positive_accounts[acc_id] = ['No negative balance']

    return positive_accounts

# Example usage:
if __name__ == "__main__":
    try:
        print(check_negative_balance({1: [('Deposit', 1), ('Deposit', 2), ('Deposit', 3)]}))
        print(check_negative_balance({1: [('Deposit', 1), ('Deposit', 2), ('Withdrawal', 4), ('Deposit', 5)]}))
        print(check_negative_balance({1: [('Deposit', 1), ('Deposit', 2), ('withdrawal', 3)]}, True))
    except InsufficientFundsError as err:
        print(err)

# Analyze Python files to detect unused functions
import ast
import os

def locate_unused_functions(project_path):
    defined_funcs = {}
    used_funcs = set()

    for current_dir, _, filenames in os.walk(project_path):
        for filename in filenames:
            if filename.endswith('.py'):
                filepath = os.path.join(current_dir, filename)
                with open(filepath, 'r') as source_file:
                    try:
                        tree = ast.parse(source_file.read(), filename=filename)
                        for element in ast.walk(tree):
                            if isinstance(element, ast.FunctionDef):
                                defined_funcs[element.name] = filename
                            elif isinstance(element, ast.Name) and isinstance(element.ctx, ast.Load):
                                used_funcs.add(element.id)
                    except SyntaxError:
                        continue  # Skip files with syntax errors

    unused = {func_name: src_file for func_name, src_file in defined_funcs.items() 
              if func_name not in used_funcs}
    return unused

