import re
from datetime import datetime, date
from collections import defaultdict
from typing import List, Dict

class Client:
    def __init__(self, full_name: str, contact_email: str, telephone: str, birth_date: str, residence: str):
        self._full_name = None
        self._contact_email = None
        self._telephone = None
        self._birth_date = None
        self._residence = None
        self.full_name = full_name
        self.contact_email = contact_email
        self.telephone = telephone
        self.birth_date = birth_date
        self.residence = residence

    @property
    def full_name(self) -> str:
        return self._full_name

    @full_name.setter
    def full_name(self, value: str):
        if not (2 <= len(value) <= 50) or not value.isalpha():
            raise ValueError("Name must be between 2 and 50 characters and contain only letters.")
        self._full_name = value

    @property
    def contact_email(self) -> str:
        return self._contact_email

    @contact_email.setter
    def contact_email(self, value: str):
        if len(value) > 100 or not re.match(r"[^@]+@[^@]+\.[^@]+", value):
            raise ValueError("Email must be valid and not exceed 100 characters.")
        self._contact_email = value

    @property
    def telephone(self) -> str:
        return self._telephone

    @telephone.setter
    def telephone(self, value: str):
        if not re.match(r"^\d{3}-\d{3}-\d{4}$", value):
            raise ValueError("Phone number must be in the format 123-456-7890.")
        self._telephone = value

    @property
    def birth_date(self) -> str:
        return self._birth_date

    @birth_date.setter
    def birth_date(self, value: str):
        try:
            dob = datetime.strptime(value, '%d/%m/%Y').date()
            if dob > date.today():
                raise ValueError
        except ValueError:
            raise ValueError("Invalid date of birth or date in the future. Format should be dd/mm/yyyy.")
        self._birth_date = value

    @property
    def residence(self) -> str:
        return self._residence

    @residence.setter
    def residence(self, value: str):
        if len(value) > 200:
            raise ValueError("Address must not exceed 200 characters.")
        self._residence = value

    def show_details(self) -> str:
        dob = datetime.strptime(self.birth_date, '%d/%m/%Y').date()
        years = (date.today() - dob).days // 365
        return f"Name: {self.full_name}, Email: {self.contact_email}, Phone: {self.telephone}, Age: {years}, Address: {self.residence}"

    @staticmethod
    def order_clients(clients: List['Client']) -> List['Client']:
        return sorted(clients, key=lambda c: (c.full_name, (date.today() - datetime.strptime(c.birth_date, '%d/%m/%Y').date()).days))

    @staticmethod
    def select_clients(clients: List['Client'], provider: str, threshold_age: int) -> List['Client']:
        selected = []
        for client in clients:
            dob = datetime.strptime(client.birth_date, '%d/%m/%Y').date()
            years = (date.today() - dob).days // 365
            if client.contact_email.endswith(f"@{provider}") and years > threshold_age:
                selected.append(client)
        return selected

    @staticmethod
    def mean_age(clients: List['Client']) -> float:
        total_years = 0
        for client in clients:
            dob = datetime.strptime(client.birth_date, '%d/%m/%Y').date()
            years = (date.today() - dob).days // 365
            total_years += years
        return total_years / len(clients) if clients else 0

    @staticmethod
    def categorize_by_email_domain(clients: List['Client']) -> Dict[str, List['Client']]:
        categorized = defaultdict(list)
        for client in clients:
            domain = client.contact_email.split('@')[1]
            categorized[domain].append(client)
        return categorized

    @staticmethod
    def categorize_by_initial(clients: List['Client']) -> Dict[str, List['Client']]:
        categorized = defaultdict(list)
        for client in clients:
            initial = client.full_name[0].upper()
            categorized[initial].append(client)
        return categorized

# A basic sentiment classification system 
class BasicEmotionDetector:
    def __init__(self):
        self.positive_terms = {"good", "great", "excellent", "amazing", "wonderful", "fantastic", "love", "happy", "best", "enjoy"}
        self.negative_terms = {"bad", "terrible", "awful", "horrible", "poor", "disappointing", "hate", "sad", "worst", "annoying"}

    def determine_emotion(self, text):
        tokens = text.lower().split()
        pos_count = sum(1 for token in tokens if token in self.positive_terms)
        neg_count = sum(1 for token in tokens if token in self.negative_terms)

        if pos_count > neg_count:
            return "Positive"
        elif neg_count > pos_count:
            return "Negative"
        else:
            return "Neutral"

