# Calculate the minimum disparity between adjacent elements after sorting
def flatten_list(data):
    """Flatten a nested list structure."""
    for item in data:
        if isinstance(item, list):
            yield from flatten_list(item)
        else:
            yield item

def to_number(val):
    """Convert various types (bool, str, numeric) to numeric values."""
    if isinstance(val, bool):
        return int(val)
    if isinstance(val, str):
        try:
            return int(val)
        except ValueError:
            try:
                return float(val)
            except ValueError:
                return None
    if isinstance(val, (int, float, complex)):
        return val
    return None

def get_smallest_difference(matrix):
    # Flatten the input structure
    flattened = list(flatten_list(matrix))

    # Convert and keep only valid numeric entries
    numbers = [to_number(x) for x in flattened if to_number(x) is not None]

    # Validate minimum required elements
    if len(numbers) < 2:
        return "At least two numeric values are needed to compute disparity."

    # Sort based on absolute value for complex numbers, otherwise natural order
    numbers.sort(key=lambda x: abs(x) if isinstance(x, complex) else x)

    # Track smallest difference and corresponding pair
    smallest_diff = float('inf')
    best_pair = (None, None)

    # Scan adjacent pairs for minimum difference
    for idx in range(len(numbers) - 1):
        diff = abs(numbers[idx] - numbers[idx + 1])
        if diff < smallest_diff:
            smallest_diff = diff
            best_pair = (numbers[idx], numbers[idx + 1])

    return smallest_diff, best_pair

# Verification tests
def run_tests():
