# Scrapy spider to extract image URLs from web pages
import scrapy
from scrapy.linkextractors import LinkExtractor
from scrapy.spiders import CrawlSpider, Rule
from bs4 import BeautifulSoup
import requests

class PhotoCrawler(CrawlSpider):
    name = 'photo_spider'
    allowed_domains = ['sample.com']
    start_urls = ['http://sample.com']

    rules = (
        Rule(LinkExtractor(allow=(), restrict_css=()), callback="extract_data", follow=True, process_request='filter_requests'),
    )

    def filter_requests(self, req):
        if req.url == self.start_urls[0]:
            return req
        if len(req.meta.get('depth', [])) < 2:
            return req

    def extract_data(self, resp):
        soup = BeautifulSoup(resp.body, 'html.parser')
        picture_tags = soup.find_all('img')
        for pic in picture_tags:
            img_src = pic.get('src')
            if img_src:
                yield {
                    'image_url': resp.urljoin(img_src),
                    'source_page': resp.url
                }

