# Modified version of the original code with Type I clone transformations
from typing import List
import bisect

def is_prime_number(value: int) -> bool:
    if value <= 1:
        return False
    if value <= 3:
        return True
    if value % 2 == 0 or value % 3 == 0:
        return False
    k = 5
    while k * k <= value:
        if value % k == 0 or value % (k + 2) == 0:
            return False
        k += 6
    return True

def find_next_prime(value: int) -> int:
    while True:
        value += 1
        if is_prime_number(value):
            return value

def closest_fibonacci(value: int) -> int:
    fib_sequence = [0, 1]
    while fib_sequence[-1] < 100:  # Precompute up to the largest single-digit number
        fib_sequence.append(fib_sequence[-1] + fib_sequence[-2])
    position = bisect.bisect_left(fib_sequence, value)
    if position == 0:
        return fib_sequence[0]
    if position == len(fib_sequence) or fib_sequence[position] - value > value - fib_sequence[position - 1]:
        return fib_sequence[position - 1]
    return fib_sequence[position]

def switch_case(char: str) -> str:
    if char.islower():
        return char.upper()
    elif char.isupper():
        return char.lower()
    return char

def transform_text(text: str) -> str:
    # Step 1: Toggle case of alphabetic characters
    switched_string = ''.join(switch_case(ch) for ch in text)

    # Step 2: Map each odd number to its adjacent Fibonacci number
    fib_transformed_string = ''
    for ch in switched_string:
        if ch.isdigit() and int(ch) % 2 != 0:
            fib_transformed_string += str(closest_fibonacci(int(ch)))
        else:
            fib_transformed_string += ch

    # Step 3: Replicate special characters based on the next prime number after their count
    special_characters = [ch for ch in fib_transformed_string if not ch.isalnum()]
    special_frequency = len(special_characters)
    next_prime_frequency = find_next_prime(special_frequency)
    replicated_string = ''
    for ch in fib_transformed_string:
        if not ch.isalnum():
            replicated_string += ch * next_prime_frequency
        else:
            replicated_string += ch

    # Step 4: Arrange all characters in a balanced Binary Search Tree
    class Node:
        def __init__(self, data=0):
            self.data = data
            self.left = None
            self.right = None

    def add_to_bst(node: Node, data: int) -> Node:
        if not node:
            return Node(data)
        if data < node.data:
            node.left = add_to_bst(node.left, data)
        else:
            node.right = add_to_bst(node.right, data)
        return node

    def get_inorder(node: Node) -> List[int]:
        return get_inorder(node.left) + [node.data] + get_inorder(node.right) if node else []

    root_node = None
    for ch in replicated_string:
        root_node = add_to_bst(root_node, ord(ch))

    inorder_values = get_inorder(root_node)
    final_string = ''.join(chr(data) for data in inorder_values)

    return final_string

# Example usage
print(transform_text('Greet5!'))

# Vector operations module for 2D vectors
import math

class Vector2D:
    def __init__(self, x_val: float, y_val: float):
        self.x_coord = round(x_val, 6)
        self.y_coord = round(y_val, 6)

    def get_x_component(self) -> float:
        return self.x_coord

    def get_y_component(self) -> float:
        return self.y_coord

    def length(self) -> float:
        return round(math.sqrt(self.x_coord**2 + self.y_coord**2), 6)

    def sum(self, other_vector: 'Vector2D') -> 'Vector2D':
        return Vector2D(self.x_coord + other_vector.x_coord, self.y_coord + other_vector.y_coord)

    def difference(self, other_vector: 'Vector2D') -> 'Vector2D':
        return Vector2D(self.x_coord - other_vector.x_coord, self.y_coord - other_vector.y_coord)

    def scale(self, factor: float) -> 'Vector2D':
        return Vector2D(self.x_coord * factor, self.y_coord * factor)

    def inner_product(self, other_vector: 'Vector2D') -> float:
        return round(self.x_coord * other_vector.x_coord + self.y_coord * other_vector.y_coord, 6)

    def pseudo_cross(self, other_vector: 'Vector2D') -> float:
        return 0.0

    def unit_vector(self) -> 'Vector2D':
        vec_length = self.length()
        if vec_length == 0:
            return Vector2D(0, 0)
        return Vector2D(self.x_coord / vec_length, self.y_coord / vec_length)

    def separation(self, other_vector: 'Vector2D') -> float:
        return round(math.sqrt((self.x_coord - other_vector.x_coord)**2 + (self.y_coord - other_vector.y_coord)**2), 6)

    def orientation(self, other_vector: 'Vector2D') -> float:
        dot = self.inner_product(other_vector)
        len_self = self.length()
        len_other = other_vector.length()
        if len_self == 0 or len_other == 0:
            return 0.0
        cos_angle = dot / (len_self * len_other)
        return round(math.degrees(math.acos(cos_angle)), 6)

    def turn(self, degrees: float) -> 'Vector2D':
        radians = math.radians(degrees)
        cos_val = math.cos(radians)
        sin_val = math.sin(radians)
        new_x = self.x_coord * cos_val - self.y_coord * sin_val
        new_y = self.x_coord * sin_val + self.y_coord * cos_val
        return Vector2D(new_x, new_y)

    def projection(self, other_vector: 'Vector2D') -> 'Vector2D':
        dot = self.inner_product(other_vector)
        mag_sq = other_vector.magnitude() ** 2
        if mag_sq == 0:
            return Vector2D(0, 0)
        coefficient = dot / mag_sq
        return other_vector.scale(coefficient)

    def parallel_check(self, other_vector: 'Vector2D') -> bool:
        return self.pseudo_cross(other_vector) == 0

    def perpendicular_check(self, other_vector: 'Vector2D') -> bool:
        return self.inner_product(other_vector) == 0

# Demonstration of usage
vec_a = Vector2D(2, 3)
vec_b = Vector2D(4, -1)

print(vec_a.get_x_component())  # Output: 2
print(vec_a.get_y_component())  # Output: 3
print(vec_a.length())  # Output: 3.605551
print(vec_a.sum(vec_b))  # Output: <__main__.Vector2D object at 0x...>
print(vec_a.difference(vec_b))  # Output: <__main__.Vector2D object at 0x...>
print(vec_a.scale(2))  # Output: <__main__.Vector2D object at 0x...>
print(vec_a.inner_product(vec_b))  # Output: 5.0
print(vec_a.pseudo_cross(vec_b))  # Output: 0.0
print(vec_a.unit_vector())  # Output: <__main__.Vector2D object at 0x...>
