# Binary Search Tree implementation with various operations
class TreeNode:
    def __init__(self, value):
        self.value = value
        self.left_child = None
        self.right_child = None

class BinarySearchTree:
    def __init__(self):
        self.root_node = None

    def add(self, value):
        self.root_node = self._add_to_tree(self.root_node, value)

    def _add_to_tree(self, current_node, value):
        if current_node is None:
            return TreeNode(value)
        if value < current_node.value:
            current_node.left_child = self._add_to_tree(current_node.left_child, value)
        else:
            current_node.right_child = self._add_to_tree(current_node.right_child, value)
        return current_node

    def remove(self, value):
        self.root_node = self._remove_from_tree(self.root_node, value)

    def _remove_from_tree(self, current_node, value):
        if current_node is None:
            return current_node
        if value < current_node.value:
            current_node.left_child = self._remove_from_tree(current_node.left_child, value)
        elif value > current_node.value:
            current_node.right_child = self._remove_from_tree(current_node.right_child, value)
        else:
            if current_node.left_child is None:
                return current_node.right_child
            elif current_node.right_child is None:
                return current_node.left_child
            min_right_node = self._find_minimum(current_node.right_child)
            current_node.value = min_right_node.value
            current_node.right_child = self._remove_from_tree(current_node.right_child, min_right_node.value)
        return current_node

    def find(self, value):
        return self._search_in_tree(self.root_node, value)

    def _search_in_tree(self, current_node, value):
        if current_node is None or current_node.value == value:
            return current_node
        if value < current_node.value:
            return self._search_in_tree(current_node.left_child, value)
        return self._search_in_tree(current_node.right_child, value)

    def minimum(self):
        return self._find_minimum(self.root_node)

    def _find_minimum(self, current_node):
        if current_node is None:
            return None
        while current_node.left_child is not None:
            current_node = current_node.left_child
        return current_node

    def maximum(self):
        return self._find_maximum(self.root_node)

    def _find_maximum(self, current_node):
        if current_node is None:
            return None
        while current_node.right_child is not None:
            current_node = current_node.right_child
        return current_node

    def kth_smallest_element(self, k):
        return self._kth_smallest_recursive(self.root_node, k, [0])

    def _kth_smallest_recursive(self, current_node, k, counter):
        if current_node is None:
            return None
        left_result = self._kth_smallest_recursive(current_node.left_child, k, counter)
        if left_result is not None:
            return left_result
        counter[0] += 1
        if counter[0] == k:
            return current_node
        return self._kth_smallest_recursive(current_node.right_child, k, counter)

    def get_height(self):
        return self._calculate_height(self.root_node)

    def _calculate_height(self, current_node):
        if current_node is None:
            return 0
        return 1 + max(self._calculate_height(current_node.left_child), 
                      self._calculate_height(current_node.right_child))

    def check_balance(self):
        return self._check_balance_status(self.root_node) != -1

    def _check_balance_status(self, current_node):
        if current_node is None:
            return 0
        left_height = self._check_balance_status(current_node.left_child)
        if left_height == -1:
            return -1
        right_height = self._check_balance_status(current_node.right_child)
        if right_height == -1:
            return -1
        if abs(left_height - right_height) > 1:
            return -1
        return 1 + max(left_height, right_height)

    def lowest_common_ancestor(self, val1, val2):
        return self._lowest_common_ancestor_recursive(self.root_node, val1, val2)

    def _lowest_common_ancestor_recursive(self, current_node, val1, val2):
        if current_node is None:
            return None
        if val1 < current_node.value and val2 < current_node.value:
            return self._lowest_common_ancestor_recursive(current_node.left_child, val1, val2)
        if val1 > current_node.value and val2 > current_node.value:
            return self._lowest_common_ancestor_recursive(current_node.right_child, val1, val2)
        return current_node

    def breadth_first_traversal(self):
        if self.root_node is None:
            return
        queue = [self.root_node]
        while queue:
            level_values = []
            for _ in range(len(queue)):
                node = queue.pop(0)
                level_values.append(node.value)
                if node.left_child:
                    queue.append(node.left_child)
                if node.right_child:
                    queue.append(node.right_child)
            print(level_values)

# Example usage:
bst = BinarySearchTree()
bst.add(50)
bst.add(30)
bst.add(20)
bst.add(40)
bst.add(70)
bst.add(60)
bst.add(80)

print("Search 40:", bst.find(40).value if bst.find(40) else "Not Found")
print("Minimum:", bst.minimum().value if bst.minimum() else "Not Found")
