print("3rd smallest:", bst.kth_smallest_element(3).value if bst.kth_smallest_element(3) else "Not Found")
print("Height:", bst.get_height())
print("Is balanced:", bst.check_balance())
print("Lowest common ancestor of 20 and 40:", bst.lowest_common_ancestor(20, 40).value if bst.lowest_common_ancestor(20, 40) else "Not Found")
print("Breadth-first traversal:")
bst.breadth_first_traversal()

# Custom delegate for handling hyperlinks in a table view
from PyQt5.QtWidgets import QStyledItemDelegate, QStyleOptionViewItem, QApplication, QWidget, QVBoxLayout, QTableView
from PyQt5.QtGui import QPainter, QCursor, QDesktopServices
from PyQt5.QtCore import Qt, QEvent, QModelIndex, QUrl
import sys

class LinkItemDelegate(QStyledItemDelegate):
    def __init__(self, parent=None):
        super(LinkItemDelegate, self).__init__(parent)
        self._hyperlinks = {}

    def paint(self, painter: QPainter, option: QStyleOptionViewItem, index: QModelIndex):
        if index.column() == 1:  # Column designated for clickable links
            text_content = index.data(Qt.DisplayRole)
            url_data = index.data(Qt.UserRole)

            if url_data:
                self._hyperlinks[index] = url_data

                # Render background
                painter.save()
                painter.setRenderHint(QPainter.Antialiasing, True)
                if option.state & QStyle.State_Selected:
                    painter.fillRect(option.rect, option.palette.highlight())
                painter.restore()

                # Draw each hyperlink
                for link in url_data:
                    text_bounds = painter.fontMetrics().boundingRect(option.rect, Qt.TextWordWrap, link['label'])
                    link_area = option.rect.adjusted(0, 0, -option.rect.width() + text_bounds.width(), 0)
                    painter.setPen(Qt.blue)
                    painter.drawText(link_area, Qt.TextWordWrap, link['label'])

                    # Add underline effect
                    painter.setPen(Qt.blue)
                    painter.drawLine(link_area.bottomLeft(), link_area.bottomRight())

                painter.restore()
            else:
                super().paint(painter, option, index)
        else:
            super().paint(painter, option, index)

    def editorEvent(self, event: QEvent, model, option: QStyleOptionViewItem, index: QModelIndex):
        if event.type() == QEvent.MouseButtonRelease and index.column() == 1:
            if index in self._hyperlinks:
                url_list = self._hyperlinks[index]
                for link in url_list:
                    text_box = self.style().itemTextRect(option.fontMetrics, option.rect, Qt.AlignLeft, True, link['label'])
                    if text_box.contains(event.pos()):
                        QDesktopServices.openUrl(QUrl(link['address']))
                        return True
        return super().editorEvent(event, model, option, index)

    def sizeHint(self, option: QStyleOptionViewItem, index: QModelIndex):
        if index.column() == 1:
            url_list = index.data(Qt.UserRole)
            if url_list:
                max_row_height = max(self.style().itemTextRect(option.fontMetrics, option.rect, Qt.AlignLeft, True, link['label']).height() for link in url_list)
                return QSize(option.rect.width(), max_row_height)
        return super().sizeHint(option, index)

# Abstract base class for different types of boats
from abc import ABC, abstractmethod
from datetime import datetime, timedelta

class Vessel(ABC):
    def __init__(self, vessel_name, hull_length, max_passengers):
        self.vessel_name = vessel_name
        self.hull_length = hull_length
        self.max_passengers = max_passengers

    def moor(self):
        current_timestamp = datetime.now().strftime("%H:%M:%S")
        print(f"Vessel {self.vessel_name} is moored at {current_timestamp}")

    def cruise(self, target_port, travel_distance):
        # Assuming a constant average speed of 10 knots for the vessel
        cruising_speed = 10  # knots
        projected_duration = travel_distance / cruising_speed
        arrival_time = datetime.now() + timedelta(hours=projected_duration)
        arrival_formatted = arrival_time.strftime("%H:%M:%S")
        print(f"Vessel {self.vessel_name} is cruising to {target_port} and is projected to arrive at {arrival_formatted}")

    @abstractmethod
    def special_capability(self):
        pass

class PowerBoat(Vessel):
    def __init__(self, vessel_name, hull_length, max_passengers, fuel_tank_size, motor_output):
        super().__init__(vessel_name, hull_length, max_passengers)
        self.fuel_tank_size = fuel_tank_size
        self.motor_output = motor_output

    def ignite_motor(self):
        print(f"Motor of PowerBoat {self.vessel_name} ignited with {self.motor_output} horsepower")

    def replenish_fuel(self, quantity):
        if quantity > 0:
            self.fuel_tank_size += quantity
            print(f"PowerBoat {self.vessel_name} replenished with {quantity} liters. Current fuel: {self.fuel_tank_size} liters")
        else:
            print("Replenishment quantity must be positive")

    def special_capability(self):
        print(f"PowerBoat {self.vessel_name} features a motor with {self.motor_output} horsepower and a fuel tank capacity of {self.fuel_tank_size} liters")

# Demonstration:
if __name__ == "__main__":
    power_boat = PowerBoat("Flash", 12.5, 8, 150, 250)
    power_boat.moor()
    power_boat.cruise("Key West", 120)
    power_boat.ignite_motor()
    power_boat.replenish_fuel(30)
    power_boat.special_capability()

# Mobile device class definition
class Smartphone:
    def __init__(self, manufacturer, device_name, operating_system, battery_size, display_dimension):
        self.manufacturer = manufacturer
        self.device_name = device_name
        self.operating_system = operating_system
        self.battery_size = battery_size
        self.display_dimension = display_dimension
        self.current_charge = battery_size  # Start with full charge
        self.is_operational = False

    def switch_on(self):
        if not self.is_operational:
            self.is_operational = True
            print(f"{self.manufacturer} {self.device_name} is now switched on.")
        else:
            print(f"{self.manufacturer} {self.device_name} is already switched on.")

    def switch_off(self):
        if self.is_operational:
            self.is_operational = False
            print(f"{self.manufacturer} {self.device_name} is now switched off.")
        else:
            print(f"{self.manufacturer} {self.device_name} is already switched off.")

    def consume_power(self, drain_amount):
        if self.is_operational:
            if self.current_charge >= drain_amount:
                self.current_charge -= drain_amount
                print(f"Current charge: {self.current_charge} mAh")
            else:
                print("Insufficient charge to execute this operation.")
        else:
            print("The smartphone is switched off. Please turn it on first.")

    def replenish_charge(self, charge_input):
        if self.current_charge + charge_input <= self.battery_size:
            self.current_charge += charge_input
            print(f"Current charge: {self.current_charge} mAh")
        else:
            self.current_charge = self.battery_size
            print("Battery has reached full capacity.")

