# Cinema booking system implementation
from datetime import datetime
from typing import List, Dict

class Movie:
    def __init__(self, title: str, director: str, category: str):
        self.title = title
        self.director = director
        self.genre = category

class Auditorium:
    def __init__(self, room_id: int, capacity: int):
        self.room_number = room_id
        self.max_seats = capacity
        self.showings: List['Show'] = []
        self.occupied_seats: Dict[str, bool] = {f'Place_{i}': True for i in range(1, capacity + 1)}

    def schedule_show(self, show: 'Show'):
        self.showings.append(show)

    def list_showings(self) -> List['Show']:
        return self.showings

    def get_free_seats(self, show: 'Show') -> List[str]:
        return [seat for seat, free in self.occupied_seats.items() if free]

class Show:
    def __init__(self, movie: Movie, start_time: datetime, end_time: datetime, auditorium: Auditorium):
        self.movie = movie
        self.start_time = start_time
        self.end_time = end_time
        self.auditorium = auditorium

class Reservation:
    def __init__(self, patron: str, show: Show, seats: List[str]):
        self.customer_name = patron
        self.show = show
        self.seats_reserved = seats

    def finalize_reservation(self):
        for seat in self.seats_reserved:
            if seat in self.show.auditorium.occupied_seats and self.show.auditorium.occupied_seats[seat]:
                self.show.auditorium.occupied_seats[seat] = False
            else:
