# Convert CMYK to HEX color representation 
def cmyk_to_hex(cmyk_values):
    try:
        c, m, y, k = cmyk_values
        if not (0 <= c <= 1 and 0 <= m <= 1 and 0 <= y <= 1 and 0 <= k <= 1):
            raise ValueError("CMYK values must be between 0 and 1")

        red = int(255 * (1 - c) * (1 - k))
        green = int(255 * (1 - m) * (1 - k))
        blue = int(255 * (1 - y) * (1 - k))

        return f"#{red:02X}{green:02X}{blue:02X}"
    except (ValueError, TypeError) as error:
        return f"Error: {error}"

def hex_to_cmyk(hex_color_code):
    try:
        if hex_color_code[0] != '#' or len(hex_color_code) != 7:
            raise ValueError("Invalid HEX color format")

        red = int(hex_color_code[1:3], 16) / 255.0
        green = int(hex_color_code[3:5], 16) / 255.0
        blue = int(hex_color_code[5:7], 16) / 255.0

        black = 1 - max(red, green, blue)
        if black == 1:
            return (0, 0, 0, 1)

        cyan = (1 - red - black) / (1 - black)
        magenta = (1 - green - black) / (1 - black)
        yellow = (1 - blue - black) / (1 - black)

        return (cyan, magenta, yellow, black)
    except (ValueError, TypeError) as error:
        return f"Error: {error}"

def convert_cmyk_list_to_hex(cmyk_collection):
    hex_collection = []
    for cmyk in cmyk_collection:
        hex_color = cmyk_to_hex(cmyk)
        hex_collection.append(hex_color)
    return hex_collection

def convert_hex_list_to_cmyk(hex_collection):
    cmyk_collection = []
    for hex_color in hex_collection:
        cmyk = hex_to_cmyk(hex_color)
        cmyk_collection.append(cmyk)
    return cmyk_collection

