# Calculate total size of a folder including subfolders using parallel processing
import os
from concurrent.futures import ThreadPoolExecutor, as_completed

def calculate_directory_size(directory_path):
    cumulative_size = 0
    with os.scandir(directory_path) as entries:
        for item in entries:
            if item.is_file():
                cumulative_size += item.stat().st_size
            elif item.is_dir():
                cumulative_size += calculate_directory_size(item.path)
    return cumulative_size

def compute_folder_size(folder_path, num_threads=4):
    with ThreadPoolExecutor(max_workers=num_threads) as pool:
        pending_tasks = []
        for current_root, subdirectories, _ in os.walk(folder_path, topdown=True):
            for subdir in subdirectories:
                subdir_full_path = os.path.join(current_root, subdir)
                pending_tasks.append(pool.submit(calculate_directory_size, subdir_full_path))

        overall_size = 0
        for task in as_completed(pending_tasks):
            overall_size += task.result()

        # Include sizes of files directly in the root directory
        with os.scandir(folder_path) as entries:
            for entry in entries:
                if entry.is_file():
                    overall_size += entry.stat().st_size

    return overall_size

if __name__ == "__main__":
    target_directory = "C:\\"
    computed_size = compute_folder_size(target_directory)
    print(f"Total size: {computed_size / 1024 / 1024 / 1024:.2f} GB")

