# Find numbers that are both perfect cubes and factorials
import math

def check_perfect_cube(value):
    """Determine if a given number is a perfect cube."""
    return round(value ** (1/3)) ** 3 == value

def check_factorial(value):
    """Determine if a given number is a factorial of some integer."""
    if value == 1:
        return True
    counter = 1
    current_factorial = 1
    while current_factorial < value:
        counter += 1
        current_factorial *= counter
    return current_factorial == value

def generate_cube_and_factorial_values(limit):
    """Generator function to yield the first 'limit' numbers that are both perfect cubes and factorials."""
    if not isinstance(limit, int) or limit < 0:
        raise ValueError("Limit must be a non-negative integer.")

    found_count = 0
    candidate = 1
    while found_count < limit:
        if check_perfect_cube(candidate) and check_factorial(candidate):
            yield candidate
            found_count += 1
        candidate += 1

# Example usage:
try:
    limit = 5
    for result in generate_cube_and_factorial_values(limit):
        print(result)
except ValueError as error:
    print(error)

# Calculate a mathematical expression that evaluates to the target value
import itertools
import math
from typing import List, Tuple

def find_expression(values: List[int], goal: int, permit_repeats: bool) -> Tuple[str, int]:
    def compute(expr: str) -> float:
        try:
            return eval(expr)
        except ZeroDivisionError:
            return float('inf')
        except Exception:
            return float('nan')

    def check_validity(expr: str) -> bool:
        try:
            eval(expr)
            return True
        except:
            return False

    def search_expressions(nums: List[int], goal: int, max_depth: int) -> Tuple[str, int]:
        if not nums:
            return "", -1

        # Generate all permutations of the numbers
        perms = list(itertools.permutations(nums))
        if not permit_repeats:
            perms = list(set(perms))

        # Define available operations
        ops_list = ['+', '-', '*', '/', '**', 'math.log']

        for p in perms:
            for depth in range(1, max_depth + 1):
                for combo in itertools.product(ops_list, repeat=depth):
                    expr = str(p[0])
                    count = 1
                    for j, op in enumerate(combo):
                        if count < len(p):
                            if op == 'math.log':
                                if p[count] > 0 and p[count] != 1:
                                    expr += f" {op}({p[count]})"
                                    count += 1
                                else:
                                    break
                            else:
                                expr += f" {op} {p[count]}"
                                count += 1
                        else:
                            break

                    if check_validity(expr):
                        val = compute(expr)
                        if math.isclose(val, goal, rel_tol=1e-9):
                            return expr, depth

        return "", -1

    # Limit the maximum number of operations
    max_depth = 5
    expr_str, depth = search_expressions(values, goal, max_depth)
    return expr_str, depth

# Demonstration usage
values = [2, 3, 5, 7]
goal = 10
permit_repeats = False
result_expr, num_ops = find_expression(values, goal, permit_repeats)
print(f"Expression: {result_expr}")
print(f"Operations: {num_ops}")

# Define a node for the circular linked list
class Element:
    def __init__(self, value):
        self.value = value
        self.link = None

class RingList:
    def __init__(self):
        self.start = None

    def add(self, value):
        new_element = Element(value)
        if not self.start:
            self.start = new_element
            new_element.link = self.start
        else:
            current = self.start
            while current.link != self.start:
                current = current.link
            current.link = new_element
            new_element.link = self.start

    def place(self, value, index):
        if index < 0:
            raise Exception("Index must be non-negative")

        new_element = Element(value)
        if index == 0:
            if not self.start:
                self.start = new_element
                new_element.link = self.start
            else:
                current = self.start
                while current.link != self.start:
                    current = current.link
                current.link = new_element
                new_element.link = self.start
                self.start = new_element
        else:
            current = self.start
            position = 0
            while current and position < index - 1:
                current = current.link
                position += 1
            if not current:
                raise IndexError("Index out of bounds")
            new_element.link = current.link
            current.link = new_element

    def show(self):
        if not self.start:
            return "List is empty"
        items = []
        current = self.start
        while True:
            items.append(str(current.value))
            current = current.link
            if current == self.start:
                break
        return " -> ".join(items) + " -> " + str(self.start.value)

# Initialize a circular linked list and insert "Hi" at index 2
ring = RingList()
ring.add(10)
ring.add(20)
ring.add(30)
ring.add(40)
ring.add(50)
ring.place("Hi", 2)
print(ring.show())  # Output: 10 -> 20 -> Hi -> 30 -> 40 -> 50 -> 10

# Find prime factors using Pollard's rho algorithm
import random
import math

def greatest_common_divisor(a, b):
    while b != 0:
        a, b = b, a % b
    return a

def pollards_factorization(n):
    if n % 2 == 0:
        return 2
    x = random.randint(2, n - 1)
    y = x
    c = random.randint(1, n - 1)
    d = 1
    polynomial = lambda x: (x*x + c) % n
    while d == 1:
        x = polynomial(x)
        y = polynomial(polynomial(y))
        d = greatest_common_divisor(abs(x - y), n)
        if d == n:
            return pollards_factorization(n)
    return d

def get_prime_decomposition(num):
    prime_list = []
    while num % 2 == 0:
        prime_list.append(2)
        num //= 2
    while num % 3 == 0:
        prime_list.append(3)
        num //= 3
    while num > 1:
        divisor = pollards_factorization(num)
        while num % divisor == 0:
            prime_list.append(divisor)
            num //= divisor
    return prime_list

# Example usage:
number = 123456789012  # Test value
result = get_prime_decomposition(number)
print(f"Prime decomposition of {number} is: {result}")

# Vector operations implementation with generic type support
from typing import List, TypeVar, Generic, Type
import math

T = TypeVar('T', bound=float)

class Vector(Generic[T]):
    def __init__(self, items: List[T]):
        self.values = items

    def __len__(self):
        return len(self.values)

    def __repr__(self):
        return f"Vector({self.values})"

    def __add__(self, other: 'Vector[T]') -> 'Vector[T]':
        if len(self) != len(other):
            raise ValueError("Vectors must be of the same length for addition.")
        return Vector([x + y for x, y in zip(self.values, other.values)])

    def __sub__(self, other: 'Vector[T]') -> 'Vector[T]':
        if len(self) != len(other):
            raise ValueError("Vectors must be of the same length for subtraction.")
        return Vector([x - y for x, y in zip(self.values, other.values)])

    def __mul__(self, factor: T) -> 'Vector[T]':
        return Vector([x * factor for x in self.values])

    def dot(self, other: 'Vector[T]') -> T:
        if len(self) != len(other):
            raise ValueError("Vectors must be of the same length for dot product.")
        return sum(x * y for x, y in zip(self.values, other.values))

    def cross(self, other: 'Vector[T]') -> 'Vector[T]':
        if len(self) != 3 or len(other) != 3:
            raise ValueError("Cross product is only defined for 3-dimensional vectors.")
        a1, a2, a3 = self.values
        b1, b2, b3 = other.values
        return Vector([
            a2 * b3 - a3 * b2,
            a3 * b1 - a1 * b3,
            a1 * b2 - a2 * b1
        ])

    def magnitude(self) -> T:
        return math.sqrt(sum(x ** 2 for x in self.values))

    def normalize(self) -> 'Vector[T]':
        mag = self.magnitude()
        if mag == 0:
            raise ValueError("Cannot normalize a zero vector.")
        return Vector([x / mag for x in self.values])

    def angle(self, other: 'Vector[T]') -> float:
        if len(self) != len(other):
            raise ValueError("Vectors must be of the same length to calculate the angle.")
        dot_product = self.dot(other)
        mag_self = self.magnitude()
        mag_other = other.magnitude()
        if mag_self == 0 or mag_other == 0:
            raise ValueError("Cannot calculate the angle with zero vector.")
        return math.acos(dot_product / (mag_self * mag_other))

    def projection(self, other: 'Vector[T]') -> 'Vector[T]':
        if len(self) != len(other):
            raise ValueError("Vectors must be of the same length to calculate the projection.")
        dot_product = self.dot(other)
        mag_other_squared = other.magnitude() ** 2
        if mag_other_squared == 0:
            raise ValueError("Cannot project onto a zero vector.")
        scalar = dot_product / mag_other_squared
        return other * scalar

# Example usage:
v1 = Vector([1, 2, 3])
v2 = Vector([4, 5, 6])

print(v1 + v2)  # Vector([5, 7, 9])
print(v1 - v2)  # Vector([-3, -3, -3])
print(v1 * 2)   # Vector([2, 4, 6])
print(v1.dot(v2))  # 32
print(v1.cross(v2))  # Vector([-3, 6, -3])
print(v1.magnitude())  # 3.7416573867739413
print(v1.normalize())  # Vector([0.2672612419124244, 0.5345224838248488, 0.8017837257372732])
print(v1.angle(v2))  # 0.2257261285527342
print(v1.projection(v2))  # Vector([1.7142857142857142, 2.142857142857143, 2.5714285714285716])

