# Modified version of the original code with Type I clone transformations
import re
from typing import Union, List

class Token:
    def __init__(self, kind: str, content: str):
        self.kind = kind
        self.content = content

class SyntaxAnalyzer:
    def __init__(self, formula: str):
        self.formula = formula
        self.token_list = self.lexical_analysis(formula)
        self.token_index = 0

    def lexical_analysis(self, formula: str) -> List[Token]:
        lexeme_patterns = [
            ('NUMERIC',   r'\d+(\.\d*)?'),  # Integer or decimal number
            ('VARIABLE', r'[a-zA-Z_][a-zA-Z_0-9]*'),  # Identifiers
            ('SYMBOL', r'[\+\-\*/=\!\&\|\<\>\~\^]'),  # Operators
            ('QUANTIFIER', r'\b(forall|exists)\b'),  # Quantifiers
            ('BRACKET', r'[\(\)]'),  # Parentheses
            ('SPACE', r'\s+'),  # Whitespace
            ('ERROR', r'.'),  # Any other character
        ]
        combined_regex = '|'.join('(?P<%s>%s)' % pair for pair in lexeme_patterns)
        token_sequence = []
        for match in re.finditer(combined_regex, formula):
            category = match.lastgroup
            text = match.group(category)
            if category == 'SPACE':
                continue
            elif category == 'ERROR':
                raise ValueError(f'Lexical error: {text}')
            token = Token(category, text)
            token_sequence.append(token)
        return token_sequence

    def analyze(self) -> dict:
        return self.parse_formula()

    def parse_formula(self) -> dict:
        current = self.token_list[self.token_index]
        if current.kind == 'VARIABLE':
            self.token_index += 1
            return {'category': 'variable', 'name': current.content}
        elif current.kind == 'NUMERIC':
            self.token_index += 1
            return {'category': 'numeric', 'value': float(current.content)}
        elif current.kind == 'BRACKET' and current.content == '(':
            self.token_index += 1
            parsed = self.parse_formula()
            if self.token_list[self.token_index].kind == 'BRACKET' and self.token_list[self.token_index].content == ')':
                self.token_index += 1
                return parsed
            else:
                raise ValueError('Mismatched parentheses')
        elif current.kind == 'SYMBOL':
            self.token_index += 1
            operand_left = self.parse_formula()
            operand_right = self.parse_formula()
            return {'category': 'binary_operation', 'operator': current.content, 'left': operand_left, 'right': operand_right}
        elif current.kind == 'QUANTIFIER':
            self.token_index += 1
            bound_var = self.parse_formula()
            body_expr = self.parse_formula()
            return {'category': 'quantified_expression', 'quantifier': current.content, 'bound_variable': bound_var, 'body': body_expr}
        else:
            raise ValueError(f'Syntax error: unexpected token {current.content}')

