class Individual:
    def __init__(self, full_name, years, title=None):
        self.full_name = full_name
        self.years = None
        self.set_years(years)
        self.title = self.resolve_title(title)

    def resolve_title(self, title):
        if title in ["Mr.", "Mrs.", "Miss", "Dr.", "Ms."]:
            return title
        else:
            return "Mr."  # Default to Mr. if no valid title is provided

    def set_years(self, years):
        if isinstance(years, int) and years > 0:
            self.years = years
        else:
            raise ValueError("Years must be a positive integer")

    def check_leap_year(self, year):
        if (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0):
            return True
        return False

    def create_expressive_message(self, present_year):
        if self.years is None:
            raise ValueError("Years is not set")

        birth_year = present_year - self.years
        if self.check_leap_year(birth_year):
            leap_note = " (a leap year)"
        else:
            leap_note = ""

        return f"{self.title} {self.full_name} is {self.years} years old, born in {birth_year}{leap_note}."

