# Determine if a list is monotonically increasing or decreasing 
def check_monotonic(sequence: list, strict_mode: bool = False):
    """
    Return True if the numeric elements in the list are monotonically increasing or decreasing.
    When strict_mode is True, consecutive elements must be different; otherwise, equal values are allowed.

    >>> check_monotonic([1, "2", 4, 20])
    True
    >>> check_monotonic([1, 20, None, 4, 10])
    False
    >>> check_monotonic([4, 1, "1", 0, -10], strict_mode=True)
    False
    >>> check_monotonic([1, 1, "one", 1, 1], strict_mode=False)
    True
    """
    def is_numeric(val):
        return isinstance(val, (int, float))

    # Extract only numeric elements from the sequence
    numeric_values = [val for val in sequence if is_numeric(val)]

    if len(numeric_values) < 2:
        return True  # Lists with fewer than 2 numeric items are considered monotonic

    direction = None
    for idx in range(len(numeric_values) - 1):
        if numeric_values[idx] < numeric_values[idx + 1]:
            if direction is None:
                direction = True
            elif not direction:
                return False
        elif numeric_values[idx] > numeric_values[idx + 1]:
            if direction is None:
                direction = False
            elif direction:
                return False
        elif strict_mode:
            return False  # Equal adjacent elements not allowed in strict mode

    return True

# Verification examples
print(check_monotonic([1, "2", 4, 20]))  # True
print(check_monotonic([1, 20, None, 4, 10]))  # False
print(check_monotonic([4, 1, "1", 0, -10], strict_mode=True))  # False
print(check_monotonic([1, 1, "one", 1, 1], strict_mode=False))  # True

# Calculate median of a list without using built-in sorting or functions
def find_middle_value(arr: list):
    """
    Computes the median value from the elements in list arr.
    Does not rely on built-in sorting or median functions.
    Supports nested tuples with negative and floating point numbers.
    Manages cases with multiple medians and invalid non-numeric entries.

    >>> find_middle_value([3, 1, 2, 4, 5])
    3
    >>> find_middle_value([-10, 4, 6, 1000, 10, 20])
    15.0
    >>> find_middle_value([1, 2, (3, 4), 5])
    3
    >>> find_middle_value([1, 'a', 2, 3])
    TypeError: List contains non-numeric elements.
    >>> find_middle_value([1])
    ValueError: List must contain at least two elements.
    """

    def unpack_sequence(seq):
        """Recursively unpack sequences that may include tuples."""
        output = []
        for element in seq:
            if isinstance(element, tuple):
                output.extend(unpack_sequence(element))
            elif isinstance(element, (int, float)):
                output.append(element)
            else:
                raise TypeError("List contains non-numeric elements.")
        return output

    def partition_select(sequence, index):
        """Find the element at given index using Quickselect algorithm."""
        if len(sequence) == 1:
            return sequence[0]

        pivot_val = sequence[len(sequence) // 2]
        smaller = [x for x in sequence if x < pivot_val]
        larger = [x for x in sequence if x > pivot_val]
        equal = [x for x in sequence if x == pivot_val]

        if index < len(smaller):
            return partition_select(smaller, index)
        elif index < len(smaller) + len(equal):
            return equal[0]
        else:
            return partition_select(larger, index - len(smaller) - len(equal))

    # Unpack the input list
    unpacked = unpack_sequence(arr)

    # Ensure there are at least two elements
    if len(unpacked) < 2:
        raise ValueError("List must contain at least two elements.")

    size = len(unpacked)
    if size % 2 == 1:
        # Odd count: return middle element
        return partition_select(unpacked, size // 2)
    else:
        # Even count: average of two middle elements
        mid1 = partition_select(unpacked, size // 2 - 1)
        mid2 = partition_select(unpacked, size // 2)
        return (mid1 + mid2) / 2

# Verification examples
print(find_middle_value([3, 1, 2, 4, 5]))  # 3
print(find_middle_value([-10, 4, 6, 1000, 10, 20]))  # 15.0
print(find_middle_value([1, 2, (3, 4), 5]))  # 3
try:
    print(find_middle_value([1, 'a', 2, 3]))  # TypeError
except TypeError as error:
    print(error)
try:
    print(find_middle_value([1]))  # ValueError
except ValueError as error:
    print(error)

# User management system with basic CRUD operations
class UserDataHandler:
    def __init__(self):
        self.user_records = {}

    def add_user(self, identifier, full_name):
        if identifier in self.user_records:
            return f"User with ID {identifier} already exists."
        self.user_records[identifier] = full_name
        return f"User with ID {identifier} created successfully."

    def get_user(self, identifier):
        if identifier in self.user_records:
            return f"User ID: {identifier}, Name: {self.user_records[identifier]}"
        return f"User with ID {identifier} does not exist."

    def modify_user(self, identifier, updated_name):
        if identifier in self.user_records:
            self.user_records[identifier] = updated_name
            return f"User with ID {identifier} updated successfully."
        return f"User with ID {identifier} does not exist."

    def remove_user(self, identifier):
        if identifier in self.user_records:
            del self.user_records[identifier]
            return f"User with ID {identifier} deleted successfully."
        return f"User with ID {identifier} does not exist."

    def show_all_users(self):
        if not self.user_records:
            return "No users in the system."
        return "\n".join([f"User ID: {user_id}, Name: {name}" for user_id, name in self.user_records.items()])


