# Convert numbers to words and generate LaTeX table
from num2words import num2words

def convert_number_to_text(value, language='en'):
    if language == 'en':
        return num2words(value, lang='en').replace('-', ' ').replace(',', '')
    elif language == 'fr':
        return num2words(value, lang='fr').replace('-', ' ').replace(',', '')
    else:
        raise ValueError("Language not supported")

def produce_latex_table(number_sequence):
    if not all(1 <= val <= 100 for val in number_sequence):
        raise ValueError("All numbers must be between 1 and 100")

    latex_output = "\\begin{tabular}{|c|c|c|}\n"
    latex_output += "\\hline\n"
    latex_output += "Numerical Value & English & French \\\\\n"
    latex_output += "\\hline\n"

    for val in number_sequence:
        english_text = convert_number_to_text(val, 'en')
        french_text = convert_number_to_text(val, 'fr')
        latex_output += f"{val} & {english_text} & {french_text} \\\\\n"
        latex_output += "\\hline\n"

    latex_output += "\\end{tabular}\n"
    return latex_output

def execute():
    import sys

    if len(sys.argv) < 2:
        print("Usage: python script.py <comma-separated-list-of-numbers>")
        sys.exit(1)

    try:
        user_numbers = [int(num) for num in sys.argv[1].split(',')]
    except ValueError:
        print("All input values must be integers.")
        sys.exit(1)

    if len(user_numbers) > 1000:
        print("Input list cannot contain more than 1000 values.")
        sys.exit(1)

    try:
        latex_result = produce_latex_table(user_numbers)
        print(latex_result)
    except ValueError as error:
        print(error)
        sys.exit(1)

if __name__ == "__main__":
    execute()

# Calculate volumes of various 3D shapes and compare them
import math

class VolumeCalculator:
    def __init__(self, shape_kind, *measurements):
        self.shape_kind = shape_kind.lower()
        self.measurements = measurements
        self.volume_val = self.compute_volume()

    def compute_volume(self):
        if self.shape_kind == 'sphere':
            if len(self.measurements) != 1 or self.measurements[0] <= 0:
                raise ValueError("Sphere needs a positive radius.")
            r = self.measurements[0]
            return (4/3) * math.pi * (r ** 3)
        elif self.shape_kind == 'cylinder':
            if len(self.measurements) != 2 or any(m <= 0 for m in self.measurements):
                raise ValueError("Cylinder requires positive radius and height.")
            rad, h = self.measurements
            return math.pi * (rad ** 2) * h
        elif self.shape_kind == 'cone':
            if len(self.measurements) != 2 or any(m <= 0 for m in self.measurements):
                raise ValueError("Cone requires positive radius and height.")
            rad, h = self.measurements
            return (1/3) * math.pi * (rad ** 2) * h
        elif self.shape_kind == 'cube':
            if len(self.measurements) != 1 or self.measurements[0] <= 0:
                raise ValueError("Cube needs a positive side length.")
            s = self.measurements[0]
            return s ** 3
        elif self.shape_kind == 'rectangular_prism':
            if len(self.measurements) != 3 or any(m <= 0 for m in self.measurements):
                raise ValueError("Rectangular prism needs positive length, width, and height.")
            l, w, h = self.measurements
            return l * w * h
        elif self.shape_kind == 'triangular_pyramid':
            if len(self.measurements) != 3 or any(m <= 0 for m in self.measurements):
                raise ValueError("Triangular pyramid needs positive base length, base width, and height.")
            b_len, b_wid, h = self.measurements
            return (1/3) * b_len * b_wid * h
        else:
            raise ValueError("Shape type not supported.")

    def compare_volumes(self, other_shape):
        if not isinstance(other_shape, VolumeCalculator):
            raise TypeError("Comparison must be with another VolumeCalculator object.")
        if self.shape_kind != other_shape.shape_kind:
            raise ValueError("Can only compare volumes of the same shape type.")

        if self.volume_val > other_shape.volume_val:
            diff_pct = ((self.volume_val - other_shape.volume_val) / other_shape.volume_val) * 100
            return f"The {self.shape_kind} with volume {self.volume_val} is larger by {diff_pct:.2f}%."
        elif self.volume_val < other_shape.volume_val:
            diff_pct = ((other_shape.volume_val - self.volume_val) / self.volume_val) * 100
            return f"The {other_shape.shape_kind} with volume {other_shape.volume_val} is larger by {diff_pct:.2f}%."
        else:
            return f"Both {self.shape_kind}s have the same volume of {self.volume_val}."

    def subtract_volume(self, other_shape):
        if not isinstance(other_shape, VolumeCalculator):
            raise TypeError("Subtraction must be with another VolumeCalculator object.")
        if self.shape_kind != other_shape.shape_kind:
            raise ValueError("Can only subtract volumes of the same shape type.")

        if self.volume_val < other_shape.volume_val:
            raise ValueError("The volume to subtract is larger than the current volume.")

        return self.volume_val - other_shape.volume_val

# Test cases
if __name__ == "__main__":
    try:
        sphere_a = VolumeCalculator('sphere', 5)
        sphere_b = VolumeCalculator('sphere', 3)
        print(sphere_a.compare_volumes(sphere_b))  # Should indicate sphere_a is larger
