# Definition for a node in a singly linked list
class ListNode:
    def __init__(self, value):
        self.value = value
        self.successor = None

class SinglyLinkedList:
    def __init__(self):
        self.start = None

    def add_to_end(self, value):
        new_node = ListNode(value)
        if self.start is None:
            self.start = new_node
        else:
            runner = self.start
            while runner.successor:
                runner = runner.successor
            runner.successor = new_node

    def show(self):
        runner = self.start
        while runner:
            print(runner.value, end=" -> ")
            runner = runner.successor
        print("None")

    def add_to_front(self, value):
        new_node = ListNode(value)
        new_node.successor = self.start
        self.start = new_node

    def remove(self, target_value):
        runner = self.start
        if runner and runner.value == target_value:
            self.start = runner.successor
            runner = None
            return
        previous = None
        while runner and runner.value != target_value:
            previous = runner
            runner = runner.successor
        if runner is None:
            return
        previous.successor = runner.successor
        runner = None

# Demonstration of usage
if __name__ == "__main__":
    sll = SinglyLinkedList()
    sll.add_to_end(1)
    sll.add_to_end(2)
    sll.add_to_end(3)
    sll.add_to_front(0)
    sll.show()  # Expected: 0 -> 1 -> 2 -> 3 -> None
    sll.remove(2)
    sll.show()  # Expected: 0 -> 1 -> 3 -> None

# Calculate and display sorted user data by age
from datetime import datetime

def compute_user_age(birth_date):
    try:
        # Convert string to date object
        birth_date = datetime.strptime(birth_date, "%d-%m-%Y")

        # Compute current age
        current_date = datetime.today()
        years_difference = current_date.year - birth_date.year
        has_had_birthday_this_year = (current_date.month, current_date.day) >= (birth_date.month, birth_date.day)
        age = years_difference - (0 if has_had_birthday_this_year else 1)
        return age
    except ValueError:
        # Return None for invalid dates
        return None

def show_sorted_individuals(individuals):
    # Collect processed user information
    processed_users = []

    for person in individuals:
        name = person.get('Full Name')
        dob = person.get('Date of Birth')

        if name and dob:
            calculated_age = compute_user_age(dob)
            if calculated_age is not None:
                processed_users.append({
                    'Full Name': name,
                    'Date of Birth': dob,
                    'Age': calculated_age
                })
            else:
                print(f"Invalid date format for {name}: {dob}")
        else:
            print(f"Missing data for user: {name}")

    # Sort users by age in descending order
    processed_users.sort(key=lambda item: item['Age'], reverse=True)

    # Print the sorted list
    for record in processed_users:
        print(f"Full Name: {record['Full Name']}, Date of Birth: {record['Date of Birth']}, Age: {record['Age']}")

