        self.course_name = course_name
        self.instructor = instructor

    def __repr__(self):
        return f"Course(course_name='{self.course_name}', instructor='{self.instructor}')"

class StudentRecord:
    def __init__(self):
        self.pupils = {}

    def register_pupil(self, pupil_name, years_old):
        if pupil_name in self.pupils:
            raise ValueError(f"Pupil with name '{pupil_name}' already registered.")
        self.pupils[pupil_name] = {"years_old": years_old, "enrollments": []}

    def deregister_pupil(self, pupil_name):
        if pupil_name not in self.pupils:
            raise ValueError(f"Pupil with name '{pupil_name}' does not exist.")
        del self.pupils[pupil_name]

    def modify_pupil_age(self, pupil_name, years_old):
        if pupil_name not in self.pupils:
            raise ValueError(f"Pupil with name '{pupil_name}' does not exist.")
        self.pupils[pupil_name]["years_old"] = years_old

    def enroll_pupil(self, pupil_name, course_name, instructor):
        if pupil_name not in self.pupils:
            raise ValueError(f"Pupil with name '{pupil_name}' does not exist.")
        course_obj = Course(course_name, instructor)
        if course_obj not in self.pupils[pupil_name]["enrollments"]:
            self.pupils[pupil_name]["enrollments"].append(course_obj)

    def unenroll_pupil(self, pupil_name, course_name):
        if pupil_name not in self.pupils:
            raise ValueError(f"Pupil with name '{pupil_name}' does not exist.")
        self.pupils[pupil_name]["enrollments"] = [crs for crs in self.pupils[pupil_name]["enrollments"] if crs.course_name != course_name]

    def retrieve_pupil_info(self, pupil_name):
        if pupil_name not in self.pupils:
            raise ValueError(f"Pupil with name '{pupil_name}' does not exist.")
        return self.pupils[pupil_name]

    def __repr__(self):
        return f"StudentRecord(pupils={self.pupils})"

