# Calculate frustum properties for circular and elliptical shapes
import math

def check_input_parameters(r1, r2, h, a1=None, a2=None, b1=None, b2=None):
    if r1 <= 0 or r2 <= 0 or h <= 0:
        raise ValueError("All dimensions must be positive values.")
    if a1 is not None and a2 is not None and b1 is not None and b2 is not None:
        if a1 <= 0 or a2 <= 0 or b1 <= 0 or b2 <= 0:
            raise ValueError("All dimensions must be positive values.")

def curved_surface_area_circular(r1, r2, h):
    return math.pi * (r1 + r2) * math.sqrt((r2 - r1)**2 + h**2)

def curved_surface_area_elliptical(a1, a2, b1, b2, h):
    part1 = math.pi * (a1 + a2) * math.sqrt((a2 - a1)**2 + h**2)
    part2 = math.pi * (b1 + b2) * math.sqrt((b2 - b1)**2 + h**2)
    return part1 + part2

def capacity_circular(r1, r2, h):
    return (math.pi * h / 3) * (r1**2 + r2**2 + r1 * r2)

def capacity_elliptical(a1, a2, b1, b2, h):
    return (math.pi * h / 3) * (a1 * b1 + a2 * b2 + math.sqrt(a1 * b1 * a2 * b2))

def compute_frustum_characteristics(frustums):
    outputs = []
    for item in frustums:
        r1 = item['r1']
        r2 = item['r2']
        h = item['h']
        a1 = item.get('a1')
        a2 = item.get('a2')
        b1 = item.get('b1')
        b2 = item.get('b2')

        check_input_parameters(r1, r2, h, a1, a2, b1, b2)

        if a1 is not None and a2 is not None and b1 is not None and b2 is not None:
            curved_surface_area = curved_surface_area_elliptical(a1, a2, b1, b2, h)
            capacity = capacity_elliptical(a1, a2, b1, b2, h)
        else:
            curved_surface_area = curved_surface_area_circular(r1, r2, h)
            capacity = capacity_circular(r1, r2, h)

        outputs.append({
            'curved_surface_area': curved_surface_area,
            'capacity': capacity
        })

    return outputs

