# Define a class for rectangular shapes
class RectShape:
    def __init__(self, height, breadth):
        self.set_height(height)
        self.set_breadth(breadth)

    def set_height(self, height):
        if not isinstance(height, (int, float)) or height <= 0:
            raise ValueError("Height must be a positive non-zero number.")
        self._height = height

    def get_height(self):
        return self._height

    def set_breadth(self, breadth):
        if not isinstance(breadth, (int, float)) or breadth <= 0:
            raise ValueError("Breadth must be a positive non-zero number.")
        self._breadth = breadth

    def get_breadth(self):
        return self._breadth

    def surface_area(self):
        try:
            return self._height * self._breadth
        except Exception as e:
            raise RuntimeError("An error occurred while calculating the surface area.") from e

    def boundary_length(self):
        try:
            return 2 * (self._height + self._breadth)
        except Exception as e:
            raise RuntimeError("An error occurred while calculating the boundary length.") from e

    def has_equal_area(self, other_shape):
        if not isinstance(other_shape, RectShape):
            raise TypeError("The 'other_shape' parameter must be an instance of RectShape.")
        return self.surface_area() == other_shape.surface_area()

