# LLDP network topology discovery tool
from scapy.all import *

def extract_lldp_data(packet):
    if packet.haslayer(LLDPDU):
        lldp_layer = packet[LLDPDU]
        chassis_identifier = lldp_layer.get_tlv_val(1).decode("utf-8")
        port_identifier = lldp_layer.get_tlv_val(2).decode("utf-8")
        time_to_live = lldp_layer.get_tlv_val(3)
        return (chassis_identifier, port_identifier, time_to_live)

def transmit_lldp_packets(net_interface):
    ethernet_header = Ether(dst="01:80:c2:00:00:0e")
    chassis_tl = LLDPChassisID(subtype=7, id=bytes(BPFProgram(interface=net_interface).filter[0].bh_mac))
    port_tl = LLDPPortID(subtype=7, id=str(net_interface).encode())
    ttl_tl = LLDPDUTimeToLive(seconds=120)
    lldp_frame = LLDPDU(tlvs=[chassis_tl, port_tl, ttl_tl])
    full_packet = ethernet_header / lldp_frame
    sendp(full_packet, iface=net_interface, loop=1)

def main():
    network_map = {}
    available_interfaces = get_windows_if_list() if sys.platform == "win32" else get_if_list()
    print("Available network interfaces:")
    for idx in range(len(available_interfaces)):
        print(f"{idx}: {available_interfaces[idx]}")

    selected_idx = int(input("Select an interface to send LLDP frames: "))
    chosen_interface = available_interfaces[selected_idx]

    try:
        while True:
            transmit_lldp_packets(chosen_interface)
            captured_packets = sniff(iface=chosen_interface, timeout=1, filter="ether dst 01:80:c2:00:00:0e")

            for packet in captured_packets:
                data = extract_lldp_data(packet)
                if data:
                    chassis_id, port_id, ttl_value = data
                    if chassis_id not in network_map:
                        network_map[chassis_id] = []
                    network_map[chassis_id].append(port_id)

            print("\nDetected network topology:")
            for count, (chassis_id, port_list) in enumerate(network_map.items()):
                print(f"{count+1}. {chassis_id}")
                for port_id in port_list:
                    print(f"   {port_id}")
    except KeyboardInterrupt:
        pass

if __name__ == "__main__":
    main()

