# Calculate and process sequences based on arithmetic and geometric rules
import math
from typing import List, Dict, Tuple

def produce_series(initial: float, multiplier: float, increment: float, count: int) -> List[float]:
    """
    Produce a series following arithmetic and geometric progression rules.

    :param initial: Starting value of the series
    :param multiplier: Common ratio for geometric component
    :param increment: Common difference for arithmetic component
    :param count: Number of elements in the series
    :return: List of generated values
    """
    if count <= 0:
        raise ValueError("Series length must be positive.")

    if multiplier == 0 and increment == 0:
        raise ValueError("Multiplier and increment cannot both be zero.")

    if multiplier == 0:
        return [initial + idx * increment for idx in range(count)]

    if increment == 0:
        return [initial * (multiplier ** idx) for idx in range(count)]

    # Mixed progression: combine geometric and arithmetic components
    return [initial * (multiplier ** idx) + idx * increment for idx in range(count)]

def compute_average(series: List[float]) -> float:
    """
    Compute the arithmetic average of a series.

    :param series: List of numeric values
    :return: Arithmetic average
    """
    return sum(series) / len(series)

def compute_geometric_average(series: List[float]) -> float:
    """
    Compute the geometric average of a series.

    :param series: List of numeric values
    :return: Geometric average
    """
    product = math.prod(series)
    return product ** (1 / len(series))

def check_series(series: List[float], multiplier: float, increment: float) -> bool:
    """
    Verify if a series adheres to arithmetic and geometric progression rules.

    :param series: List of numeric values
    :param multiplier: Expected common ratio
    :param increment: Expected common difference
    :return: True if valid, False otherwise
    """
    if len(series) < 2:
        return True  # Single-element series are inherently valid

    for i in range(1, len(series)):
        if multiplier != 0 and series[i] / series[i - 1] != multiplier:
            return False
        if increment != 0 and series[i] - series[i - 1] != increment:
            return False
    return True

def produce_multiple_series(params_dict: Dict) -> List[Dict]:
    """
    Generate multiple series based on parameter combinations from input dictionary.

    :param params_dict: Dictionary containing lists of parameters for generation
    :return: List of dictionaries with series data and statistics
    """
    result_series = []
    for base_value in params_dict['base']:
        for factor in params_dict['factor']:
            for step in params_dict['step']:
                for size in params_dict['size']:
                    try:
                        series = produce_series(base_value, factor, step, size)
                        if not check_series(series, factor, step):
                            raise ValueError("Series does not conform to progression rules.")

                        avg_val = compute_average(series)
                        geo_avg = compute_geometric_average(series)
                        result_series.append({
                            'base': base_value,
                            'factor': factor,
                            'step': step,
                            'size': size,
                            'series': series,
                            'average': avg_val,
                            'geometric_average': geo_avg
                        })
                    except Exception as err:
                        print(f"Error generating series: {err}")
    return result_series

def order_series(series_list: List[Dict], mode: str) -> List[Dict]:
    """
    Order series according to specified criteria.

    :param series_list: List of series dictionaries
    :param mode: Ordering method ('total_first' or 'avg_first')
    :return: Ordered list of series dictionaries
    """
    if mode == 'total_first':
        return sorted(series_list, key=lambda x: (sum(x['series']), x['geometric_average']), reverse=True)
    elif mode == 'avg_first':
        return sorted(series_list, key=lambda x: (x['geometric_average'], sum(x['series'])), reverse=True)
    else:
        raise ValueError("Invalid ordering mode. Use 'total_first' or 'avg_first'.")

def execute():
    # Example parameter configuration
