class LibraryUser:
    def __init__(self, user_id, full_name, street_address, contact_number, mail_address):
        self.user_id = user_id
        self.full_name = full_name
        self.street_address = street_address
        self.contact_number = contact_number
        self.mail_address = mail_address

    def __str__(self):
        return f"User ID: {self.user_id}\nName: {self.full_name}\nAddress: {self.street_address}\nPhone: {self.contact_number}\nEmail: {self.mail_address}"

    def change_name(self, updated_name):
        self.full_name = updated_name

    def change_address(self, updated_address):
        self.street_address = updated_address

    def change_phone(self, updated_phone):
        self.contact_number = updated_phone

    def change_email(self, updated_email):
        self.mail_address = updated_email

class LibraryUserManager:
    def __init__(self):
        self.users = {}

    def register_user(self, user_id, full_name, street_address, contact_number, mail_address):
        if user_id in self.users:
            raise ValueError(f"User with ID {user_id} already registered.")
        new_user = LibraryUser(user_id, full_name, street_address, contact_number, mail_address)
        self.users[user_id] = new_user
        print(f"User with ID {user_id} registered successfully.")

    def fetch_user(self, user_id):
        if user_id not in self.users:
            raise ValueError(f"User with ID {user_id} does not exist.")
        return self.users[user_id]

    def modify_user(self, user_id, **kwargs):
        if user_id not in self.users:
            raise ValueError(f"User with ID {user_id} does not exist.")
        user = self.users[user_id]
        if 'full_name' in kwargs:
            user.change_name(kwargs['full_name'])
        if 'street_address' in kwargs:
            user.change_address(kwargs['street_address'])
        if 'contact_number' in kwargs:
            user.change_phone(kwargs['contact_number'])
        if 'mail_address' in kwargs:
            user.change_email(kwargs['mail_address'])
        print(f"User with ID {user_id} modified successfully.")

    def deregister_user(self, user_id):
        if user_id not in self.users:
            raise ValueError(f"User with ID {user_id} does not exist.")
        del self.users[user_id]
        print(f"User with ID {user_id} deregistered successfully.")

    def display_users(self):
        if not self.users:
            print("No users registered in the library.")
            return
        for user_id, user in self.users.items():
            print(user)
            print("-" * 40)

# Example usage
