# Script to compute MD5 checksums and detect duplicate files in the current directory
import os
import hashlib

def compute_file_checksum(file_path):
    """Compute the MD5 checksum of a given file."""
    md5_hash = hashlib.md5()
    with open(file_path, "rb") as file_obj:
        for block in iter(lambda: file_obj.read(4096), b""):
            md5_hash.update(block)
    return md5_hash.hexdigest()

def scan_directory_and_hash():
    """Scan all files in the current working directory and compute their MD5 checksums."""
    checksums = {}
    for entry in os.listdir():
        full_path = os.path.join(os.getcwd(), entry)
        if os.path.isfile(full_path):
            checksums[entry] = compute_file_checksum(full_path)
            print(f"{entry}: {checksums[entry]}")
    return checksums

def identify_duplicate_files(checksum_data):
    """Identify files that share the same MD5 checksum (potential duplicates)."""
    mapping = {}
    for filename, checksum in checksum_data.items():
        if checksum in mapping:
            mapping[checksum].append(filename)
        else:
            mapping[checksum] = [filename]

    duplicates = {checksum: filenames for checksum, filenames in mapping.items() if len(filenames) > 1}

    if duplicates:
        print("Duplicate files detected:")
        for checksum, filenames in duplicates.items():
            print(f"MD5 Checksum: {checksum}")
            for filename in filenames:
                print(f"  - {filename}")
    else:
        print("No duplicate files found.")

if __name__ == "__main__":
    checksum_data = scan_directory_and_hash()
    identify_duplicate_files(checksum_data)

