# Calculate the Highest Common Factor (HCF) and check divisibility 
import math

def calculate_hcf_four(w, x, y, z):
    """Determine the HCF of four integers."""
    return math.gcd(math.gcd(w, x), math.gcd(y, z))

def nearest_multiple(value, base):
    """Find the nearest integer to 'value' that is a multiple of 'base'."""
    q = value // base
    r = value % base
    if r < base / 2:
        return q * base
    else:
        return (q + 1) * base

def hcf_and_divisibility_analysis(n1, n2, n3, n4, k):
    try:
        # Compute the HCF of the four numbers
        hcf_value = calculate_hcf_four(n1, n2, n3, n4)
        print(f"The Greatest Common Divisor (GCD/HCF) of {n1}, {n2}, {n3}, and {n4} is: {hcf_value}")

        # Assess divisibility and compute nearest multiples where needed
        outcomes = {}
        for val in [n1, n2, n3, n4]:
            if val % k == 0:
                outcomes[val] = f"{val} is evenly divisible by {k}"
            else:
                nearest_val = nearest_multiple(val, k)
                outcomes[val] = f"{val} is not divisible by {k}. The nearest multiple is {nearest_val}"

        for val, msg in outcomes.items():
            print(msg)

    except ZeroDivisionError:
        print("Error: Division by zero is not allowed.")
    except TypeError:
        print("Error: All inputs must be numeric.")
    except Exception as err:
        print(f"An unexpected issue arose: {err}")

