# Calculate the average of the 5 largest and 5 smallest numbers in a list
def get_max_min_values(arr, count):
    if len(arr) < 2 * count:
        raise ValueError("Array must contain at least 10 elements to find 5 highest and 5 lowest values.")

    high_values = []
    low_values = []

    for _ in range(count):
        current_max = float('-inf')
        current_min = float('inf')

        for item in arr:
            if item > current_max and item not in high_values:
                current_max = item
            if item < current_min and item not in low_values:
                current_min = item

        high_values.append(current_max)
        low_values.append(current_min)

    return high_values, low_values

def compute_average_of_boundaries(arr):
    try:
        high_vals, low_vals = get_max_min_values(arr, 5)
        return (sum(high_vals) + sum(low_vals)) / 10
    except ValueError as error:
        return str(error)

