# Thread-safe hash table implementation with dynamic resizing
import threading
from typing import Any, Hashable, Optional

class HashMap:
    def __init__(self, capacity: int = 10, threshold: float = 0.7):
        self.capacity = capacity
        self.threshold = threshold
        self.storage = [None] * self.capacity
        self.mutex = threading.Lock()
        self.elements = 0

    def _compute_index(self, key: Hashable) -> int:
        if isinstance(key, int):
            return key % self.capacity
        elif isinstance(key, str):
            return sum(ord(character) for character in key) % self.capacity
        else:
            raise TypeError("Key must be an integer or a string")

    def _expand_storage(self) -> None:
        with self.mutex:
            previous_buckets = self.storage
            self.capacity *= 2
            self.storage = [None] * self.capacity
            self.elements = 0

            for bucket in previous_buckets:
                if bucket is not None:
                    for key, value in bucket:
                        self.put(key, value)

    def put(self, key: Hashable, value: Any) -> None:
        with self.mutex:
            position = self._compute_index(key)
            if self.storage[position] is None:
                self.storage[position] = []
            for idx, (k, v) in enumerate(self.storage[position]):
                if k == key:
                    self.storage[position][idx] = (key, value)
                    return
            self.storage[position].append((key, value))
            self.elements += 1

            if self.elements / self.capacity >= self.threshold:
                self._expand_storage()

    def get(self, key: Hashable) -> Optional[Any]:
        with self.mutex:
            position = self._compute_index(key)
            if self.storage[position] is None:
                return None
            for k, v in self.storage[position]:
                if k == key:
                    return v
            return None

    def remove(self, key: Hashable) -> None:
        with self.mutex:
            position = self._compute_index(key)
            if self.storage[position] is None:
                return
            for idx, (k, v) in enumerate(self.storage[position]):
                if k == key:
                    del self.storage[position][idx]
                    self.elements -= 1
                    return

    def __repr__(self):
        return repr(self.storage)

# Demonstration of usage
if __name__ == "__main__":
    hm = HashMap()
    hm.put(1, "one")
    hm.put(2, "two")
    hm.put("three", 3)
    hm.put(11, "eleven")  # Should trigger expansion
    print(hm.get(1))  # Output: one
