class Vehicle:
    def __init__(self, manufacturer, model_name, production_year, paint_color, top_velocity, cylinder_capacity):
        self.manufacturer = manufacturer
        self.model_name = model_name
        self.production_year = production_year
        self.paint_color = paint_color
        self.top_velocity = top_velocity
        self.cylinder_capacity = cylinder_capacity
        self.efficiency_km_per_liter = 0.0  # kilometers per liter
        self.fuel_remaining = 0.0  # liters
        self.mileage = 0.0  # kilometers
        self.cumulative_distance = 0.0  # kilometers

    def compute_efficiency(self, distance_covered, fuel_used):
        if fuel_used > 0:
            self.efficiency_km_per_liter = distance_covered / fuel_used
        else:
            self.efficiency_km_per_liter = 0.0

    def estimate_travel_duration(self, target_distance):
        if self.top_velocity > 0:
            return target_distance / self.top_velocity
        else:
            return float('inf')  # Infinite time if top speed is 0

    def determine_mean_speed(self, distance, elapsed_time):
        if elapsed_time > 0:
            return distance / elapsed_time
        else:
            return 0.0

    def assess_fuel_availability(self, planned_distance):
        if self.efficiency_km_per_liter > 0:
            needed_fuel = planned_distance / self.efficiency_km_per_liter
            return self.fuel_remaining >= needed_fuel
        else:
            return False

    def adjust_mileage(self, distance_driven):
        self.mileage += distance_driven
        self.cumulative_distance += distance_driven

    def estimate_fuel_usage(self, distance):
        if self.efficiency_km_per_liter > 0:
            return distance / self.efficiency_km_per_liter
        else:
            return float('inf')  # Infinite consumption if efficiency is 0

    def estimate_fuel_consumption_per_hundred_km(self):
        if self.efficiency_km_per_liter > 0:
            return 100 / self.efficiency_km_per_liter
        else:
            return float('inf')  # Infinite consumption if efficiency is 0

    def compute_energy_efficiency(self, distance):
        if self.cylinder_capacity > 0 and distance > 0:
            # Assuming a constant power output for simplicity
            power_rating = self.cylinder_capacity * 0.001  # kW (simplified conversion)
            energy_required = distance * self.estimate_fuel_usage(distance)  # liters
            return energy_required / (distance * power_rating)
        else:
            return float('inf')  # Infinite efficiency if capacity or distance is 0

