# Stock management system implementation
class StockManager:
    def __init__(self):
        self.stock = {}

    def insert_product(self, product_code, product_name, unit_cost, stock_count):
        if product_code in self.stock:
            print(f"Warning: Product with code {product_code} is already present.")
        else:
            self.stock[product_code] = {
                'name': product_name,
                'cost': unit_cost,
                'count': stock_count
            }
