import re

def locate_consecutive_word_and_singular_char(text):
    # Locate consecutive words with at least 4 repetitions
    matched_word = None
    matched_word_index = None
    singular_char = None
    singular_char_index = None

    # Extract words from the text
    tokens = re.findall(r'\b\w+\b', text)

    # Look for words repeated at least 4 times consecutively
    for idx in range(len(tokens) - 3):
        if tokens[idx] == tokens[idx + 1] == tokens[idx + 2] == tokens[idx + 3]:
            matched_word = tokens[idx]
            matched_word_index = idx
            break

    # Identify characters that appear only once
    char_occurrences = {}
    for index, symbol in enumerate(text):
        if symbol.isalpha():
            if symbol in char_occurrences:
                char_occurrences[symbol].append(index)
            else:
                char_occurrences[symbol] = [index]

    # Find the first character that appears exactly once
    for char, indices in char_occurrences.items():
        if len(indices) == 1:
            singular_char = char
            singular_char_index = indices[0]
            break

    return matched_word, matched_word_index, singular_char, singular_char_index

