# Compute hash of a dictionary with normalized and sorted structure
import hashlib
import json
from datetime import datetime

def sort_key_generator(pair):
    key, val = pair
    if isinstance(val, (int, float)):
        return (0, -val)
    elif isinstance(val, str):
        return (1, val.lower())
    elif isinstance(val, bool):
        return (2, val)
    elif isinstance(val, (list, dict, datetime)):
        return (3, val)
    else:
        raise TypeError(f"Unsupported data type: {type(val)}")

def normalize_item(val):
    if isinstance(val, str):
        return val.lower()
    elif isinstance(val, (int, float, bool)):
        return val
    elif isinstance(val, list):
        return [normalize_item(x) for x in val]
    elif isinstance(val, dict):
        return normalize_structure(val)
    elif isinstance(val, datetime):
        return val.isoformat().lower()
    else:
        raise TypeError(f"Unsupported data type: {type(val)}")

def normalize_structure(struct):
    if not isinstance(struct, dict):
        raise TypeError("Input must be a dictionary")

    processed_pairs = sorted(
        ((str(k).lower(), normalize_item(v)) for k, v in struct.items() if v is not None and v != ""),
        key=sort_key_generator
    )
    return dict(processed_pairs)

def compute_hash(struct, method='sha512'):
    cleaned_dict = normalize_structure(struct)
    json_text = json.dumps(cleaned_dict, sort_keys=True)
    hasher = hashlib.new(method)
    hasher.update(json_text.encode('utf-8'))
    return hasher.hexdigest()

