# Definition for singly-linked list.
class Node:
    def __init__(self, data=0, next_node=None):
        self.data = data
        self.next = next_node

class SolutionOperations:
    def mergeSort(self, start: Node) -> Node:
        if not start or not start.next:
            return start
        slow_ptr, fast_ptr = start, start.next
        while fast_ptr and fast_ptr.next:
            fast_ptr = fast_ptr.next.next
            slow_ptr = slow_ptr.next
        middle, slow_ptr.next = slow_ptr.next, None
        left_half = self.mergeSort(start)
        right_half = self.mergeSort(middle)
        return self.combine(left_half, right_half)

    def combine(self, first: Node, second: Node) -> Node:
        sentinel = current = Node(0)
        while first and second:
            if first.data < second.data:
                current.next, first = first, first.next
            else:
                current.next, second = second, second.next
            current = current.next
        current.next = first if first else second
        return sentinel.next

    def invertList(self, head: Node) -> Node:
        previous = None
        present = head
        while present:
            future_node = present.next
            present.next = previous
            previous = present
            present = future_node
        return previous

    def eliminateDuplicates(self, head: Node) -> Node:
        if not head:
            return head
        current = head
        while current and current.next:
            if current.data == current.next.data:
                current.next = current.next.next
            else:
                current = current.next
        return head

    def locateCenter(self, head: Node) -> Node:
        if not head:
            return None
        slow_runner, fast_runner = head, head
        while fast_runner and fast_runner.next:
            slow_runner = slow_runner.next
            fast_runner = fast_runner.next.next
        return slow_runner

    def processLinkedList(self, head: Node) -> (Node, int):
        # Phase 1: Sort the linked list
        ordered_head = self.mergeSort(head)

        # Phase 2: Reverse the sorted list
        inverted_head = self.invertList(ordered_head)

        # Phase 3: Remove duplicates from the reversed list
        deduplicated_head = self.eliminateDuplicates(inverted_head)

        # Phase 4: Locate the middle node
        center_node = self.locateCenter(deduplicated_head)

        return deduplicated_head, center_node.data if center_node else None

# Example usage:
# Create a linked list: 7 -> 3 -> 5 -> 1
head = Node(7, Node(3, Node(5, Node(1))))
processor = SolutionOperations()
