# Check if a string is a palindrome
def check_palindrome(text: str) -> bool:
    start, end = 0, len(text) - 1
    while start < end:
        if text[start] != text[end]:
            return False
        start += 1
        end -= 1
    return True

# Calculate cone surface areas and volumes for various configurations
import numpy as np
from scipy.integrate import quad

def check_parameters(r1, r2, a, b, h, f_func, g_func):
    if r1 < 0 or r2 < 0 or a < 0 or b < 0 or h < 0:
        raise ValueError("Invalid input: negative values are not allowed")
    if f_func is not None and not callable(f_func):
        raise ValueError("Invalid input: f must be a callable function")
    if g_func is not None and not callable(g_func):
        raise ValueError("Invalid input: g must be a callable function")

def calculate_cone_properties(r1, r2, h):
    surface_area = np.pi * (r1 + r2) * np.sqrt((r1 - r2)**2 + h**2)
    volume = (1/3) * np.pi * h * (r1**2 + r1*r2 + r2**2)
    return surface_area, volume

def calculate_elliptical_cone_properties(a1, b1, a2, b2, h):
    surface_area = quad(lambda h_val: 2 * np.pi * np.sqrt(a1**2 + b1**2) * np.sqrt(1 + (a1 - a2)**2 / h_val**2), 0, h)[0]
    volume = (1/3) * np.pi * h * (a1 * b1 + a1 * b2 + a2 * b2)
    return surface_area, volume

def calculate_variable_cone_properties(f_func, h):
    surface_area = quad(lambda h_val: 2 * np.pi * f_func(h_val) * np.sqrt(1 + (f_func(h_val + 1e-6) - f_func(h_val))**2 / 1e-6), 0, h)[0]
    volume = quad(lambda h_val: np.pi * f_func(h_val)**2, 0, h)[0]
    return surface_area, volume

def handle_cone_calculation(r1, r2, a, b, h, f_func, g_func, time_values=None):
    check_parameters(r1, r2, a, b, h, f_func, g_func)

    if g_func is not None:
        output = []
        for t in time_values:
            r1_t, r2_t, a_t, b_t, h_t = g_func(t)
            surface_area, volume = handle_cone_calculation(r1_t, r2_t, a_t, b_t, h_t, f_func, None)
            output.append((surface_area, volume))
        return output

    if f_func is not None:
        return calculate_variable_cone_properties(f_func, h)

    if a > 0 and b > 0:
        return calculate_elliptical_cone_properties(r1, r1, r2, r2, h)

    return calculate_cone_properties(r1, r2, h)

def compute_all_cones(cone_list, time_values=None):
    final_results = []
    for cone_params in cone_list:
        r1, r2, a, b, h, f_func, g_func = cone_params
        result = handle_cone_calculation(r1, r2, a, b, h, f_func, g_func, time_values)
        final_results.append(result)
    return final_results

# Example usage
cone_list = [
    (3, 2, 0, 0, 5, None, None),
    (4, 3, 5, 3, 6, None, None),
    (5, 4, 0, 0, 7, lambda h: 5 - h/2, None),
    (6, 5, 7, 4, 8, None, lambda t: (6 + t, 5 + t, 7 + t, 4 + t, 8 + t))
]

time_values = np.linspace(0, 10, 100)
final_results = compute_all_cones(cone_list, time_values)
print(final_results)

