# Modified version of the FileSystem class with renamed variables and reordered logic
import os
import json
import uuid

class StorageManager:
    def __init__(self, config):
        self.storage_path = config.get('storageDirectory')
        if not self.storage_path:
            raise ValueError("Configuration key 'storageDirectory' is mandatory.")
        os.makedirs(self.storage_path, exist_ok=True)

    def _construct_item_path(self, item_id):
        return os.path.join(self.storage_path, item_id)

    def store_item(self, item_data):
        if 'identifier' not in item_data:
            item_data['identifier'] = str(uuid.uuid4())
        item_id = item_data['identifier']
        item_dir = self._construct_item_path(item_id)
        os.makedirs(item_dir, exist_ok=True)
        data_file = os.path.join(item_dir, 'data.json')
        with open(data_file, 'w') as file:
            json.dump(item_data, file)
        return item_data

    def remove_item(self, item_id):
        item_location = self._construct_item_path(item_id)
        if os.path.exists(item_location):
            os.rmdir(item_location)
        else:
            raise FileNotFoundError(f"Item with ID {item_id} could not be located.")

    def retrieve_by_id(self, item_id):
        item_location = self._construct_item_path(item_id)
        data_file = os.path.join(item_location, 'data.json')
        if os.path.exists(data_file):
            with open(data_file, 'r') as file:
                return json.load(file)
        else:
            raise FileNotFoundError(f"Item with ID {item_id} does not exist.")

    def retrieve_multiple(self, item_ids):
        return [self.retrieve_by_id(item_id) for item_id in item_ids]

    def list_all_items(self, sort_order='ascending'):
        directory_names = [d for d in os.listdir(self.storage_path) 
                          if os.path.isdir(os.path.join(self.storage_path, d))]
        item_list = [self.retrieve_by_id(item_id) for item_id in directory_names]
        item_list.sort(key=lambda x: x['identifier'], reverse=(sort_order == 'descending'))
        return item_list

    def get_item(self, item_id):
        try:
            return self.retrieve_by_id(item_id)
        except FileNotFoundError:
            return None

