# Compute item similarity using cosine similarity for collaborative filtering
import math

def item_similarity_filtering(input_data):
    item_similarities = {}
    for item_a, features_a in input_data.items():
        for item_b, features_b in input_data.items():
            if item_a == item_b: 
                continue
            similarity_value = cosine_similarity(features_a, features_b)
            if similarity_value > 0:  # Only retain items with positive similarity
                item_similarities.setdefault(item_a, []).append((item_b, similarity_value))
    return item_similarities

def cosine_similarity(vector_a, vector_b):
    if len(vector_a) != len(vector_b):
        raise ValueError("Vectors must have the same dimension")

    dot_product = sum([x * y for x, y in zip(vector_a, vector_b)])
    magnitude_a = math.sqrt(sum([x ** 2 for x in vector_a]))
    magnitude_b = math.sqrt(sum([y ** 2 for y in vector_b]))

    if magnitude_a == 0 or magnitude_b == 0:
        return 0  # Return zero similarity if either vector is null

    return dot_product / (magnitude_a * magnitude_b)

