# Calculate the difference in age between two dates
from datetime import datetime

def leap_year_check(year):
    """Determine if a year is a leap year."""
    return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)

def days_in_month_for_year(year, month):
    """Get the number of days in a specific month of a given year."""
    if month == 2:
        return 29 if leap_year_check(year) else 28
    elif month in [4, 6, 9, 11]:
        return 30
    else:
        return 31

def compute_date_gap(start_date, end_date):
    """Compute the time gap between two dates in years, months, and days."""
    if start_date > end_date:
        start_date, end_date = end_date, start_date  # Ensure start_date is earlier

    total_years = end_date.year - start_date.year
    total_months = end_date.month - start_date.month
    total_days = end_date.day - start_date.day

    if total_days < 0:
        # Adjust by borrowing days from the previous month
        prev_month = end_date.month - 1 if end_date.month > 1 else 12
        days_in_prev_month = days_in_month_for_year(end_date.year, prev_month)
        total_days += days_in_prev_month
        total_months -= 1

    if total_months < 0:
        # Adjust by borrowing months from the previous year
        total_months += 12
        total_years -= 1

    return total_years, total_months, total_days

def execute():
    # Collect date inputs from user
    first_date_input = input("Enter the first date (YYYY-MM-DD): ")
    second_date_input = input("Enter the second date (YYYY-MM-DD): ")

    try:
        first_date_obj = datetime.strptime(first_date_input, "%Y-%m-%d")
        second_date_obj = datetime.strptime(second_date_input, "%Y-%m-%d")
    except ValueError:
        print("Invalid date format. Please use YYYY-MM-DD.")
        return

    current_date = datetime.now()
    if first_date_obj > current_date or second_date_obj > current_date:
        print("One or both dates are in the future.")
    else:
        result = compute_date_gap(first_date_obj, second_date_obj)
        print(f"The age difference is {result[0]} years, {result[1]} months, and {result[2]} days.")

if __name__ == "__main__":
    execute()

