# Implementation of a Fibonacci Heap data structure
class TreeNode:
    def __init__(self, value):
        self.value = value
        self.rank = 0
        self.parent = None
        self.children = None
        self.prev = self
        self.next = self
        self.is_marked = False

class PriorityQueue:
    def __init__(self):
        self.minimum = None
        self.total_nodes = 0

    def add(self, value):
        new_node = TreeNode(value)
        if self.minimum is None:
            self.minimum = new_node
        else:
            new_node.next = self.minimum
            new_node.prev = self.minimum.prev
            self.minimum.prev.next = new_node
            self.minimum.prev = new_node
            if value < self.minimum.value:
                self.minimum = new_node
        self.total_nodes += 1

    def merge(self, other_queue):
        if self.minimum is None:
            self.minimum = other_queue.minimum
        elif other_queue.minimum is not None:
            self.minimum.next.prev = other_queue.minimum.prev
            other_queue.minimum.prev.next = self.minimum.next
            self.minimum.next = other_queue.minimum
            other_queue.minimum.prev = self.minimum
            if other_queue.minimum.value < self.minimum.value:
                self.minimum = other_queue.minimum
        self.total_nodes += other_queue.total_nodes

    def get_min(self):
        return self.minimum.value if self.minimum else None

    def pop_min(self):
        min_node = self.minimum
        if min_node is not None:
            if min_node.children:
                child = min_node.children
                while True:
                    child.parent = None
                    child = child.next
                    if child == min_node.children:
                        break
                min_node.children.prev.next = min_node.next
                min_node.children.next.prev = min_node.prev
                min_node.next.prev = min_node.children
                min_node.prev.next = min_node.children
            min_node.prev.next = min_node.next
            min_node.next.prev = min_node.prev
            if min_node == min_node.next:
                self.minimum = None
            else:
                self.minimum = min_node.next
                self.restructure()
            self.total_nodes -= 1
        return min_node.value if min_node else None

    def restructure(self):
        max_rank = int(self.total_nodes**0.5) + 1
        rank_map = [None] * max_rank

        current = self.minimum
        nodes_list = []
        while True:
            nodes_list.append(current)
            current = current.next
            if current == self.minimum:
                break

        for node in nodes_list:
            r = node.rank
            while rank_map[r] is not None:
                other = rank_map[r]
                if node.value > other.value:
                    node, other = other, node
                self.connect(other, node)
                rank_map[r] = None
                r += 1
            rank_map[r] = node

        self.minimum = None
        for i in range(max_rank):
            if rank_map[i] is not None:
                if self.minimum is None:
                    self.minimum = rank_map[i]
                else:
                    rank_map[i].next = self.minimum
                    rank_map[i].prev = self.minimum.prev
                    self.minimum.prev.next = rank_map[i]
                    self.minimum.prev = rank_map[i]
                    if rank_map[i].value < self.minimum.value:
                        self.minimum = rank_map[i]

    def connect(self, y, x):
        y.prev.next = y.next
        y.next.prev = y.prev
        y.parent = x
        if x.children is None:
            x.children = y
            y.next = y
            y.prev = y
        else:
            y.next = x.children
            y.prev = x.children.prev
            x.children.prev.next = y
            x.children.prev = y
        x.rank += 1
        y.is_marked = False

    def update_value(self, node, new_value):
        if new_value > node.value:
            raise ValueError("New value is larger than current value")
        node.value = new_value
        parent = node.parent
        if parent is not None and node.value < parent.value:
            self.sever(node, parent)
            self.recurse_sever(parent)
        if node.value < self.minimum.value:
            self.minimum = node

    def sever(self, node, parent):
        node.prev.next = node.next
        node.next.prev = node.prev
        parent.rank -= 1
        if parent.children == node:
            parent.children = node.next if node.next != node else None
        node.next = self.minimum
        node.prev = self.minimum.prev
        self.minimum.prev.next = node
        self.minimum.prev = node
        node.parent = None
        node.is_marked = False

    def recurse_sever(self, node):
        parent = node.parent
        if parent is not None:
            if not node.is_marked:
                node.is_marked = True
            else:
                self.sever(node, parent)
                self.recurse_sever(parent)

    def remove(self, node):
        self.update_value(node, float('-inf'))
        self.pop_min()

    def __str__(self):
        if self.minimum is None:
            return "Empty Queue"
        output = []
        current = self.minimum
        while True:
            output.append(f"TreeNode({current.value}, rank={current.rank})")
            current = current.next
            if current == self.minimum:
                break
        return " <-> ".join(output)

