# Simple chatbot implementation
def handle_greeting(input_text):
    known_greetings = ['hello', 'hi', 'hey', 'hola']
    for token in input_text.split():
        if token.lower() in known_greetings:
            return "Hello! How can I help you today?"
    return ""

def handle_query(input_text):
    if "how are you" in input_text.lower():
        return "I'm just a computer program, but thanks for asking! How can I assist you?"
    return ""

def generate_response(text):
    result = handle_greeting(text)
    if result:
        return result
    result = handle_query(text)
    if result:
        return result
    return "I'm not sure how to respond to that. Could you please rephrase or ask another question?"

def run_chatbot():
    print("Chatbot: Hi, I'm your chatbot. Type something to start the conversation!")
    while True:
        user_input = input("You: ")
        if user_input.lower() in ["bye", "goodbye"]:
            print("Chatbot: Goodbye! Have a nice day.")
            break
        bot_reply = generate_response(user_input)
        print(f"Chatbot: {bot_reply}")

if __name__ == "__main__":
    run_chatbot()

