# Flask application for retrieving temperature data
from flask import Flask, jsonify, request
import requests

app = Flask(__name__)

# Configuration for the weather API
WEATHER_API_ENDPOINT = "https://api.hypotheticalweatherapi.com/data"
API_AUTH_TOKEN = "your_api_key_here"

# Rate limiting settings
MAX_REQUESTS_PER_MINUTE = 10  # Max requests allowed in one minute
request_count = 0
import time
last_reset_time = time.time()

def fetch_weather_info(city_name, month_num):
    query_params = {
        'city': city_name,
        'month': month_num,
        'api_key': API_AUTH_TOKEN
    }
    api_response = requests.get(WEATHER_API_ENDPOINT, params=query_params)
    if api_response.status_code == 200:
        return api_response.json()
    else:
        return None

def check_rate_limit():
    global request_count, last_reset_time
    current_timestamp = time.time()
    if current_timestamp - last_reset_time > 60:
        request_count = 0
        last_reset_time = current_timestamp
    if request_count < MAX_REQUESTS_PER_MINUTE:
        request_count += 1
        return True
    else:
        return False

@app.route('/temperature', methods=['GET'])
def temperature_endpoint():
    if not check_rate_limit():
        return jsonify({"error": "Too many requests. Please wait before trying again."}), 429

    city_param = request.args.get('city')
    if not city_param:
        return jsonify({"error": "City parameter is required."}), 400

    # Collect temperature data for all months
    monthly_records = []
    for month_index in range(1, 13):
        weather_info = fetch_weather_info(city_param, month_index)
        if weather_info:
            monthly_records.append({
                "month": month_index,
                "highest_temperature": weather_info['highest_temperature'],
                "lowest_temperature": weather_info['lowest_temperature']
            })

    if not monthly_records:
        return jsonify({"error": "No data found for the specified city."}), 404

    # Compute average temperatures
    sum_high = sum(record['highest_temperature'] for record in monthly_records)
    sum_low = sum(record['lowest_temperature'] for record in monthly_records)
    avg_high = sum_high / 12
    avg_low = sum_low / 12
    avg_yearly = (avg_high + avg_low) / 2

    result = {
        "city": city_param,
        "average_annual_temperature": avg_yearly,
        "monthly_temperatures": monthly_records
    }

    return jsonify(result)

if __name__ == '__main__':
    app.run(debug=True)

