# In-memory storage for blog entries
entries = []
entry_id_counter = 1

### Step 3: Define the API Endpoints

# GET /posts - Retrieve all blog entries
@server.route('/posts', methods=['GET'])
def fetch_all_entries():
    return jsonify(entries)

# GET /posts/<int:post_id> - Retrieve a specific blog entry by ID
@server.route('/posts/<int:post_id>', methods=['GET'])
def fetch_entry(post_id):
    entry = next((item for item in entries if item['id'] == post_id), None)
    if entry is None:
        return jsonify({'error': 'Entry not found'}), 404
    return jsonify(entry)

# POST /posts - Create a new blog entry
@server.route('/posts', methods=['POST'])
def add_entry():
    global entry_id_counter
    payload = request.get_json()
    if not payload or 'title' not in payload or 'content' not in payload:
        return jsonify({'error': 'Invalid request'}), 400
    new_entry = {
        'id': entry_id_counter,
        'title': payload['title'],
        'content': payload['content']
    }
    entries.append(new_entry)
    entry_id_counter += 1
    return jsonify(new_entry), 201

# PUT /posts/<int:post_id> - Update an existing blog entry
@server.route('/posts/<int:post_id>', methods=['PUT'])
def modify_entry(post_id):
    payload = request.get_json()
    entry = next((item for item in entries if item['id'] == post_id), None)
    if entry is None:
        return jsonify({'error': 'Entry not found'}), 404
    entry.update(payload)
    return jsonify(entry)

# DELETE /posts/<int:post_id> - Delete a blog entry
@server.route('/posts/<int:post_id>', methods=['DELETE'])
def remove_entry(post_id):
    global entries
    entries = [item for item in entries if item['id'] != post_id]
    return jsonify({'message': 'Entry deleted'})

