# Implementation of bank account system using abstract base class
from abc import ABC, abstractmethod

# Abstract Base Class (ABC)
class FinancialAccount(ABC):
    def __init__(self, account_id, initial_amount=0):
        self.account_id = account_id
        self.amount = initial_amount

    @abstractmethod
    def add_funds(self, value):
        pass

    @abstractmethod
    def remove_funds(self, value):
        pass

    @abstractmethod
    def check_amount(self):
        pass

# Concrete Class
class DepositAccount(FinancialAccount):
    def __init__(self, account_id, initial_amount=0, rate=0.01):
        super().__init__(account_id, initial_amount)
        self.rate = rate

    def add_funds(self, value):
        self.amount += value
        print(f"Added {value} to Deposit Account {self.account_id}. Current amount: {self.amount}")

    def remove_funds(self, value):
        if value > self.amount:
            print("Insufficient funds")
        else:
            self.amount -= value
            print(f"Removed {value} from Deposit Account {self.account_id}. Current amount: {self.amount}")

    def check_amount(self):
        return self.amount

    def compute_interest(self):
        interest = self.amount * self.rate
        self.amount += interest
        print(f"Computed interest of {interest} for Deposit Account {self.account_id}. Current amount: {self.amount}")

# Concrete Class
class TransactionAccount(FinancialAccount):
    def __init__(self, account_id, initial_amount=0, overdraft_limit=100):
        super().__init__(account_id, initial_amount)
        self.overdraft_limit = overdraft_limit

    def add_funds(self, value):
        self.amount += value
        print(f"Added {value} to Transaction Account {self.account_id}. Current amount: {self.amount}")

    def remove_funds(self, value):
        if value > self.amount + self.overdraft_limit:
            print("Exceeds overdraft limit")
        else:
            self.amount -= value
            print(f"Removed {value} from Transaction Account {self.account_id}. Current amount: {self.amount}")

    def check_amount(self):
        return self.amount

# Client Code
def execute():
    deposit_account = DepositAccount("D987654", 2000)
    transaction_account = TransactionAccount("T654321", 800)

    deposit_account.add_funds(700)
    deposit_account.remove_funds(300)
    deposit_account.compute_interest()
    print(f"Final amount of Deposit Account: {deposit_account.check_amount()}")

    transaction_account.add_funds(400)
    transaction_account.remove_funds(1200)
    print(f"Final amount of Transaction Account: {transaction_account.check_amount()}")

if __name__ == "__main__":
    execute()

