# Function to filter out comment lines 
def strip_comments(code_lines):
    if isinstance(code_lines, str):
        code_lines = code_lines.split('\n')

    non_comment_lines = [line for line in code_lines if not line.strip().startswith('//')]
    return '\n'.join(non_comment_lines)

