# Implementation of First-Come-First-Serve (FCFS) CPU scheduling algorithm
class Job:
    def __init__(self, job_id, arrival, duration):
        self.job_id = job_id
        self.arrival = arrival
        self.duration = duration
        self.remaining = duration
        self.start = None
        self.finish = None

    def __str__(self):
        return f"Job({self.job_id}, arrival={self.arrival}, duration={self.duration})"

class FCFS_Algorithm:
    def __init__(self):
        self.jobs = []

    def insert_job(self, job):
        self.jobs.append(job)

    def execute(self):
        # Order jobs by their arrival times
        self.jobs.sort(key=lambda x: x.arrival)

        clock = 0
        for job in self.jobs:
            if job.arrival > clock:
                clock = job.arrival
            job.start = clock
            clock += job.duration
            job.finish = clock

    def display_schedule(self):
        schedule = []
        for job in self.jobs:
            schedule.append((job.start, job.finish, job.job_id))
        return schedule

    def compute_avg_wait_time(self):
        total_wait = 0
        for job in self.jobs:
            if job.start is not None:
                total_wait += job.start - job.arrival
        return total_wait / len(self.jobs)

    def compute_avg_turnaround_time(self):
        total_turnaround = 0
        for job in self.jobs:
            if job.finish is not None:
                total_turnaround += job.finish - job.arrival
        return total_turnaround / len(self.jobs)

# Demonstration
if __name__ == "__main__":
    scheduler = FCFS_Algorithm()

    # Insert sample jobs
    scheduler.insert_job(Job(1, 0, 24))
    scheduler.insert_job(Job(2, 4, 3))
    scheduler.insert_job(Job(3, 5, 3))

    # Run the scheduling algorithm
    scheduler.execute()

    # Display results
    schedule = scheduler.display_schedule()
    print("Execution Timeline:")
    for start, end, job_id in schedule:
        print(f"Job {job_id} runs from {start} to {end}")

    print(f"Mean Waiting Time: {scheduler.compute_avg_wait_time():.2f}")
    print(f"Mean Turnaround Time: {scheduler.compute_avg_turnaround_time():.2f}")

