import json

def check_and_convert(json_input):
    if isinstance(json_input, dict):
        # Check and modify the main dictionary
        if 'name' in json_input:
            person_name = json_input['name']
            if not (isinstance(person_name, str) and len(person_name) >= 3 and person_name.isalpha()):
                raise ValueError("Incorrect 'name' field. Must be a string with minimum 3 alphabetic characters.")

        if 'age' in json_input:
            person_age = json_input['age']
            if not (isinstance(person_age, int) and 18 <= person_age <= 99):
                raise ValueError("Incorrect 'age' field. Must be an integer from 18 to 99 (inclusive).")

        # Check embedded objects
        for field, data in json_input.items():
            if isinstance(data, dict):
                if field == 'address':
                    if not (isinstance(data, str) and data.strip()):
                        raise ValueError("Incorrect 'address' field. Must be a non-empty string.")
