# Perform cyclic encoding on input string
def transform_cyclic(input_text: str, shift_amount: int = 5, char_set: str = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ"):
    """
    Applies a cyclic transformation to segments of 'shift_amount' consecutive characters.
    Preserves non-alphabet characters and ensures the character set contains no duplicates.
    Efficiently processes large inputs.
    """
    if not input_text:
        return ""

    # Validate that character set has unique elements
    if len(set(char_set)) != len(char_set):
        raise ValueError("Character set must contain unique characters")

    # Create mapping from character to its position in the set
    char_position_map = {char: pos for pos, char in enumerate(char_set)}

    # Process the input text
    transformed_parts = []
    for start_index in range(0, len(input_text), shift_amount):
        segment = input_text[start_index:start_index + shift_amount]
        transformed_segment = ""
        for character in segment:
            if character in char_position_map:
                new_position = (char_position_map[character] + shift_amount) % len(char_set)
                transformed_segment += char_set[new_position]
            else:
                transformed_segment += character  # Keep non-mapped characters unchanged
        transformed_parts.append(transformed_segment)

    return "".join(transformed_parts)

# Reverse the cyclic transformation to recover original text
def reverse_transform_cyclic(encoded_text: str, shift_amount: int = 5, char_set: str = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ"):
    """
    Reverses the cyclic transformation applied by transform_cyclic to restore original text.
    Preserves non-alphabet characters and ensures the character set contains no duplicates.
    Efficiently processes large inputs.
    """
    if not encoded_text:
        return ""

    # Validate that character set has unique elements
    if len(set(char_set)) != len(char_set):
        raise ValueError("Character set must contain unique characters")

    # Create mapping from character to its position in the set
    char_position_map = {char: pos for pos, char in enumerate(char_set)}

    # Process the encoded text
    reversed_parts = []
    for start_index in range(0, len(encoded_text), shift_amount):
        segment = encoded_text[start_index:start_index + shift_amount]
        reversed_segment = ""
        for character in segment:
            if character in char_position_map:
                new_position = (char_position_map[character] - shift_amount) % len(char_set)
                reversed_segment += char_set[new_position]
            else:
                reversed_segment += character  # Keep non-mapped characters unchanged
        reversed_parts.append(reversed_segment)

    return "".join(reversed_parts)

# Demonstration usage:
if __name__ == "__main__":
    sample_text = "Hello, World! This is a test."
    encoded_sample = transform_cyclic(sample_text, shift_amount=5, char_set="abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ")
    print(f"Encoded: {encoded_sample}")

    decoded_sample = reverse_transform_cyclic(encoded_sample, shift_amount=5, char_set="abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ")
    print(f"Decoded: {decoded_sample}")

