# Modified version of advanced_median function with renamed variables and reordered logic
def median_calculator(data: list, comparison_func: callable):
    """
    Compute the median of elements in data without full sorting, supporting mixed types.
    Manages tuples of varying lengths, duplicate values, and relies on comparison_func for ordering.
    """
    def split_partition(items, start, end):
        base = items[end]
        boundary = start - 1
        for index in range(start, end):
            if comparison_func(items[index], base) < 0:
                boundary += 1
                items[boundary], items[index] = items[index], items[boundary]
        items[boundary + 1], items[end] = items[end], items[boundary + 1]
        return boundary + 1

    def find_kth_element(items, position, left, right):
        if left == right:
            return items[left]

        pivot_index = split_partition(items, left, right)

        if position == pivot_index:
            return items[position]
        elif position < pivot_index:
            return find_kth_element(items, position, left, pivot_index - 1)
        else:
            return find_kth_element(items, position, pivot_index + 1, right)

    def check_compatibility(val1, val2):
        try:
            comparison_func(val1, val2)
            return True
        except TypeError:
            return False

    # Remove elements that cannot be compared consistently
    valid_items = [item for idx, item in enumerate(data) if all(check_compatibility(item, other) for other in data if idx != data.index(other))]

    if not valid_items:
        return None

    count = len(valid_items)
    if count % 2 == 1:
        return find_kth_element(valid_items, count // 2, 0, count - 1)
    else:
        lower_mid = find_kth_element(valid_items, count // 2 - 1, 0, count - 1)
        upper_mid = find_kth_element(valid_items, count // 2, 0, count - 1)
        return (lower_mid + upper_mid) / 2

# Demonstration examples
print(median_calculator([3, 1, 2, 4, 5], lambda x, y: x - y))  # => 3
print(median_calculator([-10, 4, 6, 1000, 10, 20], lambda x, y: x - y))  # => 15.0
print(median_calculator([1, 2, 2, 4, 5], lambda x, y: x - y))  # => 2
print(median_calculator(['a', 'b', 1, 2], lambda x, y: x - y))  # => None

# Web scraping and visualization script for HTML div elements
import requests
from bs4 import BeautifulSoup, Tag
import networkx as nx
import matplotlib.pyplot as plt

def retrieve_webpage(url):
    try:
        response = requests.get(url)
        response.raise_for_status()
        return response.text
    except requests.RequestException as error:
        print(f"Failed to fetch URL: {error}")
        return None

def parse_document(html_content):
    return BeautifulSoup(html_content, 'html.parser')

def extract_divs_by_keywords(soup, search_terms):
    def matches_keywords(element, terms):
        if isinstance(element, Tag):
            # Check text content
            if element.string and any(term in element.string for term in terms):
                return True
            # Check attribute values
            for attribute, attr_value in element.attrs.items():
                if isinstance(attr_value, str) and any(term in attr_value for term in terms):
                    return True
            # Recursively check child elements
            for descendant in element.children:
                if matches_keywords(descendant, terms):
                    return True
        return False

    all_divs = soup.find_all('div')
    matching_divs = [div for div in all_divs if matches_keywords(div, search_terms)]
    return matching_divs

def construct_tree_structure(div_element, parent=None, graph=None):
    if graph is None:
        graph = nx.DiGraph()
        node_label = div_element.get('id', div_element.get('class', 'div'))
        graph.add_node(div_element, label=node_label)
        parent = div_element
    for child in div_element.children:
        if isinstance(child, Tag):
            child_label = child.get('id', child.get('class', 'div'))
            graph.add_node(child, label=child_label)
            graph.add_edge(parent, child)
            construct_tree_structure(child, child, graph)
    return graph

def display_tree(graph):
    plt.figure(figsize=(12, 8))
    positions = nx.drawing.nx_agraph.graphviz_layout(graph, prog='dot')
    node_labels = {node: data['label'] for node, data in graph.nodes(data=True)}
    nx.draw(graph, positions, with_labels=True, labels=node_labels, 
            node_size=3000, node_color='lightgreen', font_size=10, font_weight='bold')
    plt.title("Tree Representation of Selected Div Elements")
    plt.show()

def process_page(url, keywords):
    html_content = retrieve_webpage(url)
    if html_content:
        parsed_soup = parse_document(html_content)
        selected_divs = extract_divs_by_keywords(parsed_soup, keywords)
        if selected_divs:
            tree_graph = construct_tree_structure(selected_divs[0])
            display_tree(tree_graph)
        else:
            print("No div elements matched the provided keywords.")

if __name__ == "__main__":
    target_url = "https://example.com"  # Update with desired URL
    search_keywords = ["term1", "term2"]  # Replace with relevant keywords
    process_page(target_url, search_keywords)

# Parse SQL to extract column and table names
import sqlparse

def get_selected_fields_and_sources(sql_statement):
    parsed_query = sqlparse.parse(sql_statement)
    query_structure = parsed_query[0]

    selected_fields = []
    source_tables = []

    # Identify columns in the SELECT part
    for item in query_structure.tokens:
        if isinstance(item, sqlparse.sql.IdentifierList):
            for field in item.get_identifiers():
                if '.' in field.value:
                    selected_fields.append(field.value)
        elif isinstance(item, sqlparse.sql.Identifier):
            if '.' in item.value:
                selected_fields.append(item.value)

    # Identify tables in the FROM part
    from_found = False
    for item in query_structure.tokens:
        if isinstance(item, sqlparse.sql.Token) and item.ttype == sqlparse.tokens.Keyword and item.value.upper() == 'FROM':
            from_found = True
        elif from_found and isinstance(item, sqlparse.sql.IdentifierList):
            for table in item.get_identifiers():
                source_tables.append(table.value)
            from_found = False
        elif from_found and isinstance(item, sqlparse.sql.Identifier):
            source_tables.append(item.value)
            from_found = False

    return selected_fields, source_tables

# Sample SQL statement
sql_statement = """
select TABLE1.Id, TABLE2.Name, TABLE3.Observations, TABLE3.Address, --and more 70 fields
from TABLE1, TABLE2, TABLE3, TABLE4
"""

selected_fields, source_tables = get_selected_fields_and_sources(sql_statement)
print("Selected Fields:", selected_fields)
print("Source Tables:", source_tables)

