import re

def check_palindrome(text):
    # Strip out non-alphanumeric characters and convert to lowercase
    cleaned_text = re.sub(r'[^a-zA-Z0-9]', '', text).lower()
    return cleaned_text == cleaned_text[::-1]

def total_ascii_value(text):
    return sum(ord(character) for character in text)

def analyze_texts(texts):
    outputs = {}
    for text in texts:
        is_palindrome = check_palindrome(text)
        outcome = 'yes' if is_palindrome else 'no'
        if is_palindrome:
            ascii_total = total_ascii_value(text)
        else:
            ascii_total = None
        outputs[text] = (outcome, ascii_total)
    return outputs

