# Process CSV-like data and manage a simple table structure
import csv
from io import StringIO

class DataGrid:
    def __init__(self, raw_data):
        self.records = self._process_input(raw_data)
        self.columns = ['name', 'age', 'city']

    def _process_input(self, raw_data):
        items = []
        for segment in raw_data.split(';'):
            fields = segment.split(',')
            if len(fields) == 3 and all(field.strip() for field in fields):
                items.append(fields)
            elif len(fields) > 1 and any(field.strip() for field in fields):
                # Handle incomplete or malformed entries
                temp_dict = {self.columns[i]: fields[i] if i < len(fields) else '' for i in range(3)}
                items.append([temp_dict[col] for col in self.columns])
        return items

    def show_grid(self):
        print(f"{self.columns[0]:<10} | {self.columns[1]:<5} | {self.columns[2]:<15}")
        print("-" * 35)
        for record in self.records:
            print(f"{record[0]:<10} | {record[1]:<5} | {record[2]:<15}")

    def insert_record(self, name, age, city):
        self.records.append([name, str(age), city])

    def find_by_name(self, name):
        matches = [record for record in self.records if record[0].strip().lower() == name.strip().lower()]
        if matches:
            print(f"Found {len(matches)} record(s) matching '{name}':")
            for record in matches:
                print(f"{record[0]:<10} | {record[1]:<5} | {record[2]:<15}")
        else:
            print(f"No records found for '{name}'")

    def export_to_csv(self):
        buffer = StringIO()
        writer = csv.writer(buffer)
        writer.writerow(self.columns)
        writer.writerows(self.records)
        return buffer.getvalue()

