# Calculate the result and expression string from postfix notation
from abc import ABC, abstractmethod
from typing import List

class TreeNode(ABC):
    @abstractmethod
    def compute(self) -> int:
        pass

    @abstractmethod
    def display(self) -> str:
        pass

class ValueNode(TreeNode):
    def __init__(self, num: int):
        self.num = num

    def compute(self) -> int:
        return self.num

    def display(self) -> str:
        return str(self.num)

class OperationNode(TreeNode):
    def __init__(self, op: str, lhs: TreeNode, rhs: TreeNode):
        self.op = op
        self.lhs = lhs
        self.rhs = rhs

    def compute(self) -> int:
        if self.op == '+':
            return self.lhs.compute() + self.rhs.compute()
        elif self.op == '-':
            return self.lhs.compute() - self.rhs.compute()
        elif self.op == '*':
            return self.lhs.compute() * self.rhs.compute()
        elif self.op == '/':
            return self.lhs.compute() // self.rhs.compute()

    def display(self) -> str:
        left_str = self.lhs.display()
        right_str = self.rhs.display()
        return f"({left_str} {self.op} {right_str})"

def construct_tree(postfix_expr: List[str]) -> TreeNode:
    stack = []
    for symbol in postfix_expr:
        if symbol.isdigit():
            stack.append(ValueNode(int(symbol)))
        else:
            right_operand = stack.pop()
            left_operand = stack.pop()
            stack.append(OperationNode(symbol, left_operand, right_operand))
    return stack[0]

def evaluate_expression(postfix_expr: List[str]) -> (int, str):
    expr_tree = construct_tree(postfix_expr)
    computed_value = expr_tree.compute()
    formatted_expr = expr_tree.display()
    return computed_value, formatted_expr

# Example usage:
postfix_sequence1 = ["3", "4", "+", "2", "*", "7", "/"]
print(evaluate_expression(postfix_sequence1))  # Output: (2, "(3 + 4) * 2 / 7")

postfix_sequence2 = ["4", "5", "7", "2", "+", "-", "*"]
print(evaluate_expression(postfix_sequence2))  # Output: (-16, "4 * (5 - (7 + 2))")

postfix_sequence3 = ["4", "2", "+", "3", "5", "1", "-", "*", "+"]
print(evaluate_expression(postfix_sequence3))  # Output: (18, "4 + 2 * (3 - (5 - 1))")

postfix_sequence4 = ["100", "200", "+", "2", "/", "5", "*", "7", "+"]
print(evaluate_expression(postfix_sequence4))  # Output: (757, "((100 + 200) / 2) * 5 + 7")

# Create a 3x3 game board initialized with zeros 
def setup_grid():
    return [[0 for _ in range(3)] for _ in range(3)]

def display_grid(grid):
    for line in grid:
        print(" ".join(["A" if cell == 1 else "B" if cell == 2 else "." for cell in line]))

def check_valid(grid, row, col):
    return grid[row][col] == 0

def apply_move(grid, row, col, player):
    if check_valid(grid, row, col):
        grid[row][col] = player
        return True
    return False

def determine_winner(grid, player):
    # Check rows, columns, and diagonals 
    for i in range(3):
        if all(grid[i][j] == player for j in range(3)) or all(grid[j][i] == player for j in range(3)):
            return True
    if all(grid[i][i] == player for i in range(3)) or all(grid[i][2-i] == player for i in range(3)):
        return True
    return False

def grid_complete(grid):
    return all(cell != 0 for line in grid for cell in line)

def run_game():
    grid = setup_grid()
    active_player = 1

    while True:
        display_grid(grid)
        row = int(input(f"Player {active_player}, enter row (0-2): "))
        col = int(input(f"Player {active_player}, enter column (0-2): "))

        if apply_move(grid, row, col, active_player):
            if determine_winner(grid, active_player):
                display_grid(grid)
                print(f"Player {active_player} wins!")
                break
            elif grid_complete(grid):
                display_grid(grid)
                print("It's a tie!")
                break
            active_player = 3 - active_player  # Switch player (1 -> 2, 2 -> 1)
        else:
            print("Invalid move. Try again.")

run_game()

# Calculate heptagonal numbers using caching and parallel processing
import threading
from concurrent.futures import ThreadPoolExecutor

# Cache to store computed heptagonal values
heptagonal_store = {0: 0}

def heptagonal_value(n):
    if n in heptagonal_store:
        return heptagonal_store[n]
    heptagonal_store[n] = (5 * n * n - 3 * n) // 2
    return heptagonal_store[n]

def calculate_heptagonal(n):
    if not isinstance(n, int) or n < 1:
        raise ValueError("Input must be a positive integer.")
    return heptagonal_value(n)

def generate_sequence(n):
    if not isinstance(n, int) or n < 1:
        raise ValueError("Input must be a positive integer.")
    return [heptagonal_value(i) for i in range(1, n + 1)]

def calculate_sum(n):
    seq = generate_sequence(n)
    return sum(seq)

def calculate_multiplication(n):
    seq = generate_sequence(n)
    result = 1
    for val in seq:
        result *= val
    return result

def calculate_interval(start, end):
    if not (isinstance(start, int) and isinstance(end, int) and start >= 1 and end >= start):
        raise ValueError("Range inputs must be positive integers and start <= end.")
    return [heptagonal_value(i) for i in range(start, end + 1)]

def process_inputs(inputs):
    if not all(isinstance(x, (int, list, tuple)) for x in inputs):
        raise ValueError("Array inputs must be integers or ranges (lists/tuples).")

    outputs = []
    with ThreadPoolExecutor() as pool:
        for item in inputs:
            if isinstance(item, int):
                outputs.append(pool.submit(calculate_heptagonal, item))
            elif isinstance(item, (list, tuple)) and len(item) == 2:
                outputs.append(pool.submit(calculate_interval, *item))
            else:
                raise ValueError("Invalid input type in array.")

    return [output.result() for output in outputs]

# Demonstration usage
try:
    m = 10
    print(f"Heptagonal value at index {m}: {calculate_heptagonal(m)}")
    print(f"Heptagonal sequence up to {m}: {generate_sequence(m)}")
    print(f"Cumulative total up to {m}: {calculate_sum(m)}")
    print(f"Multiplicative result up to {m}: {calculate_multiplication(m)}")
    print(f"Heptagonal values from 5 to 10: {calculate_interval(5, 10)}")
    print(f"Process multiple entries: {process_inputs([5, (10, 15), 20])}")
except ValueError as err:
    print(err)

