class TestKitchenTimerThreadSafety(unittest.TestCase):

    def test_concurrent_start_stop_operations(self):
        kitchen_timer = KitchenTimer()
        completion_flag = Event()

        def initiate_timer():
            try:
                kitchen_timer.start(1, lambda: completion_flag.set())
            except AlreadyRunningError:
                pass

        def terminate_timer():
            time.sleep(0.5)  # Allow timer to initialize
            try:
                kitchen_timer.stop()
            except NotRunningError:
                pass

        starter = Thread(target=initiate_timer)
        stopper = Thread(target=terminate_timer)

        starter.start()
        stopper.start()

        starter.join()
        stopper.join()

        self.assertFalse(kitchen_timer.isRunning())
        self.assertTrue(completion_flag.is_set())

    def test_concurrent_time_remaining_access(self):
        kitchen_timer = KitchenTimer()
        kitchen_timer.start(1)

        def validate_time_remaining():
            for _ in range(100):
                time.sleep(0.01)
                current_remaining = kitchen_timer.timeRemaining
                self.assertGreaterEqual(current_remaining, 0)
                self.assertLessEqual(current_remaining, 1)

        threads = [Thread(target=validate_time_remaining) for _ in range(10)]

        for worker in threads:
            worker.start()

        for worker in threads:
            worker.join()

if __name__ == '__main__':
    unittest.main()

