# Function to filter even and prime numbers from two lists, merge, and sort in descending order
def extract_even_or_prime_and_combine(arr1: list, arr2: list):
    """Extract numbers that are either even or prime from both input lists,
    combine them, and return a sorted list in descending order.

    A helper function is used to determine if a number is prime.
    """

    def check_prime(value: int) -> bool:
        """Determine whether a given integer is a prime number."""
        if value <= 1:
            return False
        if value == 2:
            return True
        if value % 2 == 0:
            return False
        for j in range(3, int(value**0.5) + 1, 2):
            if value % j == 0:
                return False
        return True

    def combine_and_order(a: list, b: list) -> list:
        """Combine two lists and arrange elements in descending order."""
        combined = a + b
        combined.sort(reverse=True)
        return combined

    selected_numbers = []
    for val in arr1 + arr2:
        if val >= 0 and (val % 2 == 0 or check_prime(val)):
            selected_numbers.append(val)

    return combine_and_order(selected_numbers, [])

