# Library management system with JSON persistence
import json
from typing import List, Dict

class LiteratureItem:
    def __init__(self, name: str, code: str, creator: str, release_year: str, category: str):
        self.name = name
        self.code = code
        self.creator = creator
        self.release_year = release_year
        self.category = category

    def to_dictionary(self):
        return {
            'name': self.name,
            'code': self.code,
            'creator': self.creator,
            'release_year': self.release_year,
            'category': self.category
        }

    @classmethod
    def from_dictionary(cls, info: Dict):
        return cls(
            name=info['name'],
            code=info['code'],
            creator=info['creator'],
            release_year=info['release_year'],
            category=info['category']
        )

class Collection:
    def __init__(self, storage_file: str = 'collection_data.json'):
        self.storage_file = storage_file
        self.items_by_name = {}
        self.items_by_code = {}
        self.restore()

    def add_item(self, name: str, code: str, creator: str, release_year: str, category: str):
        if code in self.items_by_code:
            raise ValueError(f"An item with code {code} already exists.")
        item = LiteratureItem(name, code, creator, release_year, category)
        if name not in self.items_by_name:
            self.items_by_name[name] = []
        self.items_by_name[name].append(item)
        self.items_by_code[code] = item
        self.store()

    def find_by_name(self, name: str) -> List[LiteratureItem]:
        return self.items_by_name.get(name, [])

    def find_by_code(self, code: str) -> LiteratureItem:
        return self.items_by_code.get(code, None)

    def find_fuzzy(self, keyword: str) -> List[LiteratureItem]:
        matches = []
        for item_list in self.items_by_name.values():
            for item in item_list:
                if keyword in item.name or keyword in item.code:
                    matches.append(item)
        return matches

    def delete_item(self, name: str = None, code: str = None):
        if name and code:
            raise ValueError("Please provide either name or code, not both.")
        if name:
            if name in self.items_by_name:
                for item in self.items_by_name[name]:
                    del self.items_by_code[item.code]
                del self.items_by_name[name]
        elif code:
            if code in self.items_by_code:
                item = self.items_by_code[code]
                self.items_by_name[item.name].remove(item)
                if not self.items_by_name[item.name]:
                    del self.items_by_name[item.name]
                del self.items_by_code[code]
        self.store()

    def store(self):
        with open(self.storage_file, 'w') as file:
            data = {code: item.to_dictionary() for code, item in self.items_by_code.items()}
            json.dump(data, file, indent=4)

    def restore(self):
        try:
            with open(self.storage_file, 'r') as file:
                info = json.load(file)
                for code, item_info in info.items():
                    item = LiteratureItem.from_dictionary(item_info)
                    if item.name not in self.items_by_name:
                        self.items_by_name[item.name] = []
                    self.items_by_name[item.name].append(item)
                    self.items_by_code[code] = item
        except FileNotFoundError:
            pass

# Demonstration usage
if __name__ == '__main__':
    collection = Collection()
    collection.add_item("To Kill a Mockingbird", "9780061120084", "Harper Lee", "1960", "Fiction")
    collection.add_item("Pride and Prejudice", "9780141439518", "Jane Austen", "1813", "Romance")
    collection.add_item("To Kill a Mockingbird", "9780062315007", "Harper Lee", "1960", "Fiction")  # Different edition

