# Recursive solution for Tower of Hanoi problem
def solve_hanoi(disks, start_peg, middle_peg, end_peg, move_count=1):
    if disks == 1:
        print(f"Move {move_count}: Transfer disk 1 from {start_peg} to {end_peg}")
        return 1
    else:
        move_count = solve_hanoi(disks - 1, start_peg, end_peg, middle_peg, move_count)
        print(f"Move {move_count + 1}: Transfer disk {disks} from {start_peg} to {end_peg}")
        move_count += 1
        move_count = solve_hanoi(disks - 1, middle_peg, start_peg, end_peg, move_count + 1)
        return move_count

def execute_tower_solution(n_disks):
    if not isinstance(n_disks, int) or n_disks <= 0:
        raise ValueError("Disk count must be a positive integer.")

    print(f"Processing Tower of Hanoi with {n_disks} disks:")
    final_step_count = solve_hanoi(n_disks, 'X', 'Y', 'Z')
    print(f"Overall moves performed: {final_step_count}")

if __name__ == "__main__":
    try:
        user_input = int(input("Specify the number of disks: "))
        execute_tower_solution(user_input)
    except ValueError as error_message:
        print(f"Exception: {error_message}")

# Shape Selector and Mover using Pygame
import pygame
import sys

# Start Pygame
pygame.init()

# Window setup
WINDOW_WIDTH, WINDOW_HEIGHT = 800, 600
display_surface = pygame.display.set_mode((WINDOW_WIDTH, WINDOW_HEIGHT))
pygame.display.set_caption("Shape Selector and Mover")

# Color definitions
WHITE_COLOR = (255, 255, 255)
BLACK_COLOR = (0, 0, 0)
RED_COLOR = (255, 0, 0)
GREEN_COLOR = (0, 255, 0)
BLUE_COLOR = (0, 0, 255)

# List of shapes to manage
shape_list = [
    {"kind": "circle", "color": RED_COLOR, "center": (100, 100), "radius": 20},
    {"kind": "rectangle", "color": GREEN_COLOR, "rect": pygame.Rect(200, 100, 50, 50)},
    {"kind": "triangle", "color": BLUE_COLOR, "points": [(300, 100), (350, 150), (400, 100)]}
]

# Currently selected shape
active_shape = None

# Application loop
is_running = True
while is_running:
    for event in pygame.event.get():
        if event.type == pygame.QUIT:
            is_running = False
        elif event.type == pygame.MOUSEBUTTONDOWN:
            if event.button == 1:  # Left click
                for shape in shape_list:
                    if shape["kind"] == "circle":
                        if pygame.math.Vector2(shape["center"]).distance_to(event.pos) <= shape["radius"]:
                            active_shape = shape
                            break
                    elif shape["kind"] == "rectangle":
                        if shape["rect"].collidepoint(event.pos):
                            active_shape = shape
                            break
                    elif shape["kind"] == "triangle":
                        if pygame.math.Vector2(shape["points"][0]).distance_to(event.pos) <= 10 or \
                           pygame.math.Vector2(shape["points"][1]).distance_to(event.pos) <= 10 or \
                           pygame.math.Vector2(shape["points"][2]).distance_to(event.pos) <= 10:
                            active_shape = shape
                            break
        elif event.type == pygame.MOUSEMOTION:
            if active_shape:
                if active_shape["kind"] == "circle":
                    active_shape["center"] = event.pos
                elif active_shape["kind"] == "rectangle":
                    active_shape["rect"].center = event.pos
                elif active_shape["kind"] == "triangle":
                    dx, dy = event.rel
                    active_shape["points"] = [(x + dx, y + dy) for x, y in active_shape["points"]]
        elif event.type == pygame.MOUSEBUTTONUP:
            if event.button == 1:  # Left release
                active_shape = None

    # Clear the display
    display_surface.fill(WHITE_COLOR)

    # Render each shape
    for shape in shape_list:
        if shape["kind"] == "circle":
            pygame.draw.circle(display_surface, shape["color"], shape["center"], shape["radius"])
        elif shape["kind"] == "rectangle":
            pygame.draw.rect(display_surface, shape["color"], shape["rect"])
        elif shape["kind"] == "triangle":
