# Filter and sort students based on criteria
def process_students(student_list, min_height, min_weight, min_age, min_gpa):
    def validate_student_info(info):
        if not isinstance(info, tuple) or len(info) != 4:
            return False
        if not all(isinstance(val, (int, float)) for val in info):
            return False
        return True

    def transform_to_numbers(info):
        try:
            return tuple(float(val) for val in info)
        except ValueError:
            raise TypeError(f"Non-numeric value found in student info: {info}")

    qualified_students = []
    for name, info in student_list.items():
        if not validate_student_info(info):
            raise ValueError(f"Invalid student info for {name}: {info}")
        height, weight, age, gpa = transform_to_numbers(info)
        if height >= min_height and weight >= min_weight and age >= min_age and gpa >= min_gpa:
            qualified_students.append((name, height, weight, age, gpa))

    # Sort by age (descending), then GPA (descending), then name (ascending)
    qualified_students.sort(key=lambda x: (-x[3], -x[4], x[0]))

    return qualified_students

