# Compute aggregate values and perform set operations on lists
import numpy as np
from collections import Counter
from statistics import mean, median, mode, stdev, variance, quantiles

def flatten_list(data):
    """Recursively flatten a nested list structure."""
    output = []
    for item in data:
        if isinstance(item, list):
            output.extend(flatten_list(item))
        else:
            output.append(item)
    return output

def deduplicate_sequence(seq):
    """Remove duplicate items from a sequence while maintaining original order."""
    encountered = set()
    new_list = []
    for element in seq:
        if element not in encountered:
            encountered.add(element)
            new_list.append(element)
    return new_list

def analyze_sequences(list_a, list_b, actions):
    # Validate input types
    if not isinstance(list_a, list) or not isinstance(list_b, list) or not isinstance(actions, list):
        return "Error: All inputs must be lists."

    # Check for empty lists
    if not list_a and not list_b:
        return "Error: Both lists are empty."

    # Return original lists if no actions specified
    if not actions:
        return list_a, list_b

    outcomes = []
    for action in actions:
        try:
            if action == "combine":
                outcome = list_a + list_b
            elif action == "shared_items":
                outcome = list(set(flatten_list(list_a)) & set(flatten_list(list_b)))
            elif action == "distinct_items":
                outcome = list(set(flatten_list(list_a)) ^ set(flatten_list(list_b)))
            elif action == "order_descending":
                outcome = sorted(flatten_list(list_a + list_b), reverse=True)
            elif action == "pairwise_subtract":
                outcome = [a - b for a, b in zip(flatten_list(list_a), flatten_list(list_b))]
            elif action == "count_elements":
                outcome = [len(flatten_list(list_a)), len(flatten_list(list_b))]
            elif action == "total_values":
                outcome = [sum(flatten_list(list_a)), sum(flatten_list(list_b))]
            elif action == "mean_values":
                outcome = [mean(flatten_list(list_a)), mean(flatten_list(list_b))]
            elif action == "largest_value":
                outcome = [max(flatten_list(list_a)), max(flatten_list(list_b))]
            elif action == "smallest_value":
                outcome = [min(flatten_list(list_a)), min(flatten_list(list_b))]
            elif action == "flatten_structure":
                outcome = flatten_list(list_a + list_b)
            elif action == "eliminate_repeats":
                outcome = deduplicate_sequence(flatten_list(list_a + list_b))
            elif action == "compute_median":
                outcome = [median(flatten_list(list_a)), median(flatten_list(list_b))]
            elif action == "compute_mode":
                outcome = [mode(flatten_list(list_a)), mode(flatten_list(list_b))]
            elif action == "compute_spread":
                outcome = [max(flatten_list(list_a)) - min(flatten_list(list_a)), 
                           max(flatten_list(list_b)) - min(flatten_list(list_b))]
            elif action == "compute_std_dev":
                outcome = [stdev(flatten_list(list_a)), stdev(flatten_list(list_b))]
            elif action == "compute_variance":
                outcome = [variance(flatten_list(list_a)), variance(flatten_list(list_b))]
            elif action == "compute_percentile":
                outcome = [np.percentile(flatten_list(list_a), 50), 
                           np.percentile(flatten_list(list_b), 50)]
            elif action == "compute_quartiles":
                outcome = [quantiles(flatten_list(list_a), n=4), 
                           quantiles(flatten_list(list_b), n=4)]
            elif action == "compute_iqr":
                q1, q3 = quantiles(flatten_list(list_a), n=4)[1], quantiles(flatten_list(list_a), n=4)[2]
                outcome = [q3 - q1, q3 - q1]
            else:
                return f"Error: Undefined operation '{action}'."

            outcomes.append(sorted(outcome, reverse=True))
        except Exception as err:
            return f"Error: {err}"

    return outcomes

# Demonstration
list_a = [1, 2, [3, 4], 5]
list_b = [4, 5, [6, 7], 8]
actions = ["combine", "shared_items", "distinct_items", "order_descending"]

print(analyze_sequences(list_a, list_b, actions))

# Modified version of URLManager with renamed variables and changed literals
import re
import random
import string
import logging

# Configure logging with different format
logging.basicConfig(level=logging.INFO, format='[%(levelname)s] %(message)s')

class WebAddressHandler:
    def __init__(self, scheme, subpart, main_domain, domain_suffix, path_segment):
        self.scheme = scheme
        self.subpart = subpart
        self.main_domain = main_domain
        self.domain_suffix = domain_suffix
        self.path_segment = path_segment

    def build_web_address(self):
        if not self.check_components():
            return None
        return f"{self.scheme}://{self.subpart}.{self.main_domain}{self.domain_suffix}/{self.encode_path()}"

    def parse_web_address(self, web_address):
        regex_pattern = r'^(?P<scheme>[a-zA-Z]+)://(?P<subpart>[a-zA-Z0-9-]+)\.(?P<main_domain>[a-zA-Z0-9-]+)(?P<domain_suffix>\.[a-zA-Z]{2,6})/(?P<path_segment>.+)$'
        result = re.match(regex_pattern, web_address)
        if result:
            return result.groupdict()
        else:
            logging.warning(f"Malformed web address: {web_address}")
            return None

    def check_components(self):
        if not self.scheme or not self.subpart or not self.main_domain or not self.domain_suffix or not self.path_segment:
            logging.warning("All web address parts must be specified.")
            return False
        if self.scheme not in ['http', 'https', 'ftp', 'sftp']:
            logging.warning(f"Unsupported scheme: {self.scheme}")
            return False
        if not re.match(r'^[a-zA-Z0-9-]+$', self.subpart):
            logging.warning(f"Invalid subpart: {self.subpart}")
            return False
        if not re.match(r'^[a-zA-Z0-9-]+$', self.main_domain):
            logging.warning(f"Invalid main domain: {self.main_domain}")
            return False
        if not re.match(r'^\.[a-zA-Z]{2,6}$', self.domain_suffix):
            logging.warning(f"Invalid domain suffix: {self.domain_suffix}")
            return False
        return True

    def encode_path(self, use_random=False):
        if use_random:
            return self.random_encode_path()
        else:
            return self.fixed_encode_path()

    def fixed_encode_path(self):
        return re.sub(r'[^a-zA-Z0-9/]', lambda match: f"%{ord(match.group(0)):02X}", self.path_segment)

    def random_encode_path(self):
        encoded_result = ""
        for symbol in self.path_segment:
            if re.match(r'[^a-zA-Z0-9/]', symbol):
                if random.choice([True, False]):
                    encoded_result += f"%{ord(symbol):02X}"
                else:
                    encoded_result += symbol
            else:
                encoded_result += symbol
        return encoded_result

