# Monitor and log time spent using web browsers
import psutil
import time
from datetime import datetime, timedelta

# Collection of typical browser process identifiers
BROWSER_APPS = ['chrome', 'firefox', 'safari', 'microsoftedge', 'opera', 'brave']

def fetch_active_window_title():
    """ Retrieve the title of the currently focused window. """
    import os
    if os.name == 'nt':  # Windows environment
        try:
            import win32gui
            return win32gui.GetWindowText(win32gui.GetForegroundWindow())
        except ImportError:
            print("Required module not found: pywin32. Install via: pip install pywin32")
            return None
    elif os.name == 'posix':  # Linux/macOS environment
        try:
            import subprocess
            return subprocess.check_output(["xdotool", "getwindowfocus", "getwindowname"]).strip().decode()
        except ImportError:
            print("Missing dependency: xdotool. Install via: sudo apt-get install xdotool")
            return None
    else:
        return None

def is_web_browser_running():
    """ Determine whether the active window corresponds to a web browser. """
    current_window_title = fetch_active_window_title()
    if current_window_title:
        for app in BROWSER_APPS:
            if app in current_window_title.lower():
                return True
    return False

def monitor_browser_usage():
    """ Record cumulative time spent in web browsers. """
    session_start = None
    accumulated_duration = timedelta()

    while True:
        if is_web_browser_running():
            if session_start is None:
                session_start = datetime.now()
        else:
            if session_start:
                session_end = datetime.now()
                accumulated_duration += session_end - session_start
                session_start = None
                print(f"Total browser usage duration: {accumulated_duration}")

        time.sleep(1)  # Poll every second

if __name__ == "__main__":
    monitor_browser_usage()

# Calculate prime numbers and their products from multiple lists
from math import isqrt
from functools import reduce
from operator import mul

def check_prime(value):
    """Determine whether a given number is prime."""
    if value <= 1:
        return False
    if value <= 3:
        return True
    if value % 2 == 0 or value % 3 == 0:
        return False
    for j in range(5, isqrt(value) + 1, 6):
        if value % j == 0 or value % (j + 2) == 0:
            return False
    return True

def extract_primes_and_products(data_sets):
    output = []

    for data_set in data_sets:
        primes_list = []
        try:
            for val in data_set:
                if isinstance(val, int):
                    if check_prime(val):
                        primes_list.append(val)
                else:
                    raise ValueError(f"Invalid entry: {val} is not an integer")
        except Exception as err:
            print(f"Issue encountered with list: {err}")
            continue

        primes_list.sort()
        prime_product = reduce(mul, primes_list, 1) if primes_list else 1
        output.append((primes_list, prime_product))

    return output

