# A simple hash table implementation with collision handling via chaining
class HashMap:
    def __init__(self, capacity=100):
        self.capacity = capacity
        self.data = [None] * capacity

    def _get_index(self, key):
        # Compute index using Python's built-in hash and modulo capacity
        return hash(key) % self.capacity

    def put(self, key, value):
        pos = self._get_index(key)
        if self.data[pos] is None:
            self.data[pos] = []
        # Check if key already exists and update it
        for idx, (existing_key, existing_val) in enumerate(self.data[pos]):
            if existing_key == key:
                self.data[pos][idx] = (key, value)
                return
        # Otherwise, append new key-value pair
        self.data[pos].append((key, value))

    def fetch(self, key):
        pos = self._get_index(key)
        if self.data[pos] is not None:
            for k, v in self.data[pos]:
                if k == key:
                    return v
        raise KeyError(f"Key '{key}' does not exist")

    def remove(self, key):
        pos = self._get_index(key)
        if self.data[pos] is not None:
            for idx, (k, v) in enumerate(self.data[pos]):
                if k == key:
                    del self.data[pos][idx]
                    return
        raise KeyError(f"Key '{key}' does not exist")

    def __str__(self):
        return str(self.data)

