# Calculate results using parallel execution
import concurrent.futures
from math import factorial

def calc_factorial(num):
    return factorial(num)

def calc_sum(num):
    return sum(range(1, num + 1))

def enhanced_function(limit):
    """ Modified function with parallel processing features.
    Accepts 'limit' as parameter and returns a list of size 'limit'.
    For even positions, computes the factorial of 'index'.
    For odd positions, calculates the cumulative sum from 1 to 'index'.
    Index starts at 1.

    Example:
    enhanced_function(5) == [1, 2, 6, 6, 24]
    """
    output = []
    with concurrent.futures.ThreadPoolExecutor() as pool:
        tasks = []
        for index in range(1, limit + 1):
            if index % 2 == 0:
                tasks.append(pool.submit(calc_factorial, index))
            else:
                tasks.append(pool.submit(calc_sum, index))

        for task in tasks:
            output.append(task.result())

    return output

# Demonstration usage
print(enhanced_function(5))  # Expected: [1, 2, 6, 6, 24]

# Modified version of Connect4Environment with renamed variables and reordered logic
import numpy as np

class Connect4Game:
    def __init__(self):
        self.height = 6
        self.width = 7
        self.grid = np.zeros((self.height, self.width), dtype=int)
        self.turn = 1

    def _is_valid(self, col):
        return self.grid[0, col] == 0

    def _place_piece(self, col):
        for r in range(self.height - 1, -1, -1):
            if self.grid[r, col] == 0:
                self.grid[r, col] = self.turn
                break

    def _check_victory(self):
        directions = [(-1, 0), (0, -1), (-1, -1), (-1, 1)]
        for r in range(self.height):
            for c in range(self.width):
                if self.grid[r, c] == 0:
                    continue
                for dr, dc in directions:
                    if self._check_sequence(r, c, dr, dc):
                        return self.grid[r, c]
        return 0

    def _check_sequence(self, r, c, dr, dc):
        player = self.grid[r, c]
        for _ in range(4):
            if not (0 <= r < self.height and 0 <= c < self.width) or self.grid[r, c] != player:
                return False
            r += dr
            c += dc
        return True

    def act(self, action):
        if not self._is_valid(action):
            return self.grid.copy(), -1, False, "Invalid move"

        self._place_piece(action)
        reward = 0
        terminal = False
        victor = self._check_victory()
        if victor == self.turn:
            reward = 1
            terminal = True
        elif np.all(self.grid != 0):
            terminal = True

        self.turn = 3 - self.turn  # Switch player (1 -> 2, 2 -> 1)
        return self.grid.copy(), reward, terminal, {}

    def restart(self):
        self.grid = np.zeros((self.height, self.width), dtype=int)
        self.turn = 1
        return self.grid.copy()

    def display(self):
        print(self.grid)

# Function to recursively traverse nested dictionaries and lists
def walk_structure(structure, current_path=None):
    if current_path is None:
        current_path = []

    if isinstance(structure, dict):
        for key, val in structure.items():
            updated_path = current_path + [key]
            print(f"{' -> '.join(map(str, updated_path))}: {val}")
            walk_structure(val, updated_path)
    elif isinstance(structure, list):
        for idx, element in enumerate(element for element in structure):
            updated_path = current_path + [idx]
            print(f"{' -> '.join(map(str, updated_path))}: {element}")
            walk_structure(element, updated_path)
    else:
        # Terminal node (not a dict or list)
        print(f"{' -> '.join(map(str, current_path))}: {structure}")

