# MongoDB internal MaxKey type representation
class UpperBoundKey(object):
    """Represents the maximum possible key value in MongoDB."""
    __slots__ = ()
    _type_code = 127

    def __getstate__(self):
        return {}

    def __setstate__(self, state):
        pass

    def __eq__(self, other):
        return isinstance(other, UpperBoundKey)

    def __hash__(self):
        return hash(self._type_code)

    def __ne__(self, other):
        return not self == other

    def __le__(self, other):
        return isinstance(other, UpperBoundKey)

    def __lt__(self, dummy):
        return False

    def __ge__(self, dummy):
        return True

    def __gt__(self, other):
        return not isinstance(other, UpperBoundKey)

    def __repr__(self):
        return "UpperBoundKey()"

# Calculate HMAC-based signatures for TCE Cloud API requests
import binascii
import hashlib
import hmac
import sys
from common.cmp.cloud_apis.resource_apis.tcecloud.common.exception.tce_cloud_sdk_exception import TceCloudSDKException

class SignatureGenerator(object):
    @staticmethod
    def generate_signature(api_secret, message_to_sign, signature_algorithm):
        if sys.version_info[0] > 2:
            message_to_sign = bytes(message_to_sign, "utf-8")
            api_secret = bytes(api_secret, "utf-8")

        hash_function = None
        if signature_algorithm == "HmacSHA256":
            hash_function = hashlib.sha256
        elif signature_algorithm == "HmacSHA1":
            hash_function = hashlib.sha1
        else:
            raise TceCloudSDKException("signature_algorithm invalid", "signature_algorithm only support (HmacSHA1, HmacSHA256)")

        computed_hash = hmac.new(api_secret, message_to_sign, hash_function)
        encoded_signature = binascii.b2a_base64(computed_hash.digest())[:-1]

        if sys.version_info[0] > 2:
            encoded_signature = encoded_signature.decode()
        return encoded_signature

    @staticmethod
    def generate_tc3_signature(secret_access_key, request_date, service_name, string_to_sign):
        def _compute_hmac_sha256(key_material, message_text):
            return hmac.new(key_material, message_text.encode("utf-8"), hashlib.sha256)

        def _derive_signature_keys(master_key, date_string, service_identifier):
            key_date = _compute_hmac_sha256(("TC3" + master_key).encode("utf-8"), date_string)
            key_service = _compute_hmac_sha256(key_date.digest(), service_identifier)
            key_final = _compute_hmac_sha256(key_service.digest(), "tc3_request")
            return key_final.digest()

        derived_key = _derive_signature_keys(secret_access_key, request_date, service_name)
        final_signature = _compute_hmac_sha256(derived_key, string_to_sign).hexdigest()
        return final_signature

# Utility functions for handling web responses in Django REST framework
from django.http import JsonResponse, FileResponse
from rest_framework import status
import io

class ResponseHelper:
    @staticmethod
    def success_response(data={}, msg=""):
        return JsonResponse({"payload": data, "success": True, "info": msg}, status=status.HTTP_200_OK)

    @staticmethod
    def error_response(data={}, err_msg="", http_status=status.HTTP_400_BAD_REQUEST):
        return JsonResponse({"payload": data, "success": False, "error": err_msg}, status=http_status)

    @staticmethod
    def unauthorized_response(msg):
        return JsonResponse({"success": False, "error": msg}, status=status.HTTP_401_UNAUTHORIZED)

    @staticmethod
    def forbidden_response(msg):
        return JsonResponse({"success": False, "error": msg}, status=status.HTTP_403_FORBIDDEN)

    @staticmethod
    def file_download(file_content, file_name):
        if isinstance(file_content, bytes):
            file_content = io.BytesIO(file_content)
        response = FileResponse(file_content, content_type="application/octet-stream")
        response['Content-Disposition'] = f'attachment; filename="{file_name}"'
        return response

# Generate income statement report in JSON format for a beancount ledger
import json
import click
from .helpers import extract_tree, sum_tree, convert_balance, convert_tree, filter_by_date, period_boundaries

@click.command("income-statement")
@click.pass_context
def income_statement(ctx):
    """Output income statement data as JSON for a beancount file."""
    from beancount.core import realization

    context_data = ctx.obj
    entries, options = context_data["entries"], context_data["options"]
    price_map, conversion_flag = context_data["price_map"], context_data["convert"]
    start_date, end_date = context_data["start_date"], context_data["end_date"]

    if not context_data["history"]:
        # Process single period
        filtered_entries = filter_by_date(entries, start_date, end_date)
        realized_entries = realization.realize(filtered_entries)

        output = {
            "revenue": extract_tree(realization, realized_entries, options["name_income"]),
            "costs": extract_tree(realization, realized_entries, options["name_expenses"]),
        }

        if conversion_flag:
            reference_date = end_date - datetime.timedelta(days=1) if end_date else None
            output = {k: convert_tree(v, price_map, conversion_flag, reference_date) for k, v in output.items()}

        click.echo(json.dumps(output))
        return

    # Process multiple periods
    date_ranges = period_boundaries(start_date, end_date, context_data["granularity"])
    summary = []

    for period_start, period_end, label in date_ranges:
        filtered_entries = filter_by_date(entries, period_start, period_end)
        realized_entries = realization.realize(filtered_entries)

        entry = {
            "interval": label,
            "revenue": sum_tree(realization, realized_entries, options["name_income"]),
            "costs": sum_tree(realization, realized_entries, options["name_expenses"]),
        }

        if conversion_flag:
            reference_date = period_end - datetime.timedelta(days=1)
            for field in ("revenue", "costs"):
                entry[field] = convert_balance(entry[field], price_map, conversion_flag, reference_date)

        summary.append(entry)

    click.echo(json.dumps(summary))

