def order_by_digit_sum(numbers):
    """
    Write a function which sorts the given list of integers
    in ascending order according to the sum of their digits.
    Note: if there are several items with similar sum of their digits,
    order them based on their index in original list.
    For example:
    >>> order_by_digit_sum([1, 11, -1, -11, -12]) == [-1, -11, 1, -12, 11]
    >>> order_by_digit_sum([]) == []
    """
    def calculate_digit_sum(num):
        num_str = str(num)
        if num_str[0] == '-':
            return -int(num_str[1]) + sum(int(digit) for digit in num_str[2:])
        else:
            return sum(int(digit) for digit in num_str)

    return sorted(numbers, key=calculate_digit_sum)

# Utility functions for handling JSON, images, and file operations
import io
import json
import mimetypes
import os
from multiprocessing import Lock
import numpy as np
from PIL import Image

file_lock = Lock()

def convert_int64_keys(obj):
    result = {}
    for key, val in obj.items():
        if key.isdigit():
            key = np.int64(key)
        elif isinstance(val, dict):
            updated_val = {}
            for sub_key, sub_val in val.items():
                if str(sub_val).isdigit():
                    updated_val[sub_key] = int(sub_val)
                else:
                    updated_val[sub_key] = sub_val
            val = updated_val
        result[key] = val
    return result

def read_json_file(json_path):
    if not os.path.isfile(json_path):
        raise FileNotFoundError(f"Specified file does not exist: {json_path}")
    with open(json_path, 'r', encoding='utf-8') as file:
        content = json.load(file)
    return convert_int64_keys(content)

def write_json_file(data, json_path):
    if not isinstance(data, dict):
        raise TypeError("Input data must be a dictionary.")
    processed_data = {int(k) if isinstance(k, (np.integer,)) else k: v for k, v in data.items()}
    with open(json_path, 'w', encoding='utf-8') as out_file:
        json.dump(processed_data, out_file)

def check_image_validity(img_path):
    if not os.path.exists(img_path):
        return False
    try:
        with Image.open(img_path) as img_obj:
            w, h = img_obj.size
        if w <= 0 or h <= 0:
            raise ValueError("Invalid image dimensions")
        return True
    except Exception as err:
        print(f"Failed to process image '{img_path}': {err}")
        return False

def analyze_file(filepath):
    if os.path.exists(filepath) and filepath != '.':
        if not os.path.isfile(filepath):
            raise ValueError(f"'{filepath}' is not a regular file")
        ext = os.path.splitext(filepath)[1].lower()
        content_type = mimetypes.types_map.get(ext, 'application/octet-stream')
        return (content_type, filepath)
    else:
        return (None, filepath)

def save_base64_as_image(base64_data, output_path, max_dimension=-1):
    with file_lock:
        pil_image = base64_to_pil_image(base64_data, target_size=max_dimension)
        pil_image.save(output_path)

def base64_to_pil_image(base64_data, target_size=-1):
    decoded_bytes = base64.b64decode(base64_data)
    with Image.open(io.BytesIO(decoded_bytes)) as img:
        if img.mode in ('RGBA', 'P'):
            img = img.convert('RGB')
        if target_size > 0:
            img.thumbnail((target_size, target_size))
        return img.copy()

