        if config.get('ak', None) and config.get('sk', None):
            self.set_access_key(config['ak'])
            self.set_secret_key(config['sk'])
        super(BaseTrait, self).__init__(self.service_info, self.api_info)

    @staticmethod
    def fetch_service_info(region, service_info_dict):
        service_info = service_info_dict.get(region, None)
        if not service_info:
            raise Exception('BaseService does not support region %s' % region)
        return service_info

    @staticmethod
    def fetch_api_info():
        return api_info_map

    def update_api_info(self, additional_api_info):
        self.api_info = {**self.api_info, **additional_api_info}
        return

    def mcp_get(self, operation, parameters={}, doseq=0):
        response = self.get(operation, parameters, doseq)
        if response == '':
            raise Exception("%s: empty response" % operation)
        res_json = json.loads(json.dumps(response))
        return res_json

    def mcp_post(self, operation, parameters={}, request_body={}):
        response = self.json(operation, parameters, request_body)
        if response == '':
            raise Exception("%s: empty response" % operation)
        res_json = json.loads(json.dumps(response))
        return res_json

import sys
import json

def read_json_lines(file_path):
    records = {}
    with open(file_path, "r", encoding="utf-8") as input_file:
        for line_index, current_line in enumerate(input_file, start=1):
            current_line = current_line.strip()
            if not current_line:
                continue
            try:
                parsed_obj = json.loads(current_line)
                if "id" not in parsed_obj:
                    raise ValueError(f"Missing 'id' field in line {line_index}")
                records[parsed_obj["id"]] = parsed_obj
            except json.JSONDecodeError as error:
                raise ValueError(f"Invalid JSON on line {line_index} in {file_path}: {error}")
    return records

def process_files(source_file1, source_file2, result_file):
    set1 = read_json_lines(source_file1)
    set2 = read_json_lines(source_file2)
    unique_ids = set(set1.keys()) | set(set2.keys())
    combined = []

    for identifier in sorted(unique_ids):
        if identifier in set1 and identifier in set2:
            merged_item = {**set1[identifier], **set2[identifier]}
        elif identifier in set1:
            merged_item = set1[identifier]
        else:
            merged_item = set2[identifier]
        combined.append(merged_item)

    with open(result_file, "w", encoding="utf-8") as output_file:
        for item in combined:
            output_file.write(json.dumps(item, ensure_ascii=False) + "\n")

    print(f"Successfully merged {len(combined)} entries into {result_file}")

if __name__ == "__main__":
    if len(sys.argv) != 4:
        print(
            "Usage: python generate_bfcl_tool_call_data.py <tool_call_bfcl_v3_multiple_raw.jsonl> <tool_call_bfcl_v3_multiple_gt.jsonl> <tool_call_bfcl_v3_multiple.jsonl>"
        )
        sys.exit(1)

    input_file1, input_file2, output_path = sys.argv[1], sys.argv[2], sys.argv[3]
    process_files(input_file1, input_file2, output_path)

# Convert a list of strings into a markdown-formatted list
def convert_to_markdown_list(
    items: list[str], style: t.Literal["unordered", "ordered"] = "unordered"
) -> str:
    """
    Transform a list of strings into a markdown list.
    :param items: list of strings to format
    :param style: type of list to generate ('unordered' or 'ordered')
    :return: formatted markdown string
    """
    if style == "unordered":
        return "\n".join([f"- {element}" for element in items])
    elif style == "ordered":
        return "\n".join([f"{index}. {element}" for index, element in enumerate(items, start=1)])
    else:
        raise ValueError("style must be either 'unordered' or 'ordered'")

