def pytest_generate_tests(metafunc_obj: Metafunc):
    interface_param_names = [name for name in metafunc_obj.fixturenames if name.endswith('interface')]

    # Skip if no interface parameters are present
    if len(interface_param_names) == 0:
        return

    # Ensure only one interface parameter exists
    if len(interface_param_names) > 1:
        raise Exception('maximum one interface parameter per test function')

    selected_param = interface_param_names[0]

    # Determine interfaces based on parameter type
    if selected_param == 'futures_interface':
        available_interfaces = [ex.interface for ex in FUTURES_EXCHANGES]
    elif selected_param == 'spot_interface':
