# Modified version of the original code with renamed variables and reordered statements
from enum import Enum, auto
from itertools import count
from copy import copy
from ..layers.sampler import SamplingParams

class SequenceState(Enum):
    PENDING = auto()
    ACTIVE = auto()
    COMPLETED = auto()

class Sequence:
    block_size = 256
    _id_counter = count()

    def __init__(self, input_tokens: list[int], params: SamplingParams = SamplingParams()):
        self.sequence_id = next(Sequence._id_counter)
        self.state = SequenceState.PENDING
        self.tokens = copy(input_tokens)
        self.current_token = input_tokens[-1]
        self.total_tokens = len(self.tokens)
        self.prompt_length = len(input_tokens)
        self.cached_tokens = 0
        self.block_mapping = []
        self.temperature = params.temperature
        self.max_new_tokens = params.max_tokens
        self.skip_eos_check = params.ignore_eos
        self.enable_verification = True
        self.accumulated_token_counts = []
        self.current_accumulated = 0

    def __len__(self):
        return self.total_tokens

    def __getitem__(self, index):
        return self.tokens[index]

    @property
    def is_complete(self):
        return self.state == SequenceState.COMPLETED

    @property
    def generated_token_count(self):
        return self.total_tokens - self.prompt_length

    @property
    def prompt_ids(self):
        return self.tokens[:self.prompt_length]

    @property
    def generated_ids(self):
        return self.tokens[self.prompt_length:]

    @property
    def cached_block_count(self):
        return self.cached_tokens // self.block_size

    @property
    def total_block_count(self):
        return (self.total_tokens + self.block_size - 1) // self.block_size

    @property
    def final_block_token_count(self):
        return self.total_tokens - (self.total_block_count - 1) * self.block_size

    def get_block(self, i: int):
        assert 0 <= i < self.total_block_count
        start_idx = i * self.block_size
        end_idx = (i + 1) * self.block_size
        return self.tokens[start_idx:end_idx]

    def add_token(self, token_id: int):
        self.tokens.append(token_id)
        self.current_token = token_id
        self.total_tokens += 1

    # PEARL KV cache Rollback
    def revert_tokens(self, n: int):
        assert n > 0
        self.tokens = self.tokens[:-n]
        self.current_token = self.tokens[-1]
        self.total_tokens -= n

    def map_token_to_slot(self, token_pos: int):
        block_index = token_pos // self.block_size
        offset_in_block = token_pos % self.block_size
        physical_slot = self.block_mapping[block_index] * self.block_size + offset_in_block
        return physical_slot

    def __getstate__(self):
        return (self.total_tokens, self.prompt_length, self.cached_tokens, self.block_mapping,
                self.temperature, self.skip_eos_check, self.max_new_tokens, self.sequence_id, 
                self.enable_verification, self.accumulated_token_counts, self.current_accumulated,
                self.tokens if self.generated_token_count == 0 else self.current_token)

    def __setstate__(self, state):
        (self.total_tokens, self.prompt_length, self.cached_tokens, self.block_mapping,
         self.temperature, self.skip_eos_check, self.max_new_tokens, self.sequence_id,
         self.enable_verification, self.accumulated_token_counts, self.current_accumulated) = state[:-1]

        if self.generated_token_count == 0:
            self.tokens = state[-1]
        else:
            self.current_token = state[-1]

# Script to test CDP-based browser automation with user agent override and site checks
import asyncio
import json
import sys
import urllib.request

CDP_PORT = int(sys.argv[1]) if len(sys.argv) > 1 else 9222
DEFAULT_UA = "Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/145.0.7632.116 Safari/537.36"

async def run_test():
    try:
        import websockets
    except ImportError:
        print("ERROR: pip install websockets")
        return

    # Fetch available tabs via CDP
    try:
        response = urllib.request.urlopen(f"http://127.0.0.1:{CDP_PORT}/json/list")
        tabs_data = json.loads(response.read())
    except Exception as e:
        print(f"Failed to fetch tab list: {e}")
        return

    print(f"Found {len(tabs_data)} tab(s)")

    if not tabs_data:
        print("No tabs available")
        return

    ws_endpoint = tabs_data[0]["webSocketDebuggerUrl"]

    async with websockets.connect(ws_endpoint) as socket:
        # Set custom user agent
        await socket.send(json.dumps({
            "id": 1, 
            "method": "Network.setUserAgentOverride",
            "params": {"userAgent": DEFAULT_UA}
        }))
        await socket.recv()
        print("User-Agent override applied successfully")

        # Navigate to Google Search
        await socket.send(json.dumps({
            "id": 2, 
            "method": "Page.navigate",
            "params": {"url": "https://www.google.com/search?q=test"}
        }))
        await socket.recv()
        await asyncio.sleep(5)

        # Get page title
        await socket.send(json.dumps({
            "id": 3, 
            "method": "Runtime.evaluate",
            "params": {"expression": "document.title"}
        }))
        resp = json.loads(await socket.recv())
        page_title = resp.get("result", {}).get("result", {}).get("value", "?")
        print(f"Google Search title: {page_title}")

        # Extract body text for blocking detection
        await socket.send(json.dumps({
            "id": 4, 
            "method": "Runtime.evaluate",
            "params": {"expression": "document.body.innerText.substring(0,300)"}
        }))
        resp = json.loads(await socket.recv())
        body_text = resp.get("result", {}).get("result", {}).get("value", "")

        if any(blocked_term in body_text.lower() for blocked_term in ["sorry", "captcha", "unusual traffic"]):
            print("Google: BLOCKED")
        else:
            print("Google: OK")

        # Navigate to Google Scholar
        await socket.send(json.dumps({
            "id": 5, 
            "method": "Page.navigate",
            "params": {"url": "https://scholar.google.com/scholar?q=test"}
        }))
        await socket.recv()
        await asyncio.sleep(5)

        # Get Scholar page title
        await socket.send(json.dumps({
            "id": 6, 
            "method": "Runtime.evaluate",
            "params": {"expression": "document.title"}
        }))
        resp = json.loads(await socket.recv())
        scholar_title = resp.get("result", {}).get("result", {}).get("value", "?")
        print(f"Scholar title: {scholar_title}")

        # Extract Scholar body text for blocking detection
        await socket.send(json.dumps({
            "id": 7, 
            "method": "Runtime.evaluate",
            "params": {"expression": "document.body.innerText.substring(0,300)"}
        }))
        resp = json.loads(await socket.recv())
        scholar_body = resp.get("result", {}).get("result", {}).get("value", "")

        if any(blocked_term in scholar_body.lower() for blocked_term in ["sorry", "captcha", "unusual traffic"]):
            print("Scholar: BLOCKED")
        else:
            print("Scholar: OK")

asyncio.run(run_test())

