# Generate a random example for GSEnv policy testing
import dataclasses
import einops
import numpy as np
from openpi import transforms
from openpi.models import model as _model

def create_gsenv_sample() -> dict:
    """Generates a synthetic input sample for the GSEnv policy."""
    return {
        "observation/state": np.random.rand(8),
        "observation/image": np.random.randint(256, size=(480, 640, 3), dtype=np.uint8),
        "prompt": "perform an action",
    }

def _process_image(image) -> np.ndarray:
    image = np.asarray(image)
    if np.issubdtype(image.dtype, np.floating):
        image = (255 * image).astype(np.uint8)
    if image.shape[0] == 3:
        image = einops.rearrange(image, "c h w -> h w c")
    return image

@dataclasses.dataclass(frozen=True)
class GSEnvInputs(transforms.DataTransformFn):
    network_type: _model.ModelType

    def __call__(self, batch: dict) -> dict:
        primary_image = _process_image(batch["observation/image"])
        processed_inputs = {
            "state": batch["observation/state"],
            "image": {
                "base_0_rgb": primary_image,
                "left_wrist_0_rgb": np.zeros_like(primary_image),
                "right_wrist_0_rgb": np.zeros_like(primary_image),
            },
            "image_mask": {
                "base_0_rgb": np.True_,
                "left_wrist_0_rgb": np.False_,
                "right_wrist_0_rgb": np.False_,
            },
        }
        if "actions" in batch:
            processed_inputs["actions"] = batch["actions"]
        if "prompt" in batch:
            processed_inputs["prompt"] = batch["prompt"]
        return processed_inputs

@dataclasses.dataclass(frozen=True)
class GSEnvOutputs(transforms.DataTransformFn):
    def __call__(self, batch: dict) -> dict:
        return {"actions": np.asarray(batch["actions"][:, :7])}

