# Test function for FuncBase implementations
import jax.numpy as jnp
import parametricmatrixmodels as pmm

def test_functional_base():
    # First test: sum over tree structure
    class SumTreeElements(pmm.modules.FuncBase):
        def get_hyperparameters(self):
            return {}
        def f(self, inputs):
            return jax.tree.reduce(lambda a, b: a + b, inputs)

    sum_tree = SumTreeElements()
    inputs = {
        "x": jnp.array([[1.0, 2.0], [2.0, 3.0]]),
        "y": [
            jnp.array([[3.0, 4.0], [4.0, 5.0]]),
            jnp.array([[5.0, 6.0], [6.0, 7.0]]),
        ],
    }
    output, _ = sum_tree(inputs)
    target = jnp.array([[9, 12], [12, 15]])
    assert jnp.all(output == target), f"Expected {target}, got {output}"

    # Second test: matrix exponential on tree elements
    class MatrixExponential(pmm.modules.FuncBase):
        def get_hyperparameters(self):
            return {}
        def f(self, inputs):
            return jax.tree.map(jax.scipy.linalg.expm, inputs)

    expm_op = MatrixExponential()
    inputs = {
        "x": jnp.array([[[0.0, 1.0], [0.0, 0.0]]]),
        "y": [
            jnp.array([[[0.0, 2.0], [0.0, 0.0]]]),
            jnp.array([[[0.0, 3.0], [0.0, 0.0]]]),
        ],
    }
    output, _ = expm_op(inputs)
    reference = jax.tree.map(
        jax.scipy.linalg.expm,
        inputs,
    )
    output_struct = jax.tree.structure(output)
    reference_struct = jax.tree.structure(reference)
    assert (
        output_struct == reference_struct
    ), f"Expected structure {reference_struct}, got {output_struct}"

    # Helper to check numerical closeness
    def verify_close(actual, expected):
        assert jnp.allclose(actual, expected), f"Expected {expected}, got {actual}"

    jax.tree.map(verify_close, output, reference)

