        translation_text = verse_info['text_tr']

        return f"=== {chapter_name} ({chapter_num}:{verse_num}) ===\n\n{arabic_text}\n\n{translation_text}"

    @staticmethod
    def display_chapter(verses):
        """Format a complete Chapter."""
        if not verses:
            return "Chapter not found."

        # verses is a list of verse dicts
        first_verse = verses[0]
        # In get_chapter, 'surah' key contains the chapter metadata
        chapter_meta = first_verse['surah']
        chapter_name = chapter_meta.get('englishName', f"Chapter {chapter_meta.get('number')}")
        chapter_num = chapter_meta.get('number')

        lines = [f"=== {chapter_name} (Chapter {chapter_num}) ==="]
        for verse in verses:
            lines.append(f"\n[{verse['numberInSurah']}] {verse['text_ar']}")
            lines.append(verse['text_tr'])

        return "\n".join(lines)

    @staticmethod
    def display_search_results(matches, search_term):
        """Format search results."""
        if not matches:
            return f"No matches found for '{search_term}'."

        lines = [f"Search results for '{search_term}':\n"]
        for verse in matches:
            lines.append(QuranFormatter.display_verse(verse))
            lines.append("-" * 30)

        return "\n".join(lines)

# WebSocket notification system with user-specific and broadcast messaging
from typing import Dict, List
import json
import asyncio

class ConnectionHandler:
    def __init__(self):
        self.connected_users: Dict[str, List[WebSocket]] = {}

    async def establish_connection(self, websocket: WebSocket, user_identifier: str):
        await websocket.accept()
        if user_identifier not in self.connected_users:
            self.connected_users[user_identifier] = []
        self.connected_users[user_identifier].append(websocket)

    def remove_connection(self, websocket: WebSocket, user_identifier: str):
        if user_identifier in self.connected_users:
            if websocket in self.connected_users[user_identifier]:
                self.connected_users[user_identifier].remove(websocket)

    async def deliver_private_message(self, payload: dict, user_identifier: str):
        if user_identifier in self.connected_users:
            for connection in self.connected_users[user_identifier]:
                await connection.send_json(payload)

    async def send_to_all(self, payload: dict):
        for user_identifier in self.connected_users:
            for connection in self.connected_users[user_identifier]:
                await connection.send_json(payload)

handler = ConnectionHandler()

MESSAGE_CATEGORIES = {
    "quiz_results": "Quiz scores are ready",
    "badge_earned": "Congratulations! New badge earned!",
    "daily_reminder": "Don't forget your daily journal entry",
    "account_changes": "Your account details have been modified",
}

async def handle_websocket_connection(websocket: WebSocket, user_identifier: str):
    await handler.establish_connection(websocket, user_identifier)
    try:
        while True:
            raw_data = await websocket.receive_text()
            parsed_message = json.loads(raw_data)
            if parsed_message.get("action") == "ping":
                await websocket.send_json({"action": "pong"})
    except WebSocketDisconnect:
        handler.remove_connection(websocket, user_identifier)

async def trigger_user_notification(user_identifier: str, message_category: str, extra_data: dict = None):
    notification_payload = {
        "category": message_category,
        "content": MESSAGE_CATEGORIES.get(message_category, "System Notification"),
        "payload": extra_data or {},
        "sent_at": asyncio.get_event_loop().time(),
    }
    await handler.deliver_private_message(notification_payload, user_identifier)

async def trigger_global_notification(message_category: str, extra_data: dict = None):
    broadcast_payload = {
        "category": message_category,
        "content": MESSAGE_CATEGORIES.get(message_category, "System Notification"),
        "payload": extra_data or {},
    }
    await handler.send_to_all(broadcast_payload)

