# Reference: https://vercel.com/docs/rest-api/endpoints/dns
"""
Vercel DNS Provider Implementation
"""
import requests
from typing import Tuple, Dict, Any
import logging
from .base import BaseDnsProvider

logger = logging.getLogger(__name__)

class VercelDnsProvider(BaseDnsProvider):
    PROVIDER_TYPE = "vercel"
    PROVIDER_NAME = "Vercel"
    PROVIDER_DESCRIPTION = "Vercel DNS API Service"
    REQUIRED_CREDENTIALS = ["api_token"]

    BASE_URL = "https://api.vercel.com"

    def _get_headers(self):
        return {
            'Authorization': f'Bearer {self.credentials["api_token"]}',
            'Content-Type': 'application/json',
        }

    def _request(self, method, path, data=None):
        try:
            resp = requests.request(method, f"{self.BASE_URL}{path}",
                headers=self._get_headers(), json=data, timeout=30)
            if resp.status_code >= 400:
                return False, resp.text
            return True, resp.json() if resp.text else None
        except requests.RequestException as e:
            logger.error(f"Vercel API error: {e}")
            return False, str(e)

    def create_txt_record(self, domain, record_name, record_value, ttl=300):
        zone = self.get_zone_for_domain(domain)
        relative = self.get_relative_record_name(record_name, zone)
        payload = {'name': relative, 'type': 'TXT', 'value': record_value, 'ttl': ttl}
        success, result = self._request('POST', f'/v2/domains/{zone}/records', payload)
        if not success:
            return False, f"Failed: {result}"
        return True, "Record created"

    def delete_txt_record(self, domain, record_name):
        zone = self.get_zone_for_domain(domain)
        relative = self.get_relative_record_name(record_name, zone)

        success, result = self._request('GET', f'/v4/domains/{zone}/records')
        if not success:
            return False, f"Failed: {result}"
        for rec in result.get('records', []):
            if rec.get('type') == 'TXT' and rec.get('name') == relative:
                self._request('DELETE', f'/v2/domains/{zone}/records/{rec["id"]}')
        return True, "Record deleted"

    def test_connection(self):
        success, result = self._request('GET', '/v5/domains')
        if success:
            domains = [d['name'] for d in result.get('domains', [])]
            return True, f"Connected. Domains: {', '.join(domains)}"
        return False, f"Connection failed: {result}"

    @classmethod
    def get_credential_schema(cls):
        return [
            {'name': 'api_token', 'label': 'API Token', 'type': 'password', 'required': True,
             'help': 'vercel.com > Settings > Tokens'},
        ]

# Security audit script for detecting potential risks in skill files
import re
import sys
import pathlib

EXFIL_RULES = [r"http[s]?://", r"webhook", r"pastebin", r"ngrok", r"tunnel", r"request\.bin", r"discordapp"]
SENSITIVE_FILES = [r"\.env", r"\.ssh", r"/etc/", r"credentials", r"token", r"apikey", r"private"]
SHELL_COMMANDS = [r"curl .*\| bash", r"chmod \+x", r"sudo", r"rm -rf"]
detection_rules = [("EXFIL", EXFIL_RULES), ("FILES", SENSITIVE_FILES), ("SHELL", SHELL_COMMANDS)]
threat_level = 0
detected_issues = []
target_file = pathlib.Path(sys.argv[1]) if len(sys.argv) > 1 else None

if not target_file or not target_file.exists():
    print("Usage: python audit.py path/to/skill.md", file=sys.stderr)
    sys.exit(1)

content = target_file.read_text(errors="ignore")
document_lines = content.splitlines()

for line_num, current_line in enumerate(document_lines, 1):
    lower_line = current_line.lower()
    for category, regex_patterns in detection_rules:
        for pattern in regex_patterns:
            if re.search(pattern, lower_line):
                detected_issues.append({
                    "line": line_num, 
                    "category": category, 
                    "context": current_line.strip()[:200]
                })

                if category == "EXFIL":
                    threat_level += 3
                elif category == "FILES":
                    threat_level += 2
                else:
                    threat_level += 1

if threat_level >= 6:
    severity = "HIGH"
elif threat_level >= 3:
    severity = "MED"
else:
    severity = "LOW"

print(f"RISK: {severity}\n")

for issue in detected_issues:
    print(f"- [{issue['category']}] line {issue['line']}: {issue['context']}")

if not detected_issues:
    print("No obvious red flags. Manual review still recommended.")

