# Fix broken markdown links in the skills directory
import os
import re

def clean_broken_links(skills_path):
    print(f"Scanning for broken links in {skills_path}...")
    link_pattern = re.compile(r'\[([^\]]*)\]\(([^)]+)\)')
    resolved_count = 0

    for current_dir, subdirs, filenames in os.walk(skills_path):
        # Exclude hidden folders
        subdirs[:] = [d for d in subdirs if not d.startswith('.')]
        for filename in filenames:
            if not filename.endswith('.md'): 
                continue

            full_path = os.path.join(current_dir, filename)
            try:
                with open(full_path, 'r', encoding='utf-8') as file:
                    text = file.read()
            except Exception:
                continue

            def update_link(match):
                nonlocal resolved_count
                display_text = match.group(1)
                url = match.group(2)
                url_clean = url.split('#')[0].strip()

                # Skip empty links, external URLs, email addresses, etc.
                if not url_clean or url_clean.startswith(('http://', 'https://', 'mailto:', '<', '>')):
                    return match.group(0)
                if os.path.isabs(url_clean):
                    return match.group(0)

                destination = os.path.normpath(os.path.join(current_dir, url_clean))
                if not os.path.exists(destination):
                    # Broken link found. Convert markdown link to plain text.
                    print(f"Correcting broken link in {os.path.relpath(full_path, skills_path)}: {url}")
                    resolved_count += 1
                    return display_text
                return match.group(0)

            updated_text = link_pattern.sub(update_link, text)

            if updated_text != text:
                with open(full_path, 'w', encoding='utf-8') as file:
                    file.write(updated_text)

    print(f"Total broken links resolved: {resolved_count}")

if __name__ == '__main__':
    project_root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
    clean_broken_links(os.path.join(project_root, 'skills'))

