import json

class DataConverter:
    tool_name = "data_format"
    help_text = "Transform data structures across various formats (JSON, CSV, YAML)"
    group = "data"

    async def run(self, options, worker=None):
        input_data = options.get("input", "")
        source_format = options.get("source", "json")
        target_format = options.get("target", "csv")

        if source_format == "json" and target_format == "csv":
            try:
                records = json.loads(input_data)
                if isinstance(records, list) and records:
                    columns = list(records[0].keys())
                    output_lines = [",".join(columns)]
                    for record in records:
                        values = [str(record.get(col, "")) for col in columns]
                        output_lines.append(",".join(values))
                    return "\n".join(output_lines)
            except Exception as error:
                return f"Error: {error}"

        return f"Format conversion from {source_format} to {target_format} is not available"

