import json
from io import BytesIO

class MockResponse:
    """Minimal HTTP response stand-in."""
    def __init__(self, code=200, content=None):
        self.status = code
        self._content = content or {}

    def read(self):
        return json.dumps(self._content).encode("utf-8")

class MockHTTPConnection:
    """Stand-in for http.client.HTTPConnection.
    Records requests and returns configured responses for
    ExternalRFClient integration testing without real HTTP.
    """
    def __init__(self, hostname="localhost", port=8270, deadline=5):
        self.host = hostname
        self.port = port
        self.timeout = deadline
        self.history = []
        self._mock_response = MockResponse()
        self._is_connected = False

    def connect(self):
        self._is_connected = True

    def close(self):
        self._is_connected = False

    def request(self, method, endpoint, payload=None, headers=None):
        parsed_payload = json.loads(payload) if isinstance(payload, str) else payload
        self.history.append({
            "method": method,
            "path": endpoint,
            "body": parsed_payload,
            "headers": headers or {},
        })

    def getresponse(self):
        return self._mock_response

    def configure_response(self, status_code=200, data=None):
        """Configure the response to return."""
        self._mock_response = MockResponse(status_code, data)
        return self

    def latest_request(self):
        """Get the most recent request, or None."""
        return self.history[-1] if self.history else None

import torch.fx as fx
from graph_net.torch.dim_gen_passes import DimensionGeneralizationPass
from collections import namedtuple
import os
import operator

class CustomPass(DimensionGeneralizationPass):
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)

    @classmethod
    def get_pass_name(cls) -> str:
        return os.path.basename(__file__)[:-3]

    def should_transform(self, traced_module: fx.GraphModule) -> bool:
        # Skip if batch dimension is present
        if 0 in self.axes:
            return False
        return any(self._requires_transformation(node) for node in traced_module.graph.nodes)

    def _target_op(self):
        return torch.full

    def _requires_transformation(self, node) -> bool:
        if not (node.op == "call_function"):
            return False
        if not (node.target == self._target_op()):
            return False
        if not (len(node.args) == 1):
            return False
        if not (any(dim == self.dim + self._dynamic_dim_offset() for dim in node.args[0])):
            return False
        if not (any(self._is_upper_triangular(downstream) for downstream in node.users)):
            return False
        return True

    def _dynamic_dim_offset(self):
        return 1

    def _is_upper_triangular(self, node):
        return node.op == "call_function" and node.target == torch.triu

    def transform(self, traced_module: fx.GraphModule) -> fx.GraphModule:
        # Build a new graph with transformed nodes
        updated_graph = fx.Graph()
        # Map old nodes to their replacements in the new graph
        node_mapping = {}
        NodeShapeAxis = namedtuple("NodeShapeAxis", ["node", "dim_index"])
        current_node_axis = None

        def update_current_node_axis(original_node, transformed_node):
            nonlocal current_node_axis
            tensor_meta = original_node.meta.get("tensor_meta")
            if tensor_meta is None:
                return
            if not hasattr(tensor_meta, "shape"):
                return
            for idx, size in enumerate(tensor_meta.shape):
                if not (size == self.dim and idx > 0):
                    continue
                current_node_axis = NodeShapeAxis(node=transformed_node, dim_index=idx)
                return

        def compute_new_dimension(index, dim_value):
            if not (dim_value == self.dim + self._dynamic_dim_offset()):
                return node_mapping[dim_value] if dim_value in node_mapping else dim_value
            assert dim_value == self.dim + self._dynamic_dim_offset()
            # Retrieve dynamic dimension using .size() method
            size_node = updated_graph.call_method(
                "size", args=(current_node_axis.node, current_node_axis.dim_index)
            )
            increment_node = updated_graph.call_function(operator.add, args=(size_node, 1))
            return increment_node

        def build_transformed_node(original_node):
            if not (self._requires_transformation(original_node) and current_node_axis is not None):
                # Copy unchanged nodes to new graph
                transformed_node = updated_graph.node_copy(original_node, lambda x: node_mapping[x])
                update_current_node_axis(original_node=original_node, transformed_node=transformed_node)
                return transformed_node

            new_dims = tuple(
                compute_new_dimension(i, dim) for i, dim in enumerate(original_node.args[0])
            )
            transformed_node = updated_graph.call_function(
                self._target_op(), args=(new_dims,), kwargs=original_node.kwargs
            )
            return transformed_node

        for node in traced_module.graph.nodes:
            node_mapping[node] = build_transformed_node(node)

        # Replace the original graph with the updated one
        traced_module.graph = updated_graph
        traced_module.recompile()
        return traced_module

