# Import necessary modules
import numpy as np
from .common import TimeStep

class RepeatAction(gym.Wrapper):
    def __init__(self, env, repeat_count=4):
        super().__init__(env)
        self._action_repeats = repeat_count

    def step(self, action: np.ndarray) -> TimeStep:
        accumulated_reward = 0.0
        termination_flag = None
        merged_info = {}

        for _ in range(self._action_repeats):
            observation, reward, termination_flag, info = self.env.step(action)
            accumulated_reward += reward
            merged_info.update(info)

            if termination_flag:
                break

        return observation, accumulated_reward, termination_flag, merged_info

