def determine_checkpoint_directory(checkpoints_dir, step, is_release=False):
    """Determine the directory name for this rank's checkpoint."""
    if is_release:
        folder_name = 'release'
    else:
        folder_name = 'iter_{:07d}'.format(step)
    base_path = os.path.join(checkpoints_dir, folder_name)
    return base_path

def get_training_tracker_file(checkpoints_dir):
    """Tracker file records the latest checkpoint during training to resume from."""
    return os.path.join(checkpoints_dir, 'latest_checkpointed_iteration.txt')

def parse_checkpoint_metadata(tracker_path):
    # Read the tracker file and either set the iteration or
    # mark it as a release checkpoint.
    current_step = 0
    is_release_version = False
    with open(tracker_path, 'r') as file_handle:
        metadata = file_handle.read().strip()
        try:
            current_step = int(metadata)
        except ValueError as err:
            is_release_version = metadata == 'release'
            if not is_release_version:
                raise ValueError('ERROR: Invalid metadata file {}.'.format(tracker_path)) from err

    if not (current_step > 0 or is_release_version):
        print('error parsing metadata file {}'.format(tracker_path))

    return current_step, is_release_version

