import os, sys
import ctypes as ct
import json
from . import xtbson as bson

def parse_bson_from_memory(mem_buffer):
    output = []
    index = 0
    while True:
        if index + 4 < len(mem_buffer):
            size_bytes = mem_buffer[index : index + 4]
        else:
            break
        size = ct.cast(size_bytes, ct.POINTER(ct.c_int32))[0]
        if size >= 5:
            try:
                record_bytes = mem_buffer[index : index + size]
                index += size
                output.append(bson.decode(record_bytes))
            except Exception as err:
                continue
        else:
            break
    return output

def serialize_to_bson_buffer(records):
    mem_buffer = b''
    for item in records:
        mem_buffer += bson.encode(item)
    return mem_buffer

