import torch
import re

def transform_llama_weights(args, layer_name, weight_tensor):
    if layer_name == "module.module.embedding.word_embeddings.weight":
        return [("model.embed_tokens.weight", weight_tensor)]
    if layer_name == "module.module.output_layer.weight":
        return [("lm_head.weight", weight_tensor)]
    if layer_name == "module.module.decoder.final_layernorm.weight":
        return [("model.norm.weight", weight_tensor)]

    try:
        dim_per_head = args.kv_channels if args.kv_channels is not None else args.hidden_size // args.num_attention_heads
    except AttributeError:
        dim_per_head = args.hidden_size // args.num_attention_heads

    q_per_group = args.num_attention_heads // args.num_query_groups
    decoder_layer_regex = r"module\.module\.decoder\.layers\.(\d+)\.(.+)"
    layer_match = re.match(decoder_layer_regex, layer_name)

    if layer_match:
        layer_id, sub_name = layer_match.groups()

        if sub_name == "self_attention.linear_proj.weight":
            return [(f"model.layers.{layer_id}.self_attn.o_proj.weight", weight_tensor)]

        elif sub_name == "self_attention.linear_qkv.weight":
            # Reshape QKV for Llama conversion
            reshaped_weight = weight_tensor.view(args.num_query_groups, -1, dim_per_head, args.hidden_size)
            q_weight, k_weight, v_weight = torch.split(reshaped_weight, split_size_or_sections=[q_per_group, 1, 1], dim=1)

            q_flat = q_weight.reshape(-1, args.hidden_size)
            k_flat = k_weight.reshape(-1, args.hidden_size)
            v_flat = v_weight.reshape(-1, args.hidden_size)

            return [
                (f"model.layers.{layer_id}.self_attn.q_proj.weight", q_flat),
                (f"model.layers.{layer_id}.self_attn.k_proj.weight", k_flat),
                (f"model.layers.{layer_id}.self_attn.v_proj.weight", v_flat),
            ]

        elif sub_name == "mlp.linear_fc1.weight":
            # Split SwiGLU projections
            gate_part, up_part = weight_tensor.chunk(2, dim=0)
            return [
                (f"model.layers.{layer_id}.mlp.gate_proj.weight", gate_part),
                (f"model.layers.{layer_id}.mlp.up_proj.weight", up_part),
            ]

