# Modified version of FrameStack with renamed variables and reordering
import gym
import numpy as np
from collections import deque
from gym.spaces import Box

class LazyFrames(object):
    def __init__(self, frame_list, axis=-1):
        self._frame_list = frame_list
        self._axis = axis

    def __array__(self, dtype=None):
        result = np.concatenate(self._frame_list, axis=self._axis)
        if dtype is not None:
            result = result.astype(dtype)
        return result

class FrameStack(gym.Wrapper):
    def __init__(self, environment, stack_count: int, axis=-1, use_lazy=False):
        super().__init__(environment)
        self._stack_count = stack_count
        self._axis = axis
        self._use_lazy = use_lazy
        self._buffer = deque([], maxlen=stack_count)

        # Update observation space bounds
        obs_low = np.repeat(self.observation_space.low, stack_count, axis=axis)
        obs_high = np.repeat(self.observation_space.high, stack_count, axis=axis)
        self.observation_space = Box(low=obs_low,
                                     high=obs_high,
                                     dtype=self.observation_space.dtype)

    def reset(self):
        initial_obs = self.env.reset()
        for _ in range(self._stack_count):
            self._buffer.append(initial_obs)
        return self._compose_observation()

    def step(self, action):
        next_obs, reward, terminated, info = self.env.step(action)
        self._buffer.append(next_obs)
        return self._compose_observation(), reward, terminated, info

    def _compose_observation(self):
        assert len(self._buffer) == self._stack_count
        if self._use_lazy:
            return LazyFrames(list(self._buffer), axis=self._axis)
        else:
            return np.concatenate(list(self._buffer), axis=self._axis)

