# AFIP WSAA service consultation with retry logic and error handling
import logging
from builtins import ConnectionResetError
import httpx
from tenacity import (before_sleep_log, retry, retry_if_exception_type,
                      stop_after_attempt, wait_fixed)
from zeep.exceptions import Fault, TransportError, XMLSyntaxError
from service.soap_client.format_error import build_error_response
from service.utils.logger import logger

@retry(
    retry=retry_if_exception_type((ConnectionResetError, httpx.ConnectError, TransportError)),
    stop=stop_after_attempt(3),
    wait=wait_fixed(0.5),
    before_sleep=before_sleep_log(logger, logging.WARNING),
)
async def consult_afip_wsaa(request_func, operation_name) -> dict:
    logger.info("Initiating CMS login request to AFIP")
    try:
        ticket_response = await request_func()
        logger.info("CMS login request to AFIP completed successfully.")
        return {
            "status": "success",
            "data": ticket_response
        }

    except (httpx.ConnectError, httpx.TimeoutException) as err:
        return build_error_response(operation_name, "Network issue", str(err))

    except TransportError as err:
        return build_error_response(operation_name, "HTTP failure", str(err))

    except Fault as err:
        # SOAP Faults suggest the service couldn't process the request, 
        # typically due to incorrect input, type mismatches, or policy violations.
        # These should be addressed by the calling component.
        logger.debug(f"SOAP FAULT in {operation_name}: {err}")
        return build_error_response(operation_name, "SOAPFault", str(err))

    except XMLSyntaxError as err:
        return build_error_response(operation_name, "Malformed AFIP response", str(err))

    except Exception as err:
        logger.error(f"Unexpected error in {operation_name}: {err}")
        return build_error_response(operation_name, "unknown", str(err))

# Format z-base-32 encoded text into lines with specified grouping and length constraints
from __future__ import annotations
from ..encoding.zbase32 import ZBASE32_ALPHABET

def format_zbase32_lines(
    data: str,
    *,
    group_width: int,
    max_line_width: int,
    max_lines: int | None,
) -> list[str]:
    if group_width <= 0:
        raise ValueError("group_width must be positive")
    if max_line_width <= 0:
        raise ValueError("max_line_width must be positive")
    if group_width > max_line_width:
        raise ValueError("group_width must be <= max_line_width")
    if max_lines is not None and max_lines <= 0:
        raise ValueError("max_lines must be positive")

    valid_chars: list[str] = []
    for symbol in data:
        if symbol.isspace() or symbol == "-":
            continue
        lower_char = symbol.lower()
        if lower_char not in ZBASE32_ALPHABET:
            raise ValueError(f"invalid z-base-32 character: {symbol!r}")
        valid_chars.append(lower_char)

    encoded_str = "".join(valid_chars)
    chunked_groups = [encoded_str[i : i + group_width] for i in range(0, len(encoded_str), group_width)]

    formatted_lines: list[str] = []
    current_line = ""

    for chunk in chunked_groups:
        proposed = chunk if not current_line else f"{current_line} {chunk}"
        if len(proposed) > max_line_width:
            formatted_lines.append(current_line)
            current_line = chunk
        else:
            current_line = proposed

    if current_line:
        formatted_lines.append(current_line)

    if max_lines is not None and len(formatted_lines) > max_lines:
        raise ValueError("formatted output exceeds max_lines")

    return formatted_lines

