# Modified version of the original code with Type I clone transformations
import torch.nn as nn
import re

class IdentityMapping(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, x, *args, **kwargs):
        return x

    @property
    def configuration(self):
        return {"mm_projector_type": 'identity'}

class SimpleResidualBlock(nn.Module):
    def __init__(self, num_channels):
        super().__init__()
        self.pre_norm_layer = nn.LayerNorm(num_channels)
        self.projection = nn.Sequential(
            nn.Linear(num_channels, num_channels),
            nn.GELU(),
            nn.Linear(num_channels, num_channels)
        )

    def forward(self, input_tensor):
        input_tensor = self.pre_norm_layer(input_tensor)
        return input_tensor + self.projection(input_tensor)

def construct_vision_projector(model_config, delay_loading=False, **kwargs):
    proj_type = getattr(model_config, 'mm_projector_type', 'linear')

    if proj_type == 'linear':
        return nn.Linear(model_config.mm_hidden_size, model_config.hidden_size)

    mlp_gelu_pattern = re.match(r'^mlp(\d+)x_gelu$', proj_type)
    if mlp_gelu_pattern:
        mlp_layers = int(mlp_gelu_pattern.group(1))
        layers_list = [nn.Linear(model_config.mm_hidden_size, model_config.hidden_size)]

        for _ in range(1, mlp_layers):
            layers_list.append(nn.GELU())
            layers_list.append(nn.Linear(model_config.hidden_size, model_config.hidden_size))

        return nn.Sequential(*layers_list)

    if proj_type == 'identity':
        return IdentityMapping()

    raise ValueError(f'Unknown projector type: {proj_type}')

