class GlmPipeline(Qwen2VlPipeline, GenerationMixin):
    def __init__(self, config):
        super().__init__(config)
        self.image_processor = AutoProcessor.from_pretrained(config.tokenizer.from_pretrained,
                                        local_files_only=True, use_fast=True)

    def get_rope_index(self, input_tokens, image_dims=None, video_dims=None, attention_mask=None):
        return glm_position(
            config=self.generation_config,
            input_ids=input_tokens,
            image_grid_thw=image_dims,
            video_grid_thw=video_dims,
            attention_mask=attention_mask
        )

    def __call__(self, prompt=None, images=None, videos=None, return_ids=False):
        return super().__call__(prompt, images, videos, return_ids, skip_special_tokens=False)

    def prepare_inputs(self, prompt=None, images=None, videos=None, messages=None):
        if not images and not messages and not videos:
            return None

        if not messages:
            content_parts = []
            if images:
                content_parts.append({"type": "image", "image": images})
            if videos:
                content_parts.append({"type": "video", "video": videos})
            content_parts.append({"type": "text", "text": prompt})
            messages = [[
                {
                    "role": "user",
                    "content": content_parts,
                }
            ]]

        inputs = self.image_processor.apply_chat_template(
            messages, tokenize=True, add_generation_prompt=True, 
            return_dict=True, return_tensors="pt", padding=True)
        inputs = inputs.to(self.infer_config.device)
        return inputs

