from typing import Callable, Type, Dict, Optional, Any
from pydantic import BaseModel, ConfigDict

class RegisteredOperation(BaseModel):
    """Model for a registered operation"""
    title: str
    details: str
    handler: Callable
    schema_model: Type[BaseModel]
    needs_mac_builder: bool = False
    model_config = ConfigDict(arbitrary_types_allowed=True)

    def get_prompt_info(self) -> str:
        """Retrieve a description of the operation for the prompt"""
        exclude_fields = ['title', 'description']
        result = f'{self.details}: \n'
        result += '{' + str(self.title) + ': '
        result += str(
            {
                key: {sub_key: sub_value for sub_key, sub_value in value.items() if sub_key not in exclude_fields}
                for key, value in self.schema_model.model_json_schema()['properties'].items()
            }
        )
        result += '}'
        return result

class OperationModel(BaseModel):
    """Base model for dynamically created operation models"""
    # this will have all the registered operations, e.g.
    # select_item = param_model = SelectItemParams
    # finish = param_model = None
    #
    model_config = ConfigDict(arbitrary_types_allowed=True, extra='allow')

    def retrieve_position(self) -> int | None:
        """Get the position of the operation"""
        # {'selected_item': {'position':5}}
        data_values = self.model_dump(exclude_unset=True).values()
        if not data_values:
            return None
        for item in data_values:
            if item is not None and 'position' in item:
                return item['position']
        return None

    def update_position(self, position: int):
        """Overwrite the position of the operation"""
        # Get the operation name and params
        operation_data = self.model_dump(exclude_unset=True)
        operation_name = next(iter(operation_data.keys()))
        operation_params = getattr(self, operation_name)
        # Update the position directly on the model
        if hasattr(operation_params, 'position'):
            operation_params.position = position

class OperationRegistry(BaseModel):
    """Model representing the operation registry"""
    operations: Dict[str, RegisteredOperation] = {}

    def get_all_prompt_descriptions(self) -> str:
        """Get descriptions of all operations for the prompt"""
        return '\n'.join([op.get_prompt_info() for op in self.operations.values()])

import bisect
from collections.abc import Iterable
from typing import NamedTuple
from torch.utils.data import ConcatDataset

# can't be a local class as it is required to be pickleable
class _InterleavedConcatDataset(ConcatDataset):
    """`torch.utils.data.ConcatDataset` but it returns the dataset index."""
    def __getitem__(self, idx):
        if idx < 0:
            if -idx > len(self):
                raise ValueError("absolute value of index should not exceed dataset length")
            idx = len(self) + idx
        dataset_idx = bisect.bisect_right(self.cumulative_sizes, idx)
        if dataset_idx == 0:
            sample_idx = idx
        else:
            sample_idx = idx - self.cumulative_sizes[dataset_idx - 1]
        return dataset_idx, self.datasets[dataset_idx][sample_idx]

# can't be a local class as it is required to be pickleable
class _InterleavedCollator:
    """Holds a list of collators and calls a single one of them based on the dataset_idx that was returned."""
    def __init__(self, collators_list):
        self.collators_list = collators_list
    def __call__(self, batch_data):
        dataset_indices, data_items = zip(*batch_data, strict=True)
        if not all(dataset_indices[0] == idx for idx in dataset_indices):
            raise ValueError("All samples in a batch must come from the same dataset.")
        return self.collators_list[dataset_indices[0]](data_items)

class SamplerOutput(NamedTuple):  # lint-ignore: NoNamedTuple
    """Output of the InterleavedSampler. Contains the sample index and the dataset index."""
    is_full_batch: bool
    index: int

# can't be a local class as it is required to be pickleable
class _InterleavedBatchSampler:
    """Creates batches of indices from an iterable of indices."""
    def __init__(self, sampling_sequence: Iterable[SamplerOutput]):
        super().__init__()
        self.sampling_sequence = sampling_sequence
    def __iter__(self):
        batch_indices = []
        for is_full_batch, idx in self.sampling_sequence:
            batch_indices.append(idx)
            if is_full_batch:
                yield batch_indices
                batch_indices = []
        assert len(batch_indices) == 0
    def __len__(self):
        raise NotImplementedError

