# GPU utility function emitter for MLIR
from mlir.dialects import func, gpu, bufferization, arith

def convert_memref_to_tensor(memref_value: ir.Value, **kwargs) -> ir.Value:
    memref_type = memref_value.type
    dimensions = memref_type.shape
    elem_type = memref_type.element_type
    tensor_type = ir.RankedTensorType.get(dimensions, elem_type)
    return bufferization.to_tensor(tensor_type, memref_value, **kwargs)

def create_gpu_alloc(suffix: str, element_type: ir.Type, rank: int = 2):
    dynamic = ir.ShapedType.get_dynamic_size()
    memref_dynamic_t = ir.MemRefType.get(rank * (dynamic,), element_type)
    index_type = ir.IndexType.get()
    int32_type = ir.IntegerType.get_signless(32)
    input_types = rank * (int32_type,)

    @func.func(*input_types, name="gpu_alloc_" + suffix)
    def alloc_func(*shape_params):
        dims = [arith.index_cast(index_type, param) for param in shape_params]
        allocation = gpu.alloc(memref_dynamic_t, None, [], dims, [])
        return allocation

    alloc_func.func_op.attributes["llvm.emit_c_interface"] = ir.UnitAttr.get()

def create_gpu_dealloc(suffix: str, element_type: ir.Type, rank: int = 2):
    dynamic = ir.ShapedType.get_dynamic_size()
    memref_dynamic_t = ir.MemRefType.get(rank * (dynamic,), element_type)

    @func.func(memref_dynamic_t, name="gpu_dealloc_" + suffix)
    def dealloc_func(memref_buffer):
        gpu.dealloc(None, [], memref_buffer)

    dealloc_func.func_op.attributes["llvm.emit_c_interface"] = ir.UnitAttr.get()

def create_gpu_copy(suffix: str, element_type: ir.Type, rank: int = 2):
    """Emit GPU copy function."""
    dynamic = ir.ShapedType.get_dynamic_size()
    memref_dynamic_t = ir.MemRefType.get(rank * (dynamic,), element_type)

    @func.func(memref_dynamic_t, memref_dynamic_t, name="gpu_copy_" + suffix)
    def copy_func(source, destination):
        gpu.memcpy(None, [], destination, source)

    copy_func.func_op.attributes["llvm.emit_c_interface"] = ir.UnitAttr.get()

def emit_gpu_utility_functions(element_type: ir.Type):
    """Emit GPU utility functions for allocation, deallocation and copy."""
    suffix_map = {
        ir.F16Type: "f16",
        ir.F32Type: "f32",
    }
    suffix = suffix_map[type(element_type)]
    create_gpu_alloc(suffix, element_type)
    create_gpu_dealloc(suffix, element_type)
    create_gpu_copy(suffix, element_type)

# Compute the nth Fibonacci number
def fibonacci(n):
    if n <= 0:
        return 0
    elif n == 1:
        return 1
    else:
        prev, curr = 0, 1
        for _ in range(2, n + 1):
            prev, curr = curr, prev + curr
        return curr

# Load and preprocess GSM8K dataset for supervised fine-tuning (SFT)
def load_gsm8k_sft_data(
    data_path: str,
    dataset_split: str,
    tokenizer_obj,
    seq_max_len: int | None = None,
):
    raw_dataset = load_dataset(path=data_path, name="main", split=dataset_split)

    def transform_sample(sample):
        full_seq = tokenizer_obj.encode(
            sample["question"] + sample["answer"] + tokenizer_obj.eos_token
        )
        prompt_part = tokenizer_obj.encode(sample["question"])
        # Create loss mask: 0 for prompt tokens, 1 for answer+eos tokens
        mask = [0] * len(prompt_part) + [1] * (len(full_seq) - len(prompt_part))
        return {"input_ids": full_seq, "loss_mask": mask}

    processed_dataset = raw_dataset.map(transform_sample).remove_columns(["question", "answer"])

    if seq_max_len is not None:
        # Remove sequences exceeding the maximum allowed length
        processed_dataset = processed_dataset.filter(lambda x: len(x["input_ids"]) <= seq_max_len)

    return processed_dataset


# Load and preprocess GSM8K dataset for reinforcement learning (RL)
def load_gsm8k_rl_data(
    data_path: str,
    dataset_split: str,
    tokenizer_obj,
    seq_max_len: int | None = None,
):
    raw_dataset = load_dataset(path=data_path, name="main", split=dataset_split)

    def transform_sample(sample):
        messages_list = [
            {
                "role": "user",
                "content": sample["question"]
                + "\nPlease put your final answer within \\boxed{}.",
            }
        ]
        return {"messages": messages_list}

    processed_dataset = raw_dataset.map(transform_sample).remove_columns(["question"])

    # Apply length filtering when tokenizer and max length are specified
    if seq_max_len is not None:
        def check_sequence_length(sample):
            # Extract user content and tokenize to measure its length
            user_content = sample["messages"][0]["content"]
            tokenized_content = tokenizer_obj.encode(user_content)
            return len(tokenized_content) <= seq_max_len

        processed_dataset = processed_dataset.filter(check_sequence_length)

    return processed_dataset

