# Mapping of lazy-loaded attributes to their module paths and names
_LAZY_ATTRIBUTES = {
    "TrainDiffusionRecipe": (".train", "TrainDiffusionRecipe"),
    "build_model_and_optimizer": (".train", "build_model_and_optimizer"),
    "build_lr_scheduler": (".train", "build_lr_scheduler"),
}

# Exported symbols in sorted order
__all__ = sorted(_LAZY_ATTRIBUTES.keys())

def __getattr__(attr_name: str):
    if attr_name in _LAZY_ATTRIBUTES:
        module_path, symbol_name = _LAZY_ATTRIBUTES[attr_name]
        module = importlib.import_module(module_path, __name__)
        attribute = getattr(module, symbol_name)
        globals()[attr_name] = attribute
        return attribute
    raise AttributeError(f"module {__name__!r} has no attribute {attr_name!r}")

def __dir__():
    return sorted(__all__)

