# Decorator to ensure only one instance per class and process
def singleton_decorator(cls, *args, **kwargs):
    cache = {}
    def _get_instance():
        identifier = str(cls) + str(os.getpid())
        if identifier not in cache:
            cache[identifier] = cls(*args, **kwargs)
        return cache[identifier]
    return _get_instance

# Count occurrences of substring in string (overlapping allowed)
def count_substring(string, substring):
    if not substring or not string:
        return 0

    occurrence_count = 0
    search_start = 0

    while True:
        position = string.find(substring, search_start)
        if position == -1:
            break
        occurrence_count += 1
        search_start = position + 1

    return occurrence_count

