        super().__init__(model_file_path)
        self.var_dynamic_constraints = get_dynamic_dim_constraints(model_file_path)

    def get_class_name(self) -> str:
        return os.path.basename(__file__)[:-3]

    def check_match(self) -> bool:
        if self.var_dynamic_constraints is None:
            return False

        symbolic_shapes_str = self.var_dynamic_constraints.serialize_symbolic_input_shapes_to_str()

        if symbolic_shapes_str == "[]":
            return False
        elif symbolic_shapes_str not in self._get_mapping_sym_shapes_to_reifier():
            print(
                f"[Symbolic Dimension Reification] No reifier found for symbolic shapes: {symbolic_shapes_str} \n"
                f"Please define a corresponding reify rule in _get_mapping_sym_shapes_to_reifier()"
            )
            return False
        return True

