import pytest
import torch
import tilegym
from .. import common

class Test_Softmax(common.PyTestCase):
    @staticmethod
    def reference_func(input_tensor):
        return torch.nn.functional.softmax(input_tensor, dim=-1)

    _supported_backends = ["cutile"]

    @pytest.mark.parametrize(
        "rows, cols, precision",
        [
            (256, 256, torch.float32),
            (256, 2048, torch.float32),
            (256, 1024 * 32, torch.float32),
            (256, 256, torch.float16),
            (256, 2048, torch.float16),
            (256, 9, torch.float32),
            (256, 1009, torch.float16),
        ],
    )
    @pytest.mark.parametrize("device_backend", _supported_backends)
    @pytest.mark.parametrize("enable_tma", [True, False], ids=["tma_enabled", "tma_disabled"])
    @pytest.mark.parametrize("chunked_mode", [True, False], ids=["chunked_on", "chunked_off"])
    def test_softmax_operation(self, rows, cols, precision, arch, device_backend, enable_tma, chunked_mode):
        # Skip invalid combinations
        if chunked_mode and enable_tma:
            pytest.skip("TMA and chunked softmax cannot be used simultaneously")

        # Set up backend if available
        if tilegym.is_backend_available(device_backend):
            tilegym.set_backend(device_backend)
        else:
            pytest.skip(f"Backend {device_backend} is not supported on this system")

        # Create test tensors on GPU
        cuda_device = torch.device("cuda")
        input_data = torch.rand(
            rows,
            cols,
            device=cuda_device,
            dtype=precision,
        )
        grad_output = torch.rand_like(input_data)

        # Set tolerance based on precision
        if precision == torch.float16:
            relative_tol, absolute_tol = 1e-3, 1e-5
        else:
            relative_tol, absolute_tol = 1e-5, 1e-7

        # Run correctness test
        self.assertCorrectness(
            tilegym.ops.softmax,
            self.reference_func,
            {"x": input_data},
            extra_test_kwargs={"use_tma": enable_tma, "use_chunked": chunked_mode},
            gradient=grad_output,
            rtol=relative_tol,
            atol=absolute_tol,
        )

