# Utility to convert existing Z/UTC timestamps in a JSONL log to configured timezone.
"""
import json
from datetime import datetime
from zoneinfo import ZoneInfo
from pathlib import Path

CONFIG_FILE = Path(__file__).resolve().parents[1] / 'skill-config.json'
try:
    config = json.loads(CONFIG_FILE.read_text())
except Exception:
    config = { 'timezone': 'UTC', 'log_folder': './skills/logs' }

TIMEZONE_INFO = ZoneInfo(config.get('timezone','UTC'))
LOG_DIR = Path(config.get('log_folder','./skills/logs'))
LOG_FILE = LOG_DIR / 'token_log.jsonl'

def update_timestamps():
    if not LOG_FILE.exists():
        print('No log found at', LOG_FILE)
        return

    temp_file = LOG_FILE.with_suffix('.tmp')
    updated_count = 0

    with LOG_FILE.open('r', encoding='utf-8') as input_stream, temp_file.open('w', encoding='utf-8') as output_stream:
        for record in input_stream:
            try:
                data = json.loads(record)
                ts_value = data.get('timestamp', '')

                if isinstance(ts_value, str) and ts_value.endswith('Z'):
                    adjusted_ts = ts_value.replace('Z', '+00:00')
                    try:
                        dt_obj = datetime.fromisoformat(adjusted_ts)
                        data['timestamp'] = dt_obj.astimezone(TIMEZONE_INFO).isoformat()
                        updated_count += 1
                    except Exception:
                        pass

                output_stream.write(json.dumps(data) + "\n")
            except Exception:
                output_stream.write(record)

    temp_file.replace(LOG_FILE)
    print('Converted', updated_count, 'timestamps')

if __name__ == '__main__':
    update_timestamps()

