# Validate bounding boxes for form fields in JSON input
import json
import sys
from dataclasses import dataclass

@dataclass
class BoxAndField:
    box: list[float]
    box_type: str
    field_data: dict

def validate_bounding_boxes(input_stream) -> list[str]:
    output_lines = []
    data = json.load(input_stream)
    output_lines.append(f"Loaded {len(data['form_fields'])} form fields")

    def boxes_overlap(b1, b2):
        no_overlap_x = b1[0] >= b2[2] or b1[2] <= b2[0]
        no_overlap_y = b1[1] >= b2[3] or b1[3] <= b2[1]
        return not (no_overlap_x or no_overlap_y)

    box_list = []
    for field in data["form_fields"]:
        box_list.append(BoxAndField(field["label_bounding_box"], "label", field))
        box_list.append(BoxAndField(field["entry_bounding_box"], "entry", field))

    found_issues = False

    # Check for overlapping bounding boxes
    for idx, current_box in enumerate(box_list):
        for other_idx in range(idx + 1, len(box_list)):
            other = box_list[other_idx]
            if (current_box.field_data["page_number"] == other.field_data["page_number"] and 
                boxes_overlap(current_box.box, other.box)):
                found_issues = True

                if current_box.field_data is other.field_data:
                    output_lines.append(
                        f"ERROR: label and entry boxes overlap for `{current_box.field_data['description']}` "
                        f"({current_box.box}, {other.box})"
                    )
                else:
                    output_lines.append(
                        f"ERROR: {current_box.box_type} box for `{current_box.field_data['description']}` "
                        f"({current_box.box}) overlaps with {other.box_type} box for `{other.field_data['description']}` ({other.box})"
                    )

                if len(output_lines) >= 20:
                    output_lines.append("Stopping further checks; please fix the issues and re-run")
                    return output_lines

    # Check entry box height against font size
    for box_item in box_list:
        if box_item.box_type == "entry":
            if "entry_text" in box_item.field_data:
                text_info = box_item.field_data["entry_text"]
                font_size = text_info.get("font_size", 14)
                box_height = box_item.box[3] - box_item.box[1]

                if box_height < font_size:
                    found_issues = True
                    output_lines.append(
                        f"ERROR: entry box height ({box_height}) for `{box_item.field_data['description']}` "
                        f"is insufficient for font size ({font_size}). Please increase box height or reduce font size."
                    )

                    if len(output_lines) >= 20:
                        output_lines.append("Stopping further checks; please fix the issues and re-run")
                        return output_lines

    if not found_issues:
        output_lines.append("OK: All bounding boxes meet requirements")

    return output_lines

