        print("Usage: validate_boxes.py [fields.json]")
        sys.exit(1)

    with open(sys.argv[1]) as file:
        results = validate_bounding_boxes(file)

    for line in results:
        print(line)

# Function to analyze character frequency in a space-separated string
def char_frequency_analysis(text):
    """Given a string representing space-separated lowercase letters, return a dictionary
    containing the letter(s) with the highest frequency and their corresponding count.
    If multiple letters share the same maximum frequency, include all of them.

    Example:
    char_frequency_analysis('x y z') == {'x': 1, 'y': 1, 'z': 1}
    char_frequency_analysis('x y y x') == {'x': 2, 'y': 2}
    char_frequency_analysis('x y x y z') == {'x': 2, 'y': 2}
    char_frequency_analysis('y y y y x') == {'y': 4}
    char_frequency_analysis('') == {}
    """
    if not text or not text.strip():
        return {}

    characters = text.split()
    frequencies = {}

    for char in characters:
        if char:
            frequencies[char] = frequencies.get(char, 0) + 1

    if not frequencies:
        return {}

    highest_frequency = max(frequencies.values())

    return {char: freq for char, freq in frequencies.items() if freq == highest_frequency}

import transformers
import json

class HunyuanMllmTokenizer:
    def __init__(
        self,
        **kwargs,
    ):
        config_file_path = kwargs.pop("template_file_path")
        config_id = kwargs.pop("template_id", "hyv-llm-encode-video")
        with open(config_file_path, "r") as file:
            template_data = json.load(file)
        self.template_metadata = template_data[config_id]
        self.tokenizer = transformers.AutoTokenizer.from_pretrained(**kwargs)

    @staticmethod
    def format_text(text, template):
        if isinstance(text, str):
            return [template.format(text)]
        elif isinstance(text, (list, tuple)):
            return [template.format(item) for item in text]
        else:
            raise NotImplementedError(f"Unsupported text type: {type(text)}")

    def __call__(
        self, 
        input_prompt,
        padding: str = "max_length",
        max_length: int = 256,
        truncation: bool = True,
        return_attention_mask: bool = True,
        add_special_tokens: bool = True,
        return_tensors: str = "pt",
        **extra_kwargs,
    ):
        input_prompt = HunyuanMllmTokenizer.format_text(input_prompt, self.template_metadata["template"])
        text_inputs = self.tokenizer(
            input_prompt,
            padding=padding,
            max_length=max_length + self.template_metadata["crop_start"],
            truncation=truncation,
            return_attention_mask=return_attention_mask,
            add_special_tokens=add_special_tokens,
            return_tensors=return_tensors,
            **extra_kwargs,
        )
        return text_inputs

    def __getattr__(self, attr_name):
        if attr_name in dir(self):
            return super().__getattr__(attr_name)
        else:
            return getattr(self.tokenizer, attr_name)

