# Module for handling request hooks
# ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
# This module enables the hook system for Requests.
# Supported hooks:
# `response`:
#     The response object produced by a Request.
"""
HOOK_NAMES = ["response"]

def initialize_hooks():
    return {event: [] for event in HOOK_NAMES}

# TODO: response is currently the only supported hook
def execute_hook(hook_type, hooks_dict, data, **additional_kwargs):
    """Executes a set of hooks for a specified event on provided data."""
    hooks_dict = hooks_dict or {}
    hooks_list = hooks_dict.get(hook_type)
    if hooks_list:
        if callable(hooks_list):
            hooks_list = [hooks_list]
        for hook_func in hooks_list:
            updated_data = hook_func(data, **additional_kwargs)
            if updated_data is not None:
                data = updated_data
    return data

