# Modified version of AgentTask class with renamed variables and reordered logic
from pathlib import Path
import json
from datetime import datetime

class TaskManager:
    """Handles the lifecycle and dependencies of extended, multi-phase agent operations."""

    def __init__(self, operation_name: str, storage_file: Path = Path('operation_state.json')):
        self.operation_name = operation_name
        self.storage_file = storage_file
        self.current_state = self._retrieve_state()

    def _retrieve_state(self):
        """Fetches all operation states from the JSON persistence file."""
        if not self.storage_file.exists():
            return {}
        try:
            with open(self.storage_file, 'r') as file_handle:
                return json.load(file_handle)
        except json.JSONDecodeError:
            print(f"Notice: Unable to parse {self.storage_file}. Initializing empty state.")
            return {}

    def _persist_state(self):
        """Writes the current operation state to disk."""
        with open(self.storage_file, 'w') as file_handle:
            json.dump(self.current_state, file_handle, indent=2)

    def fetch_operation_state(self):
        """Gets or creates the state record for the specified operation."""
        if self.operation_name not in self.current_state:
            self.current_state[self.operation_name] = {
                "progress": "PENDING",
                "phases_done": 0,
                "timestamp": None,
                "payload": {}
            }
            self._persist_state()
        return self.current_state[self.operation_name]

    def set_status(self, updated_status: str, extra_info: dict = None):
        """Modifies the status and optionally merges additional data into the operation record."""
        op_record = self.fetch_operation_state()
        op_record["progress"] = updated_status
        op_record["timestamp"] = datetime.now().isoformat()

        if extra_info:
            op_record["payload"].update(extra_info)

        self._persist_state()
        print(f"Operation '{self.operation_name}' progress changed to: {updated_status}")

