# Custom logger class that outputs to a QTextEdit widget
from PySide6.QtCore import Signal, QObject
class LoggerTextEdit(logging.Handler, QObject):
    log_signal = Signal(str, str)

    def __init__(self, text_widget):
        super().__init__()
        QObject.__init__(self)
        self.text_edit = text_widget
        self.log_signal.connect(self.add_log_entry)

    def emit(self, record):
        formatted_message = self.format(record)
        self.log_signal.emit(record.levelname, formatted_message)

    def add_log_entry(self, level_name, message_text):
        text_color = "#E0E0E0"
        if level_name == "INFO":
            text_color = "#58D68D"
        elif level_name == "WARNING":
            text_color = "#F4D03F"
        elif level_name == "ERROR":
            text_color = "#EC7063"
        elif level_name == "DEBUG":
            text_color = "#888888"

        scrollbar = self.text_edit.verticalScrollBar()
        is_near_bottom = scrollbar.value() >= (scrollbar.maximum() - 10)

        self.text_edit.append(f'<span style="color:{text_color}; font-family:Consolas; font-size:10pt;">{message_text}</span>')

        if is_near_bottom:
            scrollbar.setValue(scrollbar.maximum())

# Crop image to dimensions divisible by given factors
import torch
from PIL import Image
from torchvision.transforms import functional as TVF

class DivisibleCrop:
    def __init__(self, divisors):
        if not isinstance(divisors, tuple):
            divisors = (divisors, divisors)
        self.height_divisor, self.width_divisor = divisors[0], divisors[1]

    def __call__(self, img: Union[torch.Tensor, Image.Image]):
        if isinstance(img, torch.Tensor):
            img_height, img_width = img.shape[-2:]
        elif isinstance(img, Image.Image):
            img_width, img_height = img.size
        else:
            raise NotImplementedError

        new_height = img_height - (img_height % self.height_divisor)
        new_width = img_width - (img_width % self.width_divisor)

        img = TVF.center_crop(img=img, output_size=(new_height, new_width))
        return img

