# Process CSV file and generate formatted LaTeX output

import csv
import sys

def load_csv_content(file_location, separator=','):
    try:
        with open(file_location, 'r', encoding='utf-8') as input_file:
            parser = csv.reader(input_file, delimiter=separator)
            rows = [line for line in parser]
        return rows
    except FileNotFoundError:
        print(f"Error: File not found at '{file_location}'.")
        sys.exit(1)
    except Exception as error:
        print(f"Error: Unexpected issue while reading file: {error}")
        sys.exit(1)

def check_data_integrity(rows):
    if len(rows) == 0:
        print("Error: No data found in the CSV file.")
        sys.exit(1)

def prepare_latex_output(rows, highlight_terms):
    first_column_items = [row[0] for row in rows]
    first_column_items.sort(reverse=True)

    processed_values = []
    for item in first_column_items:
        if item in highlight_terms:
            processed_values.append(r'\textbf{\textit{' + item + r'}}')
        else:
            processed_values.append(item)

    latex_prefix = r'\textbf{\textit{Concatenated Values:}} '
    return latex_prefix + ' '.join(processed_values)

def main():
    if len(sys.argv) < 3:
        print("Usage: python script.py <file_path> <delimiter> [keywords ...]")
        sys.exit(1)

    target_file = sys.argv[1]
    field_separator = sys.argv[2]
    emphasized_words = sys.argv[3:]

    table_data = load_csv_content(target_file, field_separator)
    check_data_integrity(table_data)

