# Ensure all dependencies from requirements.txt are installed

import subprocess
import sys

def ensure_package(package_name):
    """Install a package using pip if it's not already available."""
    subprocess.run([sys.executable, "-m", "pip", "install", package_name], check=True)

def extract_packages(file_path):
    """Parse the requirements file and return a list of package names (excluding comments and empty lines)."""
    packages = []
    with open(file_path, 'r') as f:
        for line in f:
            stripped = line.strip()
            if stripped and not stripped.startswith('#'):
                # Extract base package name without version specifiers
                pkg = stripped.split('==')[0].split('>=')[0].split('<=')[0].split('>')[0].split('<')[0]
                packages.append(pkg)
    return packages

def verify_and_install_deps(file_path):
    """Verify required packages are present; install missing ones."""
    deps = extract_packages(file_path)
    for dep in deps:
        try:
            __import__(dep)
        except ImportError:
            print(f"Missing dependency: {dep}. Installing now...")
            # Re-read original line to preserve version info for installation
            with open(file_path, 'r') as f:
                for line in f:
                    if dep in line and not line.strip().startswith('#'):
                        full_spec = line.strip()
                        ensure_package(full_spec)
                        break

if __name__ == "__main__":
    req_file = "requirements.txt"
    verify_and_install_deps(req_file)
    print("All required dependencies have been verified and installed.")

def check_dict_case(dct):
    # Handle empty dictionary case
    if not dct:
        return False

    # Collect all keys and values for unified case checking
    all_items = list(dct.keys()) + list(dct.values())

    # Check if all items are strings (required for islower/isupper methods)
    if not all(isinstance(item, str) for item in all_items):
        return False

    # Determine the dominant case pattern among keys
    keys_lower = sum(1 for k in dct.keys() if isinstance(k, str) and k.islower())
    keys_upper = sum(1 for k in dct.keys() if isinstance(k, str) and k.isupper())

    # Determine if keys are consistently cased
    keys_consistent = (keys_lower == len(dct)) or (keys_upper == len(dct))

    if not keys_consistent:
        return False

    # If keys are all lowercase, check values are also all lowercase
    if keys_lower == len(dct):
        return all(isinstance(v, str) and v.islower() for v in dct.values())

    # If keys are all uppercase, check values are also all uppercase  
    if keys_upper == len(dct):
        return all(isinstance(v, str) and v.isupper() for v in dct.values())

    return False

# Calculate median without sorting or using built-in functions

def median(values: list):
    """Return median of elements in the list values without sorting it or using built-in functions.
    Handles lists with negative numbers.
    >>> median([3, 1, 2, 4, 5])
    3
    >>> median([-10, 4, 6, 1000, 10, 20])
    15.0
    >>> median([-5, -1, -3, -4, -2])
    -3
    >>> median([1, 2, 3, 4, 5, 6])
    3.5
    """
    def split_array(arr, start, end):
        pivot_val = arr[end]
        left_pos = start - 1
        for right_pos in range(start, end):
            if arr[right_pos] <= pivot_val:
                left_pos += 1
                arr[left_pos], arr[right_pos] = arr[right_pos], arr[left_pos]
        arr[left_pos + 1], arr[end] = arr[end], arr[left_pos + 1]
        return left_pos + 1

    def find_kth(arr, k, begin, finish):
        if begin == finish:
            return arr[begin]
        pivot_position = split_array(arr, begin, finish)
        if k == pivot_position:
            return arr[k]
        elif k < pivot_position:
            return find_kth(arr, k, begin, pivot_position - 1)
        else:
            return find_kth(arr, k, pivot_position + 1, finish)

    size = len(values)
    if size % 2 == 1:
        return find_kth(values, size // 2, 0, size - 1)
    else:
        lower_mid = find_kth(values, size // 2 - 1, 0, size - 1)
        upper_mid = find_kth(values, size // 2, 0, size - 1)
        return (lower_mid + upper_mid) / 2.0

