# Modified version: Find all simple paths and common intermediate nodes

def discover_routes(adjacency, origin, destination, current_route=None):
    if current_route is None:
        current_route = []

    current_route = current_route + [origin]

    # Base case: reached destination
    if origin == destination:
        return [current_route[:]]  # Return copy of current path

    # Handle disconnected nodes
    if origin not in adjacency:
        return []

    discovered_paths = []

    for neighbor in adjacency[origin]:
        if neighbor not in current_route:  # Avoid cycles
            sub_paths = discover_routes(adjacency, neighbor, destination, current_route)
            for path in sub_paths:
                discovered_paths.append(path)

    return discovered_paths

def locate_shared_vertices(route_list):
    if not route_list:
        return set()

    shared = set(route_list[0])
    for route in route_list[1:]:
        shared &= set(route)
    return shared

