class Individual:
    def __init__(self, full_name, year_of_birth, sex):
        self.full_name = full_name
        self.year_of_birth = year_of_birth
        self.sex = sex
        self.ancestors = []
        self.partner = None
        self.descendants = []

    def include_parent(self, parent):
        if parent not in self.ancestors:
            self.ancestors.append(parent)
            if self not in parent.descendants:
                parent.descendants.append(self)

    def establish_marriage(self, partner):
        if self.partner is None:
            self.partner = partner
            if partner.partner is None:
                partner.partner = self

    def register_offspring(self, child):
        if child not in self.descendants:
            self.descendants.append(child)
            if self not in child.ancestors:
                child.ancestors.append(self)

    def __str__(self):
        return f"Individual(full_name={self.full_name}, year_of_birth={self.year_of_birth}, sex={self.sex})"

# Count the number of islands in a grid using BFS instead of DFS

def numIslands(grid):
    if not grid or not grid[0]:
        return 0

    rows, cols = len(grid), len(grid[0])
    island_count = 0

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def bfs(start_r, start_c):
        from collections import deque
        queue = deque([(start_r, start_c)])
        grid[start_r][start_c] = '0'  # Mark as visited

        while queue:
            r, c = queue.popleft()

            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '1':
                    grid[nr][nc] = '0'  # Mark as visited
                    queue.append((nr, nc))

    for row_idx in range(rows):
        for col_idx in range(cols):
            if grid[row_idx][col_idx] == '1':
                island_count += 1
                bfs(row_idx, col_idx)

    return island_count

