# Alternative implementation to compute prime factor frequencies for numbers below n

def check_prime(value):
    if value < 2:
        return False
    divisor = 2
    while divisor * divisor <= value:
        if value % divisor == 0:
            return False
        divisor += 1
    return True

def get_prime_decomposition(number):
    decomposition = []
    candidate = 2
    while number > 1:
        if number % candidate == 0:
            decomposition.append(candidate)
            number //= candidate
        else:
            candidate += 1
    return decomposition

def count_factor_occurrences(limit):
    if limit <= 2:
        return {}

    occurrence_map = {}

    for current in range(2, limit):
        parts = get_prime_decomposition(current)
        for part in parts:
            occurrence_map[part] = occurrence_map.get(part, 0) + 1

    return occurrence_map

