import uuid
from datetime import date

class StaffMember:
    def __init__(self, full_name, years_old, compensation, position, join_date):
        self.unique_identifier = str(uuid.uuid4())
        self.full_name = full_name
        self.years_old = years_old
        self.compensation = compensation
        self.position = position
        self.join_date = join_date

    def compute_tenure(self):
        current_date = date.today()
        joined = date.fromisoformat(self.join_date)
        days_worked = (current_date - joined).days
        return days_worked // 365

    def __repr__(self):
        return f"Staff ID: {self.unique_identifier}, Name: {self.full_name}, Age: {self.years_old}, Compensation: {self.compensation}, Position: {self.position}, Joined: {self.join_date}"

class HumanResourcesManager:
    def __init__(self):
        self.staff_list = []

    def recruit_staff(self, full_name, years_old, compensation, position, join_date):
        new_member = StaffMember(full_name, years_old, compensation, position, join_date)
        self.staff_list.append(new_member)
        print(f"Staff member {full_name} has been recruited.")

    def dismiss_staff(self, staff_id):
        for member in self.staff_list:
            if member.unique_identifier == staff_id:
                self.staff_list.remove(member)
                print(f"Staff member with ID {staff_id} has been dismissed.")
                return
        print(f"No staff member found with ID {staff_id}.")

    def modify_staff_details(self, staff_id, **changes):
        for member in self.staff_list:
            if member.unique_identifier == staff_id:
                for attribute, new_value in changes.items():
                    setattr(member, attribute, new_value)
                print(f"Staff member with ID {staff_id} has been updated.")
                return
        print(f"No staff member found with ID {staff_id}.")

    def locate_staff(self, staff_id):
        for member in self.staff_list:
            if member.unique_identifier == staff_id:
                return member
        print(f"Staff member with ID {staff_id} could not be located.")
        return None

    def get_tenure(self, staff_id):
        member = self.locate_staff(staff_id)
        if member:
            return member.compute_tenure()
        return None

    def display_all_staff(self):
        for member in self.staff_list:
            print(member)

    def is_executive_role(self, staff_id):
        member = self.locate_staff(staff_id)
        if member and member.position.lower() == 'management':
            return True
        return False

