# Modified version of the number guessing game with different logic structure

import random

def get_valid_guess(player_name, low_bound, high_bound):
    while True:
        try:
            user_input = int(input(f"{player_name}, enter your guess ({low_bound}-{high_bound}): "))
            if low_bound <= user_input <= high_bound:
                return user_input
            else:
                print(f"Invalid input! Must be between {low_bound} and {high_bound}.")
        except ValueError:
            print("Error: Please enter a whole number.")

def run_game():
    lower_limit = 1
    upper_limit = 100
    max_attempts = 10

    target_number = random.randint(lower_limit, upper_limit)

    p1_name = input("Enter name for Player 1: ")
    p2_name = input("Enter name for Player 2: ")

    attempts_p1 = 0
    attempts_p2 = 0

    game_over = False

    # Alternate turns until someone wins or both exhaust their attempts
    while not game_over:
        # Player 1's attempt
        if attempts_p1 < max_attempts:
            current_guess = get_valid_guess(p1_name, lower_limit, upper_limit)
            attempts_p1 += 1

            if current_guess == target_number:
                print(f"🎉 {p1_name} guessed correctly! The number was {target_number}.")
                game_over = True
                break
            else:
                hint = "higher" if current_guess < target_number else "lower"
                remaining = max_attempts - attempts_p1
                print(f"❌ {p1_name} guessed {current_guess}. Try {hint}. Attempts left: {remaining}")

        # Player 2's attempt
        if attempts_p2 < max_attempts and not game_over:
            current_guess = get_valid_guess(p2_name, lower_limit, upper_limit)
            attempts_p2 += 1

            if current_guess == target_number:
                print(f"🎉 {p2_name} guessed correctly! The number was {target_number}.")
                game_over = True
                break
            else:
                hint = "higher" if current_guess < target_number else "lower"
                remaining = max_attempts - attempts_p2
                print(f"❌ {p2_name} guessed {current_guess}. Try {hint}. Attempts left: {remaining}")

        # Check if both players exhausted their attempts
        if attempts_p1 >= max_attempts and attempts_p2 >= max_attempts:
            game_over = True

    if not game_over or (attempts_p1 >= max_attempts and attempts_p2 >= max_attempts):
        print(f"🏁 Game over! Neither player found the number. The correct answer was {target_number}.")

if __name__ == "__main__":
    run_game()

