# ISBN validation utility class - Type III clone with modified logic

class ISBNChecker:
    def __init__(self, raw_isbn):
        # Clean the input: remove spaces and hyphens
        self.raw_input = raw_isbn
        cleaned = raw_isbn.strip().replace('-', '')
        self.isbn_digits = list(cleaned)
        self.clean_length = len(cleaned)
        self.validation_result = False
        self.failure_reason = None

    def check(self):
        # Determine ISBN type based on length
        if self.clean_length == 10:
            self.validation_result = self._check_isbn_10()
        elif self.clean_length == 13:
            self.validation_result = self._check_isbn_13()
        else:
            self.failure_reason = f"Length error: Expected 10 or 13 digits, got {self.clean_length}"
        return self.validation_result

    def _check_isbn_10(self):
        # Check character validity for ISBN-10
        core_part = self.isbn_digits[:-1]
        last_char = self.isbn_digits[-1] if self.isbn_digits else ''

        # Verify first 9 characters are digits
        if not all(ch.isdigit() for ch in core_part):
            self.failure_reason = "Format issue: First 9 characters must be digits"
            return False

        # Verify last character is digit or 'X'
        if not (last_char.isdigit() or last_char == 'X'):
            self.failure_reason = "Format issue: Last character must be digit or 'X'"
            return False

        # Convert to numeric values, treating 'X' as 10
        numeric_values = []
        for idx, char in enumerate(self.isbn_digits):
            if char == 'X':
                numeric_values.append(10)
            else:
                numeric_values.append(int(char))

        # Calculate weighted sum with decreasing weights (10 to 1)
        total = 0
        weight = 10
        for value in numeric_values:
            total += value * weight
            weight -= 1

        # Validate checksum (must be divisible by 11)
        if total % 11 != 0:
            self.failure_reason = "Checksum failure: ISBN-10 verification failed"
            return False

        return True

    def _check_isbn_13(self):
        # Verify all characters are digits
        if not all(ch.isdigit() for ch in self.isbn_digits):
            self.failure_reason = "Format issue: All characters must be digits for ISBN-13"
            return False

        # Convert to integers
        numbers = [int(d) for d in self.isbn_digits]

        # Apply alternating weights: 1, 3, 1, 3...
        weighted_sum = 0
        for i, num in enumerate(numbers):
            if i % 2 == 0:
                weighted_sum += num * 1
            else:
                weighted_sum += num * 3

        # Validate checksum (must be divisible by 10)
        if weighted_sum % 10 != 0:
            self.failure_reason = "Checksum failure: ISBN-13 verification failed"
            return False

        return True

    def get_error_details(self):
        return self.failure_reason


# Example usage demonstration
if __name__ == "__main__":
    test_cases = [
        "0-306-40615-2",  # Valid ISBN-10
        "978-0-306-40615-7",  # Valid ISBN-13
        "0-306-40615-3",  # Invalid ISBN-10
        "978-0-306-40615-8",  # Invalid ISBN-13
        "12345678901234",  # Invalid length
        "0-306-4061X-2"  # Invalid characters
    ]

    for isbn in test_cases:
        checker = ISBNChecker(isbn)
        if checker.check():
            print(f"{isbn} is a valid ISBN")
        else:
            print(f"{isbn} is an invalid ISBN: {checker.get_error_details()}")

import subprocess
import sys
import os

def execute_git_command(cmd_list, working_dir=None):
    try:
        process = subprocess.run(
            cmd_list,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            check=False,
            cwd=working_dir
        )
        if process.returncode == 0:
            return process.stdout.strip()
        else:
            return process.stderr.strip()
    except Exception as e:
        return str(e)

def fetch_repo(repo_address, local_name):
    git_clone_cmd = ['git', 'clone', repo_address, local_name]
    response = execute_git_command(git_clone_cmd)
    if any(keyword in response.lower() for keyword in ['fatal', 'error']):
        raise RuntimeError(f"Unable to clone repository: {response}")

def establish_branch_at_commit(project_path, new_branch_label, target_commit_id):
    # First checkout the specific commit
    checkout_commit_cmd = ['git', 'checkout', target_commit_id]
    result = execute_git_command(checkout_commit_cmd, project_path)
    if any(keyword in result.lower() for keyword in ['fatal', 'error']):
        raise RuntimeError(f"Commit hash '{target_commit_id}' not found: {result}")

    # Then create and switch to the new branch
    create_branch_cmd = ['git', 'checkout', '-b', new_branch_label]
    result = execute_git_command(create_branch_cmd, project_path)
    if any(keyword in result.lower() for keyword in ['fatal', 'error']):
        raise RuntimeError(f"Could not create branch '{new_branch_label}': {result}")

def main(repo_url, commit_id, branch_label):
    directory_name = os.path.basename(repo_url).rstrip('.git')

    # Clone the repository
    try:
        fetch_repo(repo_url, directory_name)
    except RuntimeError as error:
        print(error)
        sys.exit(1)

    # Create the new branch at the specified commit
    try:
        establish_branch_at_commit(directory_name, branch_label, commit_id)
    except RuntimeError as error:
        print(error)
        sys.exit(1)

    print(f"Branch '{branch_label}' successfully created from commit '{commit_id}' in '{repo_url}'.")

if __name__ == "__main__":
    if len(sys.argv) != 4:
        print("Usage: python git_branch_creator.py <repository_url> <commit_hash> <branch_name>")
        sys.exit(1)

    repository_url = sys.argv[1]
    commit_identifier = sys.argv[2]
    branch_title = sys.argv[3]

    main(repository_url, commit_identifier, branch_title)

# Convert numeric scores to letter grades and compute GPA

def score_to_letter(score):
    # Validate input range
    if score < 1 or score > 100:
        raise ValueError("Score must be between 1 and 100.")

    # Assign letter grade based on score thresholds
    if score >= 90:
        return 'A'
    elif score >= 80:
        return 'B'
    elif score >= 70:
        return 'C'
    elif score >= 60:
        return 'D'
    else:
        return 'F'

def letter_to_points(letter):
    # Map letter grades to grade points
    conversion_table = {
        'A': 4.0,
        'B': 3.0,
        'C': 2.0,
        'D': 1.0,
        'F': 0.0
    }
    return conversion_table.get(letter, 0.0)

def average_gpa(grade_list):
    # Handle empty list case
    if len(grade_list) == 0:
        return 0.0

    # Sum up all grade points and divide by count
    cumulative_points = 0.0
    for g in grade_list:
        cumulative_points += letter_to_points(g)
    return cumulative_points / len(grade_list)

def run_program():
    collected_grades = []

    while True:
        try:
            user_input = input("Enter a numeric score between 1 and 100 (or 'done' to finish): ")

            # Check for exit condition
            if user_input.lower() == 'done':
                break

            # Process numeric input
            numeric_value = float(user_input)
            letter_grade = score_to_letter(numeric_value)
            print(f"Numeric Score: {numeric_value} -> Grade: {letter_grade}")
            collected_grades.append(letter_grade)

        except ValueError as error:
            print(f"Error: {error}")

    # Display results if any valid grades were entered
    if collected_grades:
        final_gpa = average_gpa(collected_grades)
        print(f"Grades: {', '.join(collected_grades)}")
        print(f"Grade Point Average (GPA): {final_gpa:.2f}")
    else:
        print("No valid scores entered.")

if __name__ == "__main__":
    run_program()

