    Spaces are ignored, and all sections must have balanced brackets.

    :param input_text: The input string with nested parentheses and square brackets.
    :param include_nested: Flag to determine if inner nested groups should be included.
    :return: List of extracted bracketed sections.
    """
    def check_bracket_match(open_char, close_char):
        return (open_char == '(' and close_char == ')') or (open_char == '[' and close_char == ']')

    def process_section(text: str, capture_inner: bool) -> List[str]:
        bracket_stack = []
        output_sections = []
        current_buffer = []

        for symbol in text:
            if symbol in '([':
                # Start of a new bracket group
                if not bracket_stack or (bracket_stack and capture_inner):
                    current_buffer.append(symbol)
                bracket_stack.append(symbol)

            elif symbol in ')]':
                if bracket_stack:
                    last_open = bracket_stack.pop()
                    if check_bracket_match(last_open, symbol):
                        current_buffer.append(symbol)
                        # If stack is empty, we've completed a top-level group
                        if not bracket_stack:
                            output_sections.append(''.join(current_buffer))
                            current_buffer = []
                    else:
                        raise ValueError("Mismatched or unbalanced brackets detected")
                else:
                    raise ValueError("Unbalanced closing bracket found")

            elif symbol != ' ':
                # Add non-space characters to the current buffer
                current_buffer.append(symbol)

        # Final validation: ensure no unmatched opening brackets remain
        if bracket_stack:
            raise ValueError("Unbalanced opening brackets remain")

        return output_sections

    # Remove spaces before processing
    normalized_input = input_text.replace(' ', '')
    return process_section(normalized_input, include_nested)

# Example usage:
print(extract_bracket_sections('( ) [( ( ) )] (( )( ))'))
print(extract_bracket_sections('( ) [( ( ) )] (( )( ))', True))

