from rest_framework import serializers
from .models import Book, Page

class PageSerializer(serializers.ModelSerializer):
    class Meta:
        model = Page
        fields = ['id', 'text']

class RequestSerializer(serializers.Serializer):
    book_id = serializers.IntegerField()
    pages = PageSerializer(many=True)

    def save(self, validated_data):
        book_identifier = validated_data['book_id']
        page_list = validated_data['pages']

        # Retrieve or initialize the book record
        book, _ = Book.objects.get_or_create(pk=book_identifier)

        # Process each page in the list
        for page_info in page_list:
            current_page_id = page_info.get('id')
            if current_page_id is not None:
                # Modify existing page entry
                Page.objects.update_or_create(
                    pk=current_page_id, 
                    book=book, 
                    defaults=page_info
                )
            else:
                # Add new page entry
                Page.objects.create(book=book, **page_info)

        return {'book_id': book_identifier, 'pages': page_list}

    def modify(self, instance, validated_data):
        book_identifier = validated_data['book_id']
        page_list = validated_data['pages']

        # Fetch the target book
        book = Book.objects.get(pk=book_identifier)

        # Iterate through pages to update or create
        for page_info in page_list:
            current_page_id = page_info.get('id')
            if current_page_id is not None:
                # Update existing page
                Page.objects.update_or_create(
                    pk=current_page_id, 
                    book=book, 
                    defaults=page_info
                )
            else:
                # Insert new page
                Page.objects.create(book=book, **page_info)

