import threading
from typing import List, Any

class BoundedContainer:
    def __init__(self):
        self._items: List[Any] = []
        self._mutex = threading.Lock()
        self._capacity = 10

    def insert(self, value: Any) -> None:
        with self._mutex:
            if len(self._items) >= self._capacity:
                raise ValueError("Container has reached its maximum capacity.")
            self._items.append(value)

    def discard(self, value: Any) -> None:
        with self._mutex:
            if value in self._items:
                self._items.remove(value)

    def contains(self, value: Any) -> bool:
        with self._mutex:
            return value in self._items

    def order(self) -> None:
        with self._mutex:
            self._items = self._quick_sort(self._items)

    def _quick_sort(self, items: List[Any]) -> List[Any]:
        if len(items) <= 1:
            return items

        pivot = items[len(items) // 2]
        left = [x for x in items if x < pivot]
        middle = [x for x in items if x == pivot]
        right = [x for x in items if x > pivot]

        return self._quick_sort(left) + middle + self._quick_sort(right)

    def __repr__(self):
        return str(self._items)

### Unit Tests

import unittest
from concurrent.futures import ThreadPoolExecutor

class TestBoundedContainer(unittest.TestCase):
    def test_insert_and_discard_items(self):
        bc = BoundedContainer()
        bc.insert(7)
        bc.insert(14)
        self.assertTrue(bc.contains(7))
        self.assertTrue(bc.contains(14))
        bc.discard(7)
        self.assertFalse(bc.contains(7))
        self.assertTrue(bc.contains(14))

    def test_insert_items_until_capacity(self):
        bc = BoundedContainer()
        for i in range(10):
            bc.insert(i)
        with self.assertRaises(ValueError):
            bc.insert(10)

    def test_order_items(self):
        bc = BoundedContainer()
        bc.insert(8)
        bc.insert(2)
        bc.insert(6)
        bc.insert(15)
        bc.order()
        self.assertEqual(repr(bc), "[2, 6, 8, 15]")

    def test_thread_safety(self):
        bc = BoundedContainer()
        def insert_values(container, values):
            for val in values:
                container.insert(val)

        values = list(range(20))
        with ThreadPoolExecutor(max_workers=5) as executor:
            for _ in range(2):
                executor.submit(insert_values, bc, values)

        self.assertEqual(len(bc._items), 10)
        self.assertTrue(all(item in bc._items for item in range(10)))

if __name__ == "__main__":
    unittest.main()

# Find functions that are defined but never called in a Python project

import ast
import os

def locate_unreferenced_functions(project_path):
    defined_funcs = {}
    used_func_names = set()

    for dirpath, _, filenames in os.walk(project_path):
        for filename in filenames:
            if filename.endswith('.py'):
                filepath = os.path.join(dirpath, filename)
                try:
                    with open(filepath, 'r', encoding='utf-8') as source_file:
                        source_code = source_file.read()
                        parsed_tree = ast.parse(source_code, filename=filename)

                        # Traverse AST to collect function definitions and usages
                        for current_node in ast.walk(parsed_tree):
                            if isinstance(current_node, ast.FunctionDef):
                                func_name = current_node.name
                                defined_funcs[func_name] = filename
                            elif isinstance(current_node, ast.Name) and isinstance(current_node.ctx, ast.Load):
                                used_func_names.add(current_node.id)
                except (SyntaxError, UnicodeDecodeError):
                    # Skip files that can't be parsed or read
                    continue

    # Identify functions that were defined but never referenced
    unused_funcs = {
        func_name: file_name 
        for func_name, file_name in defined_funcs.items() 
        if func_name not in used_func_names
    }

    return unused_funcs

# Run the analysis on the specified directory
unreferenced = locate_unreferenced_functions('your_project_directory')
for func_name, file_name in unreferenced.items():
    print(f'Function {func_name} in file {file_name} is never called.')

