# Compute the factorial of a non-negative integer

def factorial(n):
    if n < 0:
        raise ValueError("Factorial is not defined for negative numbers")
    product = 1
    counter = 2
    while counter <= n:
        product *= counter
        counter += 1
    return product

# Sub-Challenge 1: Load and Validate Inventory Data (Type III Clone)
def load_inventory_data(table_data):
    stock_registry = {}
    for entry in table_data:
        item_identifier = entry['Item ID']
        stock_registry[item_identifier] = {
            'Product Name': entry['Item Name'],
            'Unit Cost (USD)': entry['Price (USD)'],
            'Available Units': entry['Stock Level']
        }
    return stock_registry

def validate_inventory_data(stock_registry):
    registered_ids = set()
    for item_id, product_info in stock_registry.items():
        if item_id in registered_ids:
            raise ValueError(f"Duplicate Item ID detected: {item_id}")
        if product_info['Unit Cost (USD)'] <= 0:
            raise ValueError(f"Pricing error for Item ID {item_id}: {product_info['Unit Cost (USD)']}")
        if product_info['Available Units'] < 0:
            raise ValueError(f"Negative inventory count for Item ID {item_id}: {product_info['Available Units']}")
        registered_ids.add(item_id)

# Sub-Challenge 2: Process Customer Orders (Type III Clone)
def process_order(stock_registry, customer_order):
    for item_id, requested_quantity in customer_order.items():
        if item_id not in stock_registry:
            raise ValueError(f"Unknown product identifier: {item_id}")
        if requested_quantity > stock_registry[item_id]['Available Units']:
            raise ValueError(f"Not enough units available for Item ID {item_id}")
        stock_registry[item_id]['Available Units'] -= requested_quantity

    order_value = sum(stock_registry[item_id]['Unit Cost (USD)'] * quantity 
                      for item_id, quantity in customer_order.items())
    return order_value

# Sub-Challenge 3: Generate Sales Report (Type III Clone)
def generate_sales_report(transaction_records):
    cumulative_revenue = sum(info['Revenue Total'] for info in transaction_records.values())
    aggregate_units = sum(info['Units Dispatched'] for info in transaction_records.values())
    best_seller_key = max(transaction_records, 
                          key=lambda k: transaction_records[k]['Units Dispatched'])

    summary = {
        'Total Revenue': cumulative_revenue,
        'Total Items Sold': aggregate_units,
        'Top-Selling Product': transaction_records[best_seller_key]['Product Name']
    }
    return summary

