# Student Management System with indexing capabilities

class PersonRecord:
    def __init__(self, identifier, name, years, scores, extracurriculars):
        self.identifier = identifier
        self.name = name
        self.years = years
        self.scores = scores
        self.extracurriculars = extracurriculars

class EnrollmentManager:
    def __init__(self):
        self.records = []
        self.age_map = {}
        self.score_range_map = {}
        self.activity_map = {}

    def enroll(self, identifier, name, years, scores, extracurriculars):
        record = PersonRecord(identifier, name, years, scores, extracurriculars)
        self.records.append(record)
        self._refresh_indices(record, mode='insert')

    def modify_record(self, identifier, name=None, years=None, scores=None, extracurriculars=None):
        for record in self.records:
            if record.identifier == identifier:
                if name is not None:
                    record.name = name
                if years is not None:
                    record.years = years
                if scores is not None:
                    record.scores = scores
                if extracurriculars is not None:
                    record.extracurriculars = extracurriculars
                self._refresh_indices(record, mode='update')
                return
        raise ValueError(f"Record with ID {identifier} does not exist")

    def find_by_age(self, years):
        return [record for record in self.records if record.identifier in self.age_map.get(years, [])]

    def find_by_score_band(self, low, high):
        band = (low, high)
        return [record for record in self.records if record.identifier in self.score_range_map.get(band, [])]

    def find_by_activity(self, activity):
        return [record for record in self.records if record.identifier in self.activity_map.get(activity, [])]

    def _refresh_indices(self, record, mode='insert'):
        # Remove old indices first if updating
        if mode == 'update':
            self.age_map[record.years].remove(record.identifier)
            for score in record.scores:
                band = (min(score), max(score))
                self.score_range_map[band].remove(record.identifier)
            for activity in record.extracurriculars:
                self.activity_map[activity].remove(record.identifier)

        # Add new indices
        self.age_map.setdefault(record.years, []).append(record.identifier)
        for score in record.scores:
            band = (min(score), max(score))
            self.score_range_map.setdefault(band, []).append(record.identifier)
        for activity in record.extracurriculars:
            self.activity_map.setdefault(activity, []).append(record.identifier)

# Demonstration
if __name__ == "__main__":
    manager = EnrollmentManager()

    manager.enroll(1, "Alice Smith", 18, [85, 90, 92], ["Chess Club", "Debate Team"])
    manager.enroll(2, "Bob Johnson", 19, [78, 80, 85], ["Chess Club", "Robotics Club"])
    manager.enroll(3, "Charlie Brown", 20, [95, 98, 99], ["Drama Club"])

    print("Students aged 18:")
    for person in manager.find_by_age(18):
        print(person.name)

    print("Students with grades between 80 and 90:")
    for person in manager.find_by_score_band(80, 90):
        print(person.name)

    print("Students in Chess Club:")
    for person in manager.find_by_activity("Chess Club"):
        print(person.name)

    manager.modify_record(1, name="Alice Doe")
    print("Updated students aged 18:")
    for person in manager.find_by_age(18):
