import re
from datetime import datetime, date
from collections import defaultdict
from typing import List, Dict

class Customer:
    def __init__(self, name: str, email: str, phone: str, dob: str, address: str):
        self._name = None
        self._email = None
        self._phone = None
        self._dob = None
        self._address = None
        self.name = name
        self.email = email
        self.phone = phone
        self.dob = dob
        self.address = address

    @property
    def name(self) -> str:
        return self._name

    @name.setter
    def name(self, value: str):
        if not (2 <= len(value) <= 50) or not value.isalpha():
            raise ValueError("Name must be between 2 and 50 characters and contain only letters.")
        self._name = value

    @property
    def email(self) -> str:
        return self._email

    @email.setter
    def email(self, value: str):
        if len(value) > 100 or not re.match(r"[^@]+@[^@]+\.[^@]+", value):
            raise ValueError("Email must be valid and not exceed 100 characters.")
        self._email = value

    @property
    def phone(self) -> str:
        return self._phone

    @phone.setter
    def phone(self, value: str):
        if not re.match(r"^\d{3}-\d{3}-\d{4}$", value):
            raise ValueError("Phone number must be in the format 123-456-7890.")
        self._phone = value

    @property
    def dob(self) -> str:
        return self._dob

    @dob.setter
    def dob(self, value: str):
        try:
            parsed_dob = datetime.strptime(value, '%d/%m/%Y').date()
            if parsed_dob > date.today():
                raise ValueError
        except ValueError:
            raise ValueError("Invalid date of birth or date in the future. Format should be dd/mm/yyyy.")
        self._dob = value

    @property
    def address(self) -> str:
        return self._address

    @address.setter
    def address(self, value: str):
        if len(value) > 200:
            raise ValueError("Address must not exceed 200 characters.")
        self._address = value

    def display_info(self) -> str:
        dob_date = datetime.strptime(self.dob, '%d/%m/%Y').date()
        age_years = (date.today() - dob_date).days // 365
        return f"Name: {self.name}, Email: {self.email}, Phone: {self.phone}, Age: {age_years}, Address: {self.address}"

    @staticmethod
    def sort_customers(customers: List['Customer']) -> List['Customer']:
        def sort_key(customer):
            dob_date = datetime.strptime(customer.dob, '%d/%m/%Y').date()
            days_old = (date.today() - dob_date).days
            return (customer.name, days_old)
        return sorted(customers, key=sort_key)

    @staticmethod
    def filter_customers(customers: List['Customer'], domain: str, min_age: int) -> List['Customer']:
        result = []
        for customer in customers:
            dob_date = datetime.strptime(customer.dob, '%d/%m/%Y').date()
            age_years = (date.today() - dob_date).days // 365
            email_domain = customer.email.split('@')[1]
            if email_domain == domain and age_years > min_age:
                result.append(customer)
        return result

    @staticmethod
    def average_age(customers: List['Customer']) -> float:
        if not customers:
            return 0.0
        total_age = 0
        for customer in customers:
            dob_date = datetime.strptime(customer.dob, '%d/%m/%Y').date()
            age_years = (date.today() - dob_date).days // 365
            total_age += age_years
        return total_age / len(customers)

    @staticmethod
    def group_by_email_domain(customers: List['Customer']) -> Dict[str, List['Customer']]:
        domain_groups = defaultdict(list)
        for customer in customers:
            domain = customer.email.split('@')[1]
            domain_groups[domain].append(customer)
        return dict(domain_groups)

    @staticmethod
    def group_by_name_initial(customers: List['Customer']) -> Dict[str, List['Customer']]:
        initial_groups = defaultdict(list)
        for customer in customers:
            first_char = customer.name[0].upper()
            initial_groups[first_char].append(customer)
        return dict(initial_groups)

# Alternative implementation of a basic sentiment analyzer

class BasicEmotionClassifier:
    def __init__(self):
        # Define positive and negative word sets with different variable names
        self.upbeat_terms = {"good", "great", "excellent", "amazing", "wonderful", "fantastic", "love", "happy", "best", "enjoy"}
        self.downbeat_terms = {"bad", "terrible", "awful", "horrible", "poor", "disappointing", "hate", "sad", "worst", "annoying"}

    def determine_sentiment(self, text):
        # Convert to lowercase and split into words
        tokens = text.lower().split()

        # Count occurrences using different iteration approach
        pos_score = 0
        for term in tokens:
            if term in self.upbeat_terms:
                pos_score += 1

        neg_score = 0
        for term in tokens:
            if term in self.downbeat_terms:
                neg_score += 1

        # Determine overall sentiment based on scores
        if pos_score > neg_score:
            return "Positive"
        elif neg_score > pos_score:
            return "Negative"
        else:
            return "Neutral"

