# Calculate minimum disparity between any two numeric values in a (potentially nested) list

def flatten_list(nested):
    """Recursively yield items from nested lists."""
    for item in nested:
        if isinstance(item, list):
            yield from flatten_list(item)
        else:
            yield item

def to_number(val):
    """Convert various types to numeric (int/float/complex), return None if not convertible."""
    if isinstance(val, bool):
        return 1 if val else 0
    if isinstance(val, str):
        try:
            return int(val)
        except ValueError:
            try:
                return float(val)
            except ValueError:
                return None
    if isinstance(val, (int, float)):
        return val
    if isinstance(val, complex):
        return val
    return None

def smallest_difference(data):
    # Flatten and convert all elements
    processed = [to_number(x) for x in flatten_list(data)]
    valid_nums = [n for n in processed if n is not None]

    # Validate input size
    if len(valid_nums) < 2:
        return "Array should contain at least two numeric elements for comparison."

    # Sort by magnitude for complex numbers, otherwise by value
    def sort_key(x):
        return abs(x) if isinstance(x, complex) else x

    valid_nums.sort(key=sort_key)

    # Find adjacent pair with smallest absolute difference
    min_diff = float('inf')
    best_pair = (None, None)

    for idx in range(len(valid_nums) - 1):
        diff = abs(valid_nums[idx] - valid_nums[idx + 1])
        if diff < min_diff:
            min_diff = diff
            best_pair = (valid_nums[idx], valid_nums[idx + 1])

    return min_diff, best_pair

