# Web crawler to extract image URLs from websites

import scrapy
from scrapy.spiders import CrawlSpider
from scrapy.linkextractors import LinkExtractor
from bs4 import BeautifulSoup

class PictureCrawler(CrawlSpider):
    name = 'photo_extractor'
    allowed_domains = ['example.com']
    start_urls = ['http://example.com']

    custom_settings = {
        'DEPTH_LIMIT': 2,
    }

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.visited_pages = set()

    def parse_start_url(self, response):
        return self._extract_images(response)

    def _extract_images(self, response):
        soup = BeautifulSoup(response.body, 'html.parser')
        found_images = []

        for tag in soup.find_all('img'):
            image_source = tag.get('src')
            if image_source:
                full_url = response.urljoin(image_source)
                found_images.append({
                    'image_url': full_url,
                    'source_page': response.url
                })

        for item in found_images:
            yield item

    def parse(self, response):
        # Process only pages within depth limit
        current_depth = response.meta.get('depth', 0)
        if current_depth <= 1:
            yield from self._extract_images(response)

            # Extract links for further crawling
            extractor = LinkExtractor(allow=(), deny_extensions=[])
            links = extractor.extract_links(response)

            for link in links:
                if link.url not in self.visited_pages:
                    self.visited_pages.add(link.url)
                    yield scrapy.Request(
                        url=link.url,
                        callback=self.parse,
                        meta={'depth': current_depth + 1}
                    )

