from typing import List

def is_prime(n: int) -> bool:
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for divisor in range(3, int(n**0.5) + 1, 2):
        if n % divisor == 0:
            return False
    return True

def find_next_prime(n: int) -> int:
    candidate = n + 1
    while not is_prime(candidate):
        candidate += 1
    return candidate

def generate_fibonacci_sequence(limit: int) -> List[int]:
    fib_sequence = [0, 1]
    while fib_sequence[-1] <= limit:
        fib_sequence.append(fib_sequence[-1] + fib_sequence[-2])
    return fib_sequence

def closest_fibonacci(value: int) -> int:
    fib_list = generate_fibonacci_sequence(100)
    # Find insertion point using linear search instead of bisect
    prev_fib = fib_list[0]
    for fib in fib_list[1:]:
        if fib >= value:
            if value - prev_fib <= fib - value:
                return prev_fib
            else:
                return fib
        prev_fib = fib
    return prev_fib

def flip_character_case(char: str) -> str:
    if 'a' <= char <= 'z':
        return chr(ord(char) - 32)  # Convert lowercase to uppercase
    elif 'A' <= char <= 'Z':
        return chr(ord(char) + 32)  # Convert uppercase to lowercase
    return char

def transform_text(text: str) -> str:
    # Phase 1: Invert letter cases
    inverted_text = ''.join(flip_character_case(ch) for ch in text)

    # Phase 2: Replace odd digits with nearest Fibonacci number
    transformed_digits = ''
    for char in inverted_text:
        if char.isdigit() and int(char) % 2 == 1:
            transformed_digits += str(closest_fibonacci(int(char)))
        else:
            transformed_digits += char

    # Phase 3: Duplicate non-alphanumeric characters according to next prime
    non_alnum_chars = [ch for ch in transformed_digits if not ch.isalnum()]
    duplication_factor = find_next_prime(len(non_alnum_chars))
    duplicated_text = ''
    for char in transformed_digits:
        if not char.isalnum():
            duplicated_text += char * duplication_factor
        else:
            duplicated_text += char

    # Phase 4: Sort characters using BST-based approach
    class BSTNode:
        def __init__(self, ascii_value):
            self.value = ascii_value
            self.left_child = None
            self.right_child = None

    def add_to_bst(node, ascii_code):
        if node is None:
            return BSTNode(ascii_code)
        if ascii_code < node.value:
            node.left_child = add_to_bst(node.left_child, ascii_code)
        else:
            node.right_child = add_to_bst(node.right_child, ascii_code)
        return node

    def collect_sorted_values(node):
        result = []
        if node:
            result.extend(collect_sorted_values(node.left_child))
            result.append(node.value)
            result.extend(collect_sorted_values(node.right_child))
        return result

    bst_root = None
    for character in duplicated_text:
        bst_root = add_to_bst(bst_root, ord(character))

    sorted_ascii_codes = collect_sorted_values(bst_root)
    final_output = ''.join(chr(code) for code in sorted_ascii_codes)

    return final_output

# Example usage
print(transform_text('Greet5!'))

# Vector2D class implementation with alternative logic and structure

import math

class Vector2D:
    def __init__(self, x_val: float, y_val: float):
        self.x_coord = round(x_val, 6)
        self.y_coord = round(y_val, 6)

    def get_x_component(self) -> float:
        return self.x_coord

    def get_y_component(self) -> float:
        return self.y_coord

    def length(self) -> float:
        squared_sum = self.x_coord * self.x_coord + self.y_coord * self.y_coord
        return round(math.sqrt(squared_sum), 6)

    def sum_with(self, vector: 'Vector2D') -> 'Vector2D':
        return Vector2D(self.x_coord + vector.x_coord, self.y_coord + vector.y_coord)

    def diff_from(self, vector: 'Vector2D') -> 'Vector2D':
        return Vector2D(self.x_coord - vector.x_coord, self.y_coord - vector.y_coord)

    def scale_by(self, factor: float) -> 'Vector2D':
        return Vector2D(self.x_coord * factor, self.y_coord * factor)

    def inner_product(self, vector: 'Vector2D') -> float:
        return round(self.x_coord * vector.x_coord + self.y_coord * vector.y_coord, 6)

    def pseudo_cross(self, vector: 'Vector2D') -> float:
        # In 2D, the cross product magnitude is x1*y2 - y1*x2
        return round(self.x_coord * vector.y_coord - self.y_coord * vector.x_coord, 6)

    def unit_vector(self) -> 'Vector2D':
        len_val = self.length()
        if len_val == 0:
            return Vector2D(0, 0)
        return Vector2D(self.x_coord / len_val, self.y_coord / len_val)

    def separation_from(self, vector: 'Vector2D') -> float:
        dx = self.x_coord - vector.x_coord
        dy = self.y_coord - vector.y_coord
        return round(math.sqrt(dx*dx + dy*dy), 6)

    def angle_between(self, vector: 'Vector2D') -> float:
        dot_prod = self.inner_product(vector)
        len_self = self.length()
        len_other = vector.length()
        if len_self == 0 or len_other == 0:
            return 0.0
        cos_angle = dot_prod / (len_self * len_other)
        # Clamp value to [-1, 1] to avoid floating point errors in acos
        cos_angle = max(-1.0, min(1.0, cos_angle))
        return round(math.degrees(math.acos(cos_angle)), 6)

    def rotated(self, degrees: float) -> 'Vector2D':
        radians = math.radians(degrees)
        cos_val = math.cos(radians)
        sin_val = math.sin(radians)
        new_x = self.x_coord * cos_val - self.y_coord * sin_val
        new_y = self.x_coord * sin_val + self.y_coord * cos_val
        return Vector2D(new_x, new_y)

    def projection_on(self, vector: 'Vector2D') -> 'Vector2D':
        dot_val = self.inner_product(vector)
        mag_sq = vector.length() ** 2
        if mag_sq == 0:
            return Vector2D(0, 0)
        scalar = dot_val / mag_sq
        return vector.scale_by(scalar)

    def parallel_to(self, vector: 'Vector2D') -> bool:
        return abs(self.pseudo_cross(vector)) < 1e-10

    def perpendicular_to(self, vector: 'Vector2D') -> bool:
        return abs(self.inner_product(vector)) < 1e-10

# Example usage
v1 = Vector2D(2, 3)
v2 = Vector2D(4, -1)

