# Type III Clone: BST with equivalent functionality but different implementation style

class TreeNode:
    def __init__(self, value):
        self.value = value
        self.left_child = None
        self.right_child = None

class BinarySearchTree:
    def __init__(self):
        self.head = None

    def add(self, val):
        self.head = self._add_node(self.head, val)

    def _add_node(self, current, val):
        if current is None:
            return TreeNode(val)
        if val < current.value:
            current.left_child = self._add_node(current.left_child, val)
        else:
            current.right_child = self._add_node(current.right_child, val)
        return current

    def remove(self, val):
        self.head = self._remove_node(self.head, val)

    def _remove_node(self, current, val):
        if current is None:
            return None
        if val < current.value:
            current.left_child = self._remove_node(current.left_child, val)
        elif val > current.value:
            current.right_child = self._remove_node(current.right_child, val)
        else:
            # Node to delete found
            if current.left_child is None:
                return current.right_child
            elif current.right_child is None:
                return current.left_child

            # Find in-order successor (smallest in right subtree)
            successor = self._find_smallest(current.right_child)
            current.value = successor.value
            current.right_child = self._remove_node(current.right_child, successor.value)
        return current

    def find(self, val):
        return self._search_node(self.head, val)

    def _search_node(self, current, val):
        if current is None or current.value == val:
            return current
        if val < current.value:
            return self._search_node(current.left_child, val)
        return self._search_node(current.right_child, val)

    def minimum(self):
        return self._locate_minimum(self.head)

    def _locate_minimum(self, current):
        if current is None:
            return None
        while current.left_child is not None:
            current = current.left_child
        return current

    def maximum(self):
        return self._locate_maximum(self.head)

    def _locate_maximum(self, current):
        if current is None:
            return None
        while current.right_child is not None:
            current = current.right_child
        return current

    def get_kth_element(self, k):
        result = [None]
        count = [0]
        self._kth_inorder(self.head, k, count, result)
        return result[0]

    def _kth_inorder(self, current, k, counter, result):
        if current is None or result[0] is not None:
            return
        self._kth_inorder(current.left_child, k, counter, result)
        counter[0] += 1
        if counter[0] == k and result[0] is None:
            result[0] = current
            return
        self._kth_inorder(current.right_child, k, counter, result)

    def depth(self):
        return self._calculate_depth(self.head)

    def _calculate_depth(self, current):
        if current is None:
            return 0
        left_depth = self._calculate_depth(current.left_child)
        right_depth = self._calculate_depth(current.right_child)
        return 1 + max(left_depth, right_depth)

    def balanced_check(self):
        return self._check_balance(self.head) != -1

    def _check_balance(self, current):
        if current is None:
            return 0

        left_height = self._check_balance(current.left_child)
        if left_height == -1:
            return -1

        right_height = self._check_balance(current.right_child)
        if right_height == -1:
            return -1

        if abs(left_height - right_height) > 1:
            return -1

        return 1 + max(left_height, right_height)

    def common_ancestor(self, val1, val2):
        return self._find_common_ancestor(self.head, val1, val2)

    def _find_common_ancestor(self, current, val1, val2):
        if current is None:
            return None

        # If both values are smaller, go left
        if val1 < current.value and val2 < current.value:
            return self._find_common_ancestor(current.left_child, val1, val2)

        # If both values are larger, go right
        if val1 > current.value and val2 > current.value:
            return self._find_common_ancestor(current.right_child, val1, val2)

        # Found the split point or exact match
        return current

    def breadth_first_print(self):
        if self.head is None:
            return

        queue = [self.head]
        while queue:
            level_values = []
            next_queue = []

            for node in queue:
                level_values.append(node.value)
                if node.left_child:
                    next_queue.append(node.left_child)
                if node.right_child:
                    next_queue.append(node.right_child)

            print(level_values)
            queue = next_queue

