# Abstract base class for watercraft
from abc import ABC, abstractmethod
from datetime import datetime, timedelta

class Watercraft(ABC):
    def __init__(self, vessel_name, hull_length, max_passengers):
        self.vessel_name = vessel_name
        self.hull_length = hull_length
        self.max_passengers = max_passengers

    def secure_anchor(self):
        current_timestamp = datetime.now().strftime("%H:%M:%S")
        print(f"Watercraft {self.vessel_name} is secured with anchor at {current_timestamp}")

    def navigate_to(self, target_port, nautical_miles):
        # Assuming constant cruising speed of 10 nautical miles per hour
        cruising_speed = 10  # knots
        travel_duration = nautical_miles / cruising_speed
        arrival_time = datetime.now() + timedelta(hours=travel_duration)
        arrival_formatted = arrival_time.strftime("%H:%M:%S")
        print(f"Watercraft {self.vessel_name} is navigating to {target_port} and预计 arrives at {arrival_formatted}")

    @abstractmethod
    def unique_capability(self):
        pass

class PowerBoat(Watercraft):
    def __init__(self, vessel_name, hull_length, max_passengers, fuel_tank_size, motor_output):
        super().__init__(vessel_name, hull_length, max_passengers)
        self.fuel_tank_size = fuel_tank_size
        self.motor_output = motor_output

    def ignite_motor(self):
