    def replenish_fuel(self, quantity):
        if quantity > 0:
            self.fuel_tank_size += quantity
            print(f"PowerBoat {self.vessel_name} replenished with {quantity} liters. Current fuel level: {self.fuel_tank_size} liters")
        else:
            print("Fuel quantity must be positive")

    def unique_capability(self):
        print(f"PowerBoat {self.vessel_name} features a motor delivering {self.motor_output} HP and a fuel tank capacity of {self.fuel_tank_size} liters")

