# Custom sorting and shifting logic for mixed-type lists

def custom_compare(a, b):
    # Determine type priority: int/float/complex < str < list < dict < tuple < set < frozenset
    def get_type_priority(val):
        if isinstance(val, (int, float, complex)):
            return 0
        elif isinstance(val, str):
            return 1
        elif isinstance(val, list):
            return 2
        elif isinstance(val, dict):
            return 3
        elif isinstance(val, tuple):
            return 4
        elif isinstance(val, set):
            return 5
        elif isinstance(val, frozenset):
            return 6
        else:
            return -1

    type_a = get_type_priority(a)
    type_b = get_type_priority(b)

    # If types are different, sort by type priority
    if type_a != type_b:
        return type_a - type_b

    # Same type comparisons
    if isinstance(a, (int, float, complex)) and isinstance(b, (int, float, complex)):
        return a - b
    elif isinstance(a, str) and isinstance(b, str):
        return (a > b) - (a < b)
    elif isinstance(a, list) and isinstance(b, list):
        return sum(a) - sum(b)
    elif isinstance(a, dict) and isinstance(b, dict):
        return sum(a.values()) - sum(b.values())
    elif isinstance(a, tuple) and isinstance(b, tuple) and len(a) > 0 and len(b) > 0:
        return a[0] - b[0]
    elif isinstance(a, set) and isinstance(b, set):
        return len(a) - len(b)
    elif isinstance(a, frozenset) and isinstance(b, frozenset):
        return len(a) - len(b)
    else:
        return 0

def rotate_and_order(data, steps):
    size = len(data)
    if size == 0:
        return data

    # Normalize rotation count
    rotation = steps % size
    if rotation == 0:
        return data

    # Perform left rotation
    rotated = data[rotation:] + data[:rotation]

    # Sort elements after the rotation point using custom comparison
    from functools import cmp_to_key
    sorted_part = sorted(rotated[rotation:], key=cmp_to_key(custom_compare))

    return rotated[:rotation] + sorted_part

# Example usage with mixed data types
mixed_data = [1, -3, 2.5, "apple", [1, 2], {"a": 1, "b": 2}, (1, 2), {1, 2}, frozenset([1, 2])]
result = rotate_and_order(mixed_data, 3)
print(result)

