        self.capacity = max_capacity
        self.showings: List['MovieSession'] = []
        self.occupied_seats: Dict[str, bool] = {f"Seat_{i}": False for i in range(1, max_capacity + 1)}

    def schedule_session(self, session: 'MovieSession'):
        self.showings.append(session)

    def list_sessions(self) -> List['MovieSession']:
        return self.showings

    def get_free_seats(self, session: 'MovieSession') -> List[str]:
        return [seat for seat, occupied in self.occupied_seats.items() if not occupied]

class MovieSession:
    def __init__(self, movie: Movie, start_time: datetime, end_time: datetime, auditorium: Auditorium):
        self.movie = movie
        self.start_time = start_time
        self.end_time = end_time
        self.auditorium = auditorium

class Reservation:
    def __init__(self, patron: str, session: MovieSession, selected_seats: List[str]):
        self.patron = patron
        self.session = session
        self.selected_seats = selected_seats

    def finalize_reservation(self):
        for seat in self.selected_seats:
            if seat in self.session.auditorium.occupied_seats and not self.session.auditorium.occupied_seats[seat]:
                self.session.auditorium.occupied_seats[seat] = True
            else:
                raise ValueError(f"Seat {seat} is already reserved or invalid.")

class Multiplex:
    def __init__(self, venue_name: str):
        self.name = venue_name
        self.auditoriums: List[Auditorium] = []

    def register_auditorium(self, auditorium: Auditorium):
        self.auditoriums.append(auditorium)

    def list_auditoriums(self) -> List[Auditorium]:
        return self.auditoriums

