# Calculate total disk usage of a directory tree using parallel processing

import os
from concurrent.futures import ProcessPoolExecutor, as_completed

def calculate_dir_size(directory):
    size = 0
    try:
        with os.scandir(directory) as entries:
            for item in entries:
                try:
                    if item.is_file():
                        size += item.stat().st_size
                    elif item.is_dir():
                        size += calculate_dir_size(item.path)
                except (OSError, PermissionError):
                    continue
    except (OSError, PermissionError):
        pass
    return size

def compute_total_size(root_path, processes=4):
    # Collect all subdirectories first
    subdirs = []
    try:
        for dirpath, dirnames, _ in os.walk(root_path, topdown=True):
            subdirs.extend([os.path.join(dirpath, d) for d in dirnames])
    except (OSError, PermissionError):
        pass

    # Process directories in parallel
    total = 0
    with ProcessPoolExecutor(max_workers=processes) as pool:
        tasks = [pool.submit(calculate_dir_size, subdir) for subdir in subdirs]

        for task in as_completed(tasks):
            try:
                total += task.result()
            except Exception:
                continue

    # Add size of files directly in the root directory
    try:
        with os.scandir(root_path) as items:
            for item in items:
                try:
                    if item.is_file():
                        total += item.stat().st_size
                except (OSError, PermissionError):
                    continue
    except (OSError, PermissionError):
        pass

    return total

if __name__ == "__main__":
    target_directory = "C:\\"
    size_in_bytes = compute_total_size(target_directory)
    print(f"Total size: {size_in_bytes / (1024 ** 3):.2f} GB")

