            f"Time: {item['time_min']} minutes, Cost: ${item['cost_usd']}, Complexity: {item['comp']}")

def arrange_by_complexity(items):
    # Using bubble sort instead of built-in sorted for variation
    n = len(items)
    arr = items.copy()
    for i in range(n):
        for j in range(0, n - i - 1):
            if arr[j]['comp'] > arr[j + 1]['comp']:
                arr[j], arr[j + 1] = arr[j + 1], arr[j]
    return arr

def main():
    items = create_items()
    print("List of 3D Printable Objects (Unsorted):")
    for item in items:
        print(format_item(item))

    print("\nList of 3D Printable Objects (Sorted by Complexity):")
    arranged_items = arrange_by_complexity(items)
    for item in arranged_items:
        print(format_item(item))

