        self.episode_name = ep_title
        self.episode_summary = ep_desc
        self.episode_runtime = ep_length
        self.episode_publish_date = ep_air_date

class ShowManager:
    def __init__(self):
        self.episode_collection = {}
        self.current_episode_counter = 1

    def register_episode(self, title, description, duration, release_date):
        assigned_id = self.current_episode_counter
        created_episode = ShowEpisode(assigned_id, title, description, duration, release_date)
        self.episode_collection[assigned_id] = created_episode
        self.current_episode_counter += 1
        return assigned_id

    def modify_episode(self, episode_id, title=None, description=None, duration=None, release_date=None):
        if episode_id not in self.episode_collection:
            raise ValueError(f"No episode found with ID {episode_id}")

        target_episode = self.episode_collection[episode_id]
        if title is not None:
            target_episode.episode_name = title
        if description is not None:
            target_episode.episode_summary = description
        if duration is not None:
            target_episode.episode_runtime = duration
        if release_date is not None:
