# Find numbers that are both perfect cubes and factorials

def is_cube_number(x):
    """Determine if a number is a perfect cube using integer approximation."""
    if x < 0:
        return False
    root = round(x ** (1/3))
    return root ** 3 == x

def is_factorial_number(value):
    """Check whether the given value equals some factorial."""
    if value == 1:
        return True

    current_product = 1
    multiplier = 2

    while current_product < value:
        current_product *= multiplier
        multiplier += 1

    return current_product == value

def generate_special_numbers(limit):
    """Yield the first 'limit' integers that satisfy both conditions."""
    if not isinstance(limit, int) or limit < 0:
        raise ValueError("Limit must be a non-negative integer.")

    found = 0
    candidate = 1

    while found < limit:
        if is_cube_number(candidate) and is_factorial_number(candidate):
            yield candidate
            found += 1
        candidate += 1

# Demonstration of functionality
try:
    count = 5
    for result in generate_special_numbers(count):
        print(result)
except ValueError as error_message:
    print(error_message)

# Custom HTTP server implementation handling GET and POST requests

from http.server import BaseHTTPRequestHandler, HTTPServer

class CustomRequestHandler(BaseHTTPRequestHandler):
    def handle_get_request(self):
        if self.path == '/':
            self._send_response(200, b'Hello, World!')
        elif self.path == '/about':
            self._send_response(200, b'This is the about page.')
        else:
            self._send_response(404, b'404 Not Found')

    def _send_response(self, status_code, content):
        self.send_response(status_code)
        self.send_header('Content-type', 'text/html')
        self.end_headers()
        self.wfile.write(content)

    def do_GET(self):
        self.handle_get_request()

    def do_POST(self):
        content_length = int(self.headers['Content-Length'])
        post_data = self.rfile.read(content_length)
        response_content = b'Post data received: ' + post_data
        self._send_response(200, response_content)

def start_server(server_class=HTTPServer, handler_class=CustomRequestHandler, port=8000):
    server_address = ('', port)
    httpd = server_class(server_address, handler_class)
    print(f'Starting custom HTTP server on port {port}...')
    httpd.serve_forever()

if __name__ == '__main__':
    start_server()

# Alternative implementation to find a mathematical expression that evaluates to the target

import itertools
import math
from typing import List, Tuple, Optional

def find_expression(values: List[int], goal: int, permit_repeats: bool) -> Tuple[str, int]:
    def safe_eval(expr: str) -> float:
        try:
            return eval(expr)
        except ZeroDivisionError:
            return float('inf')
        except (ValueError, SyntaxError, TypeError):
            return float('nan')

    def check_validity(expr: str) -> bool:
        try:
            eval(expr)
            return True
        except:
            return False

    def construct_expressions(nums: List[int], goal: int, depth_limit: int) -> Tuple[str, int]:
        if not nums:
            return "", -1

        # Generate unique permutations if duplicates are not allowed
        perms = list(itertools.permutations(nums))
        if not permit_repeats:
            unique_perms = set()
            for p in perms:
                unique_perms.add(p)
            perms = list(unique_perms)

        # Available operations including exponentiation and logarithm
        ops = ['+', '-', '*', '/', '**', 'math.log']

        for sequence in perms:
            for step_count in range(1, depth_limit + 1):
                for combo in itertools.product(ops, repeat=step_count):
                    current_expr = str(sequence[0])
                    consumed = 1
                    valid = True

                    for j, operator in enumerate(combo):
                        if consumed >= len(sequence):
                            break

                        if operator == 'math.log':
                            base_val = sequence[consumed]
                            if base_val > 0 and base_val != 1:
                                current_expr += f" {operator}({base_val})"
                                consumed += 1
                            else:
                                valid = False
                                break
                        else:
                            current_expr += f" {operator} {sequence[consumed]}"
                            consumed += 1

                    if not valid:
                        continue

                    if check_validity(current_expr):
                        value = safe_eval(current_expr)
                        if math.isclose(value, goal, rel_tol=1e-9):
                            return current_expr, step_count

        return "", -1

    # Limit search depth to prevent excessive computation
    max_depth = 5
    expr_str, count = construct_expressions(values, goal, max_depth)
    return expr_str, count

# Demonstration usage
