# Implementation of a circular singly linked list with insert and display operations

class ListNode:
    def __init__(self, value):
        self.value = value
        self.link = None

class CircularList:
    def __init__(self):
        self.start = None

    def add(self, value):
        new_item = ListNode(value)
        if self.start is None:
            self.start = new_item
            new_item.link = self.start
        else:
            current = self.start
            while current.link != self.start:
                current = current.link
            current.link = new_item
            new_item.link = self.start

    def insert_at(self, value, index):
        if index < 0:
            raise Exception("Index must be non-negative")

        new_node = ListNode(value)
        if index == 0:
            if self.start is None:
                self.start = new_node
                new_node.link = self.start
            else:
                last = self.start
                while last.link != self.start:
                    last = last.link
                last.link = new_node
                new_node.link = self.start
                self.start = new_node
        else:
            current = self.start
            position = 0
            while current and position < index - 1:
                current = current.link
                position += 1
            if current is None:
                raise IndexError("Index out of bounds")
            new_node.link = current.link
            current.link = new_node

    def show(self):
        if self.start is None:
            return "List is empty"
        elements = []
        current = self.start
        while True:
            elements.append(str(current.value))
            current = current.link
            if current == self.start:
                break
        return " -> ".join(elements) + " -> " + str(self.start.value)

# Build the circular list and insert "Hello" at index 2
circular_list = CircularList()
circular_list.add(1)
circular_list.add(2)
circular_list.add(3)
circular_list.add(4)
circular_list.add(5)
circular_list.insert_at("Hello", 2)
print(circular_list.show())  # Output: 1 -> 2 -> Hello -> 3 -> 4 -> 5 -> 1

# Vector operations implementation using different approach

from typing import List, TypeVar, Generic
import math

T = TypeVar('T', bound=float)

class Vector(Generic[T]):
    def __init__(self, items: List[T]):
        self.data = items

    def size(self) -> int:
        return len(self.data)

    def __repr__(self):
        return f"Vector({self.data})"

    def add(self, other: 'Vector[T]') -> 'Vector[T]':
        if self.size() != other.size():
            raise ValueError("Vectors must be of the same length for addition.")
        result = []
        for i in range(self.size()):
            result.append(self.data[i] + other.data[i])
        return Vector(result)

    def subtract(self, other: 'Vector[T]') -> 'Vector[T]':
        if self.size() != other.size():
            raise ValueError("Vectors must be of the same length for subtraction.")
        result = []
        for i in range(self.size()):
            result.append(self.data[i] - other.data[i])
        return Vector(result)

    def scale(self, factor: T) -> 'Vector[T]':
        result = []
        for value in self.data:
            result.append(value * factor)
        return Vector(result)

    def inner_product(self, other: 'Vector[T]') -> T:
        if self.size() != other.size():
            raise ValueError("Vectors must be of the same length for dot product.")
        total = 0
        for i in range(self.size()):
            total += self.data[i] * other.data[i]
        return total

    def vector_product(self, other: 'Vector[T]') -> 'Vector[T]':
        if self.size() != 3 or other.size() != 3:
            raise ValueError("Cross product is only defined for 3-dimensional vectors.")
        x1, y1, z1 = self.data
        x2, y2, z2 = other.data
        return Vector([
            y1 * z2 - z1 * y2,
            z1 * x2 - x1 * z2,
            x1 * y2 - y1 * x2
        ])

    def length(self) -> T:
        squared_sum = 0
        for value in self.data:
            squared_sum += value * value
        return math.sqrt(squared_sum)

    def unit(self) -> 'Vector[T]':
        norm = self.length()
        if norm == 0:
            raise ValueError("Cannot normalize a zero vector.")
        result = []
        for value in self.data:
            result.append(value / norm)
        return Vector(result)

    def angle_between(self, other: 'Vector[T]') -> float:
        if self.size() != other.size():
            raise ValueError("Vectors must be of the same length to calculate the angle.")
        dot = self.inner_product(other)
        len_self = self.length()
        len_other = other.length()
        if len_self == 0 or len_other == 0:
            raise ValueError("Cannot calculate the angle with zero vector.")
        return math.acos(dot / (len_self * len_other))

    def project_onto(self, other: 'Vector[T]') -> 'Vector[T]':
        if self.size() != other.size():
            raise ValueError("Vectors must be of the same length to calculate the projection.")
        dot_product = self.inner_product(other)
        other_length_squared = other.length() ** 2
        if other_length_squared == 0:
            raise ValueError("Cannot project onto a zero vector.")
        coefficient = dot_product / other_length_squared
        return other.scale(coefficient)

# Example usage:
v1 = Vector([1, 2, 3])
v2 = Vector([4, 5, 6])

print(v1.add(v2))      # Vector([5, 7, 9])
print(v1.subtract(v2)) # Vector([-3, -3, -3])
print(v1.scale(2))     # Vector([2, 4, 6])
print(v1.inner_product(v2))  # 32
print(v1.vector_product(v2)) # Vector([-3, 6, -3])
print(v1.length())       # 3.7416573867739413
print(v1.unit())         # Vector([0.2672612419124244, 0.5345224838248488, 0.8017837257372732])
print(v1.angle_between(v2))  # 0.2257261285527342
print(v1.project_onto(v2))   # Vector([1.7142857142857142, 2.142857142857143, 2.5714285714285716])

