# Refactored version of the tokenizer and parser with equivalent functionality but different implementation approach

import re
from typing import List, Dict, Any

class Lexeme:
    def __init__(self, category: str, content: str):
        self.category = category
        self.content = content

class SyntaxAnalyzer:
    def __init__(self, input_text: str):
        self.input_text = input_text
        self.lexemes = []
        self.index = 0
        self._scan_input()

    def _scan_input(self) -> None:
        # Define token patterns using alternative regex structure
        patterns = [
            (r'\d+\.\d+', 'DECIMAL'),
            (r'\d+', 'INTEGER'),
            (r'[a-zA-Z_][a-zA-Z_0-9]*', 'NAME'),
            (r'[\+\-\*/=\!\&\|\<\>\~\^]', 'SYMBOL'),
            (r'\b(forall|exists)\b', 'BOUNDARY'),
            (r'[\(\)]', 'BRACKET'),
            (r'\s+', 'SPACE'),
        ]

        remaining = self.input_text
        while remaining:
            matched = False
            for pattern, token_type in patterns:
                regex = re.compile(pattern)
                match = regex.match(remaining)
                if match:
                    value = match.group(0)
                    if token_type != 'SPACE':
                        self.lexemes.append(Lexeme(token_type, value))
                    remaining = remaining[len(value):]
                    matched = True
                    break

            if not matched:
                raise ValueError(f"Unrecognized character sequence: {remaining[:10]}")

    def analyze(self) -> Dict[str, Any]:
        return self._process_expression()

    def _process_expression(self) -> Dict[str, Any]:
        if self.index >= len(self.lexemes):
            raise ValueError("Unexpected end of expression")

        current = self.lexemes[self.index]

        if current.category == 'NAME':
            self.index += 1
            return {'category': 'variable', 'content': current.content}

        elif current.category in ('INTEGER', 'DECIMAL'):
            self.index += 1
            return {'category': 'literal', 'content': float(current.content)}

        elif current.category == 'BRACKET' and current.content == '(':
            self.index += 1
            inner = self._process_expression()

            if self.index < len(self.lexemes) and self.lexemes[self.index].category == 'BRACKET' and self.lexemes[self.index].content == ')':
                self.index += 1
                return inner
            else:
                raise ValueError("Mismatched parentheses detected")

        elif current.category == 'SYMBOL':
            self.index += 1
            operand_a = self._process_expression()
            operand_b = self._process_expression()
            return {'category': 'operation', 'operator': current.content, 'left': operand_a, 'right': operand_b}

        elif current.category == 'BOUNDARY':
            self.index += 1
            var_expr = self._process_expression()
            body_expr = self._process_expression()
            return {'category': 'quantification', 'quantifier': current.content, 'parameter': var_expr, 'body': body_expr}

        else:
            raise ValueError(f"Syntax error at token: {current.content}")

#### Step 2: Syntax Checking

# Process SQL file to remove comments and empty lines, preserving multi-line INSERT and CREATE FUNCTION blocks

import re

def is_comment_line(line):
    # Check if line starts with comment marker (--)
    return line.strip().startswith('--')

def is_blank_line(line):
    # Check if line is empty or contains only whitespace
    return len(line.strip()) == 0

def begins_insert_statement(line):
    # Check if line starts an INSERT statement (case-insensitive)
    return line.strip().upper().startswith('INSERT')

def completes_insert_statement(line):
    # Check if line ends an INSERT statement (ends with semicolon)
    return line.strip().upper().endswith(';')

def initiates_function_definition(line):
    # Check if line contains CREATE FUNCTION keyword
    return 'CREATE FUNCTION' in line.upper()

def finishes_function_definition(line, func_depth):
    # Check if current line marks the end of a function block
    if 'END' in line.upper():
        if func_depth:
            func_depth.pop()
    return len(func_depth) == 0

def sanitize_sql(input_path, output_path):
    # Read all lines from input file
    with open(input_path, 'r') as src:
        content = src.readlines()

    # State tracking variables
    inside_multiline_insert = False
    inside_function_block = False
    function_depth = []
    processed_lines = []

    for current_line in content:
        # Detect start of new blocks
        if begins_insert_statement(current_line):
            inside_multiline_insert = True
        if initiates_function_definition(current_line):
            function_depth.append(True)
            inside_function_block = True

        # Decide whether to keep the line: preserve if it's not a comment/blank OR if we're inside special blocks
        if not (is_comment_line(current_line) or is_blank_line(current_line)) or \
           inside_multiline_insert or inside_function_block:
            processed_lines.append(current_line)

        # Detect end of blocks
        if inside_multiline_insert and completes_insert_statement(current_line):
            inside_multiline_insert = False
        if inside_function_block:
            inside_function_block = finishes_function_definition(current_line, function_depth)

    # Write cleaned content to output file
    with open(output_path, 'w') as dst:
        dst.writelines(processed_lines)

# Example usage
input_file = 'file.sql'
output_file = 'cleaned_file.sql'
sanitize_sql(input_file, output_file)

import random
from typing import List

class Solution:
    def __init__(self, nums: List[int]):
        self.nums = nums
        # Store indices grouped by value using a different approach
        self.indices_by_value = {}
        for position, value in enumerate(nums):
            if value not in self.indices_by_value:
                self.indices_by_value[value] = []
            self.indices_by_value[value].append(position)

    def pick(self, target: int, left_bound: int, right_bound: int) -> int:
        # Check if target exists in our mapping
        if target not in self.indices_by_value:
            return -1

        # Filter indices within the specified range using list comprehension
        candidates = []
        for idx in self.indices_by_value[target]:
            if left_bound <= idx <= right_bound:
                candidates.append(idx)

        # Return -1 if no valid candidates found
        if not candidates:
            return -1

        # Since all candidates have equal probability in the original logic,
        # use simple random selection instead of weighted choice
        selection_index = random.randint(0, len(candidates) - 1)
        return candidates[selection_index]

# Example usage:
solution = Solution([1, 2, 3, 3, 3])
print(solution.pick(3, 1, 4))  # Output: 2, 3, or 4 with equal probability
print(solution.pick(1, 0, 1))  # Output: 0
print(solution.pick(3, 2, 4))  # Output: 2, 3, or 4 with equal probability

# Define a class to represent a person with name, age, and title information

class Individual:
    def __init__(self, full_name, years, title=None):
        self.full_name = full_name
        self.years = 0
        self.assign_years(years)
        self.title = self.resolve_title(title)

    def resolve_title(self, title):
        valid_titles = ["Mr.", "Mrs.", "Miss", "Dr.", "Ms."]
        if title in valid_titles:
            return title
        else:
            return "Mr."  # Default fallback title

    def assign_years(self, years):
        if isinstance(years, int) and years > 0:
            self.years = years
        else:
            raise ValueError("Years must be a positive integer")

    def check_leap_year(self, year):
        if (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0):
            return True
        return False

    def create_narrative(self, present_year):
        if self.years == 0:
            raise ValueError("Years have not been assigned")

        birth_year = present_year - self.years
        leap_indicator = " (a leap year)" if self.check_leap_year(birth_year) else ""

        return f"{self.title} {self.full_name} is {self.years} years old, born in {birth_year}{leap_indicator}."

