# User management system with basic CRUD operations

class UserManagement:
    def __init__(self):
        self.user_records = {}

    def add_user(self, identifier, full_name):
        if identifier in self.user_records:
            return f"An entry for user ID {identifier} is already present."
        self.user_records[identifier] = full_name
        return f"New user with ID {identifier} has been added."

    def get_user(self, identifier):
        if identifier in self.user_records:
            return f"User ID: {identifier}, Full Name: {self.user_records[identifier]}"
        return f"No record found for user ID {identifier}."

    def modify_user(self, identifier, updated_name):
        if identifier in self.user_records:
            self.user_records[identifier] = updated_name
            return f"User ID {identifier} has been updated successfully."
        return f"Cannot update: no record exists for user ID {identifier}."

    def remove_user(self, identifier):
        if identifier in self.user_records:
            del self.user_records[identifier]
            return f"User ID {identifier} has been removed successfully."
        return f"Removal failed: user ID {identifier} not found."

    def display_all(self):
        if len(self.user_records) == 0:
            return "The system contains no user records."
        return "\n".join([f"User ID: {uid}, Name: {name}" for uid, name in self.user_records.items()])


