# Volume calculator for geometric shapes with comparison and subtraction capabilities

import math

class GeometricVolume:
    def __init__(self, shape_name, *measurements):
        self.shape_name = shape_name.lower()
        self.measurements = measurements
        self.volume_value = self.compute_volume()

    def compute_volume(self):
        if self.shape_name == 'sphere':
            if len(self.measurements) != 1 or self.measurements[0] <= 0:
                raise ValueError("Sphere needs a positive radius value.")
            r = self.measurements[0]
            return (4.0/3.0) * math.pi * (r ** 3)

        elif self.shape_name == 'cylinder':
            if len(self.measurements) != 2 or any(m <= 0 for m in self.measurements):
                raise ValueError("Cylinder requires positive radius and height values.")
            r, h = self.measurements
            return math.pi * (r ** 2) * h

        elif self.shape_name == 'cone':
            if len(self.measurements) != 2 or any(m <= 0 for m in self.measurements):
                raise ValueError("Cone requires positive radius and height values.")
            r, h = self.measurements
            return (1.0/3.0) * math.pi * (r ** 2) * h

        elif self.shape_name == 'cube':
            if len(self.measurements) != 1 or self.measurements[0] <= 0:
                raise ValueError("Cube requires a positive side length value.")
            s = self.measurements[0]
            return s ** 3

        elif self.shape_name == 'rectangular_prism':
            if len(self.measurements) != 3 or any(m <= 0 for m in self.measurements):
                raise ValueError("Rectangular prism requires positive length, width, and height values.")
            l, w, h = self.measurements
            return l * w * h

        elif self.shape_name == 'square_pyramid':
            if len(self.measurements) != 3 or any(m <= 0 for m in self.measurements):
                raise ValueError("Square pyramid requires positive base length, base width, and height values.")
            b_l, b_w, h = self.measurements
            return (1.0/3.0) * b_l * b_w * h

        else:
            raise ValueError("Unsupported geometric shape.")

    def compare_with(self, other_shape):
        if not isinstance(other_shape, GeometricVolume):
            raise TypeError("Comparison must be between two GeometricVolume instances.")
        if self.shape_name != other_shape.shape_name:
            raise ValueError("Can only compare volumes of identical shape types.")

        if self.volume_value > other_shape.volume_value:
            diff_percent = ((self.volume_value - other_shape.volume_value) / other_shape.volume_value) * 100
            return f"The {self.shape_name} has a larger volume by {diff_percent:.2f}%."
        elif self.volume_value < other_shape.volume_value:
            diff_percent = ((other_shape.volume_value - self.volume_value) / self.volume_value) * 100
            return f"The {other_shape.shape_name} has a larger volume by {diff_percent:.2f}%."
        else:
            return f"Both {self.shape_name}s have equal volumes of {self.volume_value}."

    def difference_from(self, other_shape):
        if not isinstance(other_shape, GeometricVolume):
            raise TypeError("Subtraction must be between two GeometricVolume instances.")
        if self.shape_name != other_shape.shape_name:
            raise ValueError("Can only subtract volumes of identical shape types.")

        if self.volume_value < other_shape.volume_value:
            raise ValueError("Cannot subtract a larger volume from a smaller one.")

        return self.volume_value - other_shape.volume_value

# Demonstration section
if __name__ == "__main__":
    try:
        # Sphere examples
        sphere_a = GeometricVolume('sphere', 5)
        sphere_b = GeometricVolume('sphere', 3)
        print(sphere_a.compare_with(sphere_b))
        print(sphere_a.difference_from(sphere_b))

        # Cylinder examples
        cyl_a = GeometricVolume('cylinder', 2, 10)
        cyl_b = GeometricVolume('cylinder', 2, 5)
        print(cyl_a.compare_with(cyl_b))
        print(cyl_a.difference_from(cyl_b))

        # Cone examples
        cone_a = GeometricVolume('cone', 4, 12)
        cone_b = GeometricVolume('cone', 4, 8)
        print(cone_a.compare_with(cone_b))
        print(cone_a.difference_from(cone_b))

        # Cube examples
        cube_a = GeometricVolume('cube', 4)
        cube_b = GeometricVolume('cube', 2)
        print(cube_a.compare_with(cube_b))
        print(cube_a.difference_from(cube_b))

        # Rectangular prism examples
        rect_a = GeometricVolume('rectangular_prism', 3, 4, 5)
        rect_b = GeometricVolume('rectangular_prism', 2, 2, 2)
        print(rect_a.compare_with(rect_b))
        print(rect_a.difference_from(rect_b))

        # Square pyramid examples
        pyr_a = GeometricVolume('square_pyramid', 6, 6, 6)
        pyr_b = GeometricVolume('square_pyramid', 3, 3, 3)
        print(pyr_a.compare_with(pyr_b))
        print(pyr_a.difference_from(pyr_b))

        # Error handling demonstration
