from typing import Any, Text, Dict, List
from rasa_sdk import Action, Tracker
from rasa_sdk.executor import CollectingDispatcher
import requests

class ActionFetchMovieDetails(Action):
    def name(self) -> Text:
        return "action_fetch_movie_details"

    def run(self, dispatcher: CollectingDispatcher,
            tracker: Tracker,
            domain: Dict[Text, Any]) -> List[Dict[Text, Any]]:

        film_title = tracker.get_slot("movie_title")
        api_response = requests.get(f"https://api.example.com/movies/{film_title}")
        movie_info = api_response.json()

        if movie_info:
            description = movie_info.get("overview", "No description provided.")
            dispatcher.utter_message(text=f"Overview for '{film_title}': {description}")
        else:
            dispatcher.utter_message(text="I couldn't locate a movie with that title. Please check the spelling or try another title.")

        return []

