import re

def load_file_content(file_path):
    try:
        with open(file_path, 'r') as f:
            return f.readlines()
    except FileNotFoundError:
        print(f"Error: File '{file_path}' does not exist.")
        return None
    except IOError as e:
        print(f"Error reading file: {e}")
        return None

def locate_function_invocations(code_lines, target_func):
    found_calls = []
    for idx, code_line in enumerate(code_lines, start=1):
        if re.search(rf'\b{target_func}\s*\(', code_line):
            found_calls.append((idx, code_line.strip()))
    return found_calls

def validate_object_access(line_text, local_vars, borrowed_refs):
    # Verify if the object is locally instantiated
    for var in local_vars:
        if var in line_text:
            return True

    # Verify if the object's reference is explicitly retained
    for ref_var in borrowed_refs:
        if ref_var in line_text:
            return True

    return False

def analyze_json_usage(input_file):
    content = load_file_content(input_file)
    if content is None:
        return

    declared_objects = []
    referenced_objects = []

    # Identify all json_object creation and reference patterns
    for line in content:
        if re.search(r'\bj\s*=\s*json_object_new\s*\(', line):
            declared_objects.append('j')

        if re.search(r'\bj\s*=\s*json_object_get\s*\(', line):
            referenced_objects.append('j')

    # Locate all json_object_object_add and json_object_array_add calls
    obj_add_calls = locate_function_invocations(content, 'json_object_object_add')
    arr_add_calls = locate_function_invocations(content, 'json_object_array_add')

    combined_calls = obj_add_calls + arr_add_calls

    for line_num, line_content in combined_calls:
        if not validate_object_access(line_content, declared_objects, referenced_objects):
            print(f"Warning: Potentially unsafe object usage at line {line_num}: {line_content}")

if __name__ == "__main__":
    target_file = 'example.c'  # Update this path to your C source file
    analyze_json_usage(target_file)

# Custom implementation of a singly linked list with similar functionality

class ListNode:
    def __init__(self, value):
        self.value = value
        self.next_node = None

class SinglyLinkedList:
    def __init__(self):
        self.start_node = None

    def add_to_end(self, value):
        new_node = ListNode(value)
        if self.start_node is None:
            self.start_node = new_node
        else:
            current_node = self.start_node
            while current_node.next_node is not None:
                current_node = current_node.next_node
            current_node.next_node = new_node

    def print_list(self):
        current_node = self.start_node
        while current_node is not None:
            print(current_node.value, end=" -> ")
            current_node = current_node.next_node
        print("None")

    def add_to_front(self, value):
        new_node = ListNode(value)
        new_node.next_node = self.start_node
        self.start_node = new_node

    def remove_value(self, target):
        current_node = self.start_node
        if current_node and current_node.value == target:
            self.start_node = current_node.next_node
            current_node = None
            return
        previous_node = None
        while current_node and current_node.value != target:
            previous_node = current_node
            current_node = current_node.next_node
        if current_node is None:
            return
        previous_node.next_node = current_node.next_node
        current_node = None

# Demonstration
if __name__ == "__main__":
    my_list = SinglyLinkedList()
    my_list.add_to_end(1)
    my_list.add_to_end(2)
    my_list.add_to_end(3)
    my_list.add_to_front(0)
    my_list.print_list()  # Output: 0 -> 1 -> 2 -> 3 -> None
    my_list.remove_value(2)
    my_list.print_list()  # Output: 0 -> 1 -> 3 -> None

from datetime import datetime

def compute_years_since_birth(birth_date_str):
    try:
        # Convert string to date object using specified format
        birth_date = datetime.strptime(birth_date_str, "%d-%m-%Y")

        # Get current date
        current_date = datetime.now()

        # Compute age considering leap years and exact day/month comparison
        years = current_date.year - birth_date.year
        if (current_date.month, current_date.day) < (birth_date.month, birth_date.day):
            years -= 1

        return years
    except ValueError:
        # Return None for invalid dates
        return None

def show_users_by_age_descending(user_list):
    # Prepare list with user details including computed age
    processed_users = []

    for person in user_list:
        name = person.get('Full Name')
        dob_str = person.get('Date of Birth')

        if name and dob_str:
            age_val = compute_years_since_birth(dob_str)
            if age_val is not None:
                processed_users.append({
                    'Full Name': name,
                    'Date of Birth': dob_str,
                    'Age': age_val
                })
            else:
                print(f"Invalid date format for {name}: {dob_str}")
        else:
            print(f"Incomplete information for user: {name}")

    # Sort users by age (highest first)
    processed_users.sort(key=lambda u: u['Age'], reverse=True)

    # Print sorted results
    for entry in processed_users:
        print(f"Full Name: {entry['Full Name']}, Date of Birth: {entry['Date of Birth']}, Age: {entry['Age']}")

