# Redefine class representation using a different internal structure and logic

class Course:
    def __init__(self, course_name, instructor):
        self.course_name = course_name
        self.instructor = instructor

    def __eq__(self, other):
        if not isinstance(other, Course):
            return False
        return self.course_name == other.course_name

    def __hash__(self):
        return hash((self.course_name, self.instructor))

    def __repr__(self):
        return f"Course(course_name='{self.course_name}', instructor='{self.instructor}')"


class StudentRegistry:
    def __init__(self):
        self.registry = {}

    def register_new_student(self, student_name, years_old):
        if student_name in self.registry:
            raise ValueError(f"Student '{student_name}' is already registered.")
        self.registry[student_name] = {"age": years_old, "enrollments": []}

    def deregister_student(self, student_name):
        if student_name not in self.registry:
            raise ValueError(f"No record found for student '{student_name}'.")
        del self.registry[student_name]

    def modify_student_age(self, student_name, new_age):
        if student_name not in self.registry:
            raise ValueError(f"No record found for student '{student_name}'.")
        self.registry[student_name]["age"] = new_age

    def add_course_to_student(self, student_name, course_title, professor):
        if student_name not in self.registry:
            raise ValueError(f"No record found for student '{student_name}'.")
        course = Course(course_title, professor)
        # Avoid duplicate enrollments by checking equality
        if course not in self.registry[student_name]["enrollments"]:
            self.registry[student_name]["enrollments"].append(course)

    def drop_course_from_student(self, student_name, course_title):
        if student_name not in self.registry:
            raise ValueError(f"No record found for student '{student_name}'.")
        self.registry[student_name]["enrollments"] = [
            c for c in self.registry[student_name]["enrollments"]
            if c.course_name != course_title
        ]

    def retrieve_student_info(self, student_name):
        if student_name not in self.registry:
            raise ValueError(f"No record found for student '{student_name}'.")
        return self.registry[student_name]

    def __repr__(self):
        return f"StudentRegistry(registry={self.registry})"


