# Generate a simple blog page with HTML and CSS

def create_webpage_header(blog_title, writer, publish_date):
    # Construct the header section of the HTML document
    header_html = f"""
        <header>
            <h1>{blog_title}</h1>
            <p>By <span>{writer}</span> on <span>{publish_date}</span></p>
        </header>"""
    return header_html

def build_page_structure(main_content, title):
    # Build the full HTML structure using provided content and title
    html_body = f"""
    <!DOCTYPE html>
    <html lang="en">
    <head>
        <meta charset="UTF-8">
        <meta name="viewport" content="width=device-width, initial-scale=1.0">
        <title>{title}</title>
        <link rel="stylesheet" href="styles.css">
    </head>
    <body>
        {create_webpage_header(title, '', '')[:-2]}  # Will be replaced below
        <main>
            <article>
                {main_content}
            </article>
        </main>
    </body>
    </html>"""

    # Replace placeholder with actual header
    full_html = html_body.replace(
        '{create_webpage_header(title, \'\', \'\')[:-2]}',
        create_webpage_header(title, '', '') + '\n'
    )
    return full_html

def generate_css_styles():
    # Define CSS styling for the blog layout
    css_rules = """
    body {
        font-family: Arial, sans-serif;
        line-height: 1.6;
        margin: 0;
        padding: 0;
        background-color: #f4f4f4;
    }
    header {
        background-color: #333;
        color: white;
        text-align: center;
        padding: 1rem;
    }
    header h1 {
        margin: 0;
    }
    header p {
        color: #ccc;
    }
    main {
        max-width: 800px;
        margin: 20px auto;
        padding: 20px;
        background-color: white;
        box-shadow: 0 0 10px rgba(0, 0, 0, 0.1);
    }
    article {
        margin-top: 20px;
    }"""
    return css_rules

def main():
    # Collect user input for blog post details
    blog_title = input("Enter the blog title: ")
    author_name = input("Enter the author's name: ")
    post_date = input("Enter the date (YYYY-MM-DD): ")
    article_text = input("Enter the blog content: ")

    # Generate HTML and CSS content
    webpage_html = build_page_structure(article_text, blog_title)
    stylesheet_css = generate_css_styles()

    # Insert author and date into header properly
    webpage_html = webpage_html.replace('<p>By <span></span> on <span></span></p>', 
