# Calculate frustum properties for circular and elliptical shapes

import math

def check_parameters(r1, r2, h, a1=None, a2=None, b1=None, b2=None):
    # Validate that all required dimensions are positive
    if r1 <= 0 or r2 <= 0 or h <= 0:
        raise ValueError("All radii and height must be positive.")

    # If elliptical parameters are provided, validate them too
    if all(param is not None for param in [a1, a2, b1, b2]):
        if a1 <= 0 or a2 <= 0 or b1 <= 0 or b2 <= 0:
            raise ValueError("All semi-axes and height must be positive.")

def curved_surface_circular(r1, r2, h):
    # Compute lateral surface area for circular frustum
    return math.pi * (r1 + r2) * math.sqrt((r2 - r1)**2 + h**2)

def curved_surface_elliptical(a1, a2, b1, b2, h):
    # Compute lateral surface area for elliptical frustum as sum of two components
    part1 = math.pi * (a1 + a2) * math.sqrt((a2 - a1)**2 + h**2)
    part2 = math.pi * (b1 + b2) * math.sqrt((b2 - b1)**2 + h**2)
    return part1 + part2

def capacity_circular(r1, r2, h):
    # Compute volume for circular frustum
    return (math.pi * h / 3) * (r1**2 + r2**2 + r1 * r2)

def capacity_elliptical(a1, a2, b1, b2, h):
    # Compute volume for elliptical frustum
    return (math.pi * h / 3) * (a1 * b1 + a2 * b2 + math.sqrt(a1 * b1 * a2 * b2))

def process_frustums(frustum_data):
    output = []
    for data in frustum_data:
        r1 = data['r1']
        r2 = data['r2']
        h = data['h']
        a1 = data.get('a1')
        a2 = data.get('a2')
        b1 = data.get('b1')
        b2 = data.get('b2')

        check_parameters(r1, r2, h, a1, a2, b1, b2)

        # Determine shape type and compute accordingly
        if all(p is not None for p in [a1, a2, b1, b2]):
            surface_area = curved_surface_elliptical(a1, a2, b1, b2, h)
            vol = capacity_elliptical(a1, a2, b1, b2, h)
        else:
            surface_area = curved_surface_circular(r1, r2, h)
            vol = capacity_circular(r1, r2, h)

        output.append({
            'curved_surface': surface_area,
            'capacity': vol
        })

    return output

# Example usage
frustums = [
    {'r1': 3, 'r2': 5, 'h': 4},
    {'r1': 2, 'r2': 4, 'h': 3, 'a1': 3, 'a2': 5, 'b1': 2, 'b2': 4}
]

results = process_frustums(frustums)
for idx, res in enumerate(results):
    print(f"Frustum {idx+1}: Curved Surface Area = {res['curved_surface']:.15f}, Capacity = {res['capacity']:.15f}")

# Define a class to represent a rectangle with validation and comparison features

class Rectangle:
    def __init__(self, length_val, width_val):
        self.update_length(length_val)
        self.update_width(width_val)

    def update_length(self, new_length):
        if not isinstance(new_length, (int, float)) or new_length <= 0:
            raise ValueError("Length must be a positive non-zero number.")
        self._length = new_length

    def retrieve_length(self):
        return self._length

    def update_width(self, new_width):
        if not isinstance(new_width, (int, float)) or new_width <= 0:
            raise ValueError("Width must be a positive non-zero number.")
        self._width = new_width

    def retrieve_width(self):
        return self._width

    def compute_area(self):
        try:
            return self._length * self._width
        except Exception as e:
            raise RuntimeError("An error occurred while calculating the area.") from e

    def compute_perimeter(self):
        try:
            return 2 * (self._length + self._width)
        except Exception as e:
            raise RuntimeError("An error occurred while calculating the perimeter.") from e

    def has_equal_area(self, other_shape):
        if not isinstance(other_shape, Rectangle):
            raise TypeError("The 'other_shape' parameter must be an instance of Rectangle.")
        return self.compute_area() == other_shape.compute_area()

# Unit tests using unittest framework
import unittest

class TestRectangle(unittest.TestCase):
    def test_valid_rectangle_initialization(self):
        rect = Rectangle(5, 10)
        self.assertEqual(rect.retrieve_length(), 5)
        self.assertEqual(rect.retrieve_width(), 10)

    def test_invalid_rectangle_initialization(self):
        with self.assertRaises(ValueError):
            Rectangle(-5, 10)
        with self.assertRaises(ValueError):
            Rectangle(5, -10)
        with self.assertRaises(ValueError):
            Rectangle(0, 10)
        with self.assertRaises(ValueError):
            Rectangle(5, 0)

    def test_area_computation(self):
        rect = Rectangle(5, 10)
        self.assertEqual(rect.compute_area(), 50)

    def test_perimeter_computation(self):
        rect = Rectangle(5, 10)
        self.assertEqual(rect.compute_perimeter(), 30)

    def test_area_equality_check(self):
        rect1 = Rectangle(5, 10)
        rect2 = Rectangle(10, 5)
        rect3 = Rectangle(4, 6)
        self.assertTrue(rect1.has_equal_area(rect2))
        self.assertFalse(rect1.has_equal_area(rect3))

    def test_type_error_in_area_comparison(self):
        rect1 = Rectangle(5, 10)
        with self.assertRaises(TypeError):
            rect1.has_equal_area(123)

if __name__ == '__main__':
    unittest.main()

