# library_member.py (Type III Clone)

class LibraryUser:
    def __init__(self, uid, full_name, location, contact_number, mail_address):
        self.uid = uid
        self.full_name = full_name
        self.location = location
        self.contact_number = contact_number
        self.mail_address = mail_address

    def __repr__(self):
        return f"UID: {self.uid}\nName: {self.full_name}\nLocation: {self.location}\nContact: {self.contact_number}\nEmail: {self.mail_address}"

    def change_name(self, updated_name):
        self.full_name = updated_name

    def change_location(self, updated_location):
        self.location = updated_location

    def change_contact(self, updated_contact):
        self.contact_number = updated_contact

    def change_email(self, updated_email):
        self.mail_address = updated_email

class LibraryUserRegistry:
    def __init__(self):
        self.users = {}

    def register_user(self, uid, full_name, location, contact_number, mail_address):
        if uid in self.users:
            raise ValueError(f"User with ID {uid} is already registered.")
        new_user = LibraryUser(uid, full_name, location, contact_number, mail_address)
        self.users[uid] = new_user
        print(f"User with ID {uid} registered successfully.")

    def fetch_user(self, uid):
        if uid not in self.users:
            raise ValueError(f"User with ID {uid} is not registered.")
        return self.users[uid]

    def modify_user(self, uid, **changes):
        if uid not in self.users:
            raise ValueError(f"User with ID {uid} is not registered.")
        user = self.users[uid]
        if 'full_name' in changes:
            user.change_name(changes['full_name'])
        if 'location' in changes:
            user.change_location(changes['location'])
        if 'contact_number' in changes:
            user.change_contact(changes['contact_number'])
        if 'mail_address' in changes:
            user.change_email(changes['mail_address'])
        print(f"User with ID {uid} modified successfully.")

    def deregister_user(self, uid):
        if uid not in self.users:
            raise ValueError(f"User with ID {uid} is not registered.")
        del self.users[uid]
        print(f"User with ID {uid} deregistered successfully.")

    def show_all_users(self):
        if not self.users:
            print("No users registered in the system.")
            return
        for uid, user in self.users.items():
            print(user)
            print("-" * 40)

# Example usage
