    # Show all users after modification
    registry.show_all_users()

    # Deregister user
    registry.deregister_user(2)

    # Show all users after deregistration
    registry.show_all_users()

# Flask REST API for managing items using SQLite database

from flask import Flask, request, jsonify
from flask_sqlalchemy import SQLAlchemy
from flask_marshmallow import Marshmallow

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///items.db'
app.config['SQLALCHEMY_TRACK_MODIFICATIONS'] = False

db = SQLAlchemy(app)
ma = Marshmallow(app)

class Item(db.Model):
    item_id = db.Column(db.Integer, primary_key=True)
    item_name = db.Column(db.String(100), unique=True)
    item_desc = db.Column(db.String(200))

    def __init__(self, name, description):
        self.item_name = name
        self.item_desc = description

class ItemSchema(ma.Schema):
    class Meta:
        fields = ('item_id', 'item_name', 'item_desc')

item_schema = ItemSchema()
items_schema = ItemSchema(many=True)

@app.route('/item', methods=['POST'])
def create_item():
    name = request.json.get('name')
    description = request.json.get('description')
    new_item = Item(name, description)
    db.session.add(new_item)
    db.session.commit()
    return item_schema.jsonify(new_item)

@app.route('/item', methods=['GET'])
def list_items():
    all_items = Item.query.all()
    result = items_schema.dump(all_items)
    return jsonify(result)

@app.route('/item/<int:item_id>', methods=['GET'])
def retrieve_item(item_id):
    item = Item.query.get(item_id)
    if not item:
        return jsonify({'error': 'Item not found'}), 404
    return item_schema.jsonify(item)

@app.route('/item/<int:item_id>', methods=['PUT'])
def modify_item(item_id):
    item = Item.query.get(item_id)
    if not item:
        return jsonify({'error': 'Item not found'}), 404

    item.item_name = request.json.get('name', item.item_name)
    item.item_desc = request.json.get('description', item.item_desc)
    db.session.commit()
    return item_schema.jsonify(item)

@app.route('/item/<int:item_id>', methods=['DELETE'])
def remove_item(item_id):
    item = Item.query.get(item_id)
    if not item:
        return jsonify({'error': 'Item not found'}), 404
    db.session.delete(item)
    db.session.commit()
    return item_schema.jsonify(item)

if __name__ == '__main__':
    with app.app_context():
        db.create_all()
    app.run(debug=True)

