import re

class MathEvaluator:
    def __init__(self, input_expr):
        self.input_expr = input_expr
        self.lexemes = self.scan(input_expr)
        self.index = 0
        self.current_lexeme = None
        self.next_token()

    def scan(self, expr):
        # Convert expression into list of tokens (numbers and operators)
        token_patterns = [
            ('NUM',   r'\d+(\.\d*)?'),  # Numbers (integers or decimals)
            ('ADD',   r'\+'),           # Plus sign
            ('SUB',   r'-'),            # Minus sign
            ('MUL',   r'\*'),           # Multiplication
            ('DIV',   r'/'),            # Division
            ('OPEN',  r'\('),           # Opening parenthesis
            ('CLOSE', r'\)'),           # Closing parenthesis
            ('SPACE', r'[ \t]+'),       # Whitespace to skip
        ]
        regex = '|'.join(f'(?P<{name}>{pattern})' for name, pattern in token_patterns)
        lexemes = []
        for match in re.finditer(regex, expr):
            token_type = match.lastgroup
            value = match.group(token_type)
            if token_type == 'NUM':
                lexemes.append(('NUM', float(value)))
            elif token_type == 'SPACE':
                continue
            else:
                lexemes.append((token_type, value))
        return lexemes

    def next_token(self):
        # Get next token from the list
        if self.index < len(self.lexemes):
            self.current_lexeme = self.lexemes[self.index]
            self.index += 1
        else:
            self.current_lexeme = None

    def evaluate(self):
        # Entry point for parsing
        return self.compute_expression()

    def compute_expression(self):
        # Handle addition and subtraction (lowest precedence)
        left_value = self.compute_term()
        while self.current_lexeme and self.current_lexeme[0] in ('ADD', 'SUB'):
            op = self.current_lexeme[0]
            self.next_token()
            right_value = self.compute_term()
            if op == 'ADD':
                left_value += right_value
            else:
                left_value -= right_value
        return left_value

    def compute_term(self):
        # Handle multiplication and division (higher precedence)
        left_value = self.compute_factor()
        while self.current_lexeme and self.current_lexeme[0] in ('MUL', 'DIV'):
            op = self.current_lexeme[0]
            self.next_token()
            right_value = self.compute_factor()
            if op == 'MUL':
                left_value *= right_value
            else:
                left_value /= right_value
        return left_value

    def compute_factor(self):
        # Handle numbers and parentheses (highest precedence)
        if self.current_lexeme[0] == 'NUM':
            val = self.current_lexeme[1]
            self.next_token()
            return val
        elif self.current_lexeme[0] == 'OPEN':
            self.next_token()  # consume '('
            result = self.compute_expression()
            if not self.current_lexeme or self.current_lexeme[0] != 'CLOSE':
                raise ValueError("Missing closing parenthesis")
            self.next_token()  # consume ')'
            return result
        else:
            raise ValueError("Unexpected token in expression")

# Example usage
expr = "3 + 5 * (10 - 4)"
evaluator = MathEvaluator(expr)
final_result = evaluator.evaluate()
print(f"Result: {final_result}")

