# Script to compute SHA-256 hashes and detect duplicate files in current directory

import os
import hashlib

def compute_sha256(file_path):
    """Compute the SHA-256 hash of a file."""
    sha256_hash = hashlib.sha256()
    with open(file_path, "rb") as f:
        # Read file in chunks of 8192 bytes
        for chunk in iter(lambda: f.read(8192), b""):
            sha256_hash.update(chunk)
    return sha256_hash.hexdigest()

def scan_directory_for_hashes():
    """Scan current working directory and collect file names with their SHA-256 hashes."""
    file_checksums = {}
    current_dir_files = os.listdir()

    for item in current_dir_files:
        full_path = os.path.join(os.getcwd(), item)
        if os.path.isfile(full_path):
            file_checksums[item] = compute_sha256(full_path)
            print(f"{item}: {file_checksums[item]}")

    return file_checksums

def identify_duplicate_files(checksum_data):
    """Identify files that share the same checksum (potential duplicates)."""
    checksum_to_files = {}

    for filename, checksum in checksum_data.items():
        if checksum not in checksum_to_files:
            checksum_to_files[checksum] = [filename]
        else:
            checksum_to_files[checksum].append(filename)

    # Filter only those checksums associated with more than one file
    duplicate_groups = {
        checksum: filenames 
        for checksum, filenames in checksum_to_files.items() 
        if len(filenames) > 1
    }

    if duplicate_groups:
        print("Duplicate files detected:")
        for checksum, filenames in duplicate_groups.items():
            print(f"SHA-256: {checksum}")
            for name in filenames:
                print(f"  - {name}")
    else:
        print("No duplicate files identified.")

if __name__ == "__main__":
    collected_hashes = scan_directory_for_hashes()
    identify_duplicate_files(collected_hashes)

