# Web image scraper using recursive depth-limited crawling

import requests
from bs4 import BeautifulSoup
from urllib.parse import urljoin, urlparse

def collect_images_from_site(start_url, max_depth=2):
    visited_pages = set()
    found_images = []

    def crawl_page(page_url, current_level=0):
        if current_level > max_depth or page_url in visited_pages:
            return

        visited_pages.add(page_url)

        try:
            response = requests.get(page_url)
            soup = BeautifulSoup(response.content, 'html.parser')

            # Extract image sources
            for image_tag in soup.find_all('img'):
                image_source = image_tag.get('src')
                if image_source:
                    absolute_image_url = urljoin(page_url, image_source)
                    found_images.append(absolute_image_url)

            # Recursively follow internal links
            for anchor_tag in soup.find_all('a', href=True):
                next_page_url = urljoin(page_url, anchor_tag['href'])

                # Only follow links within the same domain
                if urlparse(next_page_url).netloc == urlparse(page_url).netloc:
                    crawl_page(next_page_url, current_level + 1)

        except Exception as error:
            print(f"Failed to process {page_url}: {error}")

    crawl_page(start_url)
    return found_images

# Alternative implementation for HCF and divisibility checking

def compute_gcd_pairwise(a, b):
    """Compute GCD of two numbers using Euclidean algorithm."""
    while b:
        a, b = b, a % b
    return a

def find_hcf_of_four_values(val1, val2, val3, val4):
    """Calculate the HCF (GCD) of four numbers by pairwise reduction."""
    gcd_first_pair = compute_gcd_pairwise(val1, val2)
    gcd_second_pair = compute_gcd_pairwise(val3, val4)
    return compute_gcd_pairwise(gcd_first_pair, gcd_second_pair)

def nearest_multiple_value(value, base):
    """Find the nearest integer multiple of 'base' to 'value'."""
    # Calculate quotient and remainder
    q = value // base
    r = value - q * base

    # Determine which multiple is closer
    lower = q * base
    upper = (q + 1) * base

    if abs(value - lower) <= abs(upper - value):
        return lower
    else:
        return upper

def analyze_numbers_and_divisibility(n1, n2, n3, n4, divisor_val):
    try:
        # Ensure all inputs are integers
        if not all(isinstance(x, int) for x in [n1, n2, n3, n4]):
            raise TypeError("All input numbers must be integers.")

        # Handle zero divisor case explicitly
        if divisor_val == 0:
            raise ZeroDivisionError("Divisor cannot be zero.")

        # Compute HCF using alternative method
        hcf_result = find_hcf_of_four_values(n1, n2, n3, n4)
        print(f"The Highest Common Factor (HCF) of {n1}, {n2}, {n3}, and {n4} is: {hcf_result}")

        # Analyze each number for divisibility
        analysis_results = {}
        for current_val in [n1, n2, n3, n4]:
            if current_val % divisor_val == 0:
                analysis_results[current_val] = f"{current_val} is divisible by {divisor_val}"
            else:
                adjusted_val = nearest_multiple_value(current_val, divisor_val)
                analysis_results[current_val] = f"{current_val} is not divisible by {divisor_val}. The closest divisible number is {adjusted_val}"

        # Print results for each number
        for key, msg in analysis_results.items():
            print(msg)

    except ZeroDivisionError as zde:
        print("Error: Divisor cannot be zero.")
    except TypeError as te:
        print(f"Error: {te}")
    except Exception as ex:
        print(f"An unexpected error occurred: {ex}")

