# Calculate the average of 5 largest and 5 smallest numbers in a list

def get_top_and_bottom_values(data, count):
    if len(data) < 2 * count:
        raise ValueError("List must contain at least 10 elements to find 5 highest and 5 lowest values.")

    top_values = []
    bottom_values = []

    for _ in range(count):
        current_max = float('-inf')
        current_min = float('inf')

        for item in data:
            if item > current_max and item not in top_values:
                current_max = item
            if item < current_min and item not in bottom_values:
                current_min = item

        top_values.append(current_max)
        bottom_values.append(current_min)

    return top_values, bottom_values

def compute_average_of_boundaries(data_list):
    try:
        high_vals, low_vals = get_top_and_bottom_values(data_list, 5)
        total_sum = sum(high_vals) + sum(low_vals)
        return total_sum / 10
    except ValueError as error:
        return str(error)

