# Thread-safe hash table implementation with dynamic resizing

import threading
from typing import Any, Hashable, Optional

class HashMap:
    def __init__(self, capacity: int = 10, threshold: float = 0.7):
        self.capacity = capacity
        self.threshold = threshold
        self.data = [None] * self.capacity
        self.mutex = threading.Lock()
        self.elements = 0

    def _compute_index(self, key: Hashable) -> int:
        if isinstance(key, int):
            return abs(key) % self.capacity
        elif isinstance(key, str):
            return sum(ord(c) for c in key) % self.capacity
        else:
            raise TypeError("Keys must be integers or strings")

    def _expand_storage(self) -> None:
        with self.mutex:
            previous_buckets = self.data
            self.capacity *= 2
            self.data = [None] * self.capacity
            self.elements = 0

            for bucket in previous_buckets:
                if bucket is not None:
                    for k, v in bucket:
                        self.put(k, v)

    def put(self, key: Hashable, value: Any) -> None:
        with self.mutex:
            position = self._compute_index(key)
            if self.data[position] is None:
                self.data[position] = []

            # Update existing key or append new entry
            found = False
            for idx, (existing_key, _) in enumerate(self.data[position]):
                if existing_key == key:
                    self.data[position][idx] = (key, value)
                    found = True
                    break

            if not found:
                self.data[position].append((key, value))
                self.elements += 1

            # Check if resizing is needed
            if self.elements / self.capacity >= self.threshold:
                self._expand_storage()

    def get(self, key: Hashable) -> Optional[Any]:
        with self.mutex:
            position = self._compute_index(key)
            if self.data[position] is None:
                return None

            for k, v in self.data[position]:
                if k == key:
                    return v
            return None

    def remove(self, key: Hashable) -> None:
        with self.mutex:
            position = self._compute_index(key)
            if self.data[position] is None:
                return

            for idx, (k, _) in enumerate(self.data[position]):
                if k == key:
                    del self.data[position][idx]
                    self.elements -= 1
                    return

    def __repr__(self):
        return repr(self.data)

# Demonstration
if __name__ == "__main__":
    hm = HashMap()
    hm.put(1, "one")
    hm.put(2, "two")
    hm.put("three", 3)
    hm.put(11, "eleven")  # Triggers expansion
    print(hm.get(1))      # Output: one
    print(hm.get("three")) # Output: 3
    hm.remove(2)
    print(hm.get(2))      # Output: None
    print(hm)

import json
from collections import Counter
from typing import Any, Dict, List, Union

class EnhancedJSONProcessor:
    def __init__(self):
        self.processed_ids = set()
        self.key_frequency = Counter()

    def process(self, json_text: str) -> Dict[str, str]:
        try:
            parsed_data = json.loads(json_text)
        except json.JSONDecodeError as error:
            raise ValueError(f"Malformed JSON input: {error}")

        return self._handle_element(parsed_data)

    def _handle_element(self, element: Any) -> Union[str, List[str], Dict[str, str]]:
        if isinstance(element, dict):
            return self._process_dictionary(element)
        elif isinstance(element, list):
            return self._process_array(element)
        else:
            return self._transform_to_string(element)

    def _process_dictionary(self, dictionary: Dict[Any, Any]) -> Dict[str, str]:
        output = {}
        for original_key, original_value in dictionary.items():
            adjusted_key = self._make_key_unique(original_key)
            output[adjusted_key] = self._handle_element(original_value)
        return output

    def _process_array(self, array: List[Any]) -> List[str]:
        return [self._handle_element(item) for item in array]

    def _make_key_unique(self, key: Any) -> str:
        key_str = str(key)
        if self.key_frequency[key_str] > 0:
            key_str = f"{key_str}_{self.key_frequency[key_str]}"
        self.key_frequency[key_str] += 1
        return key_str

    def _transform_to_string(self, data: Any) -> str:
        if data is None:
            return "null"
        return str(data)

    def _check_for_cycles(self, obj: Any) -> bool:
        obj_identifier = id(obj)
        if obj_identifier in self.processed_ids:
            return True
        self.processed_ids.add(obj_identifier)
        return False

    def verify_structure(self, input_data: Dict[str, str], template: Dict[str, Any]) -> bool:
        for field_name, expected_value in template.items():
            if field_name not in input_data:
                raise ValueError(f"Required field '{field_name}' is missing")
            if not isinstance(input_data[field_name], str):
                raise ValueError(f"Field '{field_name}' must be a string")
            if expected_value is not None and not input_data[field_name].startswith(expected_value):
                raise ValueError(f"Field '{field_name}' does not meet the required prefix condition")
        return True

# Demonstration usage
json_input = '{"name": "John", "age": 30, "address": {"city": "New York", "zip": 10001}, "hobbies": ["reading", "coding"], "name": "Jane"}'
processor = EnhancedJSONProcessor()
