# Abstract base class for library books with borrowing functionality

from abc import ABC, abstractmethod
from datetime import datetime, timedelta

class LibraryItem(ABC):
    def __init__(self, name, creator, publication_year, category):
        self.title = name
        self.author = creator
        self.year = publication_year
        self.item_category = category
        self.license_status = "Not specified"
        self.borrowed_flag = False
        self.return_deadline = None

    @abstractmethod
    def display_details(self):
        pass

    def checkout(self, loan_period):
        if not self.borrowed_flag:
            self.borrowed_flag = True
            self.return_deadline = datetime.now() + timedelta(days=loan_period)
            print(f"'{self.title}' has been checked out and is due on {self.return_deadline}")
        else:
            print(f"'{self.title}' is already checked out.")

    def check_in(self):
        if self.borrowed_flag:
            self.borrowed_flag = False
            self.return_deadline = None
            print(f"'{self.title}' has been returned.")
        else:
            print(f"'{self.title}' is not currently checked out.")

    def overdue_check(self):
        if self.borrowed_flag and self.return_deadline < datetime.now():
            print(f"'{self.title}' is overdue.")
        else:
            print(f"'{self.title}' is not overdue.")

# Function to determine if a nested structure contains only empty containers and count them

def check_nested_containers(obj, seen=None):
    if seen is None:
        seen = set()

    # Prevent infinite recursion for circular references
    obj_id = id(obj)
    if obj_id in seen:
        return True, 0

    seen.add(obj_id)

    # Handle dictionary type
    if isinstance(obj, dict):
        if len(obj) == 0:
            return True, 1

        all_empty = True
        total_empty = 0

        for val in obj.values():
            is_empty, cnt = check_nested_containers(val, seen)
            if not is_empty:
                all_empty = False
            total_empty += cnt

        return all_empty, total_empty

    # Handle list, tuple, and set types
    elif isinstance(obj, (list, tuple, set)):
        all_empty = True
        total_empty = 0

        for item in obj:
            is_empty, cnt = check_nested_containers(item, seen)
            if not is_empty:
                all_empty = False
            total_empty += cnt

        return all_empty, total_empty

    # For any other data type, consider it non-empty
    else:
        return False, 0

