# Alternative implementation of a hash table with linear probing and dynamic resizing

def is_prime_number(value):
    if value < 2:
        return False
    divisor = 2
    while divisor * divisor <= value:
        if value % divisor == 0:
            return False
        divisor += 1
    return True

def find_next_prime(start_value):
    candidate = start_value
    while not is_prime_number(candidate):
        candidate += 1
    return candidate

class HashMap:
    def __init__(self, capacity=1009):
        self.capacity = capacity
        self.buckets = [None] * self.capacity
        self.element_count = 0

    def _compute_index(self, item_key):
        return hash(item_key) % self.capacity

    def _expand_storage(self):
        new_capacity = find_next_prime(2 * self.capacity)
        new_buckets = [None] * new_capacity

        for pair in self.buckets:
            if pair is not None:
                original_key, original_value = pair
                new_position = self._compute_index(original_key)

                while new_buckets[new_position] is not None:
                    new_position = (new_position + 1) % new_capacity

                new_buckets[new_position] = (original_key, original_value)

        self.buckets = new_buckets
        self.capacity = new_capacity

    def store(self, key, data):
        load_factor = self.element_count / self.capacity
        if load_factor >= 0.4:
            self._expand_storage()

        position = self._compute_index(key)
        while self.buckets[position] is not None and self.buckets[position][0] != key:
            position = (position + 1) % self.capacity

        self.buckets[position] = (key, data)
        self.element_count += 1

    def retrieve(self, key):
        position = self._compute_index(key)
        while self.buckets[position] is not None:
            if self.buckets[position][0] == key:
                return self.buckets[position][1]
            position = (position + 1) % self.capacity
        raise KeyError(f"Key '{key}' does not exist")

    def remove(self, key):
        position = self._compute_index(key)
        while self.buckets[position] is not None:
            if self.buckets[position][0] == key:
                self.buckets[position] = None
                self.element_count -= 1
                return
            position = (position + 1) % self.capacity
        raise KeyError(f"Key '{key}' does not exist")

