import re

def detect_consecutive_repetition_and_isolated_char(text):
    # Initialize variables to store results
    repeated_token = None
    repeated_token_index = None
    isolated_char = None
    isolated_char_index = None

    # Extract words using regex (alphanumeric sequences as tokens)
    tokens = re.findall(r'\b\w+\b', text)

    # Look for any token that repeats at least 4 times in a row
    for idx in range(len(tokens) - 3):
        if (tokens[idx] == tokens[idx + 1] == 
            tokens[idx + 2] == tokens[idx + 3]):
            repeated_token = tokens[idx]
            repeated_token_index = idx
            break

    # Track positions of each alphabetic character in the original text
    char_occurrences = {}
    for index, symbol in enumerate(text):
        if symbol.isalpha():
            if symbol not in char_occurrences:
                char_occurrences[symbol] = []
            char_occurrences[symbol].append(index)

    # Find the first character that appears exactly once
    for char, indices in char_occurrences.items():
        if len(indices) == 1:
            isolated_char = char
            isolated_char_index = indices[0]
            break

    return (repeated_token, repeated_token_index, 
            isolated_char, isolated_char_index)

