    print(f"Repeated word: '{repeated_token}' at position {repeated_token_index}")
else:
    print("No repeated word with at least 4 consecutive occurrences found.")

if isolated_char:
    print(f"Unique letter: '{isolated_char}' at position {isolated_char_index}")
else:
    print("No unique letter found.")

