import hashlib
import json
from datetime import datetime

def get_sort_priority(item):
    key, val = item
    if isinstance(val, (int, float)):
        return (0, -val)
    elif isinstance(val, str):
        return (1, val.lower())
    elif isinstance(val, bool):
        return (2, val)
    elif isinstance(val, (list, dict, datetime)):
        return (3, val)
    else:
        raise TypeError(f"Unsupported data type: {type(val)}")

def transform_value(val):
    if isinstance(val, str):
        return val.lower()
    elif isinstance(val, (int, float, bool)):
        return val
    elif isinstance(val, list):
        return [transform_value(v) for v in val]
    elif isinstance(val, dict):
        return transform_dict(val)
    elif isinstance(val, datetime):
        return val.isoformat().lower()
    else:
        raise TypeError(f"Unsupported data type: {type(val)}")

def transform_dict(d):
    if not isinstance(d, dict):
        raise TypeError("Input must be a dictionary")

    transformed_items = sorted(
        ((str(k).lower(), transform_value(v)) for k, v in d.items() if v is not None and v != ""),
        key=get_sort_priority
    )
    return dict(transformed_items)

def compute_hash(d, method='sha512'):
    processed_dict = transform_dict(d)
    json_str = json.dumps(processed_dict, sort_keys=True)
    hash_obj = hashlib.new(method)
    hash_obj.update(json_str.encode('utf-8'))
    return hash_obj.hexdigest()

