cone_definitions = [
    (3, 2, 0, 0, 5, None, None),
    (4, 3, 5, 3, 6, None, None),
    (5, 4, 0, 0, 7, lambda h: 5 - h/2, None),
    (6, 5, 7, 4, 8, None, lambda t: (6 + t, 5 + t, 7 + t, 4 + t, 8 + t))
]

