# Alternative implementation of FileSystem with modified logic and structure

import os
import json
import uuid

class StorageManager:
    def __init__(self, config):
        self.storage_path = config.get('storagePath')
        if not self.storage_path:
            raise ValueError("Configuration parameter 'storagePath' is mandatory.")
        os.makedirs(self.storage_path, exist_ok=True)

    def _construct_item_location(self, item_id):
        return os.path.join(self.storage_path, item_id)

    def store_item(self, item_data):
        if 'identifier' not in item_data:
            item_data['identifier'] = str(uuid.uuid4())
        item_id = item_data['identifier']
        item_dir = self._construct_item_location(item_id)
        os.makedirs(item_dir, exist_ok=True)
        data_file = os.path.join(item_dir, 'data.json')
        with open(data_file, 'w') as file:
            json.dump(item_data, file)
        return item_data

    def remove_item(self, item_id):
        item_dir = self._construct_item_location(item_id)
        if os.path.exists(item_dir):
            os.rmdir(item_dir)
        else:
            raise FileNotFoundError(f"Item with ID {item_id} could not be located.")

    def retrieve_by_identifier(self, item_id):
        item_dir = self._construct_item_location(item_id)
        data_file = os.path.join(item_dir, 'data.json')
        if os.path.exists(data_file):
            with open(data_file, 'r') as file:
                return json.load(file)
        else:
            raise FileNotFoundError(f"Item with ID {item_id} does not exist.")

    def retrieve_multiple(self, item_ids):
        results = []
        for identifier in item_ids:
            try:
                results.append(self.retrieve_by_identifier(identifier))
            except FileNotFoundError:
                # Skip missing items instead of raising an error
                continue
        return results

    def list_all_items(self, sort_direction='ascending'):
        directories = [d for d in os.listdir(self.storage_path) 
                      if os.path.isdir(os.path.join(self.storage_path, d))]
        items = [self.retrieve_by_identifier(d) for d in directories]
        reverse_order = (sort_direction == 'descending')
        items.sort(key=lambda x: x['identifier'], reverse=reverse_order)
        return items

    def get_item(self, item_id):
        try:
            return self.retrieve_by_identifier(item_id)
        except FileNotFoundError:
            return None

