# Compute item similarity using cosine similarity and collect positive matches

import math

def find_similar_items(item_data):
    # Dictionary to store items and their similar counterparts with scores
    matches = {}

    # Iterate through each item against all others (excluding itself)
    for item_a, features_a in item_data.items():
        for item_b, features_b in item_data.items():
            if item_a == item_b:
                continue

            # Calculate cosine similarity between feature vectors
            score = compute_cosine(features_a, features_b)

            # Only include items with non-zero similarity
            if score > 0:
                matches.setdefault(item_a, []).append((item_b, score))

    return matches

def compute_cosine(vec1, vec2):
    # Ensure vectors have same dimensionality
    if len(vec1) != len(vec2):
        raise ValueError("Feature vectors must have equal length")

    # Compute dot product
    dot = sum(a * b for a, b in zip(vec1, vec2))

    # Compute magnitudes
    mag1 = math.sqrt(sum(x ** 2 for x in vec1))
    mag2 = math.sqrt(sum(y ** 2 for y in vec2))

    # Handle zero vectors
    if mag1 == 0 or mag2 == 0:
        return 0.0

    return dot / (mag1 * mag2)

