# Calculate the difference between two dates in years, months, and days

def is_leap_year(year):
    """Determine if a year is a leap year."""
    return (year % 4 == 0) and (year % 100 != 0 or year % 400 == 0)

def get_days_in_month(year, month):
    """Get the number of days in a specific month."""
    if month == 2:
        return 29 if is_leap_year(year) else 28
    elif month in [4, 6, 9, 11]:
        return 30
    else:
        return 31

def compute_date_diff(date_a, date_b):
    """Compute the difference between two dates."""
    # Ensure date_a is earlier than or equal to date_b
    if date_a > date_b:
        date_a, date_b = date_b, date_a

    # Initial difference calculation
    y_diff = date_b.year - date_a.year
    m_diff = date_b.month - date_a.month
    d_diff = date_b.day - date_a.day

    # Adjust for negative days
    if d_diff < 0:
        prev_month = date_b.month - 1 if date_b.month > 1 else 12
        days_prev_month = get_days_in_month(date_b.year, prev_month)
        d_diff += days_prev_month
        m_diff -= 1

    # Adjust for negative months
    if m_diff < 0:
        m_diff += 12
        y_diff -= 1

    return y_diff, m_diff, d_diff

