# Simple conversational agent with greeting and question handling

def acknowledge_greeting(text):
    welcome_words = ['hello', 'hi', 'hey', 'hola']
    for token in text.split():
        if token.lower() in welcome_words:
            return "Hello! How can I help you today?"
    return None

def handle_inquiry(text):
    if "how are you" in text.lower():
        return "I'm just a computer program, but thanks for asking! How can I assist you?"
    return None

def process_input(text):
    reply = acknowledge_greeting(text)
    if reply is not None:
        return reply

    reply = handle_inquiry(text)
    if reply is not None:
        return reply

    return "I'm not sure how to respond to that. Could you please rephrase or ask another question?"

