from flask import Flask, jsonify, request
import requests
import time

app = Flask(__name__)

# Configuration for weather API
WEATHER_API_ENDPOINT = "https://api.hypotheticalweatherapi.com/data"
API_KEY_VALUE = "your_api_key_here"

# Rate limiting setup
MAX_REQUESTS_PER_MINUTE = 10
request_count = 0
last_reset_time = time.time()

def fetch_weather_info(location_name, month_number):
    query_params = {
        'city': location_name,
        'month': month_number,
        'api_key': API_KEY_VALUE
    }

    try:
        api_response = requests.get(WEATHER_API_ENDPOINT, params=query_params)
        if api_response.status_code == 200:
            return api_response.json()
        else:
            return None
    except Exception:
        return None

def enforce_rate_policy():
    global request_count, last_reset_time

    current_timestamp = time.time()
    time_elapsed = current_timestamp - last_reset_time

    # Reset counter if more than a minute has passed
    if time_elapsed > 60:
        request_count = 0
        last_reset_time = current_timestamp

    # Check if under rate limit
    if request_count < MAX_REQUESTS_PER_MINUTE:
        request_count += 1
        return True
    else:
        return False

@app.route('/temperature', methods=['GET'])
def temperature_handler():
    # Check rate limit before processing
    if not enforce_rate_policy():
        return jsonify({"error": "Too many requests. Please slow down."}), 429

    # Extract city parameter
    city_param = request.args.get('city')
    if not city_param:
        return jsonify({"error": "Missing required parameter: city"}), 400

    # Collect monthly data
    monthly_records = []
    for month_index in range(1, 13):
        weather_info = fetch_weather_info(city_param, month_index)
        if weather_info:
            monthly_records.append({
                "month": month_index,
                "high_temp": weather_info['highest_temperature'],
                "low_temp": weather_info['lowest_temperature']
            })

    # Handle case with no data
    if not monthly_records:
        return jsonify({"error": "No records found for this city."}), 404

    # Compute annual averages
    high_temps = [record["high_temp"] for record in monthly_records]
    low_temps = [record["low_temp"] for record in monthly_records]

    avg_high = sum(high_temps) / len(high_temps)
    avg_low = sum(low_temps) / len(low_temps)
    overall_avg = (avg_high + avg_low) / 2

    result = {
        "location": city_param,
        "annual_avg_temp": overall_avg,
        "monthly_details": monthly_records
    }

    return jsonify(result)

if __name__ == '__main__':
    app.run(debug=True)

