    global entry_id_sequence
    payload = request.get_json()
    if not payload or 'title' not in payload or 'body' not in payload:
        return jsonify({'error': 'Malformed request'}), 400
    entry = {
        'identifier': entry_id_sequence,
        'title': payload['title'],
        'body': payload['body']
    }
    blog_entries.append(entry)
    entry_id_sequence += 1
    return jsonify(entry), 201

# Endpoint: Modify an existing blog entry
