# Type III Clone: Modified logic using different control flow and variable names,
# but preserving the same functionality and structure

from abc import ABC, abstractmethod

# Abstract Base Class (ABC)
class FinancialAccount(ABC):
    def __init__(self, acc_id, initial_amount=0):
        self.account_identifier = acc_id
        self.current_amount = initial_amount

    @abstractmethod
    def add_funds(self, value):
        pass

    @abstractmethod
    def remove_funds(self, value):
        pass

    @abstractmethod
    def check_amount(self):
        pass

# Concrete Class
class RegularSavings(FinancialAccount):
    def __init__(self, acc_id, initial_amount=0, rate=0.01):
        super().__init__(acc_id, initial_amount)
        self.rate_of_return = rate

    def add_funds(self, value):
        self.current_amount += value
        print(f"Added {value} to Savings Account {self.account_identifier}. Current amount: {self.current_amount}")

    def remove_funds(self, value):
        if value > self.current_amount:
            print("Insufficient funds")
        else:
            self.current_amount -= value
            print(f"Removed {value} from Savings Account {self.account_identifier}. Current amount: {self.current_amount}")

    def check_amount(self):
        return self.current_amount

    def compute_and_apply_interest(self):
        interest = self.current_amount * self.rate_of_return
        self.current_amount += interest
        print(f"Computed interest of {interest} for Savings Account {self.account_identifier}. Current amount: {self.current_amount}")

# Concrete Class
class StandardChecking(FinancialAccount):
    def __init__(self, acc_id, initial_amount=0, max_overdraft=100):
        super().__init__(acc_id, initial_amount)
        self.overdraft_capacity = max_overdraft

    def add_funds(self, value):
        self.current_amount += value
        print(f"Added {value} to Checking Account {self.account_identifier}. Current amount: {self.current_amount}")

    def remove_funds(self, value):
        if value > self.current_amount + self.overdraft_capacity:
            print("Exceeds overdraft capacity")
        else:
            self.current_amount -= value
            print(f"Removed {value} from Checking Account {self.account_identifier}. Current amount: {self.current_amount}")

    def check_amount(self):
        return self.current_amount

# Client Code
def run_operations():
    savings_instance = RegularSavings("SA123456", 1000)
    checking_instance = StandardChecking("CA789012", 500)

    savings_instance.add_funds(500)
    savings_instance.remove_funds(200)
    savings_instance.compute_and_apply_interest()
    print(f"Final amount in Savings Account: {savings_instance.check_amount()}")

    checking_instance.add_funds(300)
    checking_instance.remove_funds(1000)
    print(f"Final amount in Checking Account: {checking_instance.check_amount()}")

if __name__ == "__main__":
    run_operations()

