# Simulate First-Come-First-Serve (FCFS) CPU scheduling algorithm

class Job:
    def __init__(self, identifier, arrival, duration):
        self.identifier = identifier
        self.arrival = arrival
        self.duration = duration
        self.remaining = duration
        self.completion_time = None
        self.start_time = None

    def __str__(self):
        return f"Job(id={self.identifier}, arrival={self.arrival}, duration={self.duration})"

class Scheduler:
    def __init__(self):
        self.jobs = []

    def enqueue(self, job):
        self.jobs.append(job)

    def run(self):
        # Order jobs by their arrival times
        self.jobs.sort(key=lambda j: j.arrival)

        clock = 0
        for job in self.jobs:
            if job.arrival > clock:
                clock = job.arrival
            job.start_time = clock
            clock += job.duration
            job.completion_time = clock

    def timeline(self):
        events = []
        for job in self.jobs:
            events.append((job.start_time, job.completion_time, job.identifier))
        return events

    def mean_wait_time(self):
        total_wait = 0
        for job in self.jobs:
            if job.start_time is not None:
                total_wait += job.start_time - job.arrival
        return total_wait / len(self.jobs) if self.jobs else 0

    def mean_response_time(self):
        total_turnaround = 0
        for job in self.jobs:
            if job.completion_time is not None:
                total_turnaround += job.completion_time - job.arrival
        return total_turnaround / len(self.jobs) if self.jobs else 0

# Demonstration
if __name__ == "__main__":
    cpu_scheduler = Scheduler()

    # Add sample jobs
    cpu_scheduler.enqueue(Job(1, 0, 24))
    cpu_scheduler.enqueue(Job(2, 4, 3))
    cpu_scheduler.enqueue(Job(3, 5, 3))

    # Execute scheduling
    cpu_scheduler.run()

    # Display results
    schedule_events = cpu_scheduler.timeline()
    print("Execution Timeline:")
    for start, finish, job_id in schedule_events:
        print(f"Job {job_id} runs from {start} to {finish}")

    print(f"Mean Waiting Time: {cpu_scheduler.mean_wait_time():.2f}")
    print(f"Mean Response Time: {cpu_scheduler.mean_response_time():.2f}")

