import json

def check_and_process(data):
    if isinstance(data, dict):
        # Check and process the root dictionary
        if 'name' in data:
            name_val = data['name']
            if not (isinstance(name_val, str) and len(name_val) >= 3 and name_val.isalpha()):
                raise ValueError("Invalid 'name' field. Must be a string with at least 3 alphabetic characters.")

        if 'age' in data:
            age_val = data['age']
            if not (isinstance(age_val, int) and 18 <= age_val <= 99):
                raise ValueError("Invalid 'age' field. Must be an integer between 18 and 99 (inclusive).")

        # Process nested structures
        for key, val in data.items():
            if isinstance(val, dict):
                if key == 'address':
                    if not (isinstance(val, str) and val.strip()):
                        raise ValueError("Invalid 'address' field. Must be a non-empty string.")
                check_and_process(val)
            elif isinstance(val, list):
                if key == 'hobbies':
                    if not (isinstance(val, list) and all(isinstance(hobby, str) for hobby in val) and val):
                        raise ValueError("Invalid 'hobbies' field. Must be a non-empty list of strings.")
                for element in val:
                    check_and_process(element)

