# Alternative implementation of cyclic encoding/decoding with different structure

def transform_text(text: str, shift_direction: int, group_size: int = 5, 
                   char_set: str = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ"):
    """
    Core transformation function that handles both encoding and decoding.
    Uses list comprehension and enumerate for cleaner processing.
    """
    if not text:
        return ""

    # Validate character set uniqueness
    if len(set(char_set)) != len(char_set):
        raise ValueError("Character set must contain unique characters")

    # Create mapping from character to position
    char_positions = {char: pos for pos, char in enumerate(char_set)}

    result_parts = []
    # Process text in chunks
    for start_idx in range(0, len(text), group_size):
        chunk = text[start_idx:start_idx + group_size]

        transformed_chunk = []
        for position, symbol in enumerate(chunk):
            if symbol in char_positions:
                original_pos = char_positions[symbol]
                new_pos = (original_pos + shift_direction * group_size) % len(char_set)
                transformed_chunk.append(char_set[new_pos])
            else:
                transformed_chunk.append(symbol)

        result_parts.append("".join(transformed_chunk))

    return "".join(result_parts)

def encode_cyclic(s: str, group_size: int = 5, alphabet: str = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ"):
    """
    Encodes string by applying forward cyclic shift to groups of characters.
    """
    return transform_text(s, shift_direction=1, group_size=group_size, char_set=alphabet)

def decode_cyclic(s: str, group_size: int = 5, alphabet: str = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ"):
    """
    Decodes string by applying reverse cyclic shift to groups of characters.
    """
    return transform_text(s, shift_direction=-1, group_size=group_size, char_set=alphabet)

# Example usage demonstration
if __name__ == "__main__":
    sample_text = "Hello, World! This is a test."

    encoded_result = encode_cyclic(sample_text, group_size=5)
    print(f"Encoded: {encoded_result}")

    decoded_result = decode_cyclic(encoded_result, group_size=5)
    print(f"Decoded: {decoded_result}")

