# Alternative implementation of median calculation using a different approach

def advanced_median(l: list, cmp_func: callable):
    """
    Return median of elements in the list l without sorting it and handles mixed datatypes.
    Handles tuples with variable sizes, duplicates, and uses cmp_func for comparisons.
    """
    def compare_elements(a, b):
        try:
            return cmp_func(a, b)
        except Exception:
            return None

    # Create a copy to avoid modifying original list
    working_list = list(l)

    # Filter out elements that can't be compared with at least one other element
    filtered = []
    for i, item in enumerate(working_list):
        comparable_with_all = True
        for j, other in enumerate(working_list):
            if i != j:
                result = compare_elements(item, other)
                if result is None:
                    comparable_with_all = False
                    break
        if comparable_with_all:
            filtered.append(item)

    if not filtered:
        return None

    n = len(filtered)

    # Helper function for partitioning (Hoare-like scheme)
    def partition_array(arr, start, end):
        pivot_val = arr[end]
        pivot_idx = start

        for i in range(start, end):
            if cmp_func(arr[i], pivot_val) < 0:
                arr[pivot_idx], arr[i] = arr[i], arr[pivot_idx]
                pivot_idx += 1

        arr[pivot_idx], arr[end] = arr[end], arr[pivot_idx]
        return pivot_idx

    # Quickselect implementation to find k-th smallest element
    def select_kth(arr, left, right, k):
        while True:
            if left == right:
                return arr[left]

            pivot_pos = partition_array(arr, left, right)

            if k == pivot_pos:
                return arr[k]
            elif k < pivot_pos:
                right = pivot_pos - 1
            else:
                left = pivot_pos + 1

    # Calculate median based on odd/even count
    if n % 2 == 1:
        return select_kth(filtered, 0, n - 1, n // 2)
    else:
        mid_left = select_kth(filtered, 0, n - 1, n // 2 - 1)
        # Reset filtered list since select_kth modifies it
        filtered_copy = list(filtered)
        mid_right = select_kth(filtered_copy, 0, n - 1, n // 2)
        return (mid_left + mid_right) / 2

# Examples
print(advanced_median([3, 1, 2, 4, 5], lambda a, b: a - b))  # => 3
print(advanced_median([-10, 4, 6, 1000, 10, 20], lambda a, b: a - b))  # => 15.0
print(advanced_median([1, 2, 2, 4, 5], lambda a, b: a - b))  # => 2
print(advanced_median(['a', 'b', 1, 2], lambda a, b: a - b))  # => None

# Extract and visualize hierarchical structure of div elements containing specific keywords

import requests
from bs4 import BeautifulSoup, Tag
import networkx as nx
import matplotlib.pyplot as plt

def retrieve_page_content(target_url):
    try:
        response = requests.get(target_url)
        response.raise_for_status()
        return response.text
    except requests.RequestException as error:
        print(f"Failed to fetch URL: {error}")
        return None

def process_html_content(html_text):
    return BeautifulSoup(html_text, 'html.parser')

def select_relevant_divs(parsed_page, search_terms):
    def matches_any_term(element, terms):
        if isinstance(element, Tag):
            # Check text content
            if element.string and any(term in element.string for term in terms):
                return True
            # Check all attributes
            for attribute, attr_value in element.attrs.items():
                if isinstance(attr_value, str) and any(term in attr_value for term in terms):
                    return True
            # Recursively check child elements
            for descendant in element.descendants:
                if matches_any_term(descendant, terms):
                    return True
        return False

    all_divs = parsed_page.find_all('div')
    relevant_divs = [div for div in all_divs if matches_any_term(div, search_terms)]
    return relevant_divs

def construct_hierarchy(root_element, current_parent=None, graph_structure=None):
    if graph_structure is None:
        graph_structure = nx.DiGraph()
        node_label = root_element.get('id', root_element.get('class', ['div'])[0] if isinstance(root_element.get('class'), list) else root_element.get('class', 'div'))
        graph_structure.add_node(root_element, label=node_label)
        current_parent = root_element

    for child_node in root_element.children:
        if isinstance(child_node, Tag):
            child_label = child_node.get('id', child_node.get('class', ['div'])[0] if isinstance(child_node.get('class'), list) else child_node.get('class', 'div'))
            graph_structure.add_node(child_node, label=child_label)
            graph_structure.add_edge(current_parent, child_node)
            construct_hierarchy(child_node, child_node, graph_structure)

    return graph_structure

def display_hierarchy(graph):
    plt.figure(figsize=(14, 10))
    layout_positions = nx.drawing.nx_agraph.graphviz_layout(graph, prog='dot')
    node_labels = {node: info['label'] for node, info in graph.nodes(data=True)}
    nx.draw(graph, layout_positions, with_labels=True, labels=node_labels, 
            node_size=3500, node_color='#add8e6', font_size=9, font_weight='bold')
    plt.title("Tree Structure of Div Elements Matching Keywords")
    plt.show()

def execute_analysis(page_url, filter_keywords):
    page_content = retrieve_page_content(page_url)
    if page_content:
        parsed_page = process_html_content(page_content)
        matching_divs = select_relevant_divs(parsed_page, filter_keywords)
        if matching_divs:
            hierarchy_tree = construct_hierarchy(matching_divs[0])
            display_hierarchy(hierarchy_tree)
        else:
            print("No div elements matched the provided keywords.")

if __name__ == "__main__":
    target_url = "https://example.com"  # Replace with actual target URL
    keywords_list = ["keyword1", "keyword2"]  # Replace with desired search terms
    execute_analysis(target_url, keywords_list)

# Parse SQL to extract selected fields and source tables

import sqlparse

def retrieve_fields_and_sources(sql_text):
    parsed_queries = sqlparse.parse(sql_text)
    current_statement = parsed_queries[0]

    selected_fields = []
    source_tables = []

    # Identify selected fields in the SELECT part
    for token in current_statement.tokens:
        if isinstance(token, sqlparse.sql.IdentifierList):
            for item in token.get_identifiers():
                if '.' in str(item):
                    selected_fields.append(str(item))
        elif isinstance(token, sqlparse.sql.Identifier):
            if '.' in str(token):
                selected_fields.append(str(token))

    # Locate tables listed after FROM keyword
    found_from = False
    for token in current_statement.tokens:
        if isinstance(token, sqlparse.sql.Token) and token.ttype is sqlparse.tokens.Keyword and token.value.upper() == 'FROM':
            found_from = True
        elif found_from and isinstance(token, sqlparse.sql.IdentifierList):
            for item in token.get_identifiers():
                source_tables.append(str(item))
            found_from = False
        elif found_from and isinstance(token, sqlparse.sql.Identifier):
            source_tables.append(str(token))
            found_from = False

    return selected_fields, source_tables

