import re

def check_palindrome(text):
    # Filter out non-alphanumeric characters and normalize to lowercase
    normalized = re.sub(r'[^a-zA-Z0-9]', '', text).lower()
    # Compare string with its reverse
    return normalized == ''.join(reversed(normalized))

def compute_ascii_total(text):
    total = 0
    for char in text:
        total += ord(char)
    return total

def analyze_texts(texts):
    output = {}
    for text in texts:
        is_pal = check_palindrome(text)
        status = 'yes' if is_pal else 'no'
        ascii_val = compute_ascii_total(text) if is_pal else None
        output[text] = (status, ascii_val)
    return output

