from typing import List, Union

class ExpressionElement:
    def __init__(self, data):
        self.data = data
        self.left = None
        self.right = None

    def is_operator(self) -> bool:
        return isinstance(self.data, str) and self.data in "+-*/"

    def is_operand(self) -> bool:
        return isinstance(self.data, int)

def create_operand(value: int) -> ExpressionElement:
    return ExpressionElement(value)

def create_operator(op: str, left: ExpressionElement, right: ExpressionElement) -> ExpressionElement:
    node = ExpressionElement(op)
    node.left = left
    node.right = right
    return node

def compute_expression(node: ExpressionElement) -> int:
    if node.is_operand():
        return node.data

    left_val = compute_expression(node.left)
    right_val = compute_expression(node.right)

    if node.data == '+':
        return left_val + right_val
    elif node.data == '-':
        return left_val - right_val
    elif node.data == '*':
        return left_val * right_val
    elif node.data == '/':
        return left_val // right_val

def format_expression(node: ExpressionElement) -> str:
    if node.is_operand():
        return str(node.data)

    left_expr = format_expression(node.left)
    right_expr = format_expression(node.right)

    # Only add parentheses when needed (for binary operators)
    return f"({left_expr} {node.data} {right_expr})"

def construct_tree(postfix_tokens: List[str]) -> ExpressionElement:
    stack = []

    for token in postfix_tokens:
        if token.isdigit():
            stack.append(create_operand(int(token)))
        else:
            right_operand = stack.pop()
            left_operand = stack.pop()
            stack.append(create_operator(token, left_operand, right_operand))

    return stack[0]

def evaluate_postfix(postfix: List[str]) -> tuple:
    expression_tree = construct_tree(postfix)
    computed_result = compute_expression(expression_tree)
    formatted_string = format_expression(expression_tree)
    return (computed_result, formatted_string)

