# Create a 3x3 Tic-Tac-Toe game board

def create_grid():
    return [[0 for _ in range(3)] for _ in range(3)]

def display_grid(grid):
    for row in grid:
        print(" ".join(["X" if cell == 1 else "O" if cell == 2 else "." for cell in row]))

def is_cell_empty(grid, r, c):
    return grid[r][c] == 0

def place_mark(grid, r, c, player):
    if is_cell_empty(grid, r, c):
        grid[r][c] = player
        return True
    return False

def has_won(grid, player):
    # Check rows and columns
    for i in range(3):
        if all(grid[i][j] == player for j in range(3)) or \
           all(grid[j][i] == player for j in range(3)):
            return True

    # Check diagonals
    if all(grid[i][i] == player for i in range(3)) or \
       all(grid[i][2-i] == player for i in range(3)):
        return True

    return False

def grid_is_full(grid):
    return all(cell != 0 for row in grid for cell in row)

def run_game():
    grid = create_grid()
    turn = 1

    while True:
        display_grid(grid)
        r = int(input(f"Player {turn}, enter row (0-2): "))
        c = int(input(f"Player {turn}, enter column (0-2): "))

        if place_mark(grid, r, c, turn):
            if has_won(grid, turn):
                display_grid(grid)
                print(f"Player {turn} wins!")
                break
            elif grid_is_full(grid):
                display_grid(grid)
                print("It's a draw!")
                break
            turn = 3 - turn  # Switch player (1 -> 2, 2 -> 1)
        else:
            print("Invalid move. Try again.")

run_game()

