# Filter even and prime numbers from two lists, combine them, and sort in descending order

def collect_special_numbers(list_a: list, list_b: list) -> list:
    """Extract numbers that are either even or prime (and non-negative), then return them sorted in descending order."""

    def check_prime(value: int) -> bool:
        """Determine if a number is prime using optimized trial division."""
        if value < 2:
            return False
        if value == 2:
            return True
        if value % 2 == 0:
            return False
        divisor = 3
        while divisor * divisor <= value:
            if value % divisor == 0:
                return False
            divisor += 2
        return True

    def combine_and_order(items: list) -> list:
        """Combine the filtered items and arrange them from largest to smallest."""
        result = items.copy()
        result.sort(reverse=True)
        return result

    # Collect qualifying numbers from both input lists
    selected_values = []
    for number in list_a + list_b:
        if number >= 0 and (number % 2 == 0 or check_prime(number)):
            selected_values.append(number)

    return combine_and_order(selected_values)

