import json
from typing import List, Dict, Optional

class LiteratureItem:
    def __init__(self, name: str, identifier: str, creator: str, release_year: str, category: str):
        self.name = name
        self.identifier = identifier
        self.creator = creator
        self.release_year = release_year
        self.category = category

    def serialize(self) -> Dict:
        return {
            'name': self.name,
            'identifier': self.identifier,
            'creator': self.creator,
            'release_year': self.release_year,
            'category': self.category
        }

    @classmethod
    def deserialize(cls, record: Dict):
        return cls(
            name=record['name'],
            identifier=record['identifier'],
            creator=record['creator'],
            release_year=record['release_year'],
            category=record['category']
        )

class Collection:
    def __init__(self, storage_path: str = 'collection_records.json'):
        self.storage_path = storage_path
        self.items_by_name = {}
        self.items_by_id = {}
        self.restore()

    def add_item(self, name: str, identifier: str, creator: str, release_year: str, category: str):
        if identifier in self.items_by_id:
            raise ValueError(f"An item with ID {identifier} already exists.")
        item = LiteratureItem(name, identifier, creator, release_year, category)
        if name not in self.items_by_name:
            self.items_by_name[name] = []
        self.items_by_name[name].append(item)
        self.items_by_id[identifier] = item
        self.record()

    def find_by_name(self, name: str) -> List[LiteratureItem]:
        return self.items_by_name.get(name, [])

    def find_by_id(self, identifier: str) -> Optional[LiteratureItem]:
        return self.items_by_id.get(identifier)

    def find_fuzzy(self, keyword: str) -> List[LiteratureItem]:
        matches = []
        for item_list in self.items_by_name.values():
            for item in item_list:
                if keyword in item.name or keyword in item.identifier:
                    matches.append(item)
        return matches

    def delete_item(self, name: str = None, identifier: str = None):
        if name and identifier:
            raise ValueError("Specify either name or identifier, not both.")
        if name:
            if name in self.items_by_name:
                for item in self.items_by_name[name]:
                    del self.items_by_id[item.identifier]
                del self.items_by_name[name]
        elif identifier:
            if identifier in self.items_by_id:
                item = self.items_by_id[identifier]
                self.items_by_name[item.name].remove(item)
                if not self.items_by_name[item.name]:
                    del self.items_by_name[item.name]
                del self.items_by_id[identifier]
        self.record()

    def record(self):
        with open(self.storage_path, 'w') as file:
            data = {identifier: item.serialize() for identifier, item in self.items_by_id.items()}
            json.dump(data, file, indent=4)

    def restore(self):
        try:
            with open(self.storage_path, 'r') as file:
                data = json.load(file)
                for identifier, item_data in data.items():
                    item = LiteratureItem.deserialize(item_data)
                    if item.name not in self.items_by_name:
                        self.items_by_name[item.name] = []
                    self.items_by_name[item.name].append(item)
                    self.items_by_id[identifier] = item
        except FileNotFoundError:
            pass

