from typing import List, Dict, Any, Optional


class CustomIterator:
    def __init__(self, items):
        self.items = items
        self.position = 0

    def __iter__(self):
        return self

    def __next__(self):
        if self.position >= len(self.items):
            raise StopIteration
        value = self.items[self.position]
        self.position += 1
        return value


class TableData:
    def __init__(self, records: Optional[Dict[str, List[Any]]] = None, field_names: Optional[List[str]] = None):
        if not records and not field_names:
            self.fields = {}
            self.field_list = []
        elif field_names:
            self.field_list = field_names
            self.fields = {name: CustomIterator([]) for name in field_names}
        else:
            raise ValueError("Field names must be provided when data is present")
        if records:
            for field, values in records.items():
                if field not in self.field_list:
                    self.field_list.append(field)
                self.fields[field].items = values
        self.row_map = {}

    def define_key(self, key_field: str):
        if key_field in self.fields.keys():
            temp_col = self.fields.pop(key_field)
            self.row_map = {val: idx for idx, val in enumerate(temp_col.items)}

    def assign_column(self, col_label: str, col_values: List[Any]):
        if col_label not in self.field_list:
            self.field_list.append(col_label)
            self.fields[col_label] = CustomIterator([])
        self.fields[col_label].items = col_values

    def get_column(self, col_label: str) -> CustomIterator:
        return self.fields[col_label]

    def locate_row(self, row_key: str) -> Dict[str, Any]:
        pos = self.row_map[row_key]
        return {field: self.fields[field].items[pos] for field in self.field_list}

    def column_pairs(self):
        return self.fields.items()

    def row_entries(self):
        for name, position in self.row_map.items():
            record = self.locate_row(name)
            yield name, record

    def convert_type(self, target_type: type, col_name: Optional[str] = None):
        if col_name:
            self.fields[col_name] = CustomIterator([target_type(x) for x in self.fields[col_name].items])
        else:
            for field in self.field_list:
                self.fields[field] = CustomIterator([target_type(x) for x in self.fields[field].items])

    def remove_column(self, col_label: str):
        if col_label in self.field_list:
            self.field_list.remove(col_label)
            self.fields.pop(col_label)

    def average_values(self) -> Dict[str, float]:
        output = {}
        for field in self.field_list:
            total = sum(self.fields[field].items)
            avg = total / len(self.fields[field].items)
            output[field] = avg
        return output

    def __str__(self):
        rows = [self.field_list]
        for record in zip(*[self.fields[f].items for f in self.field_list]):
            rows.append(list(record))
        return "\n".join(["\t".join([str(item) for item in row]) for row in rows])


