import threading
import time
import uuid

class TimerController:
    def __init__(self):
        self.active_timers = {}
        self.sync_lock = threading.Lock()

    def initiate_timer(self, interval, handler=None):
        if not isinstance(interval, int) or interval <= 0:
            raise ValueError("Interval must be a positive integer greater than 0")

        timer_key = str(uuid.uuid4())
        new_timer = Countdown(interval, handler, self._timer_ended, timer_key)
        new_timer.launch()

        with self.sync_lock:
            self.active_timers[timer_key] = new_timer

        return timer_key

    def _timer_ended(self, timer_key):
        with self.sync_lock:
            timer = self.active_timers.pop(timer_key, None)
            if timer and timer.on_complete:
                timer.on_complete()

    def suspend_timer(self, timer_key):
        with self.sync_lock:
            timer = self.active_timers.get(timer_key)
            if timer:
                timer.suspend()

    def reactivate_timer(self, timer_key):
        with self.sync_lock:
            timer = self.active_timers.get(timer_key)
            if timer:
                timer.reactivate()

    def terminate_timer(self, timer_key):
        with self.sync_lock:
            timer = self.active_timers.pop(timer_key, None)
            if timer:
                timer.stop()

class Countdown:
    def __init__(self, total_time, on_complete, expiration_handler, identifier):
        self.total_time = total_time
        self.on_complete = on_complete
        self.expiration_handler = expiration_handler
        self.identifier = identifier
        self.worker_thread = None
        self.is_active = False
        self.is_suspended = False
        self.time_left = total_time

    def launch(self):
        if not self.is_active:
            self.is_active = True
            self.worker_thread = threading.Thread(target=self._countdown_loop)
            self.worker_thread.start()

    def _countdown_loop(self):
        initial_timestamp = time.time()
        while self.time_left > 0 and not self.is_suspended:
            current_timestamp = time.time()
            elapsed = current_timestamp - initial_timestamp
            self.time_left = max(0.0, self.total_time - elapsed)
            time.sleep(0.1)

        if self.time_left <= 0:
            self.expiration_handler(self.identifier)

    def suspend(self):
        if self.is_active and not self.is_suspended:
            self.is_suspended = True

    def reactivate(self):
        if self.is_active and self.is_suspended:
            self.is_suspended = False
            self.worker_thread = threading.Thread(target=self._countdown_loop)
            self.worker_thread.start()

    def stop(self):
        self.is_active = False
        self.is_suspended = False
        if self.worker_thread and self.worker_thread.is_alive():
            self.worker_thread.join()

