# Recursive solution for Tower of Hanoi problem

def move_disks(count, from_rod, via_rod, to_rod, step_count):
    if count == 1:
        print(f"Step {step_count}: Move disk 1 from {from_rod} to {to_rod}")
        return step_count + 1
    else:
        # Move top n-1 disks from source to auxiliary rod
        step_count = move_disks(count - 1, from_rod, to_rod, via_rod, step_count)

        # Move the largest disk from source to target rod
        print(f"Step {step_count}: Move disk {count} from {from_rod} to {to_rod}")
        step_count += 1

        # Move n-1 disks from auxiliary to target rod
        step_count = move_disks(count - 1, via_rod, from_rod, to_rod, step_count)
        return step_count

def execute_hanoi_solution(disks):
    if not isinstance(disks, int) or disks <= 0:
        raise ValueError("Number of disks must be a positive integer.")

    print(f"Tower of Hanoi solution for {disks} disks:")
    final_step = move_disks(disks, 'Peg X', 'Peg Y', 'Peg Z', 1)
    print(f"Total moves required: {final_step - 1}")

