# Filter and sort students based on criteria

def process_student_records(student_dict, threshold_height, threshold_weight, threshold_age, threshold_gpa):
    def validate_entry(record):
        if not isinstance(record, tuple) or len(record) != 4:
            return False
        for item in record:
            if not isinstance(item, (int, float)):
                return False
        return True

    def transform_to_floats(record):
        try:
            return tuple(float(value) for value in record)
        except (TypeError, ValueError):
            raise TypeError(f"Non-numeric data encountered: {record}")

    qualifying_students = []
    for student_name, metrics in student_dict.items():
        if not validate_entry(metrics):
            raise ValueError(f"Incorrect record for {student_name}: {metrics}")
        h, w, a, g = transform_to_floats(metrics)
        if h >= threshold_height and w >= threshold_weight and a >= threshold_age and g >= threshold_gpa:
            qualifying_students.append((student_name, h, w, a, g))

    # Order by age (high to low), then GPA (high to low), then name (A-Z)
    qualifying_students.sort(key=lambda entry: (-entry[3], -entry[4], entry[0]))

    return qualifying_students

