        return has_all_required and pair_count == 1

    def check_seven_pairs(self):
        # Confirm exactly seven distinct pairs exist
        unique_tiles = list(set(self.tiles))
        pair_tiles = [tile for tile in unique_tiles if self.tiles.count(tile) == 2]
        return len(pair_tiles) == 7

    def check_complete_triplets(self):
        # Validate that all tiles form triplets (3 of a kind)
        tile_frequency = {}
        for tile in self.tiles:
