# Alternative implementation of list processing functions

def flatten_list(nested):
    """Recursively flattens a nested list structure."""
    flat = []
    for element in nested:
        if isinstance(element, list):
            flat.extend(flatten_list(element))
        else:
            flat.append(element)
    return flat

def deduplicate_sequence(seq):
    """Removes duplicate items while maintaining original order."""
    seen_items = set()
    unique_items = []
    for value in seq:
        if value not in seen_items:
            seen_items.add(value)
            unique_items.append(value)
    return unique_items

def analyze_data(group_a, group_b, tasks):
    # Input validation
    if not isinstance(group_a, list) or not isinstance(group_b, list) or not isinstance(tasks, list):
        return "Error: All inputs must be lists."

    # Handle empty input case
    if len(group_a) == 0 and len(group_b) == 0:
        return "Error: Both lists are empty."

    # Return original lists if no operations specified
    if len(tasks) == 0:
        return group_a, group_b

    output = []
    for task in tasks:
        try:
            # Flatten both groups once per operation
            flat_a = flatten_list(group_a)
            flat_b = flatten_list(group_b)

            if task == "merge":
                combined = flat_a + flat_b
            elif task == "common_elements":
                combined = list(set(flat_a) & set(flat_b))
            elif task == "unique_elements":
                combined = list(set(flat_a) ^ set(flat_b))
            elif task == "sort_in_descending":
                combined = sorted(flat_a + flat_b, reverse=True)
            elif task == "element_difference":
                min_len = min(len(flat_a), len(flat_b))
                combined = [flat_a[i] - flat_b[i] for i in range(min_len)]
            elif task == "length_of_list":
                combined = [len(flat_a), len(flat_b)]
            elif task == "sum_of_elements":
                combined = [sum(flat_a), sum(flat_b)]
            elif task == "average_of_elements":
                from statistics import mean
                combined = [mean(flat_a) if flat_a else 0, mean(flat_b) if flat_b else 0]
            elif task == "max_element":
                combined = [max(flat_a) if flat_a else None, max(flat_b) if flat_b else None]
            elif task == "min_element":
                combined = [min(flat_a) if flat_a else None, min(flat_b) if flat_b else None]
            elif task == "flatten_nested_list":
                combined = flatten_list(group_a + group_b)
            elif task == "remove_duplicates":
                combined = deduplicate_sequence(flatten_list(group_a + group_b))
            elif task == "find_median":
                from statistics import median
                combined = [median(flat_a) if flat_a else 0, median(flat_b) if flat_b else 0]
            elif task == "find_mode":
                from statistics import mode
                combined = [mode(flat_a) if flat_a else None, mode(flat_b) if flat_b else None]
            elif task == "find_range":
                combined = [(max(flat_a) - min(flat_a)) if flat_a else 0, 
                           (max(flat_b) - min(flat_b)) if flat_b else 0]
            elif task == "find_standard_deviation":
                from statistics import stdev
                combined = [stdev(flat_a) if len(flat_a) > 1 else 0, 
                           stdev(flat_b) if len(flat_b) > 1 else 0]
            elif task == "find_variance":
                from statistics import variance
                combined = [variance(flat_a) if len(flat_a) > 1 else 0, 
                           variance(flat_b) if len(flat_b) > 1 else 0]
            elif task == "find_percentile":
                import numpy as np
                combined = [np.percentile(flat_a, 50) if flat_a else 0,
                           np.percentile(flat_b, 50) if flat_b else 0]
            elif task == "find_quartile":
                from statistics import quantiles
                combined = [quantiles(flat_a, n=4) if len(flat_a) >= 2 else [],
                           quantiles(flat_b, n=4) if len(flat_b) >= 2 else []]
            elif task == "find_interquartile_range":
                from statistics import quantiles
                q1_a, q3_a = quantiles(flat_a, n=4)[1], quantiles(flat_a, n=4)[2] if len(flat_a) >= 2 else (0, 0)
                iqr_a = q3_a - q1_a
                q1_b, q3_b = quantiles(flat_b, n=4)[1], quantiles(flat_b, n=4)[2] if len(flat_b) >= 2 else (0, 0)
                iqr_b = q3_b - q1_b
                combined = [iqr_a, iqr_b]
            else:
                return f"Error: Undefined operation '{task}'."

            # Sort results in descending order before appending
            output.append(sorted(combined, reverse=True))
        except Exception as error:
            return f"Error: {str(error)}"

    return output

