# URL construction and validation utility module

import re
import random
import string
import logging

# Setup logging configuration
logging.basicConfig(level=logging.DEBUG, format='%(asctime)s - %(levelname)s - %(message)s')

class WebAddressHandler:
    def __init__(self, scheme, prefix, main_domain, tld_suffix, path_segment):
        self.scheme = scheme
        self.prefix = prefix
        self.main_domain = main_domain
        self.tld_suffix = tld_suffix
        self.path_segment = path_segment

    def build_web_address(self):
        if not self.check_integrity():
            return None
        return f"{self.scheme}://{self.prefix}.{self.main_domain}{self.tld_suffix}/{self.transform_path()}"

    def parse_web_address(self, address):
        regex_pattern = r'^(?P<scheme>[a-zA-Z]+)://(?P<prefix>[a-zA-Z0-9-]+)\.(?P<main_domain>[a-zA-Z0-9-]+)(?P<tld_suffix>\.[a-zA-Z]{2,6})/(?P<path_segment>.+)$'
        result = re.match(regex_pattern, address)
        if result:
            return result.groupdict()
        else:
            logging.error(f"Malformed web address: {address}")
            return None

    def check_integrity(self):
        if not all([self.scheme, self.prefix, self.main_domain, self.tld_suffix, self.path_segment]):
            logging.error("All web address components must be present.")
            return False
        if self.scheme.lower() not in ['http', 'https', 'ftp', 'sftp']:
            logging.error(f"Unsupported scheme: {self.scheme}")
            return False
        if not re.match(r'^[a-zA-Z0-9-]+$', self.prefix):
            logging.error(f"Invalid prefix: {self.prefix}")
            return False
        if not re.match(r'^[a-zA-Z0-9-]+$', self.main_domain):
            logging.error(f"Invalid main domain: {self.main_domain}")
            return False
        if not re.match(r'^\.[a-zA-Z]{2,6}$', self.tld_suffix):
            logging.error(f"Invalid TLD suffix: {self.tld_suffix}")
            return False
        return True

    def transform_path(self, use_randomization=False):
        if use_randomization:
            return self.apply_random_transformation()
        else:
            return self.apply_deterministic_transformation()

    def apply_deterministic_transformation(self):
        def replace_char(match):
            return f"%{ord(match.group(0)):02X}"
        return re.sub(r'[^a-zA-Z0-9/]', replace_char, self.path_segment)

    def apply_random_transformation(self):
        transformed = ""
        for symbol in self.path_segment:
            if re.match(r'[^a-zA-Z0-9/]', symbol):
                if random.choice([True, False]):
                    transformed += f"%{ord(symbol):02X}"
                else:
                    transformed += symbol
            else:
                transformed += symbol
        return transformed

