def check_numeric_bounds(val, val_type, min_val, max_val):
    if not isinstance(val, val_type):
        return f"not a {val_type.__name__}"
    if val < min_val or val > max_val:
        return f"{val_type.__name__} outside allowed range [{min_val}-{max_val}]."
    return "valid"

def ensure_non_default(val, val_type, default_val):
    if not isinstance(val, val_type):
        return f"not a {val_type.__name__}"
    if val == default_val:
        return f"value matches default ({default_val}) - verify this is intentional."
    return "valid"

