# Monitor and accumulate time spent using web browsers

import os
import time
from datetime import datetime, timedelta

# Supported browser process identifiers
BROWSER_IDENTIFIERS = ['chrome', 'firefox', 'safari', 'msedge', 'opera', 'brave']

def retrieve_active_title():
    """ Retrieve the title of the currently focused window. """
    if os.name == 'nt':  # Windows platform
        try:
            import win32gui
            return win32gui.GetWindowText(win32gui.GetForegroundWindow())
        except ImportError:
            print("Required module not found: pip install pywin32")
            return None
    elif os.name == 'posix':  # Unix-like systems (Linux/macOS)
        try:
            import subprocess
            output = subprocess.check_output(["xdotool", "getwindowfocus", "getwindowname"], stderr=subprocess.DEVNULL)
            return output.strip().decode()
        except (ImportError, subprocess.CalledProcessError):
            print("Missing dependency: sudo apt-get install xdotool")
            return None
    else:
        return None

def is_web_browser_running():
    """ Determine if the active window corresponds to a known web browser. """
    current_title = retrieve_active_title()
    if current_title:
        for identifier in BROWSER_IDENTIFIERS:
            if identifier in current_title.lower():
                return True
    return False

def monitor_browser_usage():
    """ Continuously monitor and log cumulative browser usage time. """
    session_start = None
    accumulated_duration = timedelta()

    while True:
        if is_web_browser_running():
            if session_start is None:
                session_start = datetime.now()
        else:
            if session_start is not None:
                session_end = datetime.now()
                accumulated_duration += session_end - session_start
                session_start = None
                print(f"Accumulated browser time: {accumulated_duration}")

        time.sleep(1)  # Poll interval set to one second

if __name__ == "__main__":
    monitor_browser_usage()

# Alternative implementation to find prime numbers and compute their products

def is_prime_number(n):
    """Determine if a number is prime using optimized trial division."""
    if n < 2:
        return False
    if n == 2 or n == 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False

    # Check divisors of the form 6k ± 1 up to sqrt(n)
    divisor = 5
    while divisor * divisor <= n:
        if n % divisor == 0 or n % (divisor + 2) == 0:
            return False
        divisor += 6
    return True

def extract_primes_and_products(data_sets):
    output = []

    for dataset in data_sets:
        primes_list = []
        try:
            for item in dataset:
                if not isinstance(item, int):
                    raise ValueError(f"Non-integer value encountered: {item}")
                if is_prime_number(item):
                    primes_list.append(item)
        except Exception as error:
            print(f"Processing issue detected: {error}")
            continue

        primes_list.sort()

        # Calculate product of primes (1 if no primes found)
        prime_product = 1
        for p in primes_list:
            prime_product *= p

        output.append((primes_list, prime_product))

    return output

