# Flask-based notes API with SQLite backend - refactored logic

from flask import Flask, request, jsonify, g
import sqlite3

app = Flask(__name__)
DB_FILE = 'notes.db'

def establish_db_connection():
    """Get or create a database connection for the current request context."""
    db_conn = getattr(g, '_db_instance', None)
    if db_conn is None:
        db_conn = g._db_instance = sqlite3.connect(DB_FILE)
    return db_conn

@app.teardown_appcontext
def release_db_connection(exception):
    """Close database connection when the application context ends."""
    db_conn = getattr(g, '_db_instance', None)
    if db_conn is not None:
        db_conn.close()

def setup_database():
    """Initialize the database schema within the app context."""
    with app.app_context():
        conn = establish_db_connection()
        with app.open_resource('schema.sql', mode='r') as schema_file:
            conn.cursor().executescript(schema_file.read())
        conn.commit()

@app.route('/notes', methods=['GET'])
def list_notes():
    """Retrieve all notes from the database."""
    conn = establish_db_connection()
    cursor = conn.execute('SELECT id, title, content FROM notes')
    notes_data = cursor.fetchall()

    formatted_notes = [
        {'id': note[0], 'title': note[1], 'content': note[2]} 
        for note in notes_data
    ]
    return jsonify(formatted_notes)

@app.route('/notes', methods=['POST'])
def add_note():
    """Create a new note with provided title and content."""
    payload = request.get_json()
    note_title = payload.get('title')
    note_content = payload.get('content')

    if not note_title or not note_content:
        return jsonify({'error': 'Title and content fields are mandatory'}), 400

    conn = establish_db_connection()
    conn.execute(
        'INSERT INTO notes (title, content) VALUES (?, ?)', 
        (note_title, note_content)
    )
    conn.commit()

    return jsonify({'message': 'Note added successfully'}), 201

@app.route('/notes/<int:note_identifier>', methods=['GET'])
def fetch_single_note(note_identifier):
    """Retrieve a specific note by its ID."""
    conn = establish_db_connection()
    cursor = conn.execute(
        'SELECT id, title, content FROM notes WHERE id = ?', 
        (note_identifier,)
    )
    note = cursor.fetchone()

    if note is None:
        return jsonify({'error': 'Requested note does not exist'}), 404

    return jsonify({
        'id': note[0], 
        'title': note[1], 
        'content': note[2]
    })

@app.route('/notes/<int:note_identifier>', methods=['PUT'])
def modify_note(note_identifier):
    """Update an existing note with new title and content."""
    payload = request.get_json()
    updated_title = payload.get('title')
    updated_content = payload.get('content')

    if not updated_title or not updated_content:
        return jsonify({'error': 'Title and content fields are required'}), 400

    conn = establish_db_connection()
    cursor = conn.execute(
        'UPDATE notes SET title = ?, content = ? WHERE id = ?', 
        (updated_title, updated_content, note_identifier)
    )

    if cursor.rowcount == 0:
        return jsonify({'error': 'Note to update was not found'}), 404

    conn.commit()
    return jsonify({'message': 'Note updated successfully'})

