# Custom hash table implementation with separate chaining for collision resolution

class Dictionary:
    def __init__(self, capacity=100):
        self.capacity = capacity
        self.buckets = [None] * capacity

    def _compute_index(self, item_key):
        # Compute bucket index using Python's built-in hash and modulo operation
        return hash(item_key) % self.capacity

    def add(self, key, value):
        bucket_index = self._compute_index(key)
        if self.buckets[bucket_index] is None:
            self.buckets[bucket_index] = []

        # Check if key already exists to update its value
        for position, (stored_key, stored_value) in enumerate(self.buckets[bucket_index]):
            if stored_key == key:
                self.buckets[bucket_index][position] = (key, value)
                return

        # If key doesn't exist, append new key-value pair
        self.buckets[bucket_index].append((key, value))

    def fetch(self, key):
        bucket_index = self._compute_index(key)
        if self.buckets[bucket_index] is not None:
            for stored_key, stored_value in self.buckets[bucket_index]:
                if stored_key == key:
                    return stored_value
        raise KeyError(f"Key '{key}' does not exist in dictionary")

    def remove(self, key):
        bucket_index = self._compute_index(key)
        if self.buckets[bucket_index] is not None:
            for position, (stored_key, _) in enumerate(self.buckets[bucket_index]):
                if stored_key == key:
                    del self.buckets[bucket_index][position]
                    return
        raise KeyError(f"Key '{key}' does not exist in dictionary")

    def __str__(self):
        return str(self.buckets)

# Demonstration of usage:
dictionary = Dictionary()
dictionary.add('apple', 10)
dictionary.add('banana', 20)
print(dictionary.fetch('apple'))  # Output: 10
dictionary.remove('banana')
print(dictionary)  # Output: [None, ..., [('apple', 10)], ..., None]

# Alternative implementation: Code analyzer using AST and linting tools

import ast
from pylint import epylint as lint
import astroid

def run_linter_on_source(source_code):
    """Run Pylint on source code and return raw output lines."""
    (stdout, _) = lint.py_run(source_code, return_std=True)
    return stdout.readlines()

def extract_issues_from_output(raw_lines):
    """Parse raw Pylint output into structured issue records."""
    issues = []
    for line in raw_lines:
        parts = line.strip().split(':')
        if len(parts) >= 4 and parts[0].endswith('.py'):
            try:
                lineno = int(parts[1])
                colno = int(parts[2])
                msg_type = parts[3].strip().split()[0]
                message = ':'.join(parts[3:]).strip()
                issues.append({
                    'line': lineno,
                    'column': colno,
                    'type': msg_type,
                    'description': message
                })
            except (ValueError, IndexError):
                continue  # Skip malformed lines
    return issues

def build_ast_tree(code_string):
    """Parse code string into an AST node."""
    return ast.parse(code_string)

def detect_patterns_in_ast(tree_root):
    """Scan AST for specific patterns that may be improved."""
    findings = []
    for node in ast.walk(tree_root):
        if isinstance(node, ast.ListComp):
            findings.append({
                'location': (node.lineno, node.col_offset),
                'pattern': 'list_comprehension',
                'note': "List comprehension detected — consider if readability can be enhanced further."
            })
        elif isinstance(node, ast.Call):
            if isinstance(node.func, ast.Name) and node.func.id == 'print':
                findings.append({
                    'location': (node.lineno, node.col_offset),
                    'pattern': 'print_call',
                    'note': "Print statement found — ensure it's not used for debugging in production."
                })
    return findings

def generate_recommendations(issues, ast_findings):
    """Combine lint results and AST analysis to produce improvement ideas."""
    recommendations = []

    # Add recommendations based on Pylint messages
    for issue in issues:
        if issue['type'] == 'C0102' or 'blacklisted-name' in issue['description'].lower():
            recommendations.append({
                'line': issue['line'],
                'col': issue['column'],
                'text': "Avoid blacklisted variable names like 'l', 'O', or 'I'."
            })
        elif issue['type'] == 'R1702' or 'too-many-nested-blocks' in issue['description'].lower():
            recommendations.append({
                'line': issue['line'],
                'col': issue['column'],
                'text': "Consider refactoring deeply nested loops for clarity."
            })

    # Add recommendations from AST pattern detection
    for finding in ast_findings:
        if finding['pattern'] == 'list_comprehension':
            recommendations.append({
                'line': finding['location'][0],
                'col': finding['location'][1],
                'text': "You're using a list comprehension — great! Ensure it doesn’t sacrifice readability."
            })
        elif finding['pattern'] == 'print_call':
            recommendations.append({
                'line': finding['location'][0],
                'col': finding['location'][1],
                'text': "Review print usage — logging might be more appropriate than print in modules."
            })

    return recommendations

def execute_analysis(code_input):
    """Main orchestration function to analyze code and report findings."""
    ast_tree = build_ast_tree(code_input)
    lint_output = run_linter_on_source(code_input)
    parsed_issues = extract_issues_from_output(lint_output)
    ast_patterns = detect_patterns_in_ast(ast_tree)
    recommendations = generate_recommendations(parsed_issues, ast_patterns)

    print("🔍 Lint Findings:")
    for issue in parsed_issues:
        print(f"  Line {issue['line']}, Col {issue['column']}: [{issue['type']}] {issue['description']}")

    print("\n💡 Suggested Improvements:")
    for idx, rec in enumerate(recommendations, start=1):
        print(f"  {idx}. Line {rec['line']}, Col {rec['col']}: {rec['text']}")

