def find_duplicates(numbers):
    duplicates = []
    for i in range(len(numbers)):
        for j in range(i + 1, len(numbers)):
            if numbers[i] == numbers[j] and numbers[i] not in duplicates:
                duplicates.append(numbers[i])
    return duplicates
"""
    execute_analysis(test_code)

# Recursively calculate total size of a directory in gigabytes

import os

def calculate_directory_size_bytes(directory_path):
    total_bytes = 0
    try:
        with os.scandir(directory_path) as entries:
            for entry in entries:
                try:
                    if entry.is_file():
                        total_bytes += entry.stat().st_size
                    elif entry.is_dir():
                        total_bytes += calculate_directory_size_bytes(entry.path)
                except (OSError, PermissionError):
                    # Skip files/directories we can't access
                    continue
    except (OSError, PermissionError):
        # Skip directories we can't scan
        pass
    return total_bytes

