import numpy as np

class ConnectFourGame:
    def __init__(self):
        self.height = 6
        self.width = 7
        self.grid = np.zeros((self.height, self.width), dtype=int)
        self.turn = 1

    def _is_legal(self, col):
        return self.grid[0, col] == 0

    def _place_piece(self, col):
        for r in range(self.height - 1, -1, -1):
            if self.grid[r, col] == 0:
                self.grid[r, col] = self.turn
                break

    def _detect_victory(self):
        vectors = [(0, -1), (-1, 0), (-1, -1), (-1, 1)]
        for r in range(self.height):
            for c in range(self.width):
                if self.grid[r, c] == 0:
                    continue
                for dr, dc in vectors:
                    if self._check_sequence(r, c, dr, dc):
                        return self.grid[r, c]
        return 0

    def _check_sequence(self, r, c, dr, dc):
        base_value = self.grid[r, c]
        for _ in range(4):
            if not (0 <= r < self.height and 0 <= c < self.width) or self.grid[r, c] != base_value:
                return False
            r += dr
            c += dc
        return True

    def play_turn(self, action):
        if not self._is_legal(action):
            return self.grid.copy(), -1, True, {"error": "illegal"}

        self._place_piece(action)
        score = 0
        finished = False
        victor = self._detect_victory()
        if victor == self.turn:
            score = 1
            finished = True
        elif np.all(self.grid != 0):
            finished = True

        self.turn = 3 - self.turn  # Toggle between players 1 and 2
        return self.grid.copy(), score, finished, {}

    def restart(self):
        self.grid = np.zeros((self.height, self.width), dtype=int)
        self.turn = 1
        return self.grid.copy()

    def display(self):
        print(self.grid)

# Recursively traverse nested data structures (dicts and lists) and print paths with values

def walk_structure(structure, current_path=None):
