            "data": payload, 
            "success": True, 
            "description": msg
        }, status=status.HTTP_200_OK)

    @staticmethod
    def error_response(payload={}, err_msg="", http_code=status.HTTP_400_BAD_REQUEST):
        return JsonResponse({
            "data": payload, 
            "success": False, 
            "error": err_msg
        }, status=http_code)

    @staticmethod
    def unauthorized_response(msg):
        return JsonResponse({
            "success": False, 
            "error": msg
        }, status=status.HTTP_401_UNAUTHORIZED)

    @staticmethod
    def forbidden_response(msg):
        return JsonResponse({
            "success": False, 
            "error": msg
        }, status=status.HTTP_403_FORBIDDEN)

