def convert_dict_keys_to_int64(data):
    """
    Recursively process dictionary keys to ensure int64 representation where applicable.
    Handles top-level keys and nested dictionary values.
    """
    result = {}
    for key, value in data.items():
        # Convert string keys that represent integers to np.int64
        if isinstance(key, str) and key.isdigit():
            new_key = np.int64(key)
        else:
            new_key = key

        # Process nested dictionaries
        if isinstance(value, dict):
            processed_value = {}
            for sub_key, sub_val in value.items():
                if isinstance(sub_key, str) and sub_key.isdigit():
                    processed_value[int(sub_key)] = sub_val
                else:
                    processed_value[sub_key] = sub_val
            result[new_key] = processed_value
        else:
            result[new_key] = value
    return result

def read_json_file(file_path):
    """Load JSON data from a file with validation."""
    if not os.path.isfile(file_path):
        raise FileNotFoundError(f"Specified file does not exist: {file_path}")

    with open(file_path, 'r', encoding='utf-8') as file:
        raw_data = json.load(file)

    return convert_dict_keys_to_int64(raw_data)

def write_json_file(data, output_path):
    """Save dictionary data to a JSON file with proper type handling."""
    if not isinstance(data, dict):
        raise TypeError("Input data must be a dictionary.")

    # Convert numpy integer types to Python int for JSON serialization
    serializable_data = {}
    for key, value in data.items():
        if isinstance(key, (np.integer, np.int64)):
            serializable_key = int(key)
        else:
            serializable_key = key
        serializable_data[serializable_key] = value

    with open(output_path, 'w', encoding='utf-8') as file:
        json.dump(serializable_data, file, indent=2)

def validate_image_file(image_path):
    """Check if the given path points to a valid image file."""
    if not os.path.exists(image_path):
        return False

    try:
        with Image.open(image_path) as img:
            width, height = img.size
            if width <= 0 or height <= 0:
                raise ValueError("Invalid image dimensions")
        return True
    except Exception as error:
        print(f"Image validation failed for '{image_path}': {error}")
        return False

def extract_file_info(path_string):
    """Determine MIME type of a file based on its extension."""
    if os.path.exists(path_string) and path_string != '.':
        if not os.path.isfile(path_string):
            raise ValueError(f"'{path_string}' is not a regular file")

        _, ext = os.path.splitext(path_string)
        mime_type = mimetypes.types_map.get(ext.lower(), 'application/octet-stream')
        return (mime_type, path_string)
    else:
        return (None, path_string)

def save_base64_as_image(base64_content, output_file, max_dimension=-1):
    """Decode base64 image data and save to file with optional resizing."""
    with image_lock:
        pil_image = decode_base64_to_pil_image(base64_content, max_dimension=max_dimension)
        pil_image.save(output_file)

def decode_base64_to_pil_image(base64_content, max_dimension=-1):
    """Convert base64-encoded image data to PIL Image object."""
    decoded_bytes = base64.b64decode(base64_content)
    image_stream = io.BytesIO(decoded_bytes)

    with Image.open(image_stream) as img:
        # Convert RGBA/P mode images to RGB to avoid compatibility issues
        if img.mode in ('RGBA', 'P'):
            img = img.convert('RGB')

        # Resize if maximum dimension is specified and positive
        if max_dimension > 0:
            img.thumbnail((max_dimension, max_dimension))

        return img.copy()

