import json
import sys

def read_json_lines(file_path):
    records = {}
    with open(file_path, 'r', encoding='utf-8') as file:
        for index, raw_line in enumerate(file, start=1):
            cleaned_line = raw_line.strip()
            if not cleaned_line:
                continue
            try:
                parsed = json.loads(cleaned_line)
                if "id" not in parsed:
                    raise ValueError(f"Entry missing 'id' field at line {index}")
                records[parsed["id"]] = parsed
            except json.JSONDecodeError as error:
                raise ValueError(f"Malformed JSON on line {index} of {file_path}: {error}")
    return records

def combine_datasets(source_file_1, source_file_2, result_file):
    dataset_a = read_json_lines(source_file_1)
    dataset_b = read_json_lines(source_file_2)

    unique_ids = sorted(set(dataset_a.keys()).union(set(dataset_b.keys())))
    combined_results = []

    for identifier in unique_ids:
        present_in_a = identifier in dataset_a
        present_in_b = identifier in dataset_b

        if present_in_a and present_in_b:
            merged_entry = {**dataset_a[identifier], **dataset_b[identifier]}
        elif present_in_a:
            merged_entry = dataset_a[identifier].copy()
        else:
            merged_entry = dataset_b[identifier].copy()

        combined_results.append(merged_entry)

    with open(result_file, 'w', encoding='utf-8') as output:
        for record in combined_results:
            output.write(json.dumps(record, ensure_ascii=False) + '\n')

    print(f"Merge completed: {len(combined_results)} entries written to {result_file}")

if __name__ == "__main__":
    if len(sys.argv) != 4:
        print(
            "Usage: python generate_bfcl_tool_call_data.py <input1.jsonl> <input2.jsonl> <output.jsonl>"
        )
        sys.exit(1)

    input_path_1 = sys.argv[1]
    input_path_2 = sys.argv[2]
    output_path = sys.argv[3]

    combine_datasets(input_path_1, input_path_2, output_path)

def convert_to_markdown_list(
    items: list[str], 
    style: str = "unordered"
) -> str:
    """
    Convert a list of strings into a markdown-formatted list.
    :param items: list of strings to format
    :param style: type of list ('unordered' or 'ordered')
    :return: formatted markdown string
    """
    if style == "unordered":
        return "\n".join(f"- {element}" for element in items)
    elif style == "ordered":
        return "\n".join(f"{index}. {element}" for index, element in enumerate(items, 1))
    else:
        raise ValueError("style must be either 'unordered' or 'ordered'")

