import copy
from enum import Enum, auto
from itertools import count
from ..layers.sampler import SamplingParams


class SequenceState(Enum):
    PENDING = auto()
    ACTIVE = auto()
    TERMINATED = auto()


class TokenSequence:
    _block_capacity = 256
    _id_generator = count()

    def __init__(self, initial_tokens: list[int], params: SamplingParams = SamplingParams()):
        self._sequence_id = next(TokenSequence._id_generator)
        self._state = SequenceState.PENDING
        self._tokens = copy.copy(initial_tokens)
        self._last_token_value = self._tokens[-1] if self._tokens else None
        self._total_length = len(self._tokens)
        self._prompt_length = self._total_length
        self._cached_length = 0
        self._block_mapping = []
        self._sampling_temp = getattr(params, 'temperature', 0.7)
        self._max_gen_len = getattr(params, 'max_tokens', 128)
        self._skip_eos_check = getattr(params, 'ignore_eos', False)
        self._enable_verification = True
        self._accumulated_lengths = []
        self._current_accumulated = 0

    # --- Public interface ---
    def __len__(self):
        return self._total_length

    def __getitem__(self, index):
        return self._tokens[index]

    @property
    def is_terminated(self) -> bool:
        return self._state == SequenceState.TERMINATED

    @property
    def generated_length(self) -> int:
        return self._total_length - self._prompt_length

    @property
    def prompt_ids(self) -> list[int]:
        return self._tokens[:self._prompt_length]

    @property
    def generated_ids(self) -> list[int]:
        return self._tokens[self._prompt_length:]

    @property
    def cached_block_count(self) -> int:
        return self._cached_length // self._block_capacity

    @property
    def total_blocks_needed(self) -> int:
        return (self._total_length + self._block_capacity - 1) // self._block_capacity

    @property
    def tokens_in_last_block(self) -> int:
        full_blocks = self.total_blocks_needed - 1
        return self._total_length - full_blocks * self._block_capacity if full_blocks >= 0 else self._total_length

    def get_block(self, block_index: int) -> list[int]:
        if not (0 <= block_index < self.total_blocks_needed):
            raise IndexError("Block index out of range")
        start = block_index * self._block_capacity
        end = min(start + self._block_capacity, self._total_length)
        return self._tokens[start:end]

    def add_token(self, token_id: int):
        self._tokens.append(token_id)
        self._last_token_value = token_id
        self._total_length += 1

    def revert_tokens(self, count_to_revert: int):
        if count_to_revert <= 0:
            raise ValueError("Revert count must be positive")
        if count_to_revert > len(self._tokens):
            raise ValueError("Cannot revert more tokens than present")
        self._tokens = self._tokens[:-count_to_revert]
        self._last_token_value = self._tokens[-1] if self._tokens else None
        self._total_length -= count_to_revert

    def map_slot_for_token(self, position: int) -> int:
        block_idx = position // self._block_capacity
        offset_in_block = position % self._block_capacity
        base_address = self._block_mapping[block_idx] * self._block_capacity
        return base_address + offset_in_block

    # Serialization support
    def _serialize_state(self):
        return (
            self._total_length,
            self._prompt_length,
            self._cached_length,
            self._block_mapping,
            self._sampling_temp,
            self._skip_eos_check,
            self._max_gen_len,
            self._sequence_id,
            self._enable_verification,
            self._accumulated_lengths,
            self._current_accumulated,
            self._tokens if self.generated_length == 0 else self._last_token_value
        )

    def _deserialize_state(self, state_tuple):
        (
            self._total_length,
            self._prompt_length,
            self._cached_length,
            self._block_mapping,
            self._sampling_temp,
            self._skip_eos_check,
            self._max_gen_len,
            self._sequence_id,
            self._enable_verification,
            self._accumulated_lengths,
            self._current_accumulated,
            payload
        ) = state_tuple

        if self.generated_length == 0:
            self._tokens = payload
        else:
            self._last_token_value = payload

    # Pickle hooks
    def __getstate__(self):
        return self._serialize_state()

    def __setstate__(self, state):
        self._deserialize_state(state)

import asyncio
import json
import urllib.request
import sys

# Extract CDP port from command line arguments, default to 9222
CDP_PORT = int(sys.argv[1]) if len(sys.argv) > 1 else 9222

# Standard browser user agent string
DEFAULT_USER_AGENT = "Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/145.0.7632.116 Safari/537.36"

async def main():
    try:
        import websockets
    except ImportError:
        print("ERROR: pip install websockets")
        return

    # Fetch list of available DevTools tabs
    try:
        response = urllib.request.urlopen(f"http://127.0.0.1:{CDP_PORT}/json/list")
        tabs_data = json.loads(response.read())
    except Exception as e:
        print(f"Failed to fetch tab list: {e}")
        return

    print(f"Found {len(tabs_data)} tab(s)")

    if not tabs_data:
        print("No active tabs found.")
        return

    ws_endpoint = tabs_data[0].get("webSocketDebuggerUrl")
    if not ws_endpoint:
        print("WebSocket debugger URL not found in the first tab.")
        return

    async with websockets.connect(ws_endpoint) as socket:
        # Set custom user agent
        await socket.send(json.dumps({
            "id": 1,
            "method": "Network.setUserAgentOverride",
            "params": {"userAgent": DEFAULT_USER_AGENT}
        }))
        await socket.recv()  # Wait for confirmation
        print("User-Agent override applied successfully")

        # Navigate to Google Search and verify title
        await socket.send(json.dumps({
            "id": 2,
            "method": "Page.navigate",
            "params": {"url": "https://www.google.com/search?q=test"}
        }))
        await socket.recv()
        await asyncio.sleep(5)

        await socket.send(json.dumps({
            "id": 3,
            "method": "Runtime.evaluate",
            "params": {"expression": "document.title"}
        }))
        resp = json.loads(await socket.recv())
        google_title = resp.get("result", {}).get("result", {}).get("value", "?")
