import dataclasses
import einops
import numpy as np
from openpi import transforms
from openpi.models import model as _model

def create_random_gsenvironment_sample() -> dict:
    """Generates a synthetic sample mimicking GSEnv policy inputs."""
    return {
        "observation/state": np.random.uniform(low=0.0, high=1.0, size=(8,)),
        "observation/image": np.random.randint(0, 256, size=(480, 640, 3), dtype=np.uint8),
        "instruction": "perform an action",
    }

def _normalize_and_rearrange_image(raw_image) -> np.ndarray:
    # Convert input to numpy array if not already
    img_array = np.asarray(raw_image)

    # Handle floating-point images: scale to [0, 255] and convert to uint8
    if np.issubdtype(img_array.dtype, np.floating):
        img_array = np.clip(img_array * 255.0, 0, 255).astype(np.uint8)

    # Reorder channels from CHW to HWC if needed
    if img_array.ndim == 3 and img_array.shape[0] == 3:
        img_array = einops.rearrange(img_array, "c h w -> h w c")

    return img_array

@dataclasses.dataclass(frozen=True)
class GSEnvPreprocessor(transforms.DataTransformFn):
    architecture_type: _model.ModelType

    def __call__(self, sample: dict) -> dict:
        # Process base image
        original_rgb = _normalize_and_rearrange_image(sample["observation/image"])

        processed_data = {
            "robot_state": sample["observation/state"],
            "visual_inputs": {
                "base_view_rgb": original_rgb,
                "left_hand_rgb": np.zeros_like(original_rgb),
                "right_hand_rgb": np.zeros_like(original_rgb),
            },
            "visual_mask": {
                "base_view_rgb": np.bool_(True),
                "left_hand_rgb": np.bool_(False),
                "right_hand_rgb": np.bool_(False),
            },
        }

        # Conditionally include optional fields
        if "actions" in sample:
            processed_data["target_actions"] = sample["actions"]
        if "instruction" in sample:
            processed_data["text_prompt"] = sample["instruction"]

        return processed_data

@dataclasses.dataclass(frozen=True)
class GSEnvPostprocessor(transforms.DataTransformFn):
    def __call__(self, output_data: dict) -> dict:
        # Extract only the first 7 action dimensions
        action_tensor = np.asarray(output_data["actions"])
        truncated_actions = action_tensor[:, :7]
        return {"predicted_actions": truncated_actions}

