@click.option('--output', default='./', type=str, help='Directory where output will be saved')
@click.option('--force-scan', is_flag=True, help='Ignore cached results and re-scan directory')
def entry_point(force, quiet, strength, temperature, prompt_file, directory_path, auto_deps_csv_path, output, force_scan):
    """Analyze code context and enhance prompt with inferred dependencies."""
    # Capture current Click context and configure execution parameters
    ctx = click.get_current_context()
