import jax.numpy as jnp
import parametricmatrixmodels as pmm
import jax

def test_functional_tree_operations():
    # First test: sum all elements in a nested tree structure
    class SumTreeElements(pmm.modules.FuncBase):
        def get_hyperparameters(self):
            return {}

        def compute(self, tree_data):
            return jax.tree.reduce(lambda acc, elem: acc + elem, tree_data)

    sum_module = SumTreeElements()
    input_data = {
        "x": jnp.array([[1.0, 2.0], [2.0, 3.0]]),
        "y": [
            jnp.array([[3.0, 4.0], [4.0, 5.0]]),
            jnp.array([[5.0, 6.0], [6.0, 7.0]]),
        ],
    }
    output, _ = sum_module(input_data)
    target = jnp.array([[9.0, 12.0], [12.0, 15.0]])
    assert jnp.all(output == target), f"Expected {target}, got {output}"

    # Second test: apply matrix exponential to each element in tree
    class MatrixExponential(pmm.modules.FuncBase):
        def get_hyperparameters(self):
            return {}

        def compute(self, tree_data):
            return jax.tree.map(jax.scipy.linalg.expm, tree_data)

    expm_module = MatrixExponential()
    input_data = {
        "x": jnp.array([[[0.0, 1.0], [0.0, 0.0]]]),
        "y": [
            jnp.array([[[0.0, 2.0], [0.0, 0.0]]]),
            jnp.array([[[0.0, 3.0], [0.0, 0.0]]]),
        ],
    }
    result, _ = expm_module(input_data)

    # Compute expected result using same transformation
    expected_result = jax.tree.map(
        jax.scipy.linalg.expm,
        input_data,
    )

    # Verify tree structures match
    result_tree_struct = jax.tree.structure(result)
    expected_tree_struct = jax.tree.structure(expected_result)
    assert (
        result_tree_struct == expected_tree_struct
    ), f"Expected structure {expected_tree_struct}, got {result_tree_struct}"

    # Element-wise numerical comparison
    def verify_close_values(a, b):
        assert jnp.allclose(a, b), f"Expected {b}, got {a}"

    jax.tree.map(verify_close_values, result, expected_result)

