# WebSocket notification system with user-specific and broadcast messaging

from typing import Dict, List, Any
import json
import asyncio

class ConnectionHandler:
    def __init__(self):
        self.user_connections: Dict[str, List[Any]] = {}

    async def establish_connection(self, socket: Any, identifier: str):
        await socket.accept()
        if identifier not in self.user_connections:
            self.user_connections[identifier] = []
        self.user_connections[identifier].append(socket)

    def remove_connection(self, socket: Any, identifier: str):
        if identifier in self.user_connections:
            if socket in self.user_connections[identifier]:
                self.user_connections[identifier].remove(socket)

    async def deliver_to_user(self, payload: dict, identifier: str):
        if identifier in self.user_connections:
            for connection in self.user_connections[identifier]:
                await connection.send_json(payload)

    async def send_to_all(self, payload: dict):
        for identifier in self.user_connections:
            for connection in self.user_connections[identifier]:
                await connection.send_json(payload)

handler = ConnectionHandler()

MESSAGE_TEMPLATES = {
    "exam_result": "Exam results are available",
    "achievement": "New achievement unlocked!",
    "journal_reminder": "Time for journal reflection",
    "profile_update": "Your profile has been updated",
}

async def handle_websocket_communication(websocket: Any, user_id: str):
    await handler.establish_connection(websocket, user_id)
    try:
        while True:
            raw_data = await websocket.receive_text()
            parsed_message = json.loads(raw_data)
            if parsed_message.get("type") == "ping":
                await websocket.send_json({"type": "pong"})
    except Exception:
        handler.remove_connection(websocket, user_id)

async def issue_notification(user_id: str, message_category: str, extra_data: dict = None):
    notification = {
        "type": message_category,
        "content": MESSAGE_TEMPLATES.get(message_category, "Notification"),
        "payload": extra_data or {},
        "time": asyncio.get_event_loop().time(),
    }
    await handler.deliver_to_user(notification, user_id)

async def issue_broadcast(message_category: str, extra_data: dict = None):
    announcement = {
        "type": message_category,
        "content": MESSAGE_TEMPLATES.get(message_category, "Notification"),
        "payload": extra_data or {},
    }
    await handler.send_to_all(announcement)

"""
Vercel DNS Integration Module
Reference: https://vercel.com/docs/rest-api/endpoints/dns
"""
import requests
from typing import Tuple, Dict, Any, List
import logging
from .base import BaseDnsProvider

logger = logging.getLogger(__name__)

class VercelDnsHandler(BaseDnsProvider):
    PROVIDER_TYPE = "vercel"
    PROVIDER_NAME = "Vercel"
    PROVIDER_DESCRIPTION = "Vercel Domain Name Service API"
    REQUIRED_CREDENTIALS = ["api_token"]

    API_ENDPOINT = "https://api.vercel.com"

    def _build_headers(self) -> Dict[str, str]:
        return {
            'Authorization': f'Bearer {self.credentials["api_token"]}',
            'Content-Type': 'application/json',
        }

    def _send_request(self, http_method: str, endpoint: str, payload: Dict = None) -> Tuple[bool, Any]:
        try:
            url = f"{self.API_ENDPOINT}{endpoint}"
            response = requests.request(
                method=http_method,
                url=url,
                headers=self._build_headers(),
                json=payload,
                timeout=30
            )

            if response.status_code >= 400:
                return False, response.text

            return True, response.json() if response.content else None

        except requests.RequestException as error:
            logger.error(f"Vercel API communication failed: {error}")
            return False, str(error)

    def add_txt_record(self, domain_name: str, record_host: str, record_content: str, ttl_value: int = 300) -> Tuple[bool, str]:
        zone_domain = self.get_zone_for_domain(domain_name)
        subdomain = self.get_relative_record_name(record_host, zone_domain)

        payload = {
            'name': subdomain,
            'type': 'TXT',
            'value': record_content,
            'ttl': ttl_value
        }

        success, response_data = self._send_request('POST', f'/v2/domains/{zone_domain}/records', payload)
        if not success:
            return False, f"Creation failed: {response_data}"
        return True, "TXT record successfully added"

    def remove_txt_record(self, domain_name: str, record_host: str) -> Tuple[bool, str]:
        zone_domain = self.get_zone_for_domain(domain_name)
        subdomain = self.get_relative_record_name(record_host, zone_domain)

        success, records_response = self._send_request('GET', f'/v4/domains/{zone_domain}/records')
        if not success:
            return False, f"Lookup failed: {records_response}"

        txt_records: List[Dict] = records_response.get('records', [])
        for record in txt_records:
            if record.get('type') == 'TXT' and record.get('name') == subdomain:
                self._send_request('DELETE', f'/v2/domains/{zone_domain}/records/{record["id"]}')
                break

        return True, "TXT record removed"

    def verify_credentials(self) -> Tuple[bool, str]:
        success, domains_response = self._send_request('GET', '/v5/domains')
        if success:
            accessible_domains: List[str] = [domain['name'] for domain in domains_response.get('domains', [])]
            return True, f"Authentication successful. Available domains: {', '.join(accessible_domains)}"
        return False, f"Authentication error: {domains_response}"

    @classmethod
    def get_configuration_schema(cls) -> List[Dict[str, Any]]:
        return [
            {
                'name': 'api_token',
                'label': 'API Access Token',
                'type': 'password',
                'required': True,
                'help': 'Generate at vercel.com > Account Settings > Tokens'
            },
        ]

