import os
import re

def resolve_broken_markdown_links(directory):
    print(f"Analyzing {directory} for broken markdown references...")
    link_regex = re.compile(r'\[([^\]]+)\]\(([^)]+)\)')
    resolved_count = 0

    for current_dir, subdirs, filenames in os.walk(directory):
        # Exclude hidden folders from processing
        subdirs[:] = [d for d in subdirs if not d.startswith('.')]

        for filename in filenames:
            if not filename.endswith('.md'):
                continue

            full_path = os.path.join(current_dir, filename)
            try:
                with open(full_path, 'r', encoding='utf-8') as file:
                    original_text = file.read()
            except (IOError, OSError):
                continue

            def process_link(match):
                nonlocal resolved_count
                link_text = match.group(1)
                link_url = match.group(2)
                cleaned_url = link_url.split('#')[0].strip()

                # Skip invalid or external links
                if not cleaned_url or any(cleaned_url.startswith(prefix) for prefix in ('http://', 'https://', 'mailto:', '<', '>')):
                    return match.group(0)
                if os.path.isabs(cleaned_url):
                    return match.group(0)

                absolute_target = os.path.normpath(os.path.join(current_dir, cleaned_url))
                if not os.path.isfile(absolute_target):
                    print(f"Correcting broken reference in {os.path.relpath(full_path, directory)}: {link_url}")
                    resolved_count += 1
                    return link_text
                return match.group(0)

            updated_content = link_regex.sub(process_link, original_text)

            if updated_content != original_text:
                with open(full_path, 'w', encoding='utf-8') as file:
                    file.write(updated_content)

    print(f"Number of broken links corrected: {resolved_count}")

if __name__ == "__main__":
    project_root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
    resolve_broken_markdown_links(os.path.join(project_root, 'skills'))

