class LIBERODataset(Dataset):
    def __init__(self, trials_per_task: int = 50, mode: str = "train"):
        self.mode = mode
        self.trials_per_task = trials_per_task
        self._data_entries: List[Dict[str, Any]] = []

    def initialize(self, cfg: CosmosConfig, *unused_args, **unused_kwargs):
        self.config = cfg

        # Determine task suite name based on dataset mode
        if self.mode == "train":
            suite_name = cfg.train.train_policy.dataset.subset
        elif self.mode == "val":
            suite_name = cfg.validation.dataset.subset
        else:
            raise ValueError(f"Unsupported dataset mode: {self.mode}")

        # Load the appropriate benchmark suite
        all_benchmarks = libero_bench.get_benchmark_dict()
        if suite_name not in all_benchmarks:
            raise KeyError(f"Benchmark '{suite_name}' not found in available benchmarks")

        task_suite = all_benchmarks[suite_name]()
        num_tasks = task_suite.n_tasks

        # Generate data entries for supported benchmark suites
        supported_suites = {
            "libero_10", 
            "libero_90", 
            "libero_goal", 
            "libero_object", 
            "libero_spatial"
        }

        if suite_name in supported_suites:
            self._data_entries = []
            for task_idx in range(num_tasks):
                trial_indices = list(range(self.trials_per_task))
                for trial_num in trial_indices:
                    entry = {
                        "task_suite_name": suite_name,
                        "task_id": task_idx,
                        "trial_id": trial_num,
                        "trial_seed": -1,
                    }
                    self._data_entries.append(entry)
        else:
            raise ValueError(f"Unsupported benchmark suite: {suite_name}")

    def __len__(self) -> int:
        return len(self._data_entries)

    def __getitem__(self, index: int) -> Dict[str, Any]:
        return self._data_entries[index]


def vla_reward_computation(
    evaluation_result: Dict[str, Any],
    ground_truth: Optional[Any] = None,
    task_prompt=None,
    **extra_info,
) -> float:
    """
    Reward function specifically designed for Vision-Language-Action (VLA) tasks.

    This function determines success/failure based on metadata embedded in the
    evaluation result dictionary rather than using reference trajectories.

    Args:
        evaluation_result: Dictionary containing model outputs and metadata
        ground_truth: Unused parameter (kept for interface compatibility)
        task_prompt: The original task description/prompt
        **extra_info: Additional context including environment metadata

    Returns:
        A scalar reward value: 1.0 for successful completion, 0.0 otherwise
    """
    # Extract 'complete' flag from evaluation result to determine reward
    is_complete = evaluation_result.get("complete", False)
    return 1.0 if is_complete else 0.0


