import os
from web3 import Web3
import requests

def fetch_clob_credentials(private_key):
    # Initialize connection to Polygon network via Ankr RPC
    provider_url = 'https://rpc.ankr.com/polygon'
    web3_instance = Web3(Web3.HTTPProvider(provider_url))

    # Recover account from private key
    account = web3_instance.eth.account.from_key(private_key)

    # Prepare EIP-712 typed data structure (aligned with Polymarket's requirements)
    typed_data = {
        "types": {
            "EIP712Domain": [],
            "SomeType": []
        },
        "domain": {},
        "primaryType": "SomeType",
        "message": {}
    }

    # Sign the typed data using the private key
    signature = web3_instance.eth.account.sign_typed_data(
        private_key=private_key,
        typed_data=typed_data
    )

    # Submit signed message to CLOB API endpoint for authentication
    clob_api_endpoint = "https://clob.polymarket.com/api-keys"
    payload = {"signed_message": signature}
    api_response = requests.post(clob_api_endpoint, json=payload)

    if api_response.status_code == 200:
        return api_response.json()  # Return credentials: apiKey, secret, passphrase
    else:
        raise RuntimeError(f"Authentication failed with status {api_response.status_code}")

# Entry point for execution
if __name__ == "__main__":
    private_key = os.environ.get('POLY_PRIVATE_KEY')  # Securely retrieve private key

    if private_key:
        try:
            credentials = fetch_clob_credentials(private_key)
            print("Successfully retrieved credentials:", credentials)
        except Exception as error:
            print(f"Operation failed: {error}")
    else:
        print("Environment variable POLY_PRIVATE_KEY is not set.")

# Consolidates 3+ duplicate implementations used across test files.
"""
Simplifies HTTP request mocking for integration tests by replacing external
dependencies with controlled in-memory behavior.
"""
import json
from io import BytesIO

class MockHttpResponse:
    """Lightweight replacement for HTTP response objects."""
    def __init__(self, code=200, payload=None):
        self.status_code = code
        self._payload = payload or {}

    def read(self):
        return json.dumps(self._payload).encode("utf-8")


class MockHttpConnection:
    """In-memory substitute for http.client.HTTPConnection.
    Captures outgoing requests and returns pre-configured responses,
    enabling reliable testing of ExternalRFClient without live network calls.
    """
    def __init__(self, hostname="localhost", port=8270, deadline=5):
        self.hostname = hostname
        self.port = port
        self.deadline = deadline
        self.log = []
        self._mock_response = MockHttpResponse()
        self._is_active = False

    def establish(self):
        self._is_active = True

    def terminate(self):
        self._is_active = False

    def submit(self, verb, endpoint, data=None, meta=None):
        parsed_data = json.loads(data) if isinstance(data, str) else data
        self.log.append({
            "method": verb,
            "path": endpoint,
            "payload": parsed_data,
            "headers": meta or {},
        })

    def retrieve(self):
        return self._mock_response

    def configure_response(self, code=200, payload=None):
        """Set the next response to be returned."""
        self._mock_response = MockHttpResponse(code=code, payload=payload)
        return self

    def latest_request(self):
        """Return the most recent recorded request, or None if none exist."""
        return self.log[-1] if self.log else None

# Twilio Outbound Call Integration using ElevenLabs API
import sys
import os
import json
import re
import urllib.request
import urllib.error

# Load configuration from environment variables
AGENT_ID = os.environ.get("ELEVENLABS_AGENT_ID", "")
API_KEY = os.environ.get("ELEVENLABS_API_KEY", "")
PHONE_NUMBER_ID = os.environ.get("ELEVENLABS_PHONE_NUMBER_ID", "")

# Define the API endpoint for outbound calls
BASE_URL = "https://api.elevenlabs.io/v1/convai/twilio/outbound-call"

def place_outbound_call(target_number: str, initial_greeting: str = "", additional_context: str = "") -> dict:
    """
    Initiate an outbound voice call via ElevenLabs' Twilio integration.

    Args:
        target_number: Phone number in E.164 format (e.g., +1XXXXXXXXXX)
        initial_greeting: Optional custom first message for the agent
        additional_context: Optional dynamic context variable for the conversation

    Returns:
        Dictionary containing either success data or error information
    """
    # Validate required credentials
    if not API_KEY:
        return {"error": "Missing API key. Set ELEVENLABS_API_KEY in environment."}
    if not AGENT_ID:
        return {"error": "Agent ID not configured. Set ELEVENLABS_AGENT_ID in environment."}
    if not PHONE_NUMBER_ID:
        return {"error": "Phone number ID missing. Set ELEVENLABS_PHONE_NUMBER_ID in environment."}

    # Validate phone number format (US numbers only: +1 followed by 10 digits)
    if not re.match(r'^\+1\d{10}$', target_number):
        return {"error": f"Invalid US phone number: {target_number}. Expected format: +1XXXXXXXXXX"}

    # Build request payload
    request_body = {
        "agent_id": AGENT_ID,
        "agent_phone_number_id": PHONE_NUMBER_ID,
        "to_number": target_number,
    }

    # Add optional client data overrides
    client_data = {}
    if initial_greeting:
        client_data["conversation_config_override"] = {
            "agent": {"first_message": initial_greeting}
        }
    if additional_context:
        client_data["dynamic_variables"] = {"call_context": additional_context}

    if client_data:
        request_body["conversation_initiation_client_data"] = client_data

    # Prepare HTTP request
    encoded_data = json.dumps(request_body).encode('utf-8')
    http_request = urllib.request.Request(
        BASE_URL,
        data=encoded_data,
        headers={
            "xi-api-key": API_KEY,
            "Content-Type": "application/json",
        },
        method="POST"
    )

    try:
        with urllib.request.urlopen(http_request) as response:
            response_data = json.loads(response.read().decode())

            # Check for API-level errors even on successful HTTP status
            if not response_data.get("success", True) or "error" in response_data:
                return {
                    "error": response_data.get("error") or 
                            response_data.get("message") or 
                            "Unknown API error occurred"
                }

            return {
                "success": True,
                "conversation_id": response_data.get("conversation_id", ""),
                "call_sid": response_data.get("callSid", ""),
                "message": response_data.get("message", "Call successfully initiated")
            }

    except urllib.error.HTTPError as http_err:
        error_body = http_err.read().decode()
        return {
            "error": f"API returned error (HTTP {http_err.code}): {error_body}"
        }
    except urllib.error.URLError as url_err:
        return {
            "error": f"Network connectivity issue: {url_err.reason}"
        }

if __name__ == "__main__":
    # Command-line argument handling
    if len(sys.argv) < 2:
        print(json.dumps({"error": "Usage: call_twilio.py <phone_number> [greeting] [context]"}))
        sys.exit(1)

    # Parse arguments
    phone_target = sys.argv[1]
    greeting_text = sys.argv[2] if len(sys.argv) > 2 else ""
    context_text = sys.argv[3] if len(sys.argv) > 3 else ""

    # Execute call and output result
    call_result = place_outbound_call(phone_target, greeting_text, context_text)
    print(json.dumps(call_result, indent=2))

    # Exit with appropriate code based on success/failure
    sys.exit(0 if call_result.get("success") else 1)

