import numpy as np
from .common import TimeStep

class RepeatAction(gym.Wrapper):
    def __init__(self, env, action_repeat=4):
        super().__init__(env)
        self._action_repeat = action_repeat

    def step(self, action: np.ndarray) -> TimeStep:
        accumulated_reward = 0.0
        termination_flag = False
        merged_info = {}
        current_step = 0

        while current_step < self._action_repeat and not termination_flag:
            observation, reward, done, info = self.env.step(action)
            accumulated_reward += reward
            merged_info.update(info)

            if done:
                termination_flag = True
            else:
                current_step += 1

        return observation, accumulated_reward, termination_flag, merged_info

