api_info = {}

class BaseTrait(Service):
    def __init__(self, config=None):
        # Initialize with provided configuration or empty dict
        config = config if config is not None else {}

        # Extract region and service info map from config
        region = config.get('region', REGION_CN_NORTH1)
        service_map = config.get('service_info_map', {})

        # Set up service and API info
        self.service_info = self._fetch_service_info(region, service_map)
        self.api_info = self._static_api_info()

        # Handle authentication if credentials are provided
        if config.get('ak') and config.get('sk'):
            self.set_ak(config['ak'])
            self.set_sk(config['sk'])

        # Initialize parent class with service and API info
        super(BaseTrait, self).__init__(self.service_info, self.api_info)

    @staticmethod
    def _fetch_service_info(region, service_map):
        """Retrieve service info for the given region"""
        service_info = service_map.get(region)
        if not service_info:
            raise Exception(f'BaseService does not support region: {region}')
        return service_info

    @staticmethod
    def _static_api_info():
        """Return static API info dictionary"""
        return api_info

    def update_api_info(self, additional_api_info):
        """Merge new API info into existing API info"""
        self.api_info = {**self.api_info, **additional_api_info}
        return self

    def execute_get_request(self, operation, query_params=None, allow_list=False):
        """Execute GET request and parse JSON response"""
        query_params = query_params or {}
        result = self.get(operation, query_params, allow_list)
        if not result:
            raise Exception(f"{operation}: no response received")
        # Convert response to JSON-compatible format safely
        parsed_result = json.loads(json.dumps(result))
        return parsed_result

    def execute_post_request(self, operation, query_params=None, payload=None):
        """Execute POST request with JSON body and parse response"""
        query_params = query_params or {}
        payload = payload or {}
        result = self.json(operation, query_params, payload)
        if not result:
            raise Exception(f"{operation}: no response received")
        # Safely convert response to JSON structure
        parsed_result = json.loads(json.dumps(result))
        return parsed_result

