        self._concat_axis = concat_axis
        self._memory_opt = memory_optimized
        self._buffer = deque(maxlen=num_frames)

        # Adjust observation space bounds for stacked frames
        obs_low = self.observation_space.low
        obs_high = self.observation_space.high

        # Repeat the bounds along the specified axis
        new_low = np.tile(obs_low, self._num_frames) if concat_axis == -1 else np.repeat(obs_low, self._num_frames, axis=concat_axis)
        new_high = np.tile(obs_high, self._num_frames) if concat_axis == -1 else np.repeat(obs_high, self._num_frames, axis=concat_axis)

        # Handle shape adjustment when concatenating along specific axis
        if concat_axis != -1 and len(obs_low.shape) > 0:
            shape = list(obs_low.shape)
            shape[concat_axis] *= self._num_frames
            new_low = np.broadcast_to(new_low, tuple(shape)).copy()
            new_high = np.broadcast_to(new_high, tuple(shape)).copy()

        self.observation_space = Box(low=new_low,
                                     high=new_high,
                                     dtype=self.observation_space.dtype)

    def reset(self):
        initial_obs = self.env.reset()
        # Fill buffer with initial observation
        for _ in range(self._num_frames):
            self._buffer.append(initial_obs.copy())
        return self._compose_observation()

    def step(self, action):
        next_obs, reward, terminated, info = self.env.step(action)
        self._buffer.append(next_obs.copy())
        return self._compose_observation(), reward, terminated, info

    def _compose_observation(self):
        assert len(self._buffer) == self._num_frames

        if self._memory_opt:
            # Use memory-efficient representation
            return MemoryEfficientStack(list(self._buffer), axis=self._concat_axis)
        else:
            # Direct concatenation approach
            return np.concatenate(list(self._buffer), axis=self._concat_axis)

