import httpx
from tenacity import (
    before_sleep_log,
    retry,
    retry_if_exception_type,
    stop_after_attempt,
    wait_fixed,
)
from zeep.exceptions import Fault, TransportError, XMLSyntaxError
from service.soap_client.format_error import build_error_response
from service.utils.logger import logger

# Retry configuration for AFIP WSAA consultation
retry_config = dict(
    retry=retry_if_exception_type((ConnectionResetError, httpx.ConnectError, TransportError)),
    stop=stop_after_attempt(3),
    wait=wait_fixed(0.5),
    before_sleep=before_sleep_log(logger, logging.WARNING),
)

async def consult_afip_wsaa(make_request, METHOD) -> dict:
    # Apply retry decorator programmatically to avoid direct decorator usage
    @retry(**retry_config)
    async def _wrapped_make_request():
        return await make_request()

    logger.info("Starting CMS login request to AFIP")
    try:
        login_ticket_response = await _wrapped_make_request()
        logger.info("CMS login request to AFIP ended successfully.")
        return {
            "status": "success",
            "response": login_ticket_response,
        }
    except (httpx.ConnectError, httpx.TimeoutException) as e:
        return build_error_response(METHOD, "Network error", str(e))
    except TransportError as e:
        return build_error_response(METHOD, "HTTP Error", str(e))
    except Fault as e:
        logger.debug(f"SOAP FAULT in {METHOD}: {e}")
        return build_error_response(METHOD, "SOAPFault", str(e))
    except XMLSyntaxError as e:
        return build_error_response(METHOD, "Invalid AFIP response", str(e))
    except Exception as e:
        logger.error(f"General exception in {METHOD}: {e}")
        return build_error_response(METHOD, "unknown", str(e))

# Reformat z-base-32 encoded text into structured lines

from __future__ import annotations
from ..encoding.zbase32 import ZBASE32_ALPHABET

def format_zbase32_lines(
    text: str,
    *,
    group_size: int,
    line_length: int,
    line_count: int | None,
) -> list[str]:
    # Validate input parameters
    if group_size <= 0:
        raise ValueError("group_size must be positive")
    if line_length <= 0:
        raise ValueError("line_length must be positive")
    if group_size > line_length:
        raise ValueError("group_size must be <= line_length")
    if line_count is not None and line_count <= 0:
        raise ValueError("line_count must be positive")

    # Collect valid characters, ignoring whitespace and hyphens
    valid_chars = []
    for char in text:
        if char.isspace() or char == "-":
            continue
        lower_char = char.lower()
        if lower_char not in ZBASE32_ALPHABET:
            raise ValueError(f"invalid z-base-32 character: {char!r}")
        valid_chars.append(lower_char)

    # Combine all valid characters into a single string
    encoded_str = "".join(valid_chars)

    # Split the encoded string into groups of specified size
    group_list = [
        encoded_str[i : i + group_size] 
        for i in range(0, len(encoded_str), group_size)
    ]

    # Build lines by grouping groups without exceeding line length
    output_lines = []
    current_line = ""

    for group in group_list:
        # Prepare potential new line content
        if current_line:
            proposed_line = f"{current_line} {group}"
        else:
            proposed_line = group

        # Check if adding this group would exceed line length
        if len(proposed_line) > line_length:
            # Finalize current line and start new one with current group
            output_lines.append(current_line)
            current_line = group
        else:
            current_line = proposed_line

    # Add remaining content if any
    if current_line:
        output_lines.append(current_line)

    # Verify against maximum line count if specified
    if line_count is not None and len(output_lines) > line_count:
        raise ValueError("fallback text exceeds line_count")

    return output_lines

