# AutoRepaySetting class implementation - Type III clone with modified logic

class RepaymentConfiguration:
    """
    Represents auto-repayment configuration settings.
    This class is designed to handle repayment status management
    with validation support.
    """

    # Class-level definitions for attribute mapping
    field_types = {
        'repay_status': 'str'
    }

    json_mapping = {
        'repay_status': 'status'
    }

    def __init__(self, repay_status=None, config=None):
        """Initialize the RepaymentConfiguration instance."""
        # Use default configuration if none provided
        self.config = config or self._get_default_config()

        # Initialize internal storage
        self._repay_status = None

        # Set status if provided (with validation)
        if repay_status is not None:
            self.repay_status = repay_status

    def _get_default_config(self):
        """Get default configuration instance."""
        return Configuration()

    @property
    def repay_status(self):
        """Get the current repayment status.

        Returns:
            str: Current status ('on' or 'off')
        """
        return self._repay_status

    @repay_status.setter
    def repay_status(self, value):
        """Set and validate the repayment status.

        Args:
            value: Status string ('on' or 'off')

        Raises:
            ValueError: If value is not in allowed list
        """
        valid_options = ["on", "off"]

        # Perform validation if client-side validation is enabled
        if (hasattr(self.config, 'client_side_validation') and 
            self.config.client_side_validation and 
            value not in valid_options):
            raise ValueError(
                f"Invalid value '{value}' for repay_status, "
                f"must be one of {valid_options}"
            )

        self._repay_status = value

    def as_dict(self):
        """Convert object to dictionary representation."""
        output = {}

        # Iterate through field types
        for field_name, _ in self.field_types.items():
            # Get attribute value using mapped name
            attr_value = getattr(self, field_name, None)

            # Handle different data types
            if isinstance(attr_value, list):
                output[field_name] = [
                    item.as_dict() if hasattr(item, "as_dict") else item 
                    for item in attr_value
                ]
            elif hasattr(attr_value, "as_dict"):
                output[field_name] = attr_value.as_dict()
            elif isinstance(attr_value, dict):
                output[field_name] = {
                    k: v.as_dict() if hasattr(v, "as_dict") else v 
                    for k, v in attr_value.items()
                }
            else:
                output[field_name] = attr_value

        return output

    def __str__(self):
        """String representation using pprint formatting."""
        import pprint
        return pprint.pformat(self.as_dict())

    def __repr__(self):
        """Official string representation."""
        return self.__str__()

    def __eq__(self, other):
        """Check equality with another object."""
        if not isinstance(other, RepaymentConfiguration):
            return False
        return self.as_dict() == other.as_dict()

    def __ne__(self, other):
        """Check inequality with another object."""
        if not isinstance(other, RepaymentConfiguration):
            return True
        return self.as_dict() != other.as_dict()

import torch.nn as nn
import re

class PassThrough(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, input_tensor, *args, **kwargs):
        return input_tensor

    @property
    def configuration(self):
        return {"mm_projector_type": 'identity'}

class ResidualBlock(nn.Module):
    def __init__(self, feature_dim):
        super().__init__()
        self.norm = nn.LayerNorm(feature_dim)
        self.layers = nn.Sequential(
            nn.Linear(feature_dim, feature_dim),
            nn.GELU(),
            nn.Linear(feature_dim, feature_dim)
        )

    def forward(self, x):
        x = self.norm(x)
        return x + self.layers(x)

def create_vision_projector(config, delay_load=False, **kwargs):
    proj_type = getattr(config, 'mm_projector_type', 'linear')

    if proj_type == 'linear':
        return nn.Linear(config.mm_hidden_size, config.hidden_size)

    mlp_gelu_pattern = re.match(r'^mlp(\d+)x_gelu$', proj_type)
    if mlp_gelu_pattern:
        depth = int(mlp_gelu_pattern.group(1))
        layers_list = [nn.Linear(config.mm_hidden_size, config.hidden_size)]

        for _ in range(1, depth):
            layers_list.append(nn.GELU())
            layers_list.append(nn.Linear(config.hidden_size, config.hidden_size))

        return nn.Sequential(*layers_list)

    if proj_type == 'identity':
        return PassThrough()

    raise ValueError(f'Unsupported projector type: {proj_type}')

