train_data = dataset["train"]

def transform_sample(sample):
    # Extract conversation turns
    turns = sample["messages"]

    def normalize_role(original_role):
        # Map roles to standard format
        if original_role == "user":
            return "user"
        elif original_role == "assistant":
            return "assistant"
        elif original_role == "system":
            return "system"
        else:
            raise ValueError(f"Encountered unknown role: {original_role}")

    # Build new message list with normalized roles
    formatted_messages = []
    for turn in turns:
        formatted_messages.append({
            "role": normalize_role(turn["role"]),
            "content": turn["content"]
        })

    return {"messages": formatted_messages}

