        super().__init__(f"Duplicate node IDs: {node_identifiers}")

class NoStartNodeException(GraphValidationError):
    """Raised when no start node is found."""

class MultipleStartNodesException(GraphValidationError):
    """Raised when more than 1 start nodes are found."""

class NoEndNodeException(GraphValidationError):
    """Raised when no end node is found."""

class OrphanNodeException(GraphValidationError):
    """Raised when dangling (orphan) nodes are found."""
    def __init__(self, node_identifiers: list[str]):
        super().__init__(f"Orphan nodes' IDs: {node_identifiers}")

class BadSchemaIdentifierException(GraphValidationError):
    def __init__(self, schema_identifier: str, valid_schema_ids: list[str]):
        super().__init__(
            f"Invalid schema id: {schema_identifier}, available: {valid_schema_ids}"
        )

class InputOutputMismatchException(GraphValidationError):
    def __init__(self, node_identifier: str, description: str):
        super().__init__(f"Node '{node_identifier}': {description}")

