import torch
from .tensor_operations import Operation

class DeviceConfigurator:
    """A serializable device configuration class."""
    def __init__(self, gpu_count, gpu_ids=None):
        self.gpu_count = gpu_count
        self.gpu_ids = gpu_ids

    def apply(self):
        """Configure device settings for the current process."""
        import multiprocessing as mp
        proc_name = mp.current_process().name
        proc_rank = int(proc_name.split("-")[-1]) - 1
        Operation.local_rank = proc_rank

        if self.gpu_count > 0:
            if self.gpu_ids is not None:
                selected_gpu = self.gpu_ids[proc_rank % self.gpu_count]
            else:
                selected_gpu = proc_rank % self.gpu_count
            torch.cuda.set_device(selected_gpu)
            Operation.global_device = f"cuda:{selected_gpu}"
        else:
            Operation.global_device = "cpu"

        torch.set_grad_enabled(False)

def create_device_config(args):
    """Constructs a device configuration object suitable for serialization."""
    return DeviceConfigurator(args.gpu_count, args.gpu_ids)

def initialize_single_process(args):
    """Set up device for single-process execution."""
    if args.gpu_count > 0:
        if args.gpu_ids is not None:
            Operation.global_device = f"cuda:{args.gpu_ids[0]}"
        else:
            Operation.global_device = "cuda"
    else:
        Operation.global_device = "cpu"

    torch.set_grad_enabled(False)

from mindspeed_mm.tasks.inference.pipeline.pipeline_mixin.generation_mixin import GenerationMixin
from mindspeed_mm.tasks.inference.pipeline.qwen2vl_pipeline import Qwen2VlPipeline
from mindspeed_mm.models.vision.vlm_attentionmask_for_llm import glm_position
from transformers import AutoProcessor

class GlmPipeline(Qwen2VlPipeline, GenerationMixin):
    def __init__(self, config):
        super().__init__(config)
        tokenizer_path = config.tokenizer.from_pretrained
        self.image_processor = AutoProcessor.from_pretrained(
            tokenizer_path,
            local_files_only=True,
            use_fast=True
        )

    def compute_rope_indices(self, token_ids, img_dims=None, vid_dims=None, mask=None):
        return glm_position(
            config=self.generation_config,
            input_ids=token_ids,
            image_grid_thw=img_dims,
            video_grid_thw=vid_dims,
            attention_mask=mask
        )

    def __call__(self, text_prompt=None, image_inputs=None, video_inputs=None, return_token_ids=False):
        return super().__call__(
            text_prompt, 
            image_inputs, 
            video_inputs, 
            return_token_ids, 
            skip_special_tokens=False
        )

    def build_inputs(self, text_prompt=None, image_inputs=None, video_inputs=None, chat_history=None):
        # Early exit if no modalities provided
        if not image_inputs and not chat_history and not video_inputs:
            return None

        # Construct message content if not already in chat format
        if chat_history is None:
            media_items = []

            if image_inputs:
                media_items.append({"type": "image", "image": image_inputs})
            if video_inputs:
                media_items.append({"type": "video", "video": video_inputs})

            media_items.append({"type": "text", "text": text_prompt})

            chat_history = [[{
                "role": "user",
                "content": media_items
            }]]

        # Apply chat template and prepare model inputs
        processed = self.image_processor.apply_chat_template(
            chat_history,
            tokenize=True,
            add_generation_prompt=True,
            return_dict=True,
            return_tensors="pt",
            padding=True
        )

        # Move to appropriate device
        processed = {k: v.to(self.infer_config.device) for k, v in processed.items()}
        return processed

