class ApiResponseDetails:
    trace_id: str
    api_error: ApiErrorResponse

    @classmethod
    def create_from_dict(cls, data: dict):
        instance = cls(
            trace_id="",
            api_error=ApiErrorResponse(error_code="")
        )

        if "RequestId" in data:
            instance.trace_id = data["RequestId"]
        if "Error" in data:
            instance.api_error = ApiErrorResponse.create_from_dict(data["Error"])

        return instance

    @staticmethod
    def default_instance():
        return ApiResponseDetails(
            trace_id="",
            api_error=ApiErrorResponse(error_code="")
        )

