from typing import Callable, Type, Dict, Optional, Any
from pydantic import BaseModel, ConfigDict

class RegisteredAction(BaseModel):
    """Model for a registered action"""
    name: str
    description: str
    function: Callable
    param_model: Type[BaseModel]
    requires_mac_builder: bool = False

    model_config = ConfigDict(arbitrary_types_allowed=True)

    def get_prompt_info(self) -> str:
        """Generate a description of the action suitable for prompts"""
        excluded_fields = ['title', '$schema']
        desc_parts = [f'{self.description}: \n', '{' + self.name + ': ']

        # Extract schema properties and filter out excluded keys
        schema_props = self.param_model.model_json_schema().get('properties', {})
        filtered_props = {
            key: {
                inner_key: inner_val 
                for inner_key, inner_val in value.items() 
                if inner_key not in excluded_fields
            } 
            for key, value in schema_props.items()
        }

        desc_parts.append(str(filtered_props))
        desc_parts.append('}')
        return ''.join(desc_parts)

class ActionModel(BaseModel):
    """Base model for dynamically created action models"""
    model_config = ConfigDict(arbitrary_types_allowed=True, extra='allow')

    def extract_action_index(self) -> Optional[int]:
        """Extract the index from action parameters"""
        # {'clicked_element': {'index':5}}
        params = self.model_dump(exclude_unset=True).values()
        if not params:
            return None

        for param in params:
            if param is not None and isinstance(param, dict) and 'index' in param:
                return param['index']
        return None

    def update_action_index(self, new_index: int):
        """Update the index field in the action parameters"""
        # Get the action name and its parameters
        action_data = self.model_dump(exclude_unset=True)
        action_name = next(iter(action_data.keys()))
        action_params = getattr(self, action_name)

        # Update the index directly on the model instance
        if hasattr(action_params, 'index'):
            object.__setattr__(action_params, 'index', new_index)

class ActionRegistry(BaseModel):
    """Model representing the action registry"""
    actions: Dict[str, RegisteredAction] = {}

    def generate_prompt_text(self) -> str:
        """Generate combined descriptions of all actions for prompts"""
        return '\n'.join([action.get_prompt_info() for action in self.actions.values()])

import sqlite3

def search_users_safe(search_term, table_name):
    """Search users - SAFE using parameterized queries"""
    conn = sqlite3.connect("users.db")
    # Validate table name to prevent SQL injection (whitelist approach)
    allowed_tables = ["users", "admin", "guests"]
    if table_name not in allowed_tables:
        raise ValueError("Invalid table name")

    # Use parameterized query for the search term
    query = f"SELECT * FROM {table_name} WHERE name LIKE ?"
    cursor = conn.execute(query, (f"%{search_term}%",))
    return cursor.fetchall()

def get_user_by_id_safe(user_id):
    """Get user by ID - SAFE using parameterized queries"""
    conn = sqlite3.connect("users.db")
    # Validate user_id is an integer to prevent injection
    try:
        user_id_int = int(user_id)
    except (ValueError, TypeError):
        return None

    # Use parameterized query for the user ID
    query = "SELECT * FROM users WHERE id = ?"
    return conn.execute(query, (user_id_int,)).fetchone()

