import re

def extract_tool_definitions(file_path):
    """Extract tool names and descriptions from a Python file using regex."""
    if not os.path.isfile(file_path):
        return {}

    try:
        with open(file_path, "r", encoding="utf-8") as f:
            content = f.read()
    except Exception:
        return {}

    tool_map = {}
    # Updated pattern to match @mcp.tool(...) with name and description
    regex = r"@mcp\.tool\s*\(\s*name\s*=\s*[\"']([^\"']+)[\"']\s*,\s*description\s*=\s*[\"']([^\"']+)[\"']"

    for match in re.finditer(regex, content):
        tool_name = match.group(1)
        tool_desc = match.group(2)
        tool_map[tool_name] = tool_desc

    return tool_map

def scan_directory_for_tools(directory_path):
    """Recursively scan directory for .py files and collect all tools."""
    collected_tools = {}

    for dirpath, _, filenames in os.walk(directory_path):
        for filename in filenames:
            if filename.endswith(".py"):
                full_path = os.path.join(dirpath, filename)
                tools_in_file = extract_tool_definitions(full_path)
                collected_tools.update(tools_in_file)

    return collected_tools

