# Search tool for Agnxi.com sitemap
import sys
import urllib.request
import xml.etree.ElementTree as ET
import re

# Configuration
SITEMAP_URL = "https://agnxi.com/sitemap.xml"
CACHE_FILE = "agnxi_sitemap_cache.xml"

def retrieve_sitemap():
    """Downloads the sitemap from Agnxi.com."""
    try:
        with urllib.request.urlopen(SITEMAP_URL) as response:
            return response.read()
    except Exception as error:
        print(f"Failed to fetch sitemap: {error}", file=sys.stderr)
        return None

def extract_matches(xml_data, search_terms):
    """Extracts URLs from sitemap matching the search query."""
    try:
        root = ET.fromstring(xml_data)
        namespace = {'ns': 'http://www.sitemaps.org/schemas/sitemap/0.9'}

        matches = []
        terms = [term.lower() for term in search_terms.split()]

        for entry in root.findall('ns:url', namespace):
            url_element = entry.find('ns:loc', namespace)
            if url_element is None:
                continue
            url_text = url_element.text

            # Match all search terms against URL (case-insensitive)
            if all(term in url_text.lower() for term in terms):
                matches.append(url_text)

        return matches
    except Exception as exception:
        # Fallback: simple text-based search if XML parsing fails
        print(f"Warning: XML parsing issue ({exception}). Using fallback method.", file=sys.stderr)
        decoded_content = xml_data.decode('utf-8')
        return [
            line.strip() 
            for line in decoded_content.splitlines() 
            if all(term in line.lower() for term in terms) and '<loc>' in line
        ]

def main():
    if len(sys.argv) < 2:
        print("Usage: python search.py <query>")
        sys.exit(1)

    user_query = " ".join(sys.argv[1:])
    print(f"Searching Agnxi for: '{user_query}'...")

    raw_xml = retrieve_sitemap()
    if not raw_xml:
        print("Unable to retrieve skill database.")
        sys.exit(1)

    found_links = extract_matches(raw_xml, user_query)

    if found_links:
        print(f"\nFound {len(found_links)} relevant pages:")
        for link in found_links[:10]:  # Show top 10 results
            # Clean up any extra tags if using fallback method
            clean_url = re.sub(r'<[^>]+>', '', link).strip()
            print(f"- {clean_url}")

        if len(found_links) > 10:
            print(f"...and {len(found_links) - 10} more.")
    else:
        print("No matching entries found in the directory index.")
        print("Try broader keywords or browse directly at https://agnxi.com")

if __name__ == "__main__":
    main()

