def load_gsm8k_supervised(path: str, split_name: str, tokenizer_obj, max_seq_len: int | None = None):
    raw_data = load_dataset(path=path, name="main", split=split_name)

    def transform_sample(sample):
        # Combine question and answer with EOS token for full sequence
        full_text = sample["question"] + sample["answer"] + tokenizer_obj.eos_token
        full_ids = tokenizer_obj.encode(full_text)

        # Tokenize only the question part for prompt
        prompt_ids = tokenizer_obj.encode(sample["question"])

        # Create loss mask: 0 for prompt tokens, 1 for answer+EOS tokens
        mask = [0] * len(prompt_ids) + [1] * (len(full_ids) - len(prompt_ids))

        return {"input_ids": full_ids, "loss_mask": mask}

    processed_data = raw_data.map(transform_sample).remove_columns(["question", "answer"])

    if max_seq_len is not None:
        processed_data = processed_data.filter(lambda item: len(item["input_ids"]) <= max_seq_len)

    return processed_data


