        )
        return {"messages": [{"role": "user", "content": user_content}]}

    processed_data = raw_data.map(prepare_rl_sample).remove_columns(["question"])

    if max_seq_len is not None:
        def check_token_limit(sample):
            content_text = sample["messages"][0]["content"]
            tokenized_content = tokenizer_obj.encode(content_text)
            return len(tokenized_content) <= max_seq_len

        processed_data = processed_data.filter(check_token_limit)

    return processed_data

