def store_credential(provider_name, api_key):
    """Store an API key securely using keyring if available."""
    if not KEYRING_ENABLED:
        print("[warn] 'keyring' module is unavailable. Credentials cannot be stored securely.")
        return False

    try:
        keyring.set_password(SERVICE_ID, provider_name, api_key)
        return True
    except Exception as error:
        print(f"[warn] Unable to save credential in keyring: {error}")
        return False

