import os
import sympy


class AlternateReifier(ReifierBase):
    def __init__(self, model_path: str, **kwargs):
        super().__init__(model_path)
        self._dynamic_constraints = self._load_dynamic_dim_constraints(model_path)

    def _load_dynamic_dim_constraints(self, path: str):
        return get_dynamic_dim_constraints(path)

    def get_reifier_name(self) -> str:
        # Return module name without extension
        return os.path.splitext(os.path.basename(__file__))[0]

    def is_applicable(self) -> bool:
        if self._dynamic_constraints is None:
            return False

        serialized_shapes = self._dynamic_constraints.serialize_symbolic_input_shapes_to_str()
        if not serialized_shapes or serialized_shapes == "[]":
            return False

        mapping = self._get_nlp_shape_reifier_map()
        if serialized_shapes not in mapping:
            print(
                f"[NLP SymDim Reify] No reifier matched symbolic shapes: {serialized_shapes}\n"
                "Please add a reify rule to _get_nlp_shape_reifier_map()"
            )
            return False

        return True

    def perform_reification(self):
        assert self.is_applicable(), "Reifier must be applicable before reifying."
        shape_key = self._dynamic_constraints.serialize_symbolic_input_shapes_to_str()
        reifier_func = self._get_nlp_shape_reifier_map()[shape_key]
        return reifier_func(self)

    @classmethod
    def _get_nlp_shape_reifier_map(cls):
        if not hasattr(cls, "_nlp_shape_reifier_table"):
            cls._nlp_shape_reifier_table = {
                "[(S0,1),(S0,S1),(S0,S1)]": cls._reify_batch_s0_seq_s1,
                "[(S0,S1),(S0,S1),(S0,S1)]": cls._reify_batch_s0_seq_s1,
                "[(S0,S1),(S0,S1)]": cls._reify_batch_s0_seq_s1,
                "[(S0,S1,768)]": cls._reify_batch_s0_seq_s1,
                "[(S0,S1)]": cls._reify_nlp_or_gnn_batch_s0_seq_s1,
            }
        return cls._nlp_shape_reifier_table

    def _reify_batch_s0_seq_s1(self):
        S0, S1 = sympy.Symbol("S0"), sympy.Symbol("S1")
        candidate_dims = [
            [1, 64],
            [1, 512],
            [16, 128],
            [32, 64],
            [8, 256],
            [4, 512],
            [2, 1024],
            [64, 128],
            [128, 64],
        ]
        return {(S0, S1): candidate_dims}

    def _reify_nlp_or_gnn_batch_s0_seq_s1(self):
        S0, S1 = sympy.Symbol("S0"), sympy.Symbol("S1")
        candidate_dims = [
            [1, 128],
            [1, 1024],
            [32, 64],
            [16, 128],
            [8, 256],
            [4, 512],
            [2, 1024],
            [64, 128],
            [128, 64],
        ]
        return {(S0, S1): candidate_dims}

