# Custom HTTP request handler with routing capabilities

import json
import logging
from http.server import BaseHTTPRequestHandler

logger = logging.getLogger(__name__)

class RouteManager:
    def __init__(self):
        # Store routes organized by HTTP method and path
        self._routes = {
            "GET": {},
            "POST": {}
        }

    def register(self, method: str, endpoint: str, callback):
        method = method.upper()
        if method not in self._routes:
            self._routes[method] = {}
        self._routes[method][endpoint] = callback

    def get_endpoint(self, path: str):
        def wrapper(func):
            self.register("GET", path, func)
            return func
        return wrapper

    def post_endpoint(self, path: str):
        def wrapper(func):
            self.register("POST", path, func)
            return func
        return wrapper

    def resolve(self, request_handler: BaseHTTPRequestHandler):
        # Extract base path without query parameters
        base_path = request_handler.path.split('?')[0]
        http_method = request_handler.command.upper()

        if http_method in self._routes and base_path in self._routes[http_method]:
            try:
                self._routes[http_method][base_path](request_handler)
            except Exception as ex:
                logger.warning(f"Exception during {http_method} {base_path}: {ex}")
                self._respond_error(request_handler, 500, str(ex))
        else:
            self._respond_error(request_handler, 404, "Resource not available")

    def _respond_error(self, handler: BaseHTTPRequestHandler, status_code: int, description: str):
        handler.send_response(status_code)
        handler.send_header("Content-Type", "application/json")
        handler.end_headers()
        response_body = json.dumps({"error": description})
        handler.wfile.write(response_body.encode('utf-8'))

# Singleton router instance
_route_registry = RouteManager()

def get_route_registry() -> RouteManager:
    return _route_registry

