import json
import sys

class RectAndField:
    def __init__(self, rect, rect_type, field):
        self.rect = rect
        self.rect_type = rect_type
        self.field = field

def check_overlap(rect1, rect2):
    # Check if rectangles are NOT overlapping (disjoint)
    x_disjoint = rect1[0] >= rect2[2] or rect1[2] <= rect2[0]
    y_disjoint = rect1[1] >= rect2[3] or rect1[3] <= rect2[1]
    return not (x_disjoint or y_disjoint)

def validate_bounding_boxes(json_stream):
    output_messages = []
    data = json.load(json_stream)

    fields_list = data.get("form_fields", [])
    output_messages.append(f"Processed {len(fields_list)} form fields")

    # Prepare list of all bounding boxes with their types and associated fields
    box_collection = []
    for field in fields_list:
        box_collection.append(RectAndField(field["label_bounding_box"], "label", field))
        box_collection.append(RectAndField(field["entry_bounding_box"], "entry", field))

    issues_found = False

    # Check all pairs for overlaps on the same page
    for idx, current_box in enumerate(box_collection):
        for next_idx in range(idx + 1, len(box_collection)):
            other_box = box_collection[next_idx]

            # Only compare if they're on the same page
            if current_box.field["page_number"] == other_box.field["page_number"]:
                if check_overlap(current_box.rect, other_box.rect):
                    issues_found = True

                    # Distinguish between label-entry overlap within same field vs. cross-field overlaps
                    if current_box.field is other_box.field:
                        output_messages.append(
                            f"ERROR: Overlap between label and entry boxes for `{current_box.field['description']}` "
                            f"(boxes: {current_box.rect}, {other_box.rect})"
                        )
                    else:
                        output_messages.append(
                            f"ERROR: Overlap between {current_box.rect_type} box for `{current_box.field['description']}` "
                            f"(box: {current_box.rect}) and {other_box.rect_type} box for `{other_box.field['description']}` "
                            f"(box: {other_box.rect})"
                        )

                    # Limit number of messages to avoid overwhelming output
                    if len(output_messages) >= 20:
                        output_messages.append("Stopped checking after reaching message limit; please fix issues and re-run.")
                        return output_messages

    # Additional validation: check entry box height against font size
    for box in box_collection:
        if box.rect_type == "entry":
            if "entry_text" in box.field:
                font_size = box.field["entry_text"].get("font_size", 14)
                actual_height = box.rect[3] - box.rect[1]

                if actual_height < font_size:
                    issues_found = True
                    output_messages.append(
                        f"ERROR: Entry box for `{box.field['description']}` has insufficient height ({actual_height:.2f}) "
                        f"for specified font size ({font_size}). Consider increasing box height or reducing font size."
                    )

                    if len(output_messages) >= 20:
                        output_messages.append("Stopped checking after reaching message limit; please fix issues and re-run.")
                        return output_messages

    if not issues_found:
        output_messages.append("OK: All bounding boxes passed validation")

    return output_messages

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: validate_bounding_boxes.py [fields.json]")
        sys.exit(1)

    try:
        with open(sys.argv[1], 'r') as file:
            results = validate_bounding_boxes(file)

        for line in results:
            print(line)
    except Exception as e:
        print(f"Error processing input: {e}")
        sys.exit(1)

def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}
    """
    # Handle empty or whitespace-only input
    if not test or test.strip() == "":
        return {}

    # Split the string into individual letters
    letters_list = test.split()

    # Count occurrences using a dictionary
    frequency = {}
    for char in letters_list:
        if char:  # Ensure non-empty character
            frequency[char] = frequency.get(char, 0) + 1

    # Return empty dict if no valid characters found
    if not frequency:
        return {}

    # Find the maximum frequency value
    highest_frequency = max(frequency.values())

    # Build result dictionary with only letters having the maximum frequency
    result = {}
    for letter, freq in frequency.items():
        if freq == highest_frequency:
            result[letter] = freq

    return result

