import logging
from app.collectors.base import Collector, CollectorResult

logger = logging.getLogger("docsis.collector.backup")

class BackupCollector(Collector):
    """Collector responsible for generating and managing scheduled backups."""
    name = "backup"

    def __init__(self, config_manager, polling_interval=86400, **kwargs):
        super().__init__(polling_interval)
        self._config_manager = config_manager

    def is_enabled(self):
        return self._config_manager.is_backup_configured()

    def collect(self):
        from .backup import generate_backup_file, remove_excess_backups

        data_directory = self._config_manager.data_dir
        backup_location = self._config_manager.get("backup_path", "/backup")
        retention_count = self._config_manager.get("backup_retention", 5)

        try:
            backup_filename = generate_backup_file(data_directory, backup_location)
            remove_excess_backups(backup_location, max_to_keep=retention_count)
            logger.info("Backup task completed successfully: %s", backup_filename)
            return CollectorResult.success(self.name, {"filename": backup_filename})
        except Exception as error:
            logger.warning("Backup operation encountered an issue: %s", error)
            return CollectorResult.error(self.name, str(error))

# Agent task state manager with persistent storage and dependency tracking

import json
from pathlib import Path
from datetime import datetime

class WorkflowManager:
    """Handles the lifecycle and progress tracking of complex agent workflows."""

    def __init__(self, workflow_id: str, storage_file: Path = Path('workflow_state.json')):
        self.workflow_id = workflow_id
        self.storage_file = storage_file
        self.current_workflow = self._retrieve_workflow_data()

    def _retrieve_workflow_data(self):
        """Fetches stored workflow data from disk or returns empty structure if unavailable."""
        if not self.storage_file.exists():
            return {}

        try:
            with open(self.storage_file, 'r') as file_handle:
                return json.load(file_handle)
        except json.JSONDecodeError:
            print(f"Notice: Invalid JSON in {self.storage_file}. Initializing new state.")
            return {}

    def _persist_workflow_data(self):
        """Commits current workflow state to persistent storage."""
        with open(self.storage_file, 'w') as file_handle:
            json.dump(self.current_workflow, file_handle, indent=2)

    def initialize_or_fetch_workflow(self):
        """Creates a new workflow entry if none exists, otherwise retrieves existing one."""
        if self.workflow_id not in self.current_workflow:
            self.current_workflow[self.workflow_id] = {
                "progress": "PENDING",
                "steps_finished": 0,
                "last_execution": None,
                "metadata": {}
            }
            self._persist_workflow_data()
        return self.current_workflow[self.workflow_id]

    def set_workflow_progress(self, new_progress: str, additional_info: dict = None):
        """Advances workflow status and optionally updates associated metadata."""
        workflow_entry = self.initialize_or_fetch_workflow()
        workflow_entry["progress"] = new_progress
        workflow_entry["last_execution"] = datetime.now().isoformat()

        if additional_info:
            workflow_entry["metadata"].update(additional_info)

        self._persist_workflow_data()
        print(f"Workflow '{self.workflow_id}' updated to: {new_progress}")

