import json
import sys

def assess_market_sentiment(message):
    bullish_terms = ['moon', 'bull', 'growth', 'profit', 'buy', 'upgrade', 'success', 'stable']
    bearish_terms = ['dump', 'bear', 'crash', 'loss', 'sell', 'scam', 'fear', 'volatile']

    sentiment_score = 0.0
    tokens = message.lower().split()

    for token in tokens:
        if token in bullish_terms:
            sentiment_score += 0.2
        elif token in bearish_terms:
            sentiment_score -= 0.2

    # Clamp the score to [-1, 1]
    if sentiment_score < -1:
        sentiment_score = -1
    elif sentiment_score > 1:
        sentiment_score = 1

    mood_label = "Neutral"
    if sentiment_score > 0.3:
        mood_label = "Greedy / Bullish"
    elif sentiment_score < -0.3:
        mood_label = "Fearful / Bearish"

    return {
        "score": round(sentiment_score, 2),
        "status": mood_label,
        "narrative_drivers": ["Simulated social signals", "Keywords analysis"]
    }

if __name__ == "__main__":
    user_input = sys.argv[1] if len(sys.argv) > 1 else ""
    output = assess_market_sentiment(user_input)
    print(json.dumps(output, indent=2))

import torch
from PIL import Image
from torchvision.transforms import functional as TVF
from typing import Union

class AdjustToDivisible:
    def __init__(self, divisible_by):
        if isinstance(divisible_by, int):
            divisible_by = (divisible_by, divisible_by)
        self.h_divisor, self.w_divisor = divisible_by

    def __call__(self, img: Union[torch.Tensor, Image.Image]):
        # Determine image dimensions based on type
        if isinstance(img, torch.Tensor):
            h, w = img.size()[-2:]
        elif isinstance(img, Image.Image):
            w, h = img.size
        else:
            raise ValueError("Unsupported image type")

        # Compute new dimensions that are divisible by the specified factors
        new_h = h - (h % self.h_divisor)
        new_w = w - (w % self.w_divisor)

        # Apply center cropping to the computed dimensions
        return TVF.center_crop(img, [new_h, new_w])

import contextlib
import joblib
from tqdm.autonotebook import tqdm

@contextlib.contextmanager
def tqdm_joblib_patch(total=None, desc=None, **tqdm_kwargs):
    """Context manager to integrate joblib with tqdm progress bars."""
    progress_bar = tqdm(total=total, desc=desc, **tqdm_kwargs)

    class CustomBatchCallback(joblib.parallel.BatchCompletionCallBack):
        def __call__(self, *args, **kwargs):
            progress_bar.update(n=self.batch_size)
            return super().__call__(*args, **kwargs)

    original_callback = joblib.parallel.BatchCompletionCallBack
    joblib.parallel.BatchCompletionCallBack = CustomBatchCallback

    try:
        yield progress_bar
    finally:
        joblib.parallel.BatchCompletionCallBack = original_callback
        progress_bar.close()

def create_parallel_with_progress(desc=None, **tqdm_options):
    """Factory function to create a Parallel class with tqdm progress bar support."""

    class ProgressParallel(joblib.Parallel):
        def __call__(self, iterable):
            items = list(iterable)

            # Handle single-job case separately
            if self.n_jobs == 1:
                items = tqdm(items, desc=desc, **tqdm_options)
                return super().__call__(items)

            # Multi-job case with context manager
            with tqdm_joblib_patch(total=len(items), desc=desc, **tqdm_options):
                return super().__call__(items)

    return ProgressParallel

