import gdsfactory as gf
from gdsfactory.typings import LayerSpec
from qpdk.cells.waveguides import rectangle
from qpdk.helper import show_components

@gf.cell
def chip_boundary(
    dimensions: tuple[float, float] = (10000.0, 10000.0),
    border_thickness: float = 200.0,
    metal_layer: LayerSpec = "M1_ETCH",
) -> gf.Component:
    """Returns a chip boundary component with hollow rectangular frame.

    Constructs a rectangular frame (hollow rectangle) on an etched metal layer,
    typically used to define chip edge regions for proper fabrication.

    Args:
        dimensions: (tuple) Width and height of the chip boundary area.
        border_thickness: Thickness/width of the etched frame border.
        metal_layer: Layer to place the etched frame structure.
    """
    c = gf.Component()

    # Define four边框 segments using list comprehension
    segments = [
        {
            "dimensions": (dimensions[0], border_thickness), 
            "offset": (0, dimensions[1] - border_thickness)
        },  # Top segment
        {
            "dimensions": (dimensions[0], border_thickness), 
            "offset": (0, 0)
        },  # Bottom segment
        {
            "dimensions": (border_thickness, dimensions[1]), 
            "offset": (0, 0)
        },  # Left segment
        {
            "dimensions": (border_thickness, dimensions[1]), 
            "offset": (dimensions[0] - border_thickness, 0)
        }   # Right segment
    ]

    base_kwargs = {
        "layer": metal_layer,
        "centered": False,
        "port_type": None,
    }

    # Add each frame segment to the component
    for seg in segments:
        frame_part = c << rectangle(size=seg["dimensions"], **base_kwargs)
        frame_part.move(seg["offset"])

    return c

if __name__ == "__main__":
    show_components(
        chip_boundary,
        spacing=50,
    )

