# Configuration class that supports nested dictionaries and conversion back to dict
class ModelParallelConfig(object):
    def __init__(self, config_dict):
        for key, value in config_dict.items():
            if isinstance(value, dict):
                setattr(self, key, ModelParallelConfig(value))
            else:
                setattr(self, key, value)

    def as_dict(self):
        result = {}
        for attr_name in dir(self):
            if not attr_name.startswith('__'):
                attr_value = getattr(self, attr_name)
                if isinstance(attr_value, self.__class__):
                    result[attr_name] = attr_value.as_dict()
                else:
                    result[attr_name] = attr_value
        return result

