        openai.api_key = api_token

    def analyze(self, comment_text):
        """
        Processes natural language feedback and transforms it into structured command data.
        """
        try:
            result = openai.chat.completions.create(
                model="gpt-4.1-mini",
                messages=[
                    {
                        "role": "system",
                        "content": "You specialize in evaluating email-related feedback. Your goal is to parse free-text input and return a JSON object containing sentiment, focus area, and recommended revision. The 'focus area' must be one of: 'tone', 'length', 'style', 'vocabulary', 'call_to_action', 'greeting', 'closing', 'clarity', 'urgency', 'personalization'. The 'sentiment' should be either 'positive', 'negative', or 'neutral'. The 'recommended revision' should be a brief directive for an AI assistant; if the input lacks specificity, use 'general_improvement'."
